    private bool ShouldIgnoreStalePostTunaFallbackLegAuthorityRequest(
        FileTransferReceiveRecoveryRequest request,
        string? sessionId,
        string transferId,
        string reason)
    {
        if (!HasFileTransferFallbackLegAuthority(request) ||
            string.IsNullOrWhiteSpace(transferId))
        {
            return false;
        }

        FileTransferRouteHint routeHint;
        lock (gate)
        {
            if (!TryGetFileTransferRouteHintUnsafe(sessionId, transferId.Trim(), out routeHint))
            {
                return false;
            }
        }

        if (routeHint.Route == FileTransferRoute.PostTunaFallbackV6 &&
            routeHint.ProtocolVersion == FileTransferProtocol.ProtocolVersionV6)
        {
            return false;
        }

        MarkFileTransferFallbackLegAuthoritySupersededByRouteHint(
            transferId,
            routeHint.Token,
            routeHint.ProtocolVersion,
            "stale_fallback_authority_request");

        if (client is RealNknClientAdapter realClient)
        {
            realClient.ClearActiveFileTransferPostTunaFallbackRuntime(
                transferId,
                "stale_fallback_authority_request");
        }

        LocalOperationalLog.Warn(
            "NKN.Tuna",
            "event=filetransfer_fallback_leg_authority_stale_request_ignored; " +
            $"session_id={SanitizeLogToken(sessionId ?? "none")}; transfer_id={SanitizeLogToken(transferId)}; reason={SanitizeLogToken(reason)}; " +
            $"requested_route={SanitizeLogToken(request.RouteToken ?? "none")}; requested_protocol_version={request.ProtocolVersion}; requested_live_route_epoch={request.LiveRouteEpoch}; requested_leg_generation={request.TransferLegGeneration}; requested_transport_epoch={request.TransportEpoch}; " +
            $"current_route={SanitizeLogToken(routeHint.Token)}; current_protocol_version={routeHint.ProtocolVersion}; current_route_source={SanitizeLogToken(routeHint.Source)}");
        return true;
    }

    private void MarkFileTransferFallbackLegAuthoritySupersededByRouteHint(
        string? transferId,
        string routeToken,
        int protocolVersion,
        string source)
    {
        if (string.IsNullOrWhiteSpace(transferId))
        {
            return;
        }

        var normalizedTransferId = SanitizeLogToken(transferId.Trim());
        var normalizedRoute = SanitizeLogToken(routeToken);
        FileTransferFallbackLegAuthorityState? state;
        var shouldLog = false;
        lock (fileTransferFallbackProofGate)
        {
            state = fileTransferFallbackLegAuthorityState;
            if (state is not null &&
                !state.Completed &&
                string.Equals(state.TransferId, normalizedTransferId, StringComparison.Ordinal) &&
                (!string.Equals(normalizedRoute, FileTransferRouteResolver.PostTunaFallbackV6Token, StringComparison.Ordinal) ||
                 protocolVersion != FileTransferProtocol.ProtocolVersionV6))
            {
                state.Completed = true;
                ClearFileTransferFallbackProofAuthorityUnsafe();
                shouldLog = true;
            }
        }

        if (!shouldLog || state is null)
        {
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_fallback_leg_authority_superseded_by_route_hint; direction={state.Direction}; session_id={state.SessionId}; transfer_id={state.TransferId}; leg_generation={state.LegGeneration}; route={state.RouteToken}; protocol_version={state.ProtocolVersion}; live_route_epoch={state.LiveRouteEpoch}; transport_epoch={state.TransportEpoch}; bridge_recovery_generation={state.BridgeRecoveryGeneration}; checkpoint_request_id={SanitizeLogToken(state.CheckpointRequestId ?? "none")}; authority_reason={state.AuthorityReason}; superseded_by_route={normalizedRoute}; superseded_by_protocol_version={protocolVersion}; source={SanitizeLogToken(source)}");
    }

    internal bool IsAccelerationUserStoppedForCurrentSessionForTests => IsAccelerationUserStoppedForCurrentSession();

    internal void SetAccelerationAcceptedForTests(NknAccelerationLaneKind lanes, string? sessionId = null)
    {
        string? acceptedSessionId;
        lock (accelerationGate)
        {
            accelerationSessionId = string.IsNullOrWhiteSpace(sessionId)
                ? currentSessionSecurityState.SessionId?.Value
                : sessionId.Trim();
            accelerationNegotiatedLanes = lanes;
            acceptedSessionId = accelerationSessionId;
        }

        RequestFileTransferTunaActivationHandoff(acceptedSessionId, lanes, "test_accept");
        NotifyTransportAccelerationStateChanged("test_accept");
    }

    private bool StartTunaFallbackProofIfNeeded(string reason, string? sessionId, NknAccelerationLaneKind lanes)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? null : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId) || lanes == NknAccelerationLaneKind.None)
        {
            return false;
        }

        var normalizedReason = SanitizeLogToken(reason);
        if ((lanes & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File &&
            !HasActiveFileTransferDataSessionsForRecovery())
        {
            lanes &= ~NknAccelerationLaneKind.File;
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_post_tuna_fallback_v6_route_suppressed_no_active_transfer; session_id={SanitizeLogToken(normalizedSessionId)}; reason={normalizedReason}; remaining_lanes={FormatAccelerationLanesForLog(lanes)}");
            if (lanes == NknAccelerationLaneKind.None)
            {
                return false;
            }
        }

        TunaFallbackProofState? stateToLog = null;
        lock (accelerationGate)
        {
            if (tunaFallbackProofState is { } existing &&
                string.Equals(existing.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                if (IsFileTransferFallbackFinalForLanes(existing, lanes))
                {
                    if (ShouldReplaceFinalFileTransferFallbackForFreshUserStop(existing, lanes, normalizedReason))
                    {
                        LocalOperationalLog.Info(
                            "NKN.Tuna",
                            $"event=filetransfer_v6_fallback_start_replaced_final_for_user_stop; session_id={SanitizeLogToken(normalizedSessionId)}; reason={normalizedReason}; existing_reason={existing.Reason}; existing_fallback_epoch={existing.Epoch}; file_state={FormatTunaFallbackLaneState(existing.FileState)}; file_v6_epoch_state={FormatTunaFallbackFileV6EpochState(existing)}");
                    }
                    else
                    {
                        LocalOperationalLog.Info(
                            "NKN.Tuna",
                            $"event=filetransfer_v6_fallback_start_suppressed_final; session_id={SanitizeLogToken(normalizedSessionId)}; reason={normalizedReason}; existing_reason={existing.Reason}; file_state={FormatTunaFallbackLaneState(existing.FileState)}; file_v6_epoch_state={FormatTunaFallbackFileV6EpochState(existing)}");
                        return false;
                    }
                }
                else if (!existing.AccelerationUsedAfterFallback)
                {
                    return false;
                }
            }

            var epoch = Interlocked.Increment(ref tunaFallbackProofNextEpoch);
            tunaFallbackProofState = new TunaFallbackProofState
            {
                Epoch = epoch,
                SessionId = normalizedSessionId,
                Reason = normalizedReason,
                StartedUtc = DateTimeOffset.UtcNow,
                Lanes = lanes,
            };
            stateToLog = tunaFallbackProofState;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_fallback_started; session_id={stateToLog.SessionId}; fallback_epoch={stateToLog.Epoch}; reason={stateToLog.Reason}; lanes={FormatAccelerationLanesForLog(stateToLog.Lanes)}");
        if (IsMixedFallbackLaneSet(stateToLog.Lanes))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_mixed_handoff_started; session_id={stateToLog.SessionId}; fallback_epoch={stateToLog.Epoch}; reason={stateToLog.Reason}; lanes={FormatAccelerationLanesForLog(stateToLog.Lanes)}");
        }

        return true;
    }

    private void StartTunaFallbackProofAndRebindIfNeeded(string reason, string? sessionId, NknAccelerationLaneKind lanes)
    {
        if (!StartTunaFallbackProofIfNeeded(reason, sessionId, lanes))
        {
            return;
        }

        RebindFileTransferDataSessionsForTunaFallback(reason, sessionId, lanes);
        RebindScreenShareDataSessionsForTunaFallback(reason, sessionId, lanes);
    }

    public void ObserveFileTransferV6TransportEpoch(FileTransferV6TransportEpochSnapshot snapshot)
    {
        if (string.IsNullOrWhiteSpace(snapshot.SessionId) ||
            string.IsNullOrWhiteSpace(snapshot.TransferId) ||
            snapshot.TransportEpoch <= 0)
        {
            return;
        }

        if (!TryTrackFileTransferV6RegularNknRecoveryBoundary(snapshot, out snapshot))
        {
            return;
        }

        var key = new FileTransferV6TransportEpochKey(
            snapshot.SessionId,
            snapshot.TransferId,
            snapshot.Direction,
            snapshot.TransportEpoch);
        var updated = false;
        lock (fileTransferV6TransportEpochGate)
        {
            if (snapshot.State == V6TransportEpochState.TargetProofPending)
            {
                observedFileTransferV6TransportEpochStartedCount++;
                if (snapshot.HandoffKind == FileTransferTransportHandoffKind.NormalToTunaActivation &&
                    snapshot.TargetTransport == FileTransferTransportKind.Tuna)
                {
                    observedFileTransferV6NormalToTunaActivationStartedCount++;
                }
            }
            else if (snapshot.State == V6TransportEpochState.Recovered)
            {
                observedFileTransferV6TransportEpochRecoveredCount++;
                if (snapshot.HandoffKind == FileTransferTransportHandoffKind.NormalToTunaActivation &&
                    snapshot.TargetTransport == FileTransferTransportKind.Tuna)
                {
                    observedFileTransferV6NormalToTunaActivationRecoveredCount++;
                }

            }
            else if (snapshot.State == V6TransportEpochState.WaitingForTargetTransport)
            {
                observedFileTransferV6TransportEpochWaitingCount++;
            }
            else if (snapshot.State == V6TransportEpochState.Terminal)
            {
                observedFileTransferV6TransportEpochTerminalCount++;
            }

            if (snapshot.IsUnresolved)
            {
                unresolvedFileTransferV6TransportEpochs[key] = snapshot;
                updated = true;
            }
            else
            {
                updated = unresolvedFileTransferV6TransportEpochs.Remove(key);
            }
        }

        if (updated)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_v6_epoch_observed; session_id={SanitizeLogToken(snapshot.SessionId)}; transfer_id={SanitizeLogToken(snapshot.TransferId)}; direction={snapshot.Direction.ToString().ToLowerInvariant()}; transport_epoch={snapshot.TransportEpoch}; state={FormatFileTransferV6TransportEpochStateForLog(snapshot.State)}; handoff_kind={FormatFileTransferTransportHandoffKindForLog(snapshot.HandoffKind)}; target_transport={FormatFileTransferTransportKindForLog(snapshot.TargetTransport)}; unresolved={(snapshot.IsUnresolved ? 1 : 0)}; reason={SanitizeLogToken(snapshot.Reason)}");
        }

        if (snapshot.HandoffKind == FileTransferTransportHandoffKind.NormalToTunaActivation &&
            snapshot.TargetTransport == FileTransferTransportKind.Tuna)
        {
            ClearPendingFileTransferV6Handoffs("epoch_observed", snapshot.SessionId);
        }

        if (ShouldIgnoreFinalFileTransferFallbackEpochSnapshot(snapshot))
        {
            return;
        }

        ApplyFileTransferV6TransportEpochObservationToFallbackState(snapshot);
    }

    private void ApplyFileTransferV6TransportEpochObservationToFallbackState(
        FileTransferV6TransportEpochSnapshot snapshot)
    {
        if (snapshot.TargetTransport != FileTransferTransportKind.RegularNkn ||
            snapshot.HandoffKind is not FileTransferTransportHandoffKind.TunaToNormalFallback and not FileTransferTransportHandoffKind.RegularNknRecovery)
        {
            return;
        }

        MarkTunaFallbackFileV6EpochState(snapshot.SessionId, snapshot.TransportEpoch, snapshot.State, SanitizeLogToken(snapshot.Reason));

        if (snapshot.State == V6TransportEpochState.WaitingForTargetTransport)
        {
            MarkTunaFallbackLaneState(
                snapshot.SessionId,
                lane: NknAccelerationLaneKind.File,
                state: TunaFallbackLaneState.WaitingForRegularNkn,
                reason: SanitizeLogToken(snapshot.Reason));
            return;
        }

        if (snapshot.State == V6TransportEpochState.Recovered)
        {
            CompleteFileTransferFallbackNknProofFromV6Epoch(snapshot);
            QueueRuntimeUnlockRetryFallbackTailUnblockRecheck(snapshot);
        }
    }

    private bool TryTrackFileTransferV6RegularNknRecoveryBoundary(
        FileTransferV6TransportEpochSnapshot snapshot,
        out FileTransferV6TransportEpochSnapshot trackedSnapshot)
    {
        trackedSnapshot = snapshot;
        if (snapshot.TargetTransport != FileTransferTransportKind.RegularNkn ||
            snapshot.HandoffKind is not FileTransferTransportHandoffKind.TunaToNormalFallback and not FileTransferTransportHandoffKind.RegularNknRecovery)
        {
            return true;
        }

        var scopeKey = new FileTransferV6TransportEpochScopeKey(
            snapshot.SessionId.Trim(),
            snapshot.TransferId.Trim(),
            snapshot.Direction);
        FileTransferV6TransportEpochSnapshot? currentSnapshot = null;
        string? ignoreReason = null;
        lock (fileTransferV6TransportEpochGate)
        {
            if (!fileTransferV6RegularNknEpochScopes.TryGetValue(scopeKey, out var scopeState))
            {
                scopeState = new FileTransferV6RegularNknEpochScopeState();
                fileTransferV6RegularNknEpochScopes.Add(scopeKey, scopeState);
            }

            currentSnapshot = scopeState.LatestSnapshot;
            if (snapshot.State != V6TransportEpochState.Recovered)
            {
                if (currentSnapshot is null || snapshot.TransportEpoch >= currentSnapshot.TransportEpoch)
                {
                    scopeState.LatestSnapshot = snapshot;
                }

                return true;
            }

            var boundaryGeneration = snapshot.RecoveryBoundaryGeneration;
            if (boundaryGeneration <= 0)
            {
                if (scopeState.CurrentRecoveredBoundary is { } currentRecovered &&
                    IsSameFileTransferV6RecoveryBoundaryTuple(currentRecovered, snapshot))
                {
                    ignoreReason = "duplicate_recovery_boundary";
                }
                else
                {
                    boundaryGeneration = scopeState.LastRecoveryBoundaryGeneration + 1;
                    snapshot.RecoveryBoundaryGeneration = boundaryGeneration;
                }
            }

            if (ignoreReason is null &&
                currentSnapshot is { } latest &&
                (snapshot.TransportEpoch < latest.TransportEpoch ||
                 snapshot.TransportEpoch == latest.TransportEpoch &&
                 latest.State == V6TransportEpochState.Terminal))
            {
                ignoreReason = "stale_transport_epoch";
            }

            if (ignoreReason is null &&
                boundaryGeneration <= scopeState.LastRecoveryBoundaryGeneration)
            {
                ignoreReason = boundaryGeneration == scopeState.LastRecoveryBoundaryGeneration
                    ? "duplicate_recovery_boundary_generation"
                    : "stale_recovery_boundary_generation";
            }

            if (ignoreReason is null)
            {
                scopeState.LastRecoveryBoundaryGeneration = boundaryGeneration;
                scopeState.CurrentRecoveredBoundary = trackedSnapshot;
                scopeState.LatestSnapshot = trackedSnapshot;
                return true;
            }
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_v6_epoch_observation_ignored_stale_recovered; session_id={SanitizeLogToken(snapshot.SessionId)}; transfer_id={SanitizeLogToken(snapshot.TransferId)}; direction={snapshot.Direction.ToString().ToLowerInvariant()}; transport_epoch={snapshot.TransportEpoch}; current_transport_epoch={currentSnapshot?.TransportEpoch ?? 0}; recovery_boundary_generation={snapshot.RecoveryBoundaryGeneration}; state={FormatFileTransferV6TransportEpochStateForLog(snapshot.State)}; handoff_kind={FormatFileTransferTransportHandoffKindForLog(snapshot.HandoffKind)}; source_transport={FormatFileTransferTransportKindForLog(snapshot.SourceTransport)}; target_transport={FormatFileTransferTransportKindForLog(snapshot.TargetTransport)}; reason={SanitizeLogToken(ignoreReason ?? "stale_recovery_boundary")}");
        return false;
    }

    private static bool IsSameFileTransferV6RecoveryBoundaryTuple(
        FileTransferV6TransportEpochSnapshot left,
        FileTransferV6TransportEpochSnapshot right)
        => string.Equals(left.SessionId, right.SessionId, StringComparison.Ordinal) &&
           string.Equals(left.TransferId, right.TransferId, StringComparison.Ordinal) &&
           left.Direction == right.Direction &&
           left.TransportEpoch == right.TransportEpoch &&
           left.HandoffKind == right.HandoffKind &&
           left.SourceTransport == right.SourceTransport &&
           left.TargetTransport == right.TargetTransport &&
           left.State == right.State &&
           string.Equals(left.Reason, right.Reason, StringComparison.Ordinal) &&
           left.IsUnresolved == right.IsUnresolved;

    private bool IsCurrentFileTransferV6RegularNknRecoveryBoundary(
        FileTransferV6TransportEpochSnapshot snapshot)
    {
        var scopeKey = new FileTransferV6TransportEpochScopeKey(
            snapshot.SessionId.Trim(),
            snapshot.TransferId.Trim(),
            snapshot.Direction);
        lock (fileTransferV6TransportEpochGate)
        {
            return fileTransferV6RegularNknEpochScopes.TryGetValue(scopeKey, out var scopeState) &&
                   scopeState.CurrentRecoveredBoundary is { } current &&
                   scopeState.LatestSnapshot is { State: V6TransportEpochState.Recovered } latest &&
                   latest.TransportEpoch == current.TransportEpoch &&
                   current.RecoveryBoundaryGeneration == snapshot.RecoveryBoundaryGeneration &&
                   IsSameFileTransferV6RecoveryBoundaryTuple(current, snapshot);
        }
    }

    private bool TryGetCurrentFileTransferV6RegularNknRecoveryBoundary(
        string sessionId,
        string transferId,
        FileTransferDirection direction,
        out FileTransferV6TransportEpochSnapshot snapshot)
    {
        var scopeKey = new FileTransferV6TransportEpochScopeKey(
            sessionId.Trim(),
            transferId.Trim(),
            direction);
        lock (fileTransferV6TransportEpochGate)
        {
            if (fileTransferV6RegularNknEpochScopes.TryGetValue(scopeKey, out var scopeState) &&
                scopeState.CurrentRecoveredBoundary is { } current &&
                scopeState.LatestSnapshot is { State: V6TransportEpochState.Recovered } latest &&
                latest.TransportEpoch == current.TransportEpoch)
            {
                snapshot = current;
                return true;
            }
        }

        snapshot = default!;
        return false;
    }

    private bool ShouldIgnoreFinalFileTransferFallbackEpochSnapshot(FileTransferV6TransportEpochSnapshot snapshot)
    {
        if (snapshot.TargetTransport != FileTransferTransportKind.RegularNkn ||
            snapshot.HandoffKind is not FileTransferTransportHandoffKind.TunaToNormalFallback and not FileTransferTransportHandoffKind.RegularNknRecovery)
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (!TryGetCurrentTunaFallbackProofStateUnsafe(snapshot.SessionId, out var current) ||
                !ShouldIgnoreFinalFileTransferFallbackEpochSnapshotUnsafe(snapshot, current))
            {
                return false;
            }

            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_v6_epoch_observation_ignored_final_fallback; session_id={SanitizeLogToken(snapshot.SessionId)}; transfer_id={SanitizeLogToken(snapshot.TransferId)}; direction={snapshot.Direction.ToString().ToLowerInvariant()}; transport_epoch={snapshot.TransportEpoch}; state={FormatFileTransferV6TransportEpochStateForLog(snapshot.State)}; handoff_kind={FormatFileTransferTransportHandoffKindForLog(snapshot.HandoffKind)}; target_transport={FormatFileTransferTransportKindForLog(snapshot.TargetTransport)}; reason={SanitizeLogToken(snapshot.Reason)}; file_state={FormatTunaFallbackLaneState(current.FileState)}; file_v6_epoch_state={FormatTunaFallbackFileV6EpochState(current)}; file_v6_transport_epoch={current.FileV6TransportEpoch}");
            return true;
        }
    }

    private static bool ShouldIgnoreFinalFileTransferFallbackEpochSnapshotUnsafe(
        FileTransferV6TransportEpochSnapshot snapshot,
        TunaFallbackProofState current)
    {
        if (!IsFileTransferFallbackFinalForLanes(current, NknAccelerationLaneKind.File))
        {
            return false;
        }

        if (current.FileV6TransportEpoch > 0 &&
            snapshot.TransportEpoch > 0 &&
            snapshot.TransportEpoch < current.FileV6TransportEpoch)
        {
            return true;
        }

        // Once Core has entered an unresolved proof/waiting state for the same epoch,
        // it is still the recovery authority. Only suppress new proof-pending noise
        // caused by secondary sidecar errors after a completed fallback.
        return snapshot.State == V6TransportEpochState.TargetProofPending &&
               snapshot.HandoffKind == FileTransferTransportHandoffKind.TunaToNormalFallback;
    }

    private bool TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out FileTransferV6TransportEpochSnapshot snapshot)
    {
        var sessionId = currentSessionSecurityState.SessionId?.Value;
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            snapshot = default!;
            return false;
        }

        lock (fileTransferV6TransportEpochGate)
        {
            foreach (var candidate in unresolvedFileTransferV6TransportEpochs.Values)
            {
                if (string.Equals(candidate.SessionId, sessionId, StringComparison.Ordinal) &&
                    candidate.IsUnresolved)
                {
                    snapshot = candidate;
                    return true;
                }
            }
        }

        snapshot = default!;
        return false;
    }

    private bool ShouldSuppressFileTransferControlReceiveStallRecoveryBroadcast(
        string reason,
        out string suppressReason,
        out long cooldownRemainingMs)
    {
        suppressReason = "none";
        cooldownRemainingMs = 0;
        if (!reason.StartsWith("control_receive_stalled", StringComparison.OrdinalIgnoreCase))
        {
            return false;
        }

        var sessionId = currentSessionSecurityState.SessionId?.Value;
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        lock (fileTransferV6TransportEpochGate)
        {
            foreach (var candidate in unresolvedFileTransferV6TransportEpochs.Values)
            {
                if (string.Equals(candidate.SessionId, sessionId, StringComparison.Ordinal) &&
                    candidate.TargetTransport == FileTransferTransportKind.RegularNkn &&
                    candidate.HandoffKind is FileTransferTransportHandoffKind.TunaToNormalFallback or FileTransferTransportHandoffKind.RegularNknRecovery &&
                    candidate.IsUnresolved)
                {
                    suppressReason = "regular_nkn_epoch_unresolved";
                    return true;
                }
            }

            var recovered = fileTransferV6RegularNknEpochScopes.Values
                .Where(static scope =>
                    scope.CurrentRecoveredBoundary is { } current &&
                    scope.LatestSnapshot is { State: V6TransportEpochState.Recovered } latest &&
                    latest.TransportEpoch == current.TransportEpoch)
                .Select(static scope => scope.CurrentRecoveredBoundary)
                .FirstOrDefault(candidate =>
                    candidate is not null &&
                    string.Equals(candidate.SessionId, sessionId, StringComparison.Ordinal));
            if (recovered is not null)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=filetransfer_control_receive_stall_recovery_after_recovered_epoch_allowed; session_id={SanitizeLogToken(sessionId)}; reason={SanitizeLogToken(reason)}; recovered_transport_epoch={recovered.TransportEpoch}; recovered_handoff_kind={FormatFileTransferTransportHandoffKindForLog(recovered.HandoffKind)}");
            }
        }

        var nowTick = Stopwatch.GetTimestamp();
        var lastTick = Volatile.Read(ref fileTransferControlReceiveStallRecoveryBroadcastLastTick);
        if (lastTick > 0)
        {
            var elapsed = Stopwatch.GetElapsedTime(lastTick, nowTick);
            if (elapsed < FileTransferControlReceiveStallRecoveryBroadcastCooldown)
            {
                suppressReason = "cooldown";
                cooldownRemainingMs = Math.Max(
                    0,
                    (long)(FileTransferControlReceiveStallRecoveryBroadcastCooldown - elapsed).TotalMilliseconds);
                return true;
            }
        }

        return false;
    }

    private void MarkFileTransferControlReceiveStallRecoveryBroadcasted()
        => Volatile.Write(ref fileTransferControlReceiveStallRecoveryBroadcastLastTick, Stopwatch.GetTimestamp());

    private void ClearUnresolvedFileTransferV6TransportEpochs(string reason)
    {
        int clearedCount;
        lock (fileTransferV6TransportEpochGate)
        {
            clearedCount = unresolvedFileTransferV6TransportEpochs.Count;
            unresolvedFileTransferV6TransportEpochs.Clear();
            fileTransferV6RegularNknEpochScopes.Clear();
        }

        if (clearedCount > 0)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_v6_epoch_observer_cleared; reason={SanitizeLogToken(reason)}; cleared_count={clearedCount}");
        }
    }

    private void RebindFileTransferDataSessionsForTunaFallback(
        string reason,
        string? sessionId,
        NknAccelerationLaneKind lanes)
    {
        if ((lanes & NknAccelerationLaneKind.File) != NknAccelerationLaneKind.File ||
            string.IsNullOrWhiteSpace(sessionId))
        {
            return;
        }

        var normalizedReason = SanitizeLogToken(reason);
        RecordPendingFileTransferTunaFallbackReason(sessionId, normalizedReason);
        ClearPendingFileTransferV6Handoffs("tuna_fallback", sessionId);
        if (ShouldSuppressDuplicateRecoveredFileTransferFallback(sessionId, normalizedReason))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_v6_fallback_handoff_suppressed_duplicate; session_id={SanitizeLogToken(sessionId ?? "none")}; reason={normalizedReason}; target_transport={FormatFileTransferTransportKindForLog(FileTransferTransportKind.RegularNkn)}");
            return;
        }

        MarkTunaFallbackLaneState(
            sessionId,
            lane: NknAccelerationLaneKind.File,
            state: TunaFallbackLaneState.Pending,
            reason: normalizedReason);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_fallback_filetransfer_rebind_requested; session_id={sessionId}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}");
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_disable_handoff_started; session_id={sessionId}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}");
        MarkFileTransferFallbackNknProofPending(normalizedReason, sessionId, lanes);
        SetFileTransferDataSessionsAvailability(
            isAvailable: false,
            reason: normalizedReason,
            requiresResumeRequest: true,
            handoffKind: FileTransferTransportHandoffKind.TunaToNormalFallback,
            targetTransport: FileTransferTransportKind.RegularNkn);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_disable_handoff_nkn_pending; session_id={sessionId}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}");

        if (ShouldStartImmediateFileTransferFallbackProbe(normalizedReason))
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=filetransfer_fallback_nkn_probe_started; session_id={sessionId}; reason={normalizedReason}; trigger=cap_handoff_immediate; delay_ms=0; lanes={FormatAccelerationLanesForLog(lanes)}");
            ArmPostTunaFallbackProofSendWindow(normalizedReason, "cap_handoff_immediate", sessionId);
            SetFileTransferDataSessionsAvailability(
                isAvailable: false,
                reason: "transport_recovered_unproven",
                requiresResumeRequest: true,
                handoffKind: FileTransferTransportHandoffKind.TunaToNormalFallback,
                targetTransport: FileTransferTransportKind.RegularNkn);
        }
    }

    private bool ShouldSuppressDuplicateRecoveredFileTransferFallback(string? sessionId, string reason)
    {
        lock (accelerationGate)
        {
            if (!TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out var current))
            {
                return false;
            }

            return IsFileTransferFallbackFinalForLanes(current, NknAccelerationLaneKind.File);
        }
    }

    private static bool IsFileTransferFallbackFinalForLanes(TunaFallbackProofState state, NknAccelerationLaneKind lanes)
        => (lanes & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File &&
           (state.Lanes & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File &&
           state.FileState == TunaFallbackLaneState.Recovered;

    private static bool ShouldReplaceFinalFileTransferFallbackForFreshUserStop(
        TunaFallbackProofState state,
        NknAccelerationLaneKind lanes,
        string normalizedReason)
        => (lanes & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File &&
           IsFileTransferFallbackFinalForLanes(state, lanes) &&
           (IsUserRequestedAccelerationStopReason(normalizedReason) ||
            IsRemoteUserRequestedAccelerationStopReason(normalizedReason));

    private void RequestFileTransferTunaActivationHandoff(
        string? sessionId,
        NknAccelerationLaneKind lanes,
        string reason)
    {
        if ((lanes & NknAccelerationLaneKind.File) != NknAccelerationLaneKind.File ||
            string.IsNullOrWhiteSpace(sessionId))
        {
            return;
        }

        var normalizedReason = SanitizeLogToken(reason);
        if (IsRuntimeUnlockPostTunaFallbackActivationAwaitingCommittedAuthority(
                sessionId,
                out var activationAuthorityReason))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_runtime_unlock_handoff_held_for_retry_authority; session_id={SanitizeLogToken(sessionId)}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}; source=tuna_activation_handoff; decision_reason={SanitizeLogToken(activationAuthorityReason)}");
            return;
        }

        if (ShouldKeepPostTunaFallbackDataSessionsAvailableDuringTunaActivation(
                sessionId,
                out var fallbackOwnerReason))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_runtime_unlock_waiting_for_fallback_owner; session_id={SanitizeLogToken(sessionId)}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}; source=tuna_activation_handoff; fallback_owner_reason={SanitizeLogToken(fallbackOwnerReason)}");
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_fallback_unavailable_suppressed; session_id={SanitizeLogToken(sessionId)}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}; source=tuna_activation_handoff; fallback_owner_reason={SanitizeLogToken(fallbackOwnerReason)}");
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_runtime_unlock_handoff_held_by_fallback_owner; session_id={SanitizeLogToken(sessionId)}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}; source=tuna_activation_handoff; fallback_owner_reason={SanitizeLogToken(fallbackOwnerReason)}");
            return;
        }

        if (TryCaptureUncommittedRuntimeUnlockHandoffBlocker(
                sessionId,
                out var runtimeUnlockSnapshot))
        {
            if (runtimeUnlockSnapshot.IsTerminal &&
                IsRuntimeUnlockRetryDispatchAuthorityHeldForSession(
                    sessionId,
                    out var heldReason))
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=runtime_unlock_terminal_transaction_handoff_held_for_retry_authority; session_id={SanitizeLogToken(sessionId)}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}; transaction_generation={runtimeUnlockSnapshot.TransactionGeneration}; offer_generation={runtimeUnlockSnapshot.OfferGeneration}; state={runtimeUnlockSnapshot.State.ToString().ToLowerInvariant()}; path_probe_state={runtimeUnlockSnapshot.PathProbeState.ToString().ToLowerInvariant()}; dispatch_decision_status=Held; decision_reason={SanitizeLogToken(heldReason)}; source=tuna_activation_handoff");
                return;
            }

            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_runtime_unlock_handoff_pending_route_commit; session_id={SanitizeLogToken(sessionId)}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}; transaction_generation={runtimeUnlockSnapshot.TransactionGeneration}; offer_generation={runtimeUnlockSnapshot.OfferGeneration}; state={runtimeUnlockSnapshot.State.ToString().ToLowerInvariant()}; path_probe_state={runtimeUnlockSnapshot.PathProbeState.ToString().ToLowerInvariant()}; route_commit_pending={(runtimeUnlockSnapshot.RouteCommitPending ? 1 : 0)}; route_committed={(runtimeUnlockSnapshot.RouteCommitted ? 1 : 0)}; source=tuna_activation_handoff");
            if (ShouldRequestRuntimeUnlockPreCommitProbeLaunch(runtimeUnlockSnapshot))
            {
                RequestRuntimeUnlockPreCommitProbeLaunch(
                    sessionId,
                    lanes,
                    normalizedReason,
                    runtimeUnlockSnapshot);
            }

            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_activation_filetransfer_handoff_requested; session_id={SanitizeLogToken(sessionId)}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}");
        RequestFileTransferDataSessionsHandoff(
            normalizedReason,
            FileTransferTransportHandoffKind.NormalToTunaActivation,
            FileTransferTransportKind.Tuna,
            sessionId);
    }

    private bool IsRuntimeUnlockPostTunaFallbackActivationAwaitingCommittedAuthority(
        string sessionId,
        out string reason)
    {
        lock (accelerationGate)
        {
            var intent = runtimeUnlockPostTunaFallbackActivationIntent;
            if (intent is null ||
                !string.Equals(intent.SessionId, sessionId.Trim(), StringComparison.Ordinal))
            {
                reason = "none";
                return false;
            }

            var state = runtimeUnlockRecoveryRetryState;
            if (state?.PostTunaFallbackActivationIntent == intent &&
                state.LastCommittedDispatchInstallReceipt is { } receipt &&
                state.DispatchContract?.Authority == receipt.Authority)
            {
                reason = "committed_retry_dispatch_authority";
                return false;
            }

            reason = "post_tuna_fallback_activation_authority_not_committed";
            return true;
        }
    }

    private static TimeSpan ResolveRuntimeUnlockPreCommitProbeStartTimeout()
        => RuntimeUnlockPreCommitProbeStartTimeoutOverrideForTests ?? RuntimeUnlockPreCommitProbeStartTimeout;

    private static bool ShouldRequestRuntimeUnlockPreCommitProbeLaunch(RuntimeUnlockTransactionSnapshot snapshot)
        => !snapshot.IsTerminal &&
           snapshot.HasPeerVisibleProof &&
           snapshot.AnswerReceived &&
           !snapshot.RouteCommitted &&
           snapshot.PathProbeState == RuntimeUnlockPathProbeState.None;

    public void NotifyRuntimeUnlockPreCommitProbeLaunchHeld(RuntimeUnlockPreCommitProbeLaunchHoldNotification notification)
    {
        if (notification.TransactionGeneration <= 0 ||
            notification.OfferGeneration <= 0 ||
            string.IsNullOrWhiteSpace(notification.SessionId) ||
            string.IsNullOrWhiteSpace(notification.TransferId))
        {
            return;
        }

        var held = false;
        long launchGeneration;
        lock (accelerationGate)
        {
            if (!string.Equals(runtimeUnlockPreCommitProbeLaunchSessionId, notification.SessionId, StringComparison.Ordinal) ||
                !string.Equals(runtimeUnlockPreCommitProbeLaunchTransferId, notification.TransferId, StringComparison.Ordinal) ||
                runtimeUnlockPreCommitProbeLaunchTransactionGeneration != notification.TransactionGeneration ||
                runtimeUnlockPreCommitProbeLaunchOfferGeneration != notification.OfferGeneration ||
                runtimeUnlockPreCommitProbeLaunchSnapshot is not { LaunchGeneration: > 0 } launchSnapshot ||
                launchSnapshot.LaunchGeneration != runtimeUnlockPreCommitProbeLaunchGeneration ||
                launchSnapshot.TunaPathLeaseGeneration != notification.TunaPathLeaseGeneration)
            {
                return;
            }

            runtimeUnlockPreCommitProbeLaunchHeldByCoordinatorDenial = true;
            runtimeUnlockPreCommitProbeLaunchHeldReason = SanitizeLogToken(notification.Reason);
            runtimeUnlockPreCommitProbeLaunchHeldAdmissionReason = SanitizeLogToken(notification.AdmissionReason);
            runtimeUnlockPreCommitProbeLaunchHeldDirection = notification.Direction.ToString().ToLowerInvariant();
            runtimeUnlockPreCommitProbeLaunchTimeoutScheduled = false;
            launchGeneration = runtimeUnlockPreCommitProbeLaunchGeneration;
            held = true;
        }

        if (!held)
        {
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_precommit_probe_launch_held_by_coordinator_denial; session_id={SanitizeLogToken(notification.SessionId)}; transfer_id={SanitizeLogToken(notification.TransferId)}; direction={notification.Direction.ToString().ToLowerInvariant()}; transaction_generation={notification.TransactionGeneration}; offer_generation={notification.OfferGeneration}; launch_generation={launchGeneration}; tuna_path_lease_generation={notification.TunaPathLeaseGeneration}; source={SanitizeLogToken(notification.Source)}; reason={SanitizeLogToken(notification.Reason)}; admission_reason={SanitizeLogToken(notification.AdmissionReason)}; route=post_tuna_fallback_v6; protocol_version={FileTransferProtocol.ProtocolVersionV6}; live_route_epoch={notification.LiveRouteEpoch}; runtime_generation={notification.RuntimeGeneration}; terminal_generation={notification.TerminalGeneration}; leg_generation={notification.LegGeneration}");
    }

    private void RequestRuntimeUnlockPreCommitProbeLaunch(
        string sessionId,
        NknAccelerationLaneKind lanes,
        string reason,
        RuntimeUnlockTransactionSnapshot snapshot)
    {
        var launchTransferId = ResolveSingleActiveFileTransferDataSessionTransferId(sessionId, snapshot.TransferId);
        long launchGeneration;
        RuntimeUnlockRouteCommitSnapshot launchSnapshot;
        bool duplicate;
        bool tupleMutation;
        lock (accelerationGate)
        {
            var sameLogicalLaunch =
                string.Equals(runtimeUnlockPreCommitProbeLaunchSessionId, sessionId, StringComparison.Ordinal) &&
                string.Equals(runtimeUnlockPreCommitProbeLaunchTransferId, launchTransferId, StringComparison.Ordinal) &&
                runtimeUnlockPreCommitProbeLaunchTransactionGeneration == snapshot.TransactionGeneration &&
                runtimeUnlockPreCommitProbeLaunchOfferGeneration == snapshot.OfferGeneration;
            if (!sameLogicalLaunch)
            {
                runtimeUnlockPreCommitProbeLaunchSessionId = sessionId;
                runtimeUnlockPreCommitProbeLaunchTransferId = launchTransferId;
                runtimeUnlockPreCommitProbeLaunchTransactionGeneration = snapshot.TransactionGeneration;
                runtimeUnlockPreCommitProbeLaunchOfferGeneration = snapshot.OfferGeneration;
                runtimeUnlockPreCommitProbeLaunchGeneration++;
                runtimeUnlockPreCommitProbeLaunchTimeoutScheduled = false;
                runtimeUnlockPreCommitProbeStartedSnapshot = null;
                ClearRuntimeUnlockPreCommitProbeLaunchHoldUnsafe();
            }

            launchGeneration = runtimeUnlockPreCommitProbeLaunchGeneration;
            launchSnapshot = CreateRuntimeUnlockPreCommitProbeLaunchSnapshot(
                snapshot,
                launchTransferId,
                reason,
                launchGeneration);
            duplicate = sameLogicalLaunch &&
                runtimeUnlockPreCommitProbeLaunchSnapshot is { } existingLaunchSnapshot &&
                HasSameRuntimeUnlockPreCommitProbeLaunchTuple(existingLaunchSnapshot, launchSnapshot);
            tupleMutation = sameLogicalLaunch && !duplicate;
            if (!sameLogicalLaunch)
            {
                runtimeUnlockPreCommitProbeLaunchSnapshot = launchSnapshot;
            }
            else if (duplicate && runtimeUnlockPreCommitProbeLaunchSnapshot is { } currentLaunchSnapshot)
            {
                launchSnapshot = currentLaunchSnapshot;
            }
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_precommit_probe_launch_requested; session_id={SanitizeLogToken(sessionId)}; transfer_id={SanitizeLogToken(launchTransferId ?? "none")}; reason={SanitizeLogToken(reason)}; lanes={FormatAccelerationLanesForLog(lanes)}; transaction_generation={snapshot.TransactionGeneration}; offer_generation={snapshot.OfferGeneration}; launch_generation={launchGeneration}; tuna_path_lease_generation={snapshot.TunaPathLeaseGeneration}; tuna_path_lease_listener_run_id={SanitizeLogToken(snapshot.TunaPathLeaseListenerRunId ?? "none")}; path_probe_id={SanitizeLogToken(snapshot.PathProbeId ?? "none")}; path_probe_state={snapshot.PathProbeState.ToString().ToLowerInvariant()}; duplicate={(duplicate ? 1 : 0)}; tuple_mutation={(tupleMutation ? 1 : 0)}; responder_waiting_for_peer_probe={(IsRuntimeUnlockResponderWaitingForPeerProbe(snapshot) ? 1 : 0)}");

        if (tupleMutation)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=runtime_unlock_precommit_probe_launch_rejected; session_id={SanitizeLogToken(sessionId)}; transfer_id={SanitizeLogToken(launchTransferId ?? "none")}; transaction_generation={snapshot.TransactionGeneration}; offer_generation={snapshot.OfferGeneration}; launch_generation={launchGeneration}; tuna_path_lease_generation={snapshot.TunaPathLeaseGeneration}; tuna_path_lease_listener_run_id={SanitizeLogToken(snapshot.TunaPathLeaseListenerRunId ?? "none")}; decision_reason=launch_tuple_mismatch");
            return;
        }

        if (!duplicate)
        {
            if (!IsRuntimeUnlockResponderWaitingForPeerProbe(snapshot))
            {
                if (HasActiveFileTransferDataSessionForTransfer(sessionId, launchTransferId))
                {
                    lock (accelerationGate)
                    {
                        if (string.Equals(runtimeUnlockPreCommitProbeLaunchSessionId, sessionId, StringComparison.Ordinal) &&
                            string.Equals(runtimeUnlockPreCommitProbeLaunchTransferId, launchTransferId, StringComparison.Ordinal) &&
                            runtimeUnlockPreCommitProbeLaunchTransactionGeneration == snapshot.TransactionGeneration &&
                            runtimeUnlockPreCommitProbeLaunchOfferGeneration == snapshot.OfferGeneration &&
                            runtimeUnlockPreCommitProbeLaunchGeneration == launchGeneration &&
                            !runtimeUnlockPreCommitProbeLaunchHeldByCoordinatorDenial)
                        {
                            runtimeUnlockPreCommitProbeLaunchTimeoutScheduled = true;
                        }
                    }

                    ScheduleRuntimeUnlockPreCommitProbeStartTimeout(
                        sessionId,
                        launchTransferId,
                        snapshot.TransactionGeneration,
                        snapshot.OfferGeneration,
                        launchGeneration);
                }
                else
                {
                    LogRuntimeUnlockPreCommitProbeLaunchWaitingForDataSession(
                        sessionId,
                        launchTransferId,
                        snapshot.TransactionGeneration,
                        snapshot.OfferGeneration,
                        launchGeneration,
                        snapshot.TunaPathLeaseGeneration,
                        snapshot.TunaPathLeaseListenerRunId,
                        reason,
                        "launch_requested_without_data_session");
                }
            }

            RequestFileTransferDataSessionsHandoff(
                reason,
                FileTransferTransportHandoffKind.NormalToTunaActivation,
                FileTransferTransportKind.Tuna,
                sessionId,
                launchSnapshot);
        }
    }

    private static bool HasSameRuntimeUnlockPreCommitProbeLaunchTuple(
        RuntimeUnlockRouteCommitSnapshot left,
        RuntimeUnlockRouteCommitSnapshot right)
        => string.Equals(left.SessionId, right.SessionId, StringComparison.Ordinal) &&
           string.Equals(left.TransferId, right.TransferId, StringComparison.Ordinal) &&
           left.TransactionGeneration == right.TransactionGeneration &&
           left.OfferGeneration == right.OfferGeneration &&
           left.PeerVisibleProof == right.PeerVisibleProof &&
           left.PeerReceived == right.PeerReceived &&
           left.AnswerReceived == right.AnswerReceived &&
           left.TargetRoute == right.TargetRoute &&
           left.ProtocolVersion == right.ProtocolVersion &&
           left.HandoffKind == right.HandoffKind &&
           left.TargetTransport == right.TargetTransport &&
           string.Equals(left.TransactionState, right.TransactionState, StringComparison.Ordinal) &&
           string.Equals(left.PathProbeId, right.PathProbeId, StringComparison.Ordinal) &&
           string.Equals(left.PathProbeState, right.PathProbeState, StringComparison.Ordinal) &&
           left.PathProbeTransport == right.PathProbeTransport &&
           left.PathProbeAckedUtcMs == right.PathProbeAckedUtcMs &&
           string.Equals(left.PathProbeFailureReason, right.PathProbeFailureReason, StringComparison.Ordinal) &&
           left.TunaPathLeaseRequired == right.TunaPathLeaseRequired &&
           left.TunaPathLeaseGeneration == right.TunaPathLeaseGeneration &&
           string.Equals(left.TunaPathLeaseState, right.TunaPathLeaseState, StringComparison.Ordinal) &&
           string.Equals(left.TunaPathLeaseListenerRunId, right.TunaPathLeaseListenerRunId, StringComparison.Ordinal) &&
           left.TunaPathLeaseCurrent == right.TunaPathLeaseCurrent &&
           string.Equals(left.TunaPathLeaseFailureReason, right.TunaPathLeaseFailureReason, StringComparison.Ordinal) &&
           left.LaunchGeneration == right.LaunchGeneration;

    private static RuntimeUnlockRouteCommitSnapshot CreateRuntimeUnlockPreCommitProbeLaunchSnapshot(
        RuntimeUnlockTransactionSnapshot snapshot,
        string? transferId,
        string reason,
        long launchGeneration)
        => new(
            snapshot.SessionId,
            string.IsNullOrWhiteSpace(snapshot.TransferId) ? transferId : snapshot.TransferId,
            snapshot.TransactionGeneration,
            snapshot.OfferGeneration,
            snapshot.HasPeerVisibleProof,
            snapshot.PeerReceived,
            snapshot.AnswerReceived,
            FileTransferRoute.FileTunaV4,
            FileTransferProtocol.ProtocolVersionV4,
            FileTransferTransportHandoffKind.NormalToTunaActivation,
            FileTransferTransportKind.Tuna,
            snapshot.State.ToString(),
            SanitizeLogToken(reason),
            PathProbeId: snapshot.PathProbeId,
            PathProbeState: snapshot.PathProbeState.ToString(),
            PathProbeTransport: snapshot.PathProbeTransport,
            PathProbeAckedUtcMs: snapshot.PathProbeAckedUtcMs,
            PathProbeFailureReason: snapshot.PathProbeFailureReason,
            TunaPathLeaseRequired: snapshot.TunaPathLeaseGeneration > 0 ||
                                   snapshot.TunaPathLeaseCurrent ||
                                   !string.IsNullOrWhiteSpace(snapshot.TunaPathLeaseListenerRunId),
            TunaPathLeaseGeneration: snapshot.TunaPathLeaseGeneration,
            TunaPathLeaseState: snapshot.TunaPathLeaseState.ToString(),
            TunaPathLeaseListenerRunId: snapshot.TunaPathLeaseListenerRunId,
            TunaPathLeaseCurrent: snapshot.TunaPathLeaseCurrent,
            TunaPathLeaseFailureReason: snapshot.TunaPathLeaseFailureReason,
            LaunchGeneration: launchGeneration);

    private static bool IsRuntimeUnlockResponderWaitingForPeerProbe(RuntimeUnlockTransactionSnapshot snapshot)
        => !snapshot.IsTerminal &&
           snapshot.HasPeerVisibleProof &&
           snapshot.AnswerReceived &&
           !snapshot.RouteCommitted &&
           snapshot.PathProbeState == RuntimeUnlockPathProbeState.None &&
           !string.IsNullOrWhiteSpace(snapshot.TunaPathLeaseListenerRunId) &&
           snapshot.TunaPathLeaseListenerRunId.StartsWith("peer-offer-dialer-", StringComparison.OrdinalIgnoreCase);

    private void ScheduleRuntimeUnlockPreCommitProbeStartTimeout(
        string sessionId,
        string? transferId,
        long transactionGeneration,
        long offerGeneration,
        long launchGeneration)
        => _ = Task.Run(async () =>
        {
            try
            {
                await Task.Delay(ResolveRuntimeUnlockPreCommitProbeStartTimeout(), CancellationToken.None)
                    .ConfigureAwait(false);
            }
            catch (OperationCanceledException)
            {
                return;
            }

            FailRuntimeUnlockPreCommitProbeLaunchIfMissing(
                sessionId,
                transferId,
                transactionGeneration,
                offerGeneration,
                launchGeneration);
        });

    private void ClearRuntimeUnlockPreCommitProbeLaunchIfCurrent(
        string sessionId,
        string transferId,
        long transactionGeneration,
        long offerGeneration,
        long tunaPathLeaseGeneration,
        string? tunaPathLeaseListenerRunId,
        string probeId,
        FileTransferTransportKind targetTransport,
        string reason)
    {
        RuntimeUnlockRouteCommitSnapshot? startedSnapshot = null;
        lock (accelerationGate)
        {
            if (string.Equals(runtimeUnlockPreCommitProbeLaunchSessionId, sessionId, StringComparison.Ordinal) &&
                string.Equals(runtimeUnlockPreCommitProbeLaunchTransferId, transferId, StringComparison.Ordinal) &&
                runtimeUnlockPreCommitProbeLaunchTransactionGeneration == transactionGeneration &&
                runtimeUnlockPreCommitProbeLaunchOfferGeneration == offerGeneration &&
                runtimeUnlockPreCommitProbeLaunchSnapshot is { LaunchGeneration: > 0 } currentSnapshot &&
                currentSnapshot.LaunchGeneration == runtimeUnlockPreCommitProbeLaunchGeneration &&
                currentSnapshot.TunaPathLeaseGeneration == tunaPathLeaseGeneration &&
                string.Equals(
                    currentSnapshot.TunaPathLeaseListenerRunId,
                    tunaPathLeaseListenerRunId,
                    StringComparison.Ordinal))
            {
                startedSnapshot = currentSnapshot with
                {
                    PathProbeId = probeId,
                    PathProbeState = RuntimeUnlockPathProbeState.Started.ToString(),
                    PathProbeTransport = targetTransport,
                };
                runtimeUnlockPreCommitProbeStartedSnapshot = startedSnapshot;
                runtimeUnlockPreCommitProbeLaunchSessionId = null;
                runtimeUnlockPreCommitProbeLaunchTransferId = null;
                runtimeUnlockPreCommitProbeLaunchTransactionGeneration = 0;
                runtimeUnlockPreCommitProbeLaunchOfferGeneration = 0;
                runtimeUnlockPreCommitProbeLaunchSnapshot = null;
                runtimeUnlockPreCommitProbeLaunchGeneration++;
                runtimeUnlockPreCommitProbeLaunchTimeoutScheduled = false;
                ClearRuntimeUnlockPreCommitProbeLaunchHoldUnsafe();
            }
        }

        if (startedSnapshot is { } launch)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_precommit_probe_launch_started; session_id={SanitizeLogToken(sessionId)}; transfer_id={SanitizeLogToken(launch.TransferId ?? "none")}; transaction_generation={transactionGeneration}; offer_generation={offerGeneration}; launch_generation={launch.LaunchGeneration}; tuna_path_lease_generation={launch.TunaPathLeaseGeneration}; tuna_path_lease_listener_run_id={SanitizeLogToken(launch.TunaPathLeaseListenerRunId ?? "none")}; path_probe_id={SanitizeLogToken(launch.PathProbeId ?? "none")}; target_transport={FormatFileTransferTransportKindForLog(launch.PathProbeTransport)}; reason={SanitizeLogToken(reason)}");
        }
    }

    private void FailRuntimeUnlockPreCommitProbeLaunchIfMissing(
        string sessionId,
        string? transferId,
        long transactionGeneration,
        long offerGeneration,
        long launchGeneration)
    {
        if (!HasActiveFileTransferDataSessionForTransfer(sessionId, transferId))
        {
            RuntimeUnlockTransactionSnapshot snapshot;
            lock (accelerationGate)
            {
                var current = runtimeUnlockTransactionState;
                if (!string.Equals(runtimeUnlockPreCommitProbeLaunchSessionId, sessionId, StringComparison.Ordinal) ||
                    !string.Equals(runtimeUnlockPreCommitProbeLaunchTransferId, transferId, StringComparison.Ordinal) ||
                    runtimeUnlockPreCommitProbeLaunchTransactionGeneration != transactionGeneration ||
                    runtimeUnlockPreCommitProbeLaunchOfferGeneration != offerGeneration ||
                    runtimeUnlockPreCommitProbeLaunchGeneration != launchGeneration ||
                    current.IsTerminal ||
                    current.TransactionGeneration != transactionGeneration ||
                    current.OfferGeneration != offerGeneration ||
                    !string.Equals(current.SessionId, sessionId, StringComparison.Ordinal) ||
                    !RuntimeUnlockTransactionTransferMatches(current.TransferId, transferId) ||
                    current.PathProbeState != RuntimeUnlockPathProbeState.None ||
                    !current.HasPeerVisibleProof ||
                    !current.AnswerReceived)
                {
                    return;
                }

                runtimeUnlockPreCommitProbeLaunchTimeoutScheduled = false;
                snapshot = current;
            }

            LogRuntimeUnlockPreCommitProbeLaunchWaitingForDataSession(
                sessionId,
                transferId,
                transactionGeneration,
                offerGeneration,
                launchGeneration,
                snapshot.TunaPathLeaseGeneration,
                snapshot.TunaPathLeaseListenerRunId,
                "runtime_unlock_probe_start_timeout",
                "timeout_without_data_session");
            return;
        }

        RuntimeUnlockTransactionDecision? decision = null;
        RuntimeUnlockRouteCommitSnapshot? timeoutSnapshot = null;
        var heldByCoordinatorDenial = false;
        var heldReason = "unknown";
        var heldAdmissionReason = "unknown";
        lock (accelerationGate)
        {
            if (!string.Equals(runtimeUnlockPreCommitProbeLaunchSessionId, sessionId, StringComparison.Ordinal) ||
                !string.Equals(runtimeUnlockPreCommitProbeLaunchTransferId, transferId, StringComparison.Ordinal) ||
                runtimeUnlockPreCommitProbeLaunchTransactionGeneration != transactionGeneration ||
                runtimeUnlockPreCommitProbeLaunchOfferGeneration != offerGeneration ||
                runtimeUnlockPreCommitProbeLaunchGeneration != launchGeneration)
            {
                return;
            }

            var current = runtimeUnlockTransactionState;
            timeoutSnapshot = runtimeUnlockPreCommitProbeLaunchSnapshot;
            if (runtimeUnlockPreCommitProbeLaunchHeldByCoordinatorDenial)
            {
                runtimeUnlockPreCommitProbeLaunchTimeoutScheduled = false;
                heldByCoordinatorDenial = true;
                heldReason = runtimeUnlockPreCommitProbeLaunchHeldReason ?? "coordinator_denial";
                heldAdmissionReason = runtimeUnlockPreCommitProbeLaunchHeldAdmissionReason ?? "unknown";
            }
            else if (current.IsTerminal ||
                current.TransactionGeneration != transactionGeneration ||
                current.OfferGeneration != offerGeneration ||
                !string.Equals(current.SessionId, sessionId, StringComparison.Ordinal) ||
                !RuntimeUnlockTransactionTransferMatches(current.TransferId, transferId) ||
                current.PathProbeState != RuntimeUnlockPathProbeState.None ||
                !current.HasPeerVisibleProof ||
                !current.AnswerReceived)
            {
                runtimeUnlockPreCommitProbeLaunchSessionId = null;
                runtimeUnlockPreCommitProbeLaunchTransferId = null;
                runtimeUnlockPreCommitProbeLaunchTransactionGeneration = 0;
                runtimeUnlockPreCommitProbeLaunchOfferGeneration = 0;
                runtimeUnlockPreCommitProbeLaunchSnapshot = null;
                runtimeUnlockPreCommitProbeLaunchGeneration++;
                runtimeUnlockPreCommitProbeLaunchTimeoutScheduled = false;
                ClearRuntimeUnlockPreCommitProbeLaunchHoldUnsafe();
                return;
            }
            else
            {
                runtimeUnlockPreCommitProbeLaunchSessionId = null;
                runtimeUnlockPreCommitProbeLaunchTransferId = null;
                runtimeUnlockPreCommitProbeLaunchTransactionGeneration = 0;
                runtimeUnlockPreCommitProbeLaunchOfferGeneration = 0;
                runtimeUnlockPreCommitProbeLaunchSnapshot = null;
                runtimeUnlockPreCommitProbeLaunchGeneration++;
                runtimeUnlockPreCommitProbeLaunchTimeoutScheduled = false;
                ClearRuntimeUnlockPreCommitProbeLaunchHoldUnsafe();
                decision = ApplyRuntimeUnlockTransactionUnsafe(
                    RuntimeUnlockTransactionEventKind.Failed,
                    sessionId,
                    offerGeneration,
                    "runtime_unlock_probe_start_timeout",
                    transactionGeneration: transactionGeneration);
            }
        }

        if (heldByCoordinatorDenial)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_precommit_probe_start_timeout_suppressed_by_coordinator_denial; session_id={SanitizeLogToken(sessionId)}; transfer_id={SanitizeLogToken(transferId ?? "none")}; transaction_generation={transactionGeneration}; offer_generation={offerGeneration}; launch_generation={launchGeneration}; tuna_path_lease_generation={timeoutSnapshot?.TunaPathLeaseGeneration ?? 0}; tuna_path_lease_listener_run_id={SanitizeLogToken(timeoutSnapshot?.TunaPathLeaseListenerRunId ?? "none")}; reason={SanitizeLogToken(heldReason)}; admission_reason={SanitizeLogToken(heldAdmissionReason)}");
            return;
        }

        if (decision is null)
        {
            return;
        }

        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=runtime_unlock_precommit_probe_start_timeout; session_id={SanitizeLogToken(sessionId)}; transfer_id={SanitizeLogToken(transferId ?? "none")}; transaction_generation={transactionGeneration}; offer_generation={offerGeneration}; launch_generation={launchGeneration}; tuna_path_lease_generation={timeoutSnapshot?.TunaPathLeaseGeneration ?? 0}; tuna_path_lease_listener_run_id={SanitizeLogToken(timeoutSnapshot?.TunaPathLeaseListenerRunId ?? "none")}; path_probe_id={SanitizeLogToken(timeoutSnapshot?.PathProbeId ?? "none")}; reason=runtime_unlock_probe_start_timeout");
        LogRuntimeUnlockTransactionDecision(RuntimeUnlockTransactionEventKind.Failed, decision);
        ResumeFileTransferDataSessionsAfterTunaActivationFailure(
            "runtime_unlock_probe_start_timeout",
            sessionId,
            "precommit_probe_launch_timeout",
            forceWhenNotPaused: true);
        NotifyTransportAccelerationStateChanged("runtime_unlock_probe_start_timeout");
    }

    private static void LogRuntimeUnlockPreCommitProbeLaunchWaitingForDataSession(
        string sessionId,
        string? transferId,
        long transactionGeneration,
        long offerGeneration,
        long launchGeneration,
        long tunaPathLeaseGeneration,
        string? tunaPathLeaseListenerRunId,
        string reason,
        string waitReason)
        => LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_precommit_probe_launch_waiting_for_data_session; session_id={SanitizeLogToken(sessionId)}; transfer_id={SanitizeLogToken(transferId ?? "none")}; transaction_generation={transactionGeneration}; offer_generation={offerGeneration}; launch_generation={launchGeneration}; tuna_path_lease_generation={tunaPathLeaseGeneration}; tuna_path_lease_listener_run_id={SanitizeLogToken(tunaPathLeaseListenerRunId ?? "none")}; reason={SanitizeLogToken(reason)}; wait_reason={SanitizeLogToken(waitReason)}");

    private bool TryCaptureUncommittedRuntimeUnlockHandoffBlocker(
        string? sessionId,
        out RuntimeUnlockTransactionSnapshot snapshot)
    {
        snapshot = default!;
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        lock (accelerationGate)
        {
            var state = runtimeUnlockTransactionState;
            if (state.TransactionGeneration <= 0 ||
                state.State == RuntimeUnlockTransactionState.Idle ||
                !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
                HasRuntimeUnlockPublishedRouteCommitUnsafe(normalizedSessionId))
            {
                return false;
            }

            snapshot = state;
            return true;
        }
    }

    private void SupersedePostTunaFileFallbackRouteForFileTunaActivation(string sessionId, string reason)
    {
        TunaFallbackProofState? snapshot = null;
        TunaFallbackLaneState previousFileState = TunaFallbackLaneState.None;
        V6TransportEpochState? previousFileV6EpochState = null;
        long previousFileV6TransportEpoch = 0;

        lock (accelerationGate)
        {
            if (tunaFallbackProofState is { } state &&
                string.Equals(state.SessionId, sessionId, StringComparison.Ordinal) &&
                (state.Lanes & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File &&
                state.FileState != TunaFallbackLaneState.None)
            {
                snapshot = state;
                previousFileState = state.FileState;
                previousFileV6EpochState = state.FileV6EpochState;
                previousFileV6TransportEpoch = state.FileV6TransportEpoch;
            }
        }

        if (snapshot is not null)
        {
            var previousFileV6EpochStateToken = previousFileV6EpochState is { } epochState
                ? FormatFileTransferV6TransportEpochStateForLog(epochState)
                : "none";
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_post_tuna_fallback_v6_route_superseded; session_id={SanitizeLogToken(sessionId)}; fallback_epoch={snapshot.Epoch}; reason={SanitizeLogToken(reason)}; previous_file_state={FormatTunaFallbackLaneState(previousFileState)}; previous_file_v6_epoch_state={SanitizeLogToken(previousFileV6EpochStateToken)}; previous_file_v6_transport_epoch={previousFileV6TransportEpoch}; next_file_route=file_tuna_v4");
        }

        CompleteTunaFallbackProof("tuna_activation_started");
    }

    private bool PauseFileTransferDataSessionsForTunaActivationNegotiation(
        string reason,
        string? sessionId,
        string trigger)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (IsAccelerationNegotiatedAndHealthyUnsafe(normalizedSessionId))
            {
                return false;
            }

            if (string.Equals(fileTransferTunaActivationPauseSessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return false;
            }

            if (pendingRegularV4ToTunaRouteTransitionAvailabilityDisposition is
                    { } pendingDisposition &&
                string.Equals(
                    pendingDisposition.Authority.SessionId,
                    normalizedSessionId,
                    StringComparison.Ordinal))
            {
                return false;
            }
        }

        if (ShouldKeepPostTunaFallbackDataSessionsAvailableDuringTunaActivation(
                normalizedSessionId,
                out var suppressReason))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_tuna_activation_negotiation_post_tuna_fallback_pause_suppressed; session_id={SanitizeLogToken(normalizedSessionId)}; reason={SanitizeLogToken(reason)}; trigger={SanitizeLogToken(trigger)}; suppress_reason={SanitizeLogToken(suppressReason)}");
            return false;
        }

        long generation;
        lock (accelerationGate)
        {
            if (IsAccelerationNegotiatedAndHealthyUnsafe(normalizedSessionId))
            {
                return false;
            }

            if (string.Equals(fileTransferTunaActivationPauseSessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return false;
            }

            if (pendingRegularV4ToTunaRouteTransitionAvailabilityDisposition is
                    { } pendingDisposition &&
                string.Equals(
                    pendingDisposition.Authority.SessionId,
                    normalizedSessionId,
                    StringComparison.Ordinal))
            {
                return false;
            }

            fileTransferTunaActivationPauseSessionId = normalizedSessionId;
            generation = ++fileTransferTunaActivationPauseGeneration;
        }

        var normalizedReason = SanitizeLogToken(reason);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_tuna_activation_negotiation_regular_nkn_paused; session_id={SanitizeLogToken(normalizedSessionId)}; reason={normalizedReason}; trigger={SanitizeLogToken(trigger)}; max_pause_ms={(long)FileTransferTunaActivationPauseMax.TotalMilliseconds}");
        SetFileTransferDataSessionsAvailability(
            isAvailable: false,
            reason: "tuna_activation_negotiating",
            requiresResumeRequest: false,
            handoffKind: FileTransferTransportHandoffKind.None,
            targetTransport: FileTransferTransportKind.RegularNkn);
        ScheduleFileTransferTunaActivationPauseExpiryObservation(normalizedSessionId, generation);
        return true;
    }

    private bool ShouldKeepPostTunaFallbackDataSessionsAvailableDuringTunaActivation(
        string sessionId,
        out string reason)
    {
        if (TryGetPostTunaFallbackRuntimeUnlockAdmissionDeniedRouteHint(sessionId, out reason))
        {
            return true;
        }

        if (HasPostTunaFallbackYieldAdmissionRouteHint(sessionId, transferId: null))
        {
            reason = "post_tuna_fallback_tail_quiescent";
            return false;
        }

        reason = "none";
        return false;
    }

    private bool TryGetPostTunaFallbackRuntimeUnlockAdmissionDeniedRouteHint(
        string? sessionId,
        out string denialReason,
        string? transferId = null,
        FileTransferDirection? direction = null)
    {
        denialReason = "none";
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        var normalizedTransferId = string.IsNullOrWhiteSpace(transferId)
            ? null
            : transferId.Trim();
        lock (gate)
        {
            FileTransferRouteHint? newestGrant = null;
            FileTransferRouteHint? newestDenied = null;
            string? newestGrantTransferId = null;
            string? newestDeniedTransferId = null;
            var activeTransferIds = fileTransferDataSessions.Values
                .Where(session =>
                    !session.IsDisposed &&
                    string.Equals(session.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                    (normalizedTransferId is null ||
                     string.Equals(session.TransferId, normalizedTransferId, StringComparison.Ordinal)))
                .Select(session => session.TransferId)
                .ToHashSet(StringComparer.Ordinal);
            foreach (var pair in fileTransferRouteHints)
            {
                if (!string.Equals(pair.Key.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
                    !activeTransferIds.Contains(pair.Key.TransferId) ||
                    (direction.HasValue &&
                     pair.Key.Direction != direction.Value))
                {
                    continue;
                }

                var routeHint = pair.Value;
                if (routeHint.Route != FileTransferRoute.PostTunaFallbackV6 ||
                    routeHint.ProtocolVersion != FileTransferProtocol.ProtocolVersionV6)
                {
                    continue;
                }

                if (IsPostTunaFallbackYieldAdmissionRouteHint(routeHint))
                {
                    if (newestGrant is not { } currentGrant ||
                        IsNewerPostTunaFallbackRouteHint(routeHint, currentGrant))
                    {
                        newestGrant = routeHint;
                        newestGrantTransferId = pair.Key.TransferId;
                    }

                    continue;
                }

                if (!routeHint.RuntimeUnlockAdmissionGranted &&
                    IsRuntimeUnlockAdmissionDeniedRouteHintReason(routeHint.RuntimeUnlockAdmissionReason) &&
                    (newestDenied is not { } currentDenied ||
                     IsNewerPostTunaFallbackRouteHint(routeHint, currentDenied)))
                {
                    newestDenied = routeHint;
                    newestDeniedTransferId = pair.Key.TransferId;
                }
            }

            if (newestDenied is not { } denied)
            {
                return false;
            }

            if (newestGrant is { } grant &&
                string.Equals(grant.SessionId, denied.SessionId, StringComparison.Ordinal) &&
                string.Equals(newestGrantTransferId, newestDeniedTransferId, StringComparison.Ordinal) &&
                grant.Direction == denied.Direction &&
                grant.LiveRouteEpoch >= denied.LiveRouteEpoch &&
                grant.RoutePublicationGeneration >= denied.RoutePublicationGeneration &&
                grant.RuntimeGeneration >= denied.RuntimeGeneration &&
                grant.TerminalGeneration >= denied.TerminalGeneration &&
                grant.PublicationLegGeneration >= denied.PublicationLegGeneration)
            {
                return false;
            }

            denialReason = denied.RuntimeUnlockAdmissionReason;
            return true;
        }
    }

    private static bool IsRuntimeUnlockAdmissionDeniedRouteHintReason(string? reason)
    {
        var normalized = SanitizeLogToken(reason);
        return !string.IsNullOrWhiteSpace(normalized) &&
               !string.Equals(normalized, "unknown", StringComparison.OrdinalIgnoreCase);
    }

    private void ResumeFileTransferDataSessionsAfterTunaActivationNegotiation(
        string reason,
        string? sessionId,
        string trigger)
        => _ = TryResumeFileTransferDataSessionsAfterTunaActivationNegotiation(reason, sessionId, trigger);

    private bool TryResumeFileTransferDataSessionsAfterTunaActivationNegotiation(
        string reason,
        string? sessionId,
        string trigger)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            return false;
        }

        var coordinatorTransitionBound = false;
        lock (accelerationGate)
        {
            var boundAuthority =
                GetRegularV4ToTunaActivationPauseAuthorityUnsafe();
            coordinatorTransitionBound = boundAuthority is { } authority &&
                                         string.Equals(
                                             authority.SessionId,
                                             normalizedSessionId,
                                             StringComparison.Ordinal);
            if (!coordinatorTransitionBound &&
                !string.Equals(fileTransferTunaActivationPauseSessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return false;
            }

            if (!coordinatorTransitionBound)
            {
                fileTransferTunaActivationPauseSessionId = null;
                fileTransferTunaActivationPauseGeneration++;
            }
        }

        if (coordinatorTransitionBound)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_regular_v4_to_tuna_route_transition_pause_release_rejected; session_id={SanitizeLogToken(normalizedSessionId)}; reason={SanitizeLogToken(reason)}; trigger={SanitizeLogToken(trigger)}; decision_reason=coordinator_transition_disposition_required");
            return false;
        }

        var normalizedReason = SanitizeLogToken(reason);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_tuna_activation_negotiation_regular_nkn_resumed; session_id={SanitizeLogToken(normalizedSessionId)}; reason={normalizedReason}; trigger={SanitizeLogToken(trigger)}");
        SetFileTransferDataSessionsAvailability(
            isAvailable: true,
            reason: normalizedReason,
            requiresResumeRequest: false,
            handoffKind: FileTransferTransportHandoffKind.None,
            targetTransport: FileTransferTransportKind.RegularNkn);
        return true;
    }

    private void ResumeFileTransferDataSessionsAfterTunaActivationFailure(
        string failureReason,
        string? sessionId,
        string trigger,
        bool forceWhenNotPaused = false)
    {
        var normalizedFailureReason = SanitizeLogToken(failureReason);
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : sessionId.Trim();
        if (IsRegularV4ToTunaActivationPauseBound(normalizedSessionId))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_regular_v4_to_tuna_route_transition_pause_release_rejected; session_id={SanitizeLogToken(normalizedSessionId ?? "none")}; reason={normalizedFailureReason}; trigger={SanitizeLogToken(trigger)}; decision_reason=coordinator_transition_invalidation_required");
            return;
        }

        if (!TryResumeFileTransferDataSessionsAfterTunaActivationNegotiation(
                "tuna_activation_failed_regular_v4_resumed",
                normalizedSessionId,
                normalizedFailureReason))
        {
            if (!forceWhenNotPaused || string.IsNullOrWhiteSpace(normalizedSessionId))
            {
                return;
            }

            SetFileTransferDataSessionsAvailability(
                isAvailable: true,
                reason: "tuna_activation_failed_regular_v4_resumed",
                requiresResumeRequest: false,
                handoffKind: FileTransferTransportHandoffKind.None,
                targetTransport: FileTransferTransportKind.RegularNkn);
        }

        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=tuna_activation_failed_regular_v4_resumed; session_id={SanitizeLogToken(normalizedSessionId ?? "none")}; failure_reason={normalizedFailureReason}; trigger={SanitizeLogToken(trigger)}; forced={(forceWhenNotPaused ? 1 : 0)}");
    }

    private bool ShouldSuppressFileTransferTransportRecoveredForTunaActivationPause(
        string trigger,
        out string? sessionId)
    {
        sessionId = currentSessionSecurityState.SessionId?.Value;
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        lock (accelerationGate)
        {
            var boundAuthority =
                GetRegularV4ToTunaActivationPauseAuthorityUnsafe();
            var coordinatorTransitionBound =
                boundAuthority is { } authority &&
                string.Equals(
                    authority.SessionId,
                    sessionId,
                    StringComparison.Ordinal);
            if (!coordinatorTransitionBound &&
                (!string.Equals(
                     fileTransferTunaActivationPauseSessionId,
                     sessionId,
                     StringComparison.Ordinal) ||
                 IsAccelerationNegotiatedAndHealthyUnsafe(sessionId)))
            {
                return false;
            }
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_tuna_activation_negotiation_transport_recovered_suppressed; session_id={SanitizeLogToken(sessionId)}; reason=tuna_activation_negotiating; trigger={SanitizeLogToken(trigger)}");
        return true;
    }

    private bool TryGetActiveFileTransferTunaActivationPauseForCurrentSession(out string? sessionId)
        => TryGetActiveFileTransferTunaActivationPause(
            currentSessionSecurityState.SessionId?.Value,
            out sessionId);

    private bool TryGetActiveFileTransferTunaActivationPause(
        string? requestedSessionId,
        out string? sessionId)
    {
        sessionId = string.IsNullOrWhiteSpace(requestedSessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : requestedSessionId.Trim();
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        lock (accelerationGate)
        {
            var boundAuthority =
                GetRegularV4ToTunaActivationPauseAuthorityUnsafe();
            return (boundAuthority is { } authority &&
                    string.Equals(
                        authority.SessionId,
                        sessionId,
                        StringComparison.Ordinal)) ||
                   (string.Equals(
                        fileTransferTunaActivationPauseSessionId,
                        sessionId,
                        StringComparison.Ordinal) &&
                    !IsAccelerationNegotiatedAndHealthyUnsafe(sessionId));
        }
    }

    private void MarkFileTransferTunaActivationBridgeRecoveryStarted(string reason)
    {
        lock (accelerationBridgeRecoveryGate)
        {
            fileTransferTunaActivationBridgeRecoveryStartedTick = Stopwatch.GetTimestamp();
            fileTransferTunaActivationBridgeRecoveryActive = 1;
            if (fileTransferTunaActivationBridgeRecoverySettledTcs is null ||
                fileTransferTunaActivationBridgeRecoverySettledTcs.Task.IsCompleted)
            {
                fileTransferTunaActivationBridgeRecoverySettledTcs =
                    new TaskCompletionSource<bool>(TaskCreationOptions.RunContinuationsAsynchronously);
            }
        }
    }

    private void MarkFileTransferTunaActivationBridgeRecoverySettled(string trigger)
    {
        TaskCompletionSource<bool>? settledTcs = null;
        long startedTick;
        lock (accelerationBridgeRecoveryGate)
        {
            if (fileTransferTunaActivationBridgeRecoveryActive == 0)
            {
                return;
            }

            fileTransferTunaActivationBridgeRecoveryActive = 0;
            fileTransferTunaActivationBridgeRecoverySettledTick = Stopwatch.GetTimestamp();
            startedTick = fileTransferTunaActivationBridgeRecoveryStartedTick;
            settledTcs = fileTransferTunaActivationBridgeRecoverySettledTcs;
        }

        settledTcs?.TrySetResult(true);
        ScheduleRuntimeUnlockRetryAfterRecoveryIfArmed(trigger);
    }

    private bool IsFileTransferTunaActivationBridgeRecoveryActive()
    {
        lock (accelerationBridgeRecoveryGate)
        {
            return fileTransferTunaActivationBridgeRecoveryActive != 0;
        }
    }

    private async Task<bool> WaitForFileTransferTunaActivationBridgeRecoveryBeforeControlSendAsync(
        string purpose,
        string? activationSessionId,
        CancellationToken ct)
    {
        if (!IsTunaActivationOfferSendPurpose(purpose) ||
            !TryGetFileTransferTunaActivationBridgeRecoveryWaitSession(purpose, activationSessionId, out var sessionId))
        {
            return true;
        }

        var waitBudget = GetFileTransferTunaActivationBridgeRecoveryControlSendWaitBudget(
            purpose,
            activationSessionId,
            FileTransferTunaActivationBridgeRecoveryWaitOverrideForTests ??
            FileTransferTunaActivationBridgeRecoveryWait);
        var waitStartedTick = Stopwatch.GetTimestamp();
        var loggedWait = false;
        var loggedRegularV4PressureBypass = false;
        var loggedRegularV4ReceiveStallWait = false;
        string? lastBlockerReason = null;
        long lastBlockerRemainingMs = 0;
        long bridgeRecoveryStartedTick = 0;

        while (true)
        {
            ct.ThrowIfCancellationRequested();

            Task? waitTask = null;
            var bridgeRecoveryActive = false;
            lock (accelerationBridgeRecoveryGate)
            {
                if (fileTransferTunaActivationBridgeRecoveryActive != 0 &&
                    fileTransferTunaActivationBridgeRecoverySettledTcs is not null)
                {
                    bridgeRecoveryActive = true;
                    waitTask = fileTransferTunaActivationBridgeRecoverySettledTcs.Task;
                    bridgeRecoveryStartedTick = fileTransferTunaActivationBridgeRecoveryStartedTick;
                }
            }

            var regularV4BlockerReason = string.Empty;
            var regularV4BlockerTimingMs = 0L;
            var realClient = client as RealNknClientAdapter;
            var hasRegularV4SendBlocker =
                realClient is not null &&
                realClient.TryGetFileTransferRegularV4ActivationSendBlocker(
                    out regularV4BlockerReason,
                    out regularV4BlockerTimingMs);
            if (hasRegularV4SendBlocker &&
                realClient is not null &&
                IsCurrentRuntimeUnlockActivationOffer() &&
                !TryGetActiveFileTransferTunaActivationPause(sessionId, out _) &&
                realClient.TryGetFileTransferRegularV4ActivationSendBlocker(
                    out var nonPressureBlockerReason,
                    out var nonPressureBlockerRemainingMs,
                    includeRegularV4Pressure: false))
            {
                regularV4BlockerReason = nonPressureBlockerReason;
                regularV4BlockerTimingMs = nonPressureBlockerRemainingMs;
                if (!loggedRegularV4ReceiveStallWait)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_activation_control_send_waiting_for_regular_v4_recovery; session_id={SanitizeLogToken(sessionId ?? "none")}; purpose={SanitizeLogToken(purpose)}; blocker_reason={SanitizeLogToken(nonPressureBlockerReason)}; blocker_remaining_ms={nonPressureBlockerRemainingMs}; recovery_age_ms={FormatElapsedMilliseconds(bridgeRecoveryStartedTick)}; wait_budget_ms={(long)waitBudget.TotalMilliseconds}; reason=runtime_unlock_regular_v4_receive_stall");
                    loggedRegularV4ReceiveStallWait = true;
                }
            }

            if (hasRegularV4SendBlocker &&
                TryGetActiveFileTransferTunaActivationPause(sessionId, out _) &&
                IsRegularV4PressureActivationSendBlocker(regularV4BlockerReason))
            {
                if (!loggedRegularV4PressureBypass)
                {
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=tuna_activation_control_send_regular_v4_pressure_bypassed; session_id={SanitizeLogToken(sessionId ?? "none")}; purpose={SanitizeLogToken(purpose)}; blocker_reason={SanitizeLogToken(regularV4BlockerReason)}; blocker_evidence_age_ms={regularV4BlockerTimingMs}; reason=activation_pause_active");
                    loggedRegularV4PressureBypass = true;
                }

                hasRegularV4SendBlocker = false;
                regularV4BlockerReason = string.Empty;
                regularV4BlockerTimingMs = 0;
            }

            if (hasRegularV4SendBlocker &&
                ShouldBypassRegularV4ReceiveStallForRuntimeUnlockAuthorityProbe(
                    regularV4BlockerReason,
                    sessionId))
            {
                return true;
            }

            if (hasRegularV4SendBlocker &&
                ShouldBypassPostTunaFallbackReceiveStallForRuntimeUnlockAuthorityProbe(
                    regularV4BlockerReason,
                    sessionId,
                    regularV4BlockerTimingMs,
                    allowStaleInProgressAuthorityProbe: false))
            {
                return true;
            }

            if (hasRegularV4SendBlocker)
            {
                lastBlockerReason = regularV4BlockerReason;
                lastBlockerRemainingMs = regularV4BlockerTimingMs;
            }
            else if (bridgeRecoveryActive)
            {
                lastBlockerReason = "bridge_recovery_active";
                lastBlockerRemainingMs = 0;
            }

            if (!bridgeRecoveryActive && !hasRegularV4SendBlocker)
            {
                if (loggedWait)
                {
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=tuna_activation_control_send_bridge_recovery_settled; session_id={SanitizeLogToken(sessionId ?? "none")}; purpose={SanitizeLogToken(purpose)}; recovery_age_ms={FormatElapsedMilliseconds(bridgeRecoveryStartedTick)}; blocker_reason={SanitizeLogToken(lastBlockerReason ?? "cleared")}");
                }

                return true;
            }

            if (!loggedWait)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=tuna_activation_control_send_waiting_for_bridge_recovery; session_id={SanitizeLogToken(sessionId ?? "none")}; purpose={SanitizeLogToken(purpose)}; recovery_age_ms={FormatElapsedMilliseconds(bridgeRecoveryStartedTick)}; wait_budget_ms={(long)waitBudget.TotalMilliseconds}; blocker_reason={SanitizeLogToken(lastBlockerReason ?? "unknown")}; blocker_remaining_ms={lastBlockerRemainingMs}");
                loggedWait = true;
            }

            var elapsed = Stopwatch.GetElapsedTime(waitStartedTick);
            var remaining = waitBudget - elapsed;
            if (remaining <= TimeSpan.Zero)
            {
                if (ShouldBypassRegularV4PressureForRuntimeUnlockOffer(lastBlockerReason))
                {
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=tuna_activation_control_send_regular_v4_pressure_bypassed; session_id={SanitizeLogToken(sessionId ?? "none")}; purpose={SanitizeLogToken(purpose)}; blocker_reason={SanitizeLogToken(lastBlockerReason ?? "unknown")}; blocker_remaining_ms={lastBlockerRemainingMs}; recovery_age_ms={FormatElapsedMilliseconds(bridgeRecoveryStartedTick)}; wait_budget_ms={(long)waitBudget.TotalMilliseconds}; reason=runtime_unlock_offer_pressure_wait_elapsed");
                    return true;
                }

                if (ShouldBypassRegularV4ReceiveStallForRuntimeUnlockObservedOfferReplay(
                        lastBlockerReason,
                        sessionId,
                        purpose))
                {
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=tuna_activation_control_send_regular_v4_receive_stall_observed_replay_bypassed; session_id={SanitizeLogToken(sessionId ?? "none")}; purpose={SanitizeLogToken(purpose)}; blocker_reason={SanitizeLogToken(lastBlockerReason ?? "unknown")}; blocker_remaining_ms={lastBlockerRemainingMs}; recovery_age_ms={FormatElapsedMilliseconds(bridgeRecoveryStartedTick)}; wait_budget_ms={(long)waitBudget.TotalMilliseconds}; reason=runtime_unlock_observed_offer_replay_window");
                    return true;
                }

                if (ShouldBypassPostTunaFallbackReceiveStallForRuntimeUnlockObservedOfferReplay(
                        lastBlockerReason,
                        sessionId,
                        purpose,
                        lastBlockerRemainingMs))
                {
                    return true;
                }

                if (ShouldBypassRegularV4ReceiveStallForRuntimeUnlockOffer(
                        lastBlockerReason,
                        sessionId,
                        lastBlockerRemainingMs,
                        allowStaleInProgressAuthorityProbe: true))
                {
                    TryGrantRuntimeUnlockRecoveryContractRetryAuthorityForReceiveStallBypass(
                        sessionId,
                        purpose,
                        lastBlockerReason);
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=tuna_activation_control_send_regular_v4_receive_stall_bypassed; session_id={SanitizeLogToken(sessionId ?? "none")}; purpose={SanitizeLogToken(purpose)}; blocker_reason={SanitizeLogToken(lastBlockerReason ?? "unknown")}; blocker_remaining_ms={lastBlockerRemainingMs}; recovery_age_ms={FormatElapsedMilliseconds(bridgeRecoveryStartedTick)}; wait_budget_ms={(long)waitBudget.TotalMilliseconds}; reason=runtime_unlock_offer_receive_stall_wait_elapsed");
                    return true;
                }

                if (ShouldBypassPostTunaFallbackReceiveStallForRuntimeUnlockAuthorityProbe(
                        lastBlockerReason,
                        sessionId,
                        lastBlockerRemainingMs,
                        allowStaleInProgressAuthorityProbe: true))
                {
                    return true;
                }

                if (ShouldDeferPostTunaFallbackReceiveStallForRuntimeUnlockOffer(lastBlockerReason, sessionId))
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_activation_control_send_post_tuna_fallback_recovery_deferred; session_id={SanitizeLogToken(sessionId ?? "none")}; purpose={SanitizeLogToken(purpose)}; blocker_reason={SanitizeLogToken(lastBlockerReason ?? "unknown")}; blocker_remaining_ms={lastBlockerRemainingMs}; recovery_age_ms={FormatElapsedMilliseconds(bridgeRecoveryStartedTick)}; wait_budget_ms={(long)waitBudget.TotalMilliseconds}; reason=runtime_unlock_offer_waiting_for_post_tuna_fallback_receive_proof");
                    return false;
                }

                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_activation_control_send_deferred_for_regular_v4_recovery; session_id={SanitizeLogToken(sessionId ?? "none")}; purpose={SanitizeLogToken(purpose)}; blocker_reason={SanitizeLogToken(lastBlockerReason ?? "unknown")}; blocker_remaining_ms={lastBlockerRemainingMs}; recovery_age_ms={FormatElapsedMilliseconds(bridgeRecoveryStartedTick)}; wait_budget_ms={(long)waitBudget.TotalMilliseconds}");
                return false;
            }

            var pollDelay = TimeSpan.FromMilliseconds(Math.Min(250, Math.Max(1, remaining.TotalMilliseconds)));
            if (waitTask is not null)
            {
                var completed = await Task.WhenAny(waitTask, Task.Delay(pollDelay, ct)).ConfigureAwait(false);
                if (ReferenceEquals(completed, waitTask))
                {
                    continue;
                }
            }
            else
            {
                await Task.Delay(pollDelay, ct).ConfigureAwait(false);
            }
        }
    }

    private TimeSpan GetFileTransferTunaActivationBridgeRecoveryControlSendWaitBudget(
        string purpose,
        string? sessionId,
        TimeSpan baseBudget)
    {
        if (TryGetFileTransferTunaActivationBridgeRecoveryControlSendWaitExtension(
            purpose,
            sessionId,
            baseBudget,
            out var extendedBudget,
            out var blockerReason))
        {
            return extendedBudget;
        }

        return baseBudget;
    }

    private bool TryGetFileTransferTunaActivationBridgeRecoveryControlSendWaitExtension(
        string purpose,
        string? sessionId,
        TimeSpan baseBudget,
        out TimeSpan extendedBudget,
        out string blockerReason)
    {
        extendedBudget = baseBudget;
        blockerReason = "none";

        if (!IsTunaActivationOfferSendPurpose(purpose))
        {
            blockerReason = "not_activation_offer_send";
            return false;
        }

        if (string.IsNullOrWhiteSpace(sessionId))
        {
            blockerReason = "missing_session_id";
            return false;
        }

        var hasRuntimeUnlockOffer = IsCurrentRuntimeUnlockActivationOffer();
        if (!TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out var authorityState, sessionId) ||
            authorityState is null)
        {
            blockerReason = hasRuntimeUnlockOffer &&
                IsRuntimeUnlockRetryDispatchAuthorityHeldForSession(sessionId, out var heldReason)
                    ? heldReason
                    : hasRuntimeUnlockOffer
                        ? "missing_runtime_unlock_retry_authority"
                        : "not_current_runtime_unlock_offer";

            return false;
        }

        if (!HasRuntimeUnlockRetryDispatchWindow(authorityState))
        {
            blockerReason = "retry_not_dispatched";
            return false;
        }

        if (!authorityState.RetryAuthorityPending)
        {
            blockerReason = "retry_authority_not_pending";
            return false;
        }

        if (!string.Equals(authorityState.SessionId, sessionId.Trim(), StringComparison.Ordinal))
        {
            blockerReason = "authority_session_mismatch";
            return false;
        }

        if (!TryGetRegularV4StartedRecoveryAuthorityProbeRemaining(sessionId, out var remainingMs, out var startedAgeMs))
        {
            blockerReason = "regular_v4_started_recovery_probe_not_pending";
            return false;
        }

        var requiredBudget = TimeSpan.FromMilliseconds(Math.Max(0, remainingMs) + 1_000);
        if (requiredBudget <= baseBudget)
        {
            blockerReason = "base_budget_sufficient";
            return false;
        }

        extendedBudget = requiredBudget;
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_activation_control_send_wait_budget_extended_for_regular_v4_authority_probe; session_id={SanitizeLogToken(sessionId)}; purpose={SanitizeLogToken(purpose)}; base_wait_budget_ms={(long)baseBudget.TotalMilliseconds}; extended_wait_budget_ms={(long)requiredBudget.TotalMilliseconds}; recovery_started_age_ms={startedAgeMs}; probe_remaining_ms={remainingMs}; contract_generation={authorityState.ContractGeneration}; authority_attempt={authorityState.AuthorityAttempt}; reason=awaiting_bounded_authority_probe_window");
        return true;
    }

    private bool ShouldBypassRegularV4PressureForRuntimeUnlockOffer(string? blockerReason)
    {
        if (!IsRegularV4PressureActivationSendBlocker(blockerReason) ||
            !IsCurrentRuntimeUnlockActivationOffer())
        {
            return false;
        }

        if (client is not RealNknClientAdapter realClient)
        {
            return false;
        }

        return !realClient.TryGetFileTransferRegularV4ActivationSendBlocker(
            out _,
            out _,
            includeRegularV4Pressure: false);
    }

    private bool ShouldBypassRegularV4ReceiveStallForRuntimeUnlockAuthorityProbe(
        string? blockerReason,
        string? sessionId)
    {
        if (!IsReceiveStallActivationSendBlocker(blockerReason) ||
            !IsCurrentRuntimeUnlockActivationOffer() ||
            string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = SanitizeLogToken(sessionId);
        if (!HasActiveRegularV4FileTransferRouteHint(normalizedSessionId) ||
            HasActivePostTunaFallbackFileTransferRouteHint(normalizedSessionId) ||
            TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out _))
        {
            return false;
        }

        if (TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out var authorityState) &&
            HasRuntimeUnlockRetryDispatchWindow(authorityState))
        {
            var authority = authorityState!;
            if (IsReceiveStallRecoveryInProgressActivationSendBlocker(blockerReason) &&
                !authority.RegularV4ActivationWindowStarted)
            {
                return false;
            }

            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_activation_control_send_regular_v4_receive_stall_authority_probe_allowed; session_id={SanitizeLogToken(normalizedSessionId)}; blocker_reason={SanitizeLogToken(blockerReason ?? "unknown")}; liveness_state=authority_send_window; contract_generation={authority.ContractGeneration}; authority_attempt={authority.AuthorityAttempt}; regular_v4_activation_window={(authority.RegularV4ActivationWindowStarted ? 1 : 0)}; reason=bounded_authority_observed_send_probe");
            return true;
        }

        return false;
    }

    private bool ShouldBypassPostTunaFallbackReceiveStallForRuntimeUnlockAuthorityProbe(
        string? blockerReason,
        string? sessionId,
        long blockerRemainingMs,
        bool allowStaleInProgressAuthorityProbe)
    {
        if (!IsReceiveStallActivationSendBlocker(blockerReason) ||
            !IsCurrentRuntimeUnlockActivationOffer() ||
            string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = SanitizeLogToken(sessionId);
        if (!HasActivePostTunaFallbackFileTransferRouteHint(normalizedSessionId))
        {
            return false;
        }

        if (!TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out var authorityState) ||
            authorityState is not
            {
                RetryDispatching: true,
                RetryAuthorityGranted: true,
                RetryAuthorityPending: true
            })
        {
            return false;
        }

        if (!TryGetCurrentPostTunaFallbackObservedSendProbeProof(
                normalizedSessionId,
                out var proof,
                out var proofDirection,
                out var proofAgeMs))
        {
            if (IsCurrentPostTunaFallbackAuthorityBridgeRecoveryInProgress(
                    normalizedSessionId,
                    out var bridgeRecoveryReason))
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_activation_control_send_post_tuna_fallback_receive_stall_bypass_blocked; session_id={SanitizeLogToken(normalizedSessionId)}; blocker_reason={SanitizeLogToken(blockerReason ?? "unknown")}; blocker_remaining_ms={blockerRemainingMs}; contract_generation={authorityState.ContractGeneration}; authority_attempt={authorityState.AuthorityAttempt}; reason={SanitizeLogToken(bridgeRecoveryReason)}");
                return false;
            }

            if (IsRuntimeUnlockPostTunaFallbackFinalProbeAuthoritySnapshot(
                    authorityState,
                    out var finalProbeDeadlineRemainingMs) &&
                (!IsReceiveStallRecoveryInProgressActivationSendBlocker(blockerReason) ||
                 blockerRemainingMs <= 0 ||
                 allowStaleInProgressAuthorityProbe))
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_activation_control_send_post_tuna_fallback_receive_stall_authority_probe_allowed; session_id={SanitizeLogToken(normalizedSessionId)}; blocker_reason={SanitizeLogToken(blockerReason ?? "unknown")}; blocker_remaining_ms={blockerRemainingMs}; contract_generation={authorityState.ContractGeneration}; authority_attempt={authorityState.AuthorityAttempt}; liveness_deadline_remaining_ms={finalProbeDeadlineRemainingMs}; reason=bounded_final_observed_send_probe_without_fallback_proof");
                return true;
            }

            if (IsRuntimeUnlockPostTunaFallbackListenerRearmAuthoritySnapshot(
                    authorityState,
                    out var listenerRearmDeadlineRemainingMs) &&
                (!IsReceiveStallRecoveryInProgressActivationSendBlocker(blockerReason) ||
                 blockerRemainingMs <= 0 ||
                 allowStaleInProgressAuthorityProbe) &&
                RuntimeUnlockTunaPathLease.CanSatisfyRouteCommit(runtimeUnlockTunaPathLeaseState) &&
                string.Equals(runtimeUnlockTunaPathLeaseState.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_activation_control_send_post_tuna_fallback_receive_stall_authority_probe_allowed; session_id={SanitizeLogToken(normalizedSessionId)}; blocker_reason={SanitizeLogToken(blockerReason ?? "unknown")}; blocker_remaining_ms={blockerRemainingMs}; contract_generation={authorityState.ContractGeneration}; authority_attempt={authorityState.AuthorityAttempt}; liveness_deadline_remaining_ms={listenerRearmDeadlineRemainingMs}; tuna_path_lease_generation={runtimeUnlockTunaPathLeaseState.LeaseGeneration}; reason=listener_rearm_bounded_observed_send_probe_without_fallback_proof");
                return true;
            }

            if (TryGetCurrentPostTunaFallbackAuthorityProbeState(
                    normalizedSessionId,
                    out var authorityStable,
                    out var authorityReason) &&
                !authorityStable)
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_activation_control_send_post_tuna_fallback_receive_stall_bypass_blocked; session_id={SanitizeLogToken(normalizedSessionId)}; blocker_reason={SanitizeLogToken(blockerReason ?? "unknown")}; blocker_remaining_ms={blockerRemainingMs}; contract_generation={authorityState.ContractGeneration}; authority_attempt={authorityState.AuthorityAttempt}; reason={SanitizeLogToken(authorityReason)}");
                return false;
            }

            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_activation_control_send_post_tuna_fallback_receive_stall_bypass_blocked; session_id={SanitizeLogToken(normalizedSessionId)}; blocker_reason={SanitizeLogToken(blockerReason ?? "unknown")}; blocker_remaining_ms={blockerRemainingMs}; contract_generation={authorityState.ContractGeneration}; authority_attempt={authorityState.AuthorityAttempt}; reason=awaiting_current_fallback_receive_or_frontier_proof");
            return false;
        }

        if (IsReceiveStallRecoveryInProgressActivationSendBlocker(blockerReason) &&
            blockerRemainingMs > 0)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_activation_control_send_post_tuna_fallback_receive_stall_bypass_blocked; session_id={SanitizeLogToken(normalizedSessionId)}; blocker_reason={SanitizeLogToken(blockerReason ?? "unknown")}; blocker_remaining_ms={blockerRemainingMs}; contract_generation={authorityState.ContractGeneration}; authority_attempt={authorityState.AuthorityAttempt}; proof={SanitizeLogToken(proof)}; proof_direction={SanitizeLogToken(proofDirection)}; proof_age_ms={proofAgeMs}; reason=awaiting_bridge_recovery_settle");
            return false;
        }

        if (IsReceiveStallRecoveryInProgressActivationSendBlocker(blockerReason) &&
            !allowStaleInProgressAuthorityProbe)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_activation_control_send_post_tuna_fallback_receive_stall_authority_probe_allowed; session_id={SanitizeLogToken(normalizedSessionId)}; blocker_reason={SanitizeLogToken(blockerReason ?? "unknown")}; blocker_remaining_ms={blockerRemainingMs}; contract_generation={authorityState.ContractGeneration}; authority_attempt={authorityState.AuthorityAttempt}; proof={SanitizeLogToken(proof)}; proof_direction={SanitizeLogToken(proofDirection)}; proof_age_ms={proofAgeMs}; reason=current_fallback_proof_cleared_stale_recovery_gate");
            return true;
        }

        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=tuna_activation_control_send_post_tuna_fallback_receive_stall_authority_probe_allowed; session_id={SanitizeLogToken(normalizedSessionId)}; blocker_reason={SanitizeLogToken(blockerReason ?? "unknown")}; blocker_remaining_ms={blockerRemainingMs}; contract_generation={authorityState.ContractGeneration}; authority_attempt={authorityState.AuthorityAttempt}; proof={SanitizeLogToken(proof)}; proof_direction={SanitizeLogToken(proofDirection)}; proof_age_ms={proofAgeMs}; reason=bounded_authority_observed_send_probe_after_wait");
        return true;
    }

    private bool ShouldBypassRegularV4ReceiveStallForRuntimeUnlockOffer(string? blockerReason, string? sessionId)
        => ShouldBypassRegularV4ReceiveStallForRuntimeUnlockOffer(
            blockerReason,
            sessionId,
            blockerRemainingMs: 0,
            allowStaleInProgressAuthorityProbe: false);

    private bool ShouldBypassRegularV4ReceiveStallForRuntimeUnlockOffer(
        string? blockerReason,
        string? sessionId,
        long blockerRemainingMs,
        bool allowStaleInProgressAuthorityProbe)
    {
        if (!IsReceiveStallActivationSendBlocker(blockerReason) ||
            !IsCurrentRuntimeUnlockActivationOffer() ||
            string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = SanitizeLogToken(sessionId);
        if (!HasActiveRegularV4FileTransferRouteHint(normalizedSessionId) ||
            HasActivePostTunaFallbackFileTransferRouteHint(normalizedSessionId) ||
            TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out _))
        {
            return false;
        }

        var hasAuthority = TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out var authorityState) &&
                           HasRuntimeUnlockRetryDispatchWindow(authorityState);
        var hasLivenessStatus = TryGetActiveRegularV4RecoveryLivenessStatus(
            normalizedSessionId,
            out var receiveProofObserved,
            out var terminal,
            out var deadlineExpired,
            out var stateReason,
            out var deadlineRemainingMs);

        if (IsReceiveStallRecoveryInProgressActivationSendBlocker(blockerReason))
        {
            if (hasLivenessStatus && receiveProofObserved && !terminal && !deadlineExpired)
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_activation_control_send_regular_v4_receive_stall_authority_probe_allowed; session_id={SanitizeLogToken(normalizedSessionId)}; blocker_reason={SanitizeLogToken(blockerReason ?? "unknown")}; blocker_remaining_ms={blockerRemainingMs}; allow_stale_in_progress_authority_probe={(allowStaleInProgressAuthorityProbe ? 1 : 0)}; liveness_state={SanitizeLogToken(stateReason)}; liveness_deadline_remaining_ms={deadlineRemainingMs}; contract_generation={(authorityState?.ContractGeneration ?? 0)}; authority_attempt={(authorityState?.AuthorityAttempt ?? 0)}; reason=validated_regular_v4_receive_proof_cleared_stale_recovery_gate");
                return true;
            }

            if (hasAuthority)
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_activation_control_send_regular_v4_receive_stall_bypass_blocked; session_id={SanitizeLogToken(normalizedSessionId)}; blocker_reason={SanitizeLogToken(blockerReason ?? "unknown")}; blocker_remaining_ms={blockerRemainingMs}; allow_stale_in_progress_authority_probe={(allowStaleInProgressAuthorityProbe ? 1 : 0)}; liveness_state={(hasLivenessStatus ? SanitizeLogToken(stateReason) : "bridge_recovery_in_progress")}; liveness_deadline_remaining_ms={(hasLivenessStatus ? deadlineRemainingMs : 0)}; contract_generation={authorityState!.ContractGeneration}; authority_attempt={authorityState.AuthorityAttempt}; reason=awaiting_bridge_recovery_settle_before_authority_probe");
                return false;
            }

            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_activation_control_send_regular_v4_receive_stall_bypass_blocked; session_id={SanitizeLogToken(normalizedSessionId)}; blocker_reason={SanitizeLogToken(blockerReason ?? "unknown")}; liveness_state={(hasLivenessStatus ? SanitizeLogToken(stateReason) : "bridge_recovery_in_progress")}; reason=awaiting_bridge_recovery_settle");
            return false;
        }

        if (!hasLivenessStatus)
        {
            return true;
        }

        if (receiveProofObserved)
        {
            return true;
        }

        if (!deadlineExpired &&
            deadlineRemainingMs <= (long)RuntimeUnlockRegularV4FinalObservedSendProbeWindow.TotalMilliseconds)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_activation_control_send_regular_v4_receive_stall_final_probe_allowed; session_id={SanitizeLogToken(normalizedSessionId)}; blocker_reason={SanitizeLogToken(blockerReason ?? "unknown")}; liveness_state={SanitizeLogToken(stateReason)}; liveness_deadline_remaining_ms={deadlineRemainingMs}; reason=bounded_final_observed_send_probe");
            return true;
        }

        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=tuna_activation_control_send_regular_v4_receive_stall_bypass_blocked; session_id={SanitizeLogToken(normalizedSessionId)}; blocker_reason={SanitizeLogToken(blockerReason ?? "unknown")}; liveness_state={SanitizeLogToken(stateReason)}; reason=awaiting_validated_filetransfer_receive_proof");
        return false;
    }

    private bool TryGetRegularV4StartedRecoveryAuthorityProbeReady(
        string sessionId,
        out long startedAgeMs)
    {
        startedAgeMs = -1;
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = SanitizeLogToken(sessionId);
        var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        lock (fileTransferFallbackProofGate)
        {
            var state = fileTransferRegularV4RecoveryLivenessState;
            if (state is null ||
                !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
                !string.Equals(state.RouteToken, FileTransferRouteResolver.RegularNknV4FastToken, StringComparison.Ordinal) ||
                state.ProtocolVersion != FileTransferProtocol.ProtocolVersionV4 ||
                !IsRegularV4BridgeRecoveryStartedRuntimeUnlockProbeReadyUnsafe(state, nowMs))
            {
                return false;
            }

            startedAgeMs = Math.Max(0, nowMs - state.BridgeRecoveryStartedUtcMs);
            return true;
        }
    }

    private bool TryGetRegularV4StartedRecoveryAuthorityProbeRemaining(
        string sessionId,
        out long remainingMs,
        out long startedAgeMs)
    {
        remainingMs = -1;
        startedAgeMs = -1;
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = SanitizeLogToken(sessionId);
        var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        lock (fileTransferFallbackProofGate)
        {
            var state = fileTransferRegularV4RecoveryLivenessState;
            if (state is null ||
                !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
                !string.Equals(state.RouteToken, FileTransferRouteResolver.RegularNknV4FastToken, StringComparison.Ordinal) ||
                state.ProtocolVersion != FileTransferProtocol.ProtocolVersionV4 ||
                !state.BridgeRecoveryStarted ||
                state.BridgeRecoveryCompleted ||
                state.ReceiveProofObserved ||
                state.RecoveryExhausted ||
                state.Completed ||
                state.BridgeRecoveryStartedUtcMs <= 0)
            {
                return false;
            }

            var probeDelay = RuntimeUnlockRegularV4BridgeRecoveryStartedAuthorityProbeDelayOverrideForTests ??
                             RuntimeUnlockRegularV4BridgeRecoveryStartedAuthorityProbeDelay;
            startedAgeMs = Math.Max(0, nowMs - state.BridgeRecoveryStartedUtcMs);
            remainingMs = Math.Max(0, (long)probeDelay.TotalMilliseconds - startedAgeMs);
            return true;
        }
    }

    private bool ShouldBypassRegularV4ReceiveStallForRuntimeUnlockObservedOfferReplay(
        string? blockerReason,
        string? sessionId,
        string purpose)
    {
        if (!string.Equals(purpose, "offer_replay", StringComparison.OrdinalIgnoreCase) ||
            !IsReceiveStallActivationSendBlocker(blockerReason) ||
            !IsCurrentRuntimeUnlockActivationOffer() ||
            string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = SanitizeLogToken(sessionId);
        if (!HasActiveRegularV4FileTransferRouteHint(normalizedSessionId) ||
            HasActivePostTunaFallbackFileTransferRouteHint(normalizedSessionId) ||
            TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out _))
        {
            return false;
        }

        if (TryGetRuntimeUnlockObservedOfferReplayWindowForCurrentOffer(out var stateSnapshot, out _))
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_activation_control_send_regular_v4_receive_stall_observed_replay_allowed; session_id={SanitizeLogToken(normalizedSessionId)}; blocker_reason={SanitizeLogToken(blockerReason ?? "unknown")}; contract_generation={stateSnapshot!.ContractGeneration}; offer_generation={stateSnapshot.CurrentOfferGeneration}; observed_lane={SanitizeLogToken(stateSnapshot.AuthorizedObservedLane)}; reason=bounded_observed_offer_replay");
            return true;
        }

        return false;
    }

    private bool ShouldBypassPostTunaFallbackReceiveStallForRuntimeUnlockObservedOfferReplay(
        string? blockerReason,
        string? sessionId,
        string purpose,
        long blockerRemainingMs)
    {
        if (!string.Equals(purpose, "offer_replay", StringComparison.OrdinalIgnoreCase) ||
            !IsReceiveStallActivationSendBlocker(blockerReason) ||
            !IsCurrentRuntimeUnlockActivationOffer() ||
            string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        if (!HasActivePostTunaFallbackFileTransferRouteHint(normalizedSessionId))
        {
            return false;
        }

        if (!TryGetRuntimeUnlockObservedOfferReplayWindowForCurrentOffer(out var stateSnapshot, out _))
        {
            return false;
        }

        if (!TryGetCurrentPostTunaFallbackObservedSendProbeProof(
                normalizedSessionId,
                out var proof,
                out var proofDirection,
                out var proofAgeMs))
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_activation_control_send_post_tuna_fallback_observed_replay_blocked; session_id={SanitizeLogToken(normalizedSessionId)}; blocker_reason={SanitizeLogToken(blockerReason ?? "unknown")}; blocker_remaining_ms={blockerRemainingMs}; contract_generation={stateSnapshot!.ContractGeneration}; offer_generation={stateSnapshot.CurrentOfferGeneration}; observed_lane={SanitizeLogToken(stateSnapshot.AuthorizedObservedLane)}; reason=awaiting_current_fallback_receive_or_frontier_proof");
            return false;
        }

        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=tuna_activation_control_send_post_tuna_fallback_receive_stall_observed_replay_allowed; session_id={SanitizeLogToken(normalizedSessionId)}; blocker_reason={SanitizeLogToken(blockerReason ?? "unknown")}; blocker_remaining_ms={blockerRemainingMs}; contract_generation={stateSnapshot!.ContractGeneration}; offer_generation={stateSnapshot.CurrentOfferGeneration}; observed_lane={SanitizeLogToken(stateSnapshot.AuthorizedObservedLane)}; proof={SanitizeLogToken(proof)}; proof_direction={SanitizeLogToken(proofDirection)}; proof_age_ms={proofAgeMs}; reason=bounded_observed_offer_replay");
        return true;
    }

    private void ArmRuntimeUnlockQueueAcceptedObservedEscape(string reason)
    {
        lock (accelerationGate)
        {
            if (string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce) ||
                !IsRuntimeUnlockActivationReason(outboundAccelerationOfferTrigger) ||
                runtimeUnlockOfferProofState is not { Retired: false } state ||
                outboundAccelerationOfferGeneration != state.Generation ||
                outboundAccelerationOfferPayerDecisionId != state.PayerDecisionId)
            {
                return;
            }

            var sanitizedReason = SanitizeLogToken(reason);
            runtimeUnlockQueueAcceptedObservedEscapeGeneration = state.Generation;
            runtimeUnlockQueueAcceptedObservedEscapePayerDecisionId = state.PayerDecisionId;
            runtimeUnlockQueueAcceptedObservedEscapeTick = Stopwatch.GetTimestamp();
            runtimeUnlockQueueAcceptedObservedEscapeReason = sanitizedReason;
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_control_queue_observed_escape_armed; session_id={SanitizeLogToken(state.SessionId)}; generation={state.Generation}; payer_decision_id={state.PayerDecisionId}; reason={sanitizedReason}");
        }
    }

    private void ClearRuntimeUnlockQueueAcceptedObservedEscapeLocked()
    {
        runtimeUnlockQueueAcceptedObservedEscapeGeneration = 0;
        runtimeUnlockQueueAcceptedObservedEscapePayerDecisionId = 0;
        runtimeUnlockQueueAcceptedObservedEscapeTick = 0;
        runtimeUnlockQueueAcceptedObservedEscapeReason = null;
    }

    private bool ShouldDeferPostTunaFallbackReceiveStallForRuntimeUnlockOffer(
        string? blockerReason,
        string? sessionId)
    {
        if (!IsReceiveStallActivationSendBlocker(blockerReason) ||
            !IsCurrentRuntimeUnlockActivationOffer())
        {
            return false;
        }

        if (TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out var pendingEpoch) &&
            IsPostTunaFallbackRegularNknEpoch(pendingEpoch))
        {
            return true;
        }

        return HasActivePostTunaFallbackFileTransferRouteHint(sessionId);
    }

    private bool HasActivePostTunaFallbackFileTransferRouteHint(string? sessionId)
    {
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        lock (gate)
        {
            foreach (var session in fileTransferDataSessions.Values)
            {
                if (session.IsDisposed ||
                    !string.Equals(session.SessionId, normalizedSessionId, StringComparison.Ordinal))
                {
                    continue;
                }

                if (TryGetFileTransferRouteHintUnsafe(session.SessionId, session.TransferId, out var routeHint) &&
                    routeHint.Route == FileTransferRoute.PostTunaFallbackV6 &&
                    !routeHint.RuntimeUnlockAdmissionGranted)
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool HasPostTunaFallbackYieldAdmissionRouteHint(
        string? sessionId,
        string? transferId,
        FileTransferDirection? direction = null)
    {
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        var normalizedTransferId = string.IsNullOrWhiteSpace(transferId)
            ? null
            : transferId.Trim();
        lock (gate)
        {
            var activeTransferIds = fileTransferDataSessions.Values
                .Where(session =>
                    !session.IsDisposed &&
                    string.Equals(session.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                    (normalizedTransferId is null ||
                     string.Equals(session.TransferId, normalizedTransferId, StringComparison.Ordinal)))
                .Select(session => session.TransferId)
                .ToHashSet(StringComparer.Ordinal);
            foreach (var pair in fileTransferRouteHints)
            {
                if (!string.Equals(pair.Key.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
                    !activeTransferIds.Contains(pair.Key.TransferId) ||
                    (direction.HasValue &&
                     pair.Key.Direction != direction.Value))
                {
                    continue;
                }

                if (IsPostTunaFallbackYieldAdmissionRouteHint(pair.Value))
                {
                    return true;
                }
            }
        }

        return false;
    }

    private static bool IsPostTunaFallbackYieldAdmissionReason(string? reason)
    {
        var normalized = SanitizeLogToken(reason);
        return normalized is "fallback_tail_quiescent" or "fallback_quiescent";
    }

    private static bool IsPostTunaFallbackYieldAdmissionRouteHint(FileTransferRouteHint routeHint)
        => routeHint.Route == FileTransferRoute.PostTunaFallbackV6 &&
           routeHint.ProtocolVersion == FileTransferProtocol.ProtocolVersionV6 &&
           routeHint.RuntimeUnlockAdmissionGranted &&
           routeHint.FallbackLegCanSendData &&
           routeHint.FallbackLegGeneration > 0 &&
           string.IsNullOrWhiteSpace(routeHint.FallbackCheckpointRequestId) &&
           string.Equals(routeHint.FallbackLegState, "active", StringComparison.OrdinalIgnoreCase) &&
           IsPostTunaFallbackYieldAdmissionReason(routeHint.RuntimeUnlockAdmissionReason);

    private static bool IsNewerPostTunaFallbackRouteHint(
        FileTransferRouteHint candidate,
        FileTransferRouteHint current)
    {
        var publicationCompare = candidate.RoutePublicationGeneration.CompareTo(current.RoutePublicationGeneration);
        if (publicationCompare != 0)
        {
            return publicationCompare > 0;
        }

        var runtimeCompare = candidate.RuntimeGeneration.CompareTo(current.RuntimeGeneration);
        if (runtimeCompare != 0)
        {
            return runtimeCompare > 0;
        }

        var terminalCompare = candidate.TerminalGeneration.CompareTo(current.TerminalGeneration);
        if (terminalCompare != 0)
        {
            return terminalCompare > 0;
        }

        var legCompare = candidate.PublicationLegGeneration.CompareTo(current.PublicationLegGeneration);
        if (legCompare != 0)
        {
            return legCompare > 0;
        }

        return candidate.RecordedUtc > current.RecordedUtc;
    }

    private static bool IsRuntimeUnlockAfterFallbackTailYieldRetryReason(string? reason)
        => string.Equals(
            SanitizeLogToken(reason),
            "runtime_unlock_after_fallback_tail_quiescent",
            StringComparison.Ordinal);

    private bool HasFreshPostTunaFallbackReceiverFrontierProofHint(
        string? sessionId,
        out FileTransferPostTunaFallbackRepairProofHint proofHint)
    {
        proofHint = default;
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        var now = DateTimeOffset.UtcNow;
        lock (gate)
        {
            var staleTransferIds = fileTransferPostTunaFallbackRepairProofHints
                .Where(pair => now - pair.Value.ObservedUtc > FileTransferPostTunaFallbackRepairProofFreshness)
                .Select(static pair => pair.Key)
                .ToArray();
            foreach (var staleTransferId in staleTransferIds)
            {
                fileTransferPostTunaFallbackRepairProofHints.Remove(staleTransferId);
            }

            foreach (var session in fileTransferDataSessions.Values)
            {
                if (session.IsDisposed ||
                    !string.Equals(session.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
                    !TryGetFileTransferRouteHintUnsafe(session.SessionId, session.TransferId, out var routeHint) ||
                    routeHint.Route != FileTransferRoute.PostTunaFallbackV6 ||
                    !fileTransferPostTunaFallbackRepairProofHints.TryGetValue(session.TransferId, out var candidate) ||
                    !string.Equals(candidate.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
                    now - candidate.ObservedUtc > FileTransferPostTunaFallbackRepairProofFreshness)
                {
                    continue;
                }

                proofHint = candidate;
                return true;
            }
        }

        return false;
    }

    private bool ShouldProtectPostTunaFallbackAvailabilityDuringRuntimeUnlockRecovery(
        string? sessionId,
        string recoveryReason,
        string trigger,
        out string protectReason)
    {
        protectReason = "none";
        if (!IsRuntimeUnlockPostTunaFallbackOfferRecoveryReason(recoveryReason) ||
            !HasFreshPostTunaFallbackReceiverFrontierProofHint(sessionId, out var proofHint))
        {
            return false;
        }

        var proofAgeMs = Math.Max(0, (long)(DateTimeOffset.UtcNow - proofHint.ObservedUtc).TotalMilliseconds);
        protectReason = $"fresh_{proofHint.ProofKind}_{proofHint.Direction}";
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_post_tuna_fallback_runtime_unlock_recovery_availability_protected; session_id={SanitizeLogToken(sessionId ?? "none")}; transfer_id={SanitizeLogToken(proofHint.TransferId)}; reason={SanitizeLogToken(recoveryReason)}; trigger={SanitizeLogToken(trigger)}; proof={SanitizeLogToken(proofHint.ProofKind)}; proof_direction={SanitizeLogToken(proofHint.Direction)}; proof_age_ms={proofAgeMs}; freshness_ms={(long)FileTransferPostTunaFallbackRepairProofFreshness.TotalMilliseconds}");
        return true;
    }

    private static bool IsRuntimeUnlockPostTunaFallbackOfferRecoveryReason(string? reason)
    {
        var normalized = SanitizeLogToken(reason);
        return normalized.StartsWith(
            "post_tuna_fallback_tuna_activation_offer",
            StringComparison.OrdinalIgnoreCase);
    }

    private bool ShouldPauseRuntimeUnlockOfferOnQueueAccepted()
    {
        return TryGetRuntimeUnlockOfferQueueAcceptedPressureReason(out _);
    }

    private bool ShouldPauseRegularNknV4FileTransferForRuntimeUnlock(string sessionId)
    {
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        if (HasActivePostTunaFallbackFileTransferRouteHint(sessionId))
        {
            return false;
        }

        if (TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out var pendingEpoch) &&
            string.Equals(pendingEpoch.SessionId, sessionId, StringComparison.Ordinal) &&
            IsPostTunaFallbackRegularNknEpoch(pendingEpoch))
        {
            return false;
        }

        if (client is RealNknClientAdapter realClient &&
            realClient.HasActiveFileTransferRuntimeForActivationSend())
        {
            return true;
        }

        lock (gate)
        {
            foreach (var session in fileTransferDataSessions.Values)
            {
                if (session.IsDisposed ||
                    !string.Equals(session.SessionId, sessionId, StringComparison.Ordinal))
                {
                    continue;
                }

                if (TryGetFileTransferRouteHintUnsafe(session.SessionId, session.TransferId, out var routeHint) &&
                    routeHint.Route == FileTransferRoute.RegularNknV4Fast)
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool PauseRegularNknV4FileTransferForRuntimeUnlockMakeBeforeBreak(
        string sessionId,
        string reason,
        string trigger)
    {
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        if (!ShouldPauseRegularNknV4FileTransferForRuntimeUnlock(sessionId))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_tuna_activation_negotiation_regular_nkn_pause_deferred; session_id={SanitizeLogToken(sessionId)}; reason={SanitizeLogToken(reason)}; trigger={SanitizeLogToken(trigger)}");
            return false;
        }

        var paused = PauseFileTransferDataSessionsForTunaActivationNegotiation(
            reason,
            sessionId,
            trigger);
        if (paused)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_make_before_break_regular_v4_pause_started; session_id={SanitizeLogToken(sessionId)}; reason={SanitizeLogToken(reason)}; trigger={SanitizeLogToken(trigger)}");
        }

        return paused;
    }

    private string? GetRuntimeUnlockOfferQueueAcceptedObservedReason()
        => TryGetRuntimeUnlockQueueAcceptedObservedEscapeReason(out var reason)
            ? reason
            : null;

    private bool TryGetRuntimeUnlockOfferQueueAcceptedPressureReason(out string reason)
    {
        reason = string.Empty;
        if (!IsCurrentRuntimeUnlockActivationOffer())
        {
            return false;
        }

        if (RuntimeUnlockOfferQueueAcceptedPressureOverrideForTests?.Invoke(this) == true)
        {
            reason = "test_regular_v4_pressure";
            return true;
        }

        if (client is not RealNknClientAdapter realClient)
        {
            return TryGetRuntimeUnlockQueueAcceptedObservedEscapeReason(out reason);
        }

        if (realClient.TryGetFileTransferRegularV4ActivationSendPressure(out var pressureReason, out _))
        {
            reason = SanitizeLogToken(pressureReason ?? "regular_v4_pressure");
            return true;
        }

        if (TryGetRuntimeUnlockQueueAcceptedObservedEscapeReason(out reason))
        {
            return true;
        }

        return false;
    }

    private bool TryGetRuntimeUnlockQueueAcceptedObservedEscapeReason(out string reason)
    {
        reason = string.Empty;
        lock (accelerationGate)
        {
            if (string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce) ||
                !IsRuntimeUnlockActivationReason(outboundAccelerationOfferTrigger) ||
                runtimeUnlockOfferProofState is not { Retired: false } state ||
                runtimeUnlockQueueAcceptedObservedEscapeGeneration != state.Generation ||
                runtimeUnlockQueueAcceptedObservedEscapePayerDecisionId != state.PayerDecisionId ||
                runtimeUnlockQueueAcceptedObservedEscapeTick <= 0 ||
                string.IsNullOrWhiteSpace(runtimeUnlockQueueAcceptedObservedEscapeReason))
            {
                return false;
            }

            if (Stopwatch.GetElapsedTime(runtimeUnlockQueueAcceptedObservedEscapeTick) >
                RuntimeUnlockQueueAcceptedObservedEscapeTtl)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_control_queue_observed_escape_expired; session_id={SanitizeLogToken(state.SessionId)}; generation={state.Generation}; payer_decision_id={state.PayerDecisionId}; reason={SanitizeLogToken(runtimeUnlockQueueAcceptedObservedEscapeReason)}");
                runtimeUnlockQueueAcceptedObservedEscapeGeneration = 0;
                runtimeUnlockQueueAcceptedObservedEscapePayerDecisionId = 0;
                runtimeUnlockQueueAcceptedObservedEscapeTick = 0;
                runtimeUnlockQueueAcceptedObservedEscapeReason = null;
                return false;
            }

            reason = SanitizeLogToken(runtimeUnlockQueueAcceptedObservedEscapeReason);
            return true;
        }
    }

    private bool IsCurrentRuntimeUnlockActivationOffer()
    {
        lock (accelerationGate)
        {
            return IsRuntimeUnlockActivationReason(outboundAccelerationOfferTrigger);
        }
    }

    private bool TryGetFileTransferTunaActivationBridgeRecoveryWaitSession(
        string purpose,
        string? activationSessionId,
        out string? sessionId)
    {
        if (TryGetActiveFileTransferTunaActivationPause(activationSessionId, out sessionId))
        {
            return true;
        }

        if (!IsTunaActivationOfferSendPurpose(purpose))
        {
            return false;
        }

        sessionId = string.IsNullOrWhiteSpace(activationSessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : activationSessionId.Trim();
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        if (!string.IsNullOrWhiteSpace(activationSessionId))
        {
            return true;
        }

        lock (accelerationGate)
        {
            return !string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce) &&
                   IsRuntimeUnlockActivationReason(outboundAccelerationOfferTrigger) &&
                   !IsAccelerationNegotiatedAndHealthyUnsafe(sessionId);
        }
    }

    private static bool IsTunaActivationOfferSendPurpose(string? purpose)
        => string.Equals(purpose, "offer", StringComparison.OrdinalIgnoreCase) ||
           string.Equals(purpose, "offer_replay", StringComparison.OrdinalIgnoreCase) ||
           string.Equals(purpose, "offer_answer", StringComparison.OrdinalIgnoreCase) ||
           string.Equals(purpose, "offer_peer_response", StringComparison.OrdinalIgnoreCase);

    private static bool IsTunaActivationAnswerSendPurpose(string? purpose)
        => string.Equals(purpose, "answer", StringComparison.OrdinalIgnoreCase) ||
           string.Equals(purpose, "answer_replay", StringComparison.OrdinalIgnoreCase);

    private bool IsRuntimeUnlockPeerVisibleActivationSendPurpose(string purpose, string? sessionId)
    {
        if (IsTunaActivationOfferSendPurpose(purpose))
        {
            return IsCurrentRuntimeUnlockActivationOffer();
        }

        return IsTunaActivationAnswerSendPurpose(purpose) &&
               IsPendingAccelerationAnswerAckForSession(sessionId);
    }

    private bool IsPendingRuntimeUnlockAccelerationAnswerAck(string? sessionId)
        => IsPendingAccelerationAnswerAckForSession(sessionId, requireRuntimeUnlock: true);

    private bool IsPendingAccelerationAnswerAckForSession(string? sessionId, bool requireRuntimeUnlock = false)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? string.Empty
            : sessionId.Trim();
        lock (accelerationGate)
        {
            return !string.IsNullOrWhiteSpace(pendingAccelerationAnswerAckNonce) &&
                   (!requireRuntimeUnlock ||
                    IsRuntimeUnlockActivationReason(pendingAccelerationAnswerAckTrigger)) &&
                   (string.IsNullOrWhiteSpace(normalizedSessionId) ||
                    string.Equals(pendingAccelerationAnswerAckSessionId, normalizedSessionId, StringComparison.Ordinal));
        }
    }

    public bool TryGetActiveSessionRecoveryContract(
        string sessionId,
        out SessionRecoveryContractSnapshot snapshot)
    {
        snapshot = default!;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            return false;
        }

        var expiredAuthority = false;
        string? expiredSessionId = null;
        RuntimeUnlockRetryDispatchContract? expiredContract = null;
        RuntimeUnlockRetryDispatchSettlementReport settlementReport = default;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return false;
            }

            var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            if (ShouldExpireRuntimeUnlockRetryAuthorityUnsafe(state, nowMs) &&
                state.ContractState is not (SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed))
            {
                var contract = state.DispatchContract;
                if (contract is not null &&
                    contract.TrySettle(
                        RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch,
                        "runtime_unlock_retry_authority_expired") &&
                    TryCaptureRuntimeUnlockRetryDispatchSettlementReportUnsafe(
                        state,
                        contract,
                        new RuntimeUnlockRetryDispatchSettlementConsequence(
                            contract.OfferGeneration > 0
                                ? contract.OfferGeneration
                                : state.RetiredOfferGeneration,
                            "runtime_unlock_offer_send_not_observed",
                            "runtime_unlock_retry_authority_expired",
                            state.RequiresLocalListenerRetry,
                            RequestSuccessor: true,
                            ObservedLane: null),
                        out settlementReport))
                {
                    expiredAuthority = true;
                    expiredSessionId = state.SessionId;
                    expiredContract = contract;
                }
            }

            snapshot = CreateSessionRecoveryContractSnapshotUnsafe(state);
        }

        if (expiredAuthority)
        {
            LogRuntimeUnlockRetryDispatchContractSettled(
                expiredContract!,
                RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch,
                "runtime_unlock_retry_authority_expired");
            _ = PublishRuntimeUnlockRetryDispatchSettlementReport(settlementReport);
            lock (accelerationGate)
            {
                if (runtimeUnlockRecoveryRetryState is { } current &&
                    string.Equals(current.SessionId, normalizedSessionId, StringComparison.Ordinal))
                {
                    snapshot = CreateSessionRecoveryContractSnapshotUnsafe(current);
                }
            }
        }

        return true;
    }

    private SessionRecoveryContractSnapshot CreateSessionRecoveryContractSnapshotUnsafe(
        RuntimeUnlockRecoveryRetryState state)
        => new(
            state.SessionId,
            state.TransferId,
            state.ContractGeneration,
            state.CurrentOfferGeneration > 0 ? state.CurrentOfferGeneration : state.RetiredOfferGeneration,
            SessionRecoveryContractKind.RuntimeUnlockActivation,
            state.ContractState,
            state.RetryReason,
            state.RecoveryReason,
            DateTimeOffset.FromUnixTimeMilliseconds(state.CreatedUtcMs),
            DateTimeOffset.FromUnixTimeMilliseconds(state.RetryDeadlineUtcMs),
            DateTimeOffset.FromUnixTimeMilliseconds(state.LivenessDeferralDeadlineUtcMs),
            RecoveryPending: !state.Settled && state.ContractState == SessionRecoveryContractState.RecoveryPending,
            RecoverySettled: state.Settled,
            RetryRequired: IsSessionRecoveryContractRetryRequired(state),
            RetryDispatching: state.RetryDispatching,
            RetryDispatched: state.RetryDispatched,
            RetryObserved: state.RetryObserved,
            QueuedBehindActiveNegotiation: state.QueuedBehindActiveNegotiation,
            RetryAuthorityPending: state.RetryAuthorityPending,
            RetryAuthorityGranted: state.RetryAuthorityGranted,
            ObservedSendPending: state.ObservedSendPending,
            ObservedSendDeadlineUtc: state.ObservedSendDeadlineUtcMs > 0
                ? DateTimeOffset.FromUnixTimeMilliseconds(state.ObservedSendDeadlineUtcMs)
                : DateTimeOffset.MinValue,
            AuthorizedObservedLane: state.AuthorizedObservedLane,
            AuthorityFailureReason: state.AuthorityFailureReason,
            AuthorityAttempt: state.AuthorityAttempt,
            RuntimeUnlockTransactionGeneration: runtimeUnlockTransactionState.TransactionGeneration,
            RuntimeUnlockTransactionOfferGeneration: runtimeUnlockTransactionState.OfferGeneration,
            RuntimeUnlockTransactionState: runtimeUnlockTransactionState.State.ToString().ToLowerInvariant(),
            RuntimeUnlockPeerProofObserved: runtimeUnlockTransactionState.HasPeerVisibleProof,
            RuntimeUnlockRouteCommitPending: runtimeUnlockTransactionState.RouteCommitPending,
            RuntimeUnlockRouteCommitted: runtimeUnlockTransactionState.RouteCommitted,
            RuntimeUnlockTransactionFailureReason: runtimeUnlockTransactionState.FailureReason,
            RuntimeUnlockPathProbeId: runtimeUnlockTransactionState.PathProbeId,
            RuntimeUnlockPathProbeState: runtimeUnlockTransactionState.PathProbeState.ToString().ToLowerInvariant(),
            RuntimeUnlockPathProbeTransport: FormatFileTransferTransportKindForLog(runtimeUnlockTransactionState.PathProbeTransport),
            RuntimeUnlockPathProbeAckedUtcMs: runtimeUnlockTransactionState.PathProbeAckedUtcMs,
            RuntimeUnlockPathProbeFailureReason: runtimeUnlockTransactionState.PathProbeFailureReason,
            RuntimeUnlockTunaPathLeaseGeneration: runtimeUnlockTunaPathLeaseState.LeaseGeneration,
            RuntimeUnlockTunaPathLeaseState: runtimeUnlockTunaPathLeaseState.State.ToString().ToLowerInvariant(),
            RuntimeUnlockTunaPathLeaseListenerRunId: runtimeUnlockTunaPathLeaseState.ListenerRunId,
            RuntimeUnlockTunaPathLeaseCurrent: runtimeUnlockTunaPathLeaseState.IsCurrent,
            RuntimeUnlockTunaPathLeaseFailureReason: runtimeUnlockTunaPathLeaseState.FailureReason);

    void IRuntimeUnlockRouteCommitProofProvider.NotifyRuntimeUnlockPathProbeStarted(
        string sessionId,
        string transferId,
        long transportEpoch,
        string probeId,
        FileTransferTransportKind targetTransport,
        string reason)
    {
        NotifyRuntimeUnlockPathProbe(
            RuntimeUnlockTransactionEventKind.PathProbeStarted,
            sessionId,
            transferId,
            transportEpoch,
            probeId,
            targetTransport,
            acked: false,
            reason);
    }

    void IRuntimeUnlockRouteCommitProofProvider.NotifyRuntimeUnlockPathProbeResult(
        string sessionId,
        string transferId,
        long transportEpoch,
        string probeId,
        FileTransferTransportKind targetTransport,
        bool acked,
        string reason)
    {
        NotifyRuntimeUnlockPathProbe(
            acked
                ? RuntimeUnlockTransactionEventKind.PathProbeAcked
                : RuntimeUnlockTransactionEventKind.PathProbeFailed,
            sessionId,
            transferId,
            transportEpoch,
            probeId,
            targetTransport,
            acked,
            reason);
    }

    private void NotifyRuntimeUnlockPathProbe(
        RuntimeUnlockTransactionEventKind kind,
        string sessionId,
        string transferId,
        long transportEpoch,
        string probeId,
        FileTransferTransportKind targetTransport,
        bool acked,
        string reason)
    {
        if (string.IsNullOrWhiteSpace(sessionId) ||
            string.IsNullOrWhiteSpace(probeId))
        {
            return;
        }

        RuntimeUnlockTransactionDecision? decision;
        lock (accelerationGate)
        {
            var current = runtimeUnlockTransactionState;
            if (current.IsTerminal ||
                !string.Equals(current.SessionId, sessionId.Trim(), StringComparison.Ordinal) ||
                (!string.IsNullOrWhiteSpace(current.TransferId) &&
                 !string.IsNullOrWhiteSpace(transferId) &&
                 !string.Equals(current.TransferId, transferId.Trim(), StringComparison.Ordinal)))
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    "event=runtime_unlock_probe_stale_ignored; " +
                    $"session_id={SanitizeLogToken(sessionId)}; transfer_id={SanitizeLogToken(transferId)}; " +
                    $"transaction_generation={current.TransactionGeneration}; offer_generation={current.OfferGeneration}; " +
                    $"probe_id={SanitizeLogToken(probeId)}; target_transport={FormatFileTransferTransportKindForLog(targetTransport)}; " +
                    $"transport_epoch={transportEpoch}; state={current.State.ToString().ToLowerInvariant()}; reason={SanitizeLogToken(reason)}");
                return;
            }

            decision = ApplyRuntimeUnlockTransactionUnsafe(
                kind,
                sessionId.Trim(),
                current.OfferGeneration,
                reason,
                transactionGeneration: current.TransactionGeneration,
                pathProbeId: probeId.Trim(),
                pathProbeTransport: targetTransport);
        }

        LogRuntimeUnlockTransactionDecision(kind, decision);
        if (kind == RuntimeUnlockTransactionEventKind.PathProbeStarted)
        {
            ClearRuntimeUnlockPreCommitProbeLaunchIfCurrent(
                sessionId.Trim(),
                transferId.Trim(),
                decision.State.TransactionGeneration,
                decision.State.OfferGeneration,
                decision.State.TunaPathLeaseGeneration,
                decision.State.TunaPathLeaseListenerRunId,
                probeId.Trim(),
                targetTransport,
                reason);
        }

        RuntimeUnlockRouteCommitSnapshot? launchEvidence;
        lock (accelerationGate)
        {
            var started = runtimeUnlockPreCommitProbeStartedSnapshot;
            if (kind == RuntimeUnlockTransactionEventKind.PathProbeAcked &&
                started is not null &&
                string.Equals(started.SessionId, sessionId.Trim(), StringComparison.Ordinal) &&
                string.Equals(started.TransferId, transferId.Trim(), StringComparison.Ordinal) &&
                started.TransactionGeneration == decision.State.TransactionGeneration &&
                started.OfferGeneration == decision.State.OfferGeneration &&
                string.Equals(started.PathProbeId, probeId.Trim(), StringComparison.Ordinal))
            {
                started = started with
                {
                    PathProbeState = RuntimeUnlockPathProbeState.Acked.ToString(),
                    PathProbeTransport = targetTransport,
                    PathProbeAckedUtcMs = decision.State.PathProbeAckedUtcMs,
                };
                runtimeUnlockPreCommitProbeStartedSnapshot = started;
            }

            launchEvidence = started is not null &&
                string.Equals(started.SessionId, sessionId.Trim(), StringComparison.Ordinal) &&
                started.TransactionGeneration == decision.State.TransactionGeneration &&
                started.OfferGeneration == decision.State.OfferGeneration
                    ? started
                    : null;
        }

        if (kind == RuntimeUnlockTransactionEventKind.PathProbeAcked &&
            ((IRuntimeUnlockRouteCommitProofProvider)this).TryGetRuntimeUnlockRouteCommitProof(
                sessionId,
                transferId,
                out var acceptedSnapshot))
        {
            lock (accelerationGate)
            {
                if (runtimeUnlockPreCommitProbeStartedSnapshot is { } current &&
                    current.LaunchGeneration == acceptedSnapshot.LaunchGeneration &&
                    current.TransactionGeneration == acceptedSnapshot.TransactionGeneration &&
                    current.OfferGeneration == acceptedSnapshot.OfferGeneration &&
                    string.Equals(current.TransferId, acceptedSnapshot.TransferId, StringComparison.Ordinal))
                {
                    runtimeUnlockPreCommitProbeStartedSnapshot = acceptedSnapshot;
                    runtimeUnlockAcceptedPreCommitSnapshot = acceptedSnapshot;
                    launchEvidence = acceptedSnapshot;
                }
            }
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event={GetRuntimeUnlockProbeEventName(kind)}; session_id={SanitizeLogToken(sessionId)}; transfer_id={SanitizeLogToken(transferId)}; transaction_generation={decision.State.TransactionGeneration}; offer_generation={decision.State.OfferGeneration}; launch_generation={launchEvidence?.LaunchGeneration ?? 0}; tuna_path_lease_generation={launchEvidence?.TunaPathLeaseGeneration ?? decision.State.TunaPathLeaseGeneration}; tuna_path_lease_listener_run_id={SanitizeLogToken(launchEvidence?.TunaPathLeaseListenerRunId ?? decision.State.TunaPathLeaseListenerRunId ?? "none")}; probe_id={SanitizeLogToken(probeId)}; target_transport={FormatFileTransferTransportKindForLog(targetTransport)}; transport_epoch={transportEpoch}; acked={(acked ? 1 : 0)}; state={decision.State.PathProbeState.ToString().ToLowerInvariant()}; reason={SanitizeLogToken(reason)}");
        NotifyTransportAccelerationStateChanged(GetRuntimeUnlockProbeEventName(kind));
    }

    bool IRuntimeUnlockRouteCommitProofProvider.TryGetRuntimeUnlockRouteCommitProof(
        string sessionId,
        string transferId,
        out RuntimeUnlockRouteCommitSnapshot snapshot)
    {
        snapshot = default!;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        var normalizedTransferId = string.IsNullOrWhiteSpace(transferId) ? string.Empty : transferId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            return false;
        }

        lock (accelerationGate)
        {
            var state = runtimeUnlockTransactionState;
            var stateTransferId = string.IsNullOrWhiteSpace(state.TransferId)
                ? null
                : state.TransferId.Trim();
            if (state.IsTerminal ||
                !state.HasPeerVisibleProof ||
                !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
                (!string.IsNullOrWhiteSpace(stateTransferId) &&
                 !string.IsNullOrWhiteSpace(normalizedTransferId) &&
                 !string.Equals(stateTransferId, normalizedTransferId, StringComparison.Ordinal)))
            {
                return false;
            }

            var lease = runtimeUnlockTunaPathLeaseState;
            var leaseRequired = RuntimeUnlockTunaPathLease.IsApplicableToOffer(
                lease,
                state.SessionId,
                state.TransactionGeneration,
                state.OfferGeneration);
            var leaseTransferId = string.IsNullOrWhiteSpace(lease.TransferId)
                ? null
                : lease.TransferId.Trim();
            string? resolvedTransferId = stateTransferId;
            if (leaseRequired)
            {
                if (!string.IsNullOrWhiteSpace(stateTransferId) &&
                    !string.IsNullOrWhiteSpace(leaseTransferId) &&
                    !string.Equals(stateTransferId, leaseTransferId, StringComparison.Ordinal))
                {
                    return false;
                }

                resolvedTransferId ??= leaseTransferId;
                if (string.IsNullOrWhiteSpace(resolvedTransferId) ||
                    string.IsNullOrWhiteSpace(normalizedTransferId) ||
                    !string.Equals(resolvedTransferId, normalizedTransferId, StringComparison.Ordinal))
                {
                    return false;
                }
            }

            var launchIdentity = runtimeUnlockPreCommitProbeStartedSnapshot ??
                runtimeUnlockPreCommitProbeLaunchSnapshot;
            var launchGeneration = launchIdentity is { LaunchGeneration: > 0 } &&
                string.Equals(launchIdentity.SessionId, state.SessionId, StringComparison.Ordinal) &&
                string.Equals(launchIdentity.TransferId, resolvedTransferId, StringComparison.Ordinal) &&
                launchIdentity.TransactionGeneration == state.TransactionGeneration &&
                launchIdentity.OfferGeneration == state.OfferGeneration &&
                launchIdentity.TunaPathLeaseGeneration == (leaseRequired ? lease.LeaseGeneration : 0) &&
                string.Equals(
                    launchIdentity.TunaPathLeaseListenerRunId,
                    leaseRequired ? lease.ListenerRunId : null,
                    StringComparison.Ordinal)
                    ? launchIdentity.LaunchGeneration
                    : 0;
            snapshot = new RuntimeUnlockRouteCommitSnapshot(
                state.SessionId,
                resolvedTransferId,
                state.TransactionGeneration,
                state.OfferGeneration,
                state.HasPeerVisibleProof,
                state.PeerReceived,
                state.AnswerReceived,
                FileTransferRoute.FileTunaV4,
                FileTransferProtocol.ProtocolVersionV4,
                FileTransferTransportHandoffKind.NormalToTunaActivation,
                FileTransferTransportKind.Tuna,
                state.State.ToString(),
                "runtime_unlock_transaction_peer_proof",
                PathProbeId: state.PathProbeId,
                PathProbeState: state.PathProbeState.ToString(),
                PathProbeTransport: state.PathProbeTransport,
                PathProbeAckedUtcMs: state.PathProbeAckedUtcMs,
                PathProbeFailureReason: state.PathProbeFailureReason,
                TunaPathLeaseRequired: leaseRequired,
                TunaPathLeaseGeneration: leaseRequired ? lease.LeaseGeneration : 0,
                TunaPathLeaseState: leaseRequired ? lease.State.ToString() : "None",
                TunaPathLeaseListenerRunId: leaseRequired ? lease.ListenerRunId : null,
                TunaPathLeaseCurrent: leaseRequired && lease.IsCurrent,
                TunaPathLeaseFailureReason: leaseRequired ? lease.FailureReason : null,
                LaunchGeneration: launchGeneration);
            return true;
        }
    }

    private void RecordInitialTunaReadinessAnswerReceived(
        string? sessionId,
        long offerGeneration,
        long payerDecisionId,
        string reason,
        bool answerAckReceived)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId) ||
            offerGeneration <= 0)
        {
            return;
        }

        InitialTunaReadinessSnapshot? snapshot;
        string? ignoredReason = null;
        lock (accelerationGate)
        {
            if (!TryCaptureInitialTunaReadinessLeaseUnsafe(
                    normalizedSessionId,
                    offerGeneration,
                    payerDecisionId,
                    out var leaseGeneration,
                    out var listenerRunId,
                    out var tunaNegotiatedObserved,
                    out ignoredReason))
            {
                snapshot = null;
            }
            else
            {
                var generation = ++initialTunaReadinessNextGeneration;
                snapshot = new InitialTunaReadinessSnapshot
                {
                    Generation = generation,
                    SessionId = normalizedSessionId,
                    CapturedUtc = DateTimeOffset.UtcNow,
                    OfferGeneration = offerGeneration,
                    PayerDecisionId = payerDecisionId,
                    LeaseGeneration = leaseGeneration,
                    ListenerRunId = listenerRunId,
                    LeaseCurrent = true,
                    ListenerReady = true,
                    AnswerAckReceived = answerAckReceived,
                    TunaNegotiatedObserved = tunaNegotiatedObserved,
                };
                initialTunaReadinessState = snapshot;
            }
        }

        if (snapshot is null)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_transaction_answer_received_ignored; session_id={SanitizeLogToken(normalizedSessionId)}; offer_generation={offerGeneration}; peer_visible_proof=1; peer_received=1; answer_received=1; initial_tuna_readiness=0; reason={SanitizeLogToken(reason)}; ignored_reason={SanitizeLogToken(ignoredReason ?? "initial_tuna_listener_or_lease_not_ready")}");
            return;
        }

        LogInitialTunaReadinessAnswerReceived(snapshot, reason);
    }

    private bool TryCaptureInitialTunaReadinessLeaseUnsafe(
        string sessionId,
        long offerGeneration,
        long payerDecisionId,
        out long leaseGeneration,
        out string listenerRunId,
        out bool tunaNegotiatedObserved,
        out string rejectionReason)
    {
        leaseGeneration = 0;
        listenerRunId = string.Empty;
        tunaNegotiatedObserved = false;
        rejectionReason = "unknown";

        if (accelerationLane is not INknTunaAccelerationSession tunaSession)
        {
            rejectionReason = "tuna_lane_missing";
            return false;
        }

        if (!tunaSession.IsAvailable)
        {
            rejectionReason = "tuna_lane_unavailable";
            return false;
        }

        if (string.IsNullOrWhiteSpace(tunaSession.LocalTunaAddress))
        {
            rejectionReason = "tuna_listener_address_missing";
            return false;
        }

        if (accelerationNegotiatedLanes == NknAccelerationLaneKind.None ||
            string.IsNullOrWhiteSpace(accelerationSessionId) ||
            !string.Equals(accelerationSessionId, sessionId, StringComparison.Ordinal))
        {
            rejectionReason = "tuna_session_not_negotiated";
            return false;
        }

        leaseGeneration = payerDecisionId > 0 ? payerDecisionId : offerGeneration;
        if (leaseGeneration <= 0)
        {
            rejectionReason = "tuna_lease_generation_missing";
            return false;
        }

        var listenerRole = tunaSession.IsLocalPaidListenerActive ? "local-listener" : "peer-listener";
        listenerRunId =
            $"initial-tuna-{listenerRole}-{leaseGeneration.ToString(CultureInfo.InvariantCulture)}-{offerGeneration.ToString(CultureInfo.InvariantCulture)}";
        tunaNegotiatedObserved = true;
        return true;
    }

    private bool IsInitialTunaReadinessSnapshotCurrentUnsafe(
        InitialTunaReadinessSnapshot snapshot,
        string sessionId)
    {
        var now = DateTimeOffset.UtcNow;
        var isSessionReactivationSnapshot = !string.IsNullOrWhiteSpace(snapshot.SourceTransferId);
        var age = now - snapshot.CapturedUtc;
        var maxSnapshotAge = isSessionReactivationSnapshot
            ? InitialTunaReadinessSessionReactivationSnapshotTtl
            : InitialTunaReadinessPositiveSnapshotTtl;
        return snapshot.CapturedUtc != default &&
           snapshot.CapturedUtc <= now &&
           age <= maxSnapshotAge &&
           snapshot.LeaseCurrent &&
           snapshot.ListenerReady &&
           accelerationLane is INknTunaAccelerationSession tunaSession &&
           tunaSession.IsAvailable &&
           !string.IsNullOrWhiteSpace(tunaSession.LocalTunaAddress) &&
           accelerationNegotiatedLanes != NknAccelerationLaneKind.None &&
           !string.IsNullOrWhiteSpace(accelerationSessionId) &&
           string.Equals(accelerationSessionId, sessionId, StringComparison.Ordinal);
    }

    private static bool IsPositiveInitialTunaReadinessEvidence(
        bool leaseCurrent,
        bool listenerReady,
        bool peerVisibleProof,
        bool answerReceived)
        => leaseCurrent &&
           listenerReady &&
           peerVisibleProof &&
           answerReceived;

    private void LogInitialTunaReadinessAnswerReceived(
        InitialTunaReadinessSnapshot snapshot,
        string reason)
    {
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_transaction_answer_received; session_id={SanitizeLogToken(snapshot.SessionId)}; transaction_generation={snapshot.Generation}; offer_generation={snapshot.OfferGeneration}; state=answerreceived; peer_visible_proof=1; peer_received=1; answer_received=1; path_probe_id=(none); path_probe_state=none; path_probe_transport=unknown; path_probe_acked_utc_ms=0; path_probe_failure_reason=(none); route_commit_pending=0; route_committed=0; failure_reason=(none); retired_reason=(none); tuna_path_lease_generation={snapshot.LeaseGeneration}; tuna_path_lease_state={(snapshot.ListenerReady ? "listenerready" : "none")}; tuna_path_lease_current={(snapshot.LeaseCurrent ? 1 : 0)}; tuna_path_lease_listener_run_id={SanitizeLogToken(snapshot.ListenerRunId)}; tuna_path_lease_failure_reason=(none); answer_ack_received={(snapshot.AnswerAckReceived ? 1 : 0)}; initial_tuna_readiness=1; reason={SanitizeLogToken(reason)}");
    }

    private InitialTunaReadinessSnapshot? RefreshInitialTunaReadinessFromAcceptedRuntimeUnlockCommitUnsafe(
        RuntimeUnlockTransactionSnapshot current,
        FileTransferDirection direction,
        string reason)
    {
        if (string.IsNullOrWhiteSpace(current.SessionId) ||
            current.OfferGeneration <= 0 ||
            current.TunaPathLeaseGeneration <= 0 ||
            current.TunaPathLeaseState != RuntimeUnlockTunaPathLeaseState.ListenerReady ||
            !current.TunaPathLeaseCurrent ||
            !current.HasPeerVisibleProof ||
            !current.AnswerReceived)
        {
            return null;
        }

        var generation = ++initialTunaReadinessNextGeneration;
        var snapshot = new InitialTunaReadinessSnapshot
        {
            Generation = generation,
            SessionId = current.SessionId,
            CapturedUtc = DateTimeOffset.UtcNow,
            OfferGeneration = current.OfferGeneration,
            PayerDecisionId = current.OfferGeneration,
            LeaseGeneration = current.TunaPathLeaseGeneration,
            ListenerRunId = string.IsNullOrWhiteSpace(current.TunaPathLeaseListenerRunId)
                ? $"runtime-unlock-route-commit-{current.TunaPathLeaseGeneration.ToString(CultureInfo.InvariantCulture)}"
                : current.TunaPathLeaseListenerRunId!,
            LeaseCurrent = true,
            ListenerReady = true,
            AnswerAckReceived = true,
            TunaNegotiatedObserved = true,
            Direction = direction,
            SourceTransferId = string.IsNullOrWhiteSpace(current.TransferId) ? null : current.TransferId.Trim(),
        };
        initialTunaReadinessState = snapshot;
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=initial_tuna_readiness_reminted_from_route_commit; session_id={SanitizeLogToken(snapshot.SessionId)}; transaction_generation={current.TransactionGeneration}; offer_generation={snapshot.OfferGeneration}; snapshot_generation={snapshot.Generation}; tuna_path_lease_generation={snapshot.LeaseGeneration}; tuna_path_lease_listener_run_id={SanitizeLogToken(snapshot.ListenerRunId)}; peer_visible_proof=1; answer_received=1; initial_tuna_readiness=1; reason={SanitizeLogToken(reason)}");
        return snapshot;
    }

    private FileTransferInitialTunaReadinessEvidence CreateInitialTunaReadinessEvidenceFromSnapshotUnsafe(
        InitialTunaReadinessSnapshot snapshot,
        string transferId,
        FileTransferDirection direction,
        DateTimeOffset capturedUtc)
    {
        var sourceTransferId = string.IsNullOrWhiteSpace(snapshot.SourceTransferId)
            ? null
            : snapshot.SourceTransferId!.Trim();
        var readinessScope =
            !string.IsNullOrWhiteSpace(sourceTransferId) &&
            !string.Equals(sourceTransferId, transferId, StringComparison.Ordinal)
                ? FileTransferInitialTunaReadinessScopes.SessionReactivation
                : FileTransferInitialTunaReadinessScopes.Transfer;
        var evidenceDirection = snapshot.Direction ?? direction;

        if (string.IsNullOrWhiteSpace(snapshot.ConsumedTransferId))
        {
            snapshot.ConsumedTransferId = transferId;
            snapshot.ConsumedUtc = capturedUtc;
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=initial_tuna_readiness_snapshot_consumed; session_id={SanitizeLogToken(snapshot.SessionId)}; transfer_id={SanitizeLogToken(transferId)}; direction={evidenceDirection.ToString().ToLowerInvariant()}; source_transfer_id={SanitizeLogToken(sourceTransferId ?? "(none)")}; readiness_scope={SanitizeLogToken(readinessScope)}; snapshot_generation={snapshot.Generation}; source_captured_utc_ms={snapshot.CapturedUtc.ToUnixTimeMilliseconds()}; evidence_captured_utc_ms={capturedUtc.ToUnixTimeMilliseconds()}; offer_generation={snapshot.OfferGeneration}; tuna_path_lease_generation={snapshot.LeaseGeneration}; tuna_path_lease_listener_run_id={SanitizeLogToken(snapshot.ListenerRunId)}; decision_reason=positive_readiness_consumed_for_target_transfer");
        }

        return new FileTransferInitialTunaReadinessEvidence(
            snapshot.SessionId,
            transferId,
            evidenceDirection,
            capturedUtc,
            snapshot.LeaseGeneration,
            snapshot.ListenerRunId,
            snapshot.LeaseCurrent,
            snapshot.ListenerReady,
            snapshot.OfferGeneration,
            PeerVisibleProof: true,
            AnswerReceived: true,
            snapshot.AnswerAckReceived,
            snapshot.TunaNegotiatedObserved ||
            (!string.IsNullOrWhiteSpace(accelerationSessionId) &&
             string.Equals(accelerationSessionId, snapshot.SessionId, StringComparison.Ordinal)),
            readinessScope,
            sourceTransferId,
            snapshot.Generation,
            snapshot.CapturedUtc);
    }

    bool IFileTransferInitialTunaReadinessProvider.TryGetInitialTunaReadinessEvidence(
        string sessionId,
        string transferId,
        FileTransferDirection direction,
        out FileTransferInitialTunaReadinessEvidence? evidence)
    {
        evidence = null;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        var normalizedTransferId = string.IsNullOrWhiteSpace(transferId) ? string.Empty : transferId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId) ||
            string.IsNullOrWhiteSpace(normalizedTransferId))
        {
            return false;
        }

        lock (accelerationGate)
        {
            FileTransferInitialTunaReadinessEvidence? positiveSnapshotEvidence = null;
            InitialTunaReadinessSnapshot? consumedSnapshotForOtherTransfer = null;
            if (initialTunaReadinessState is { } initial &&
                string.Equals(initial.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                IsInitialTunaReadinessSnapshotCurrentUnsafe(initial, normalizedSessionId))
            {
                var sourceTransferId = string.IsNullOrWhiteSpace(initial.SourceTransferId)
                    ? null
                    : initial.SourceTransferId!.Trim();
                var isSessionReactivationSnapshot =
                    !string.IsNullOrWhiteSpace(sourceTransferId) &&
                    !string.Equals(sourceTransferId, normalizedTransferId, StringComparison.Ordinal);
                var snapshotDirectionMismatch =
                    initial.Direction.HasValue &&
                    initial.Direction.Value != direction;
                var snapshotDirectionMissingForReactivation =
                    isSessionReactivationSnapshot &&
                    !initial.Direction.HasValue;
                if (snapshotDirectionMismatch ||
                    snapshotDirectionMissingForReactivation)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=initial_tuna_readiness_direction_mismatch; session_id={SanitizeLogToken(normalizedSessionId)}; transfer_id={SanitizeLogToken(normalizedTransferId)}; requested_direction={direction.ToString().ToLowerInvariant()}; snapshot_direction={SanitizeLogToken(initial.Direction?.ToString().ToLowerInvariant() ?? "(none)")}; source_transfer_id={SanitizeLogToken(sourceTransferId ?? "(none)")}; snapshot_generation={initial.Generation}; decision_reason=initial_tuna_readiness_direction_mismatch");
                }
                else if (string.IsNullOrWhiteSpace(initial.ConsumedTransferId) ||
                    string.Equals(initial.ConsumedTransferId, normalizedTransferId, StringComparison.Ordinal))
                {
                    positiveSnapshotEvidence = CreateInitialTunaReadinessEvidenceFromSnapshotUnsafe(
                        initial,
                        normalizedTransferId,
                        direction,
                        DateTimeOffset.UtcNow);
                }
                else
                {
                    consumedSnapshotForOtherTransfer = initial;
                }
            }

            var state = runtimeUnlockTransactionState;
            if (!state.IsTerminal &&
                string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                (string.IsNullOrWhiteSpace(state.TransferId) ||
                 string.Equals(state.TransferId, normalizedTransferId, StringComparison.Ordinal)))
            {
                var lease = runtimeUnlockTunaPathLeaseState;
                var leaseMatches = RuntimeUnlockTunaPathLease.IsApplicableToOffer(
                    lease,
                    state.SessionId,
                    state.TransactionGeneration,
                    state.OfferGeneration);
                var answerAckReceived =
                    !string.IsNullOrWhiteSpace(pendingAccelerationAnswerAckNonce) &&
                    IsRuntimeUnlockActivationReason(pendingAccelerationAnswerAckTrigger) &&
                    string.Equals(pendingAccelerationAnswerAckSessionId, normalizedSessionId, StringComparison.Ordinal);
                var leaseGeneration = leaseMatches ? lease.LeaseGeneration : state.TunaPathLeaseGeneration;
                var listenerRunId = leaseMatches ? lease.ListenerRunId : state.TunaPathLeaseListenerRunId;
                var leaseCurrent = leaseMatches ? lease.IsCurrent : state.TunaPathLeaseCurrent;
                var listenerReady =
                    (leaseMatches ? lease.State : state.TunaPathLeaseState) == RuntimeUnlockTunaPathLeaseState.ListenerReady;
                if (IsPositiveInitialTunaReadinessEvidence(
                        leaseCurrent,
                        listenerReady,
                        state.HasPeerVisibleProof,
                        state.AnswerReceived))
                {
                    if (consumedSnapshotForOtherTransfer is { } consumedSnapshot &&
                        consumedSnapshot.OfferGeneration == state.OfferGeneration &&
                        consumedSnapshot.LeaseGeneration == leaseGeneration)
                    {
                        LocalOperationalLog.Info(
                            "NKN.Tuna",
                            $"event=initial_tuna_readiness_consumed; session_id={SanitizeLogToken(normalizedSessionId)}; transfer_id={SanitizeLogToken(normalizedTransferId)}; consumed_transfer_id={SanitizeLogToken(consumedSnapshot.ConsumedTransferId ?? "(none)")}; snapshot_generation={consumedSnapshot.Generation}; offer_generation={state.OfferGeneration}; tuna_path_lease_generation={leaseGeneration}; decision_reason=positive_readiness_already_consumed");
                        return false;
                    }

                    evidence = new FileTransferInitialTunaReadinessEvidence(
                        normalizedSessionId,
                        normalizedTransferId,
                        direction,
                        DateTimeOffset.UtcNow,
                        leaseGeneration,
                        listenerRunId,
                        leaseCurrent,
                        listenerReady,
                        state.OfferGeneration,
                        state.HasPeerVisibleProof,
                        state.AnswerReceived,
                        answerAckReceived,
                        !string.IsNullOrWhiteSpace(accelerationSessionId) &&
                        string.Equals(accelerationSessionId, normalizedSessionId, StringComparison.Ordinal),
                        FileTransferInitialTunaReadinessScopes.Transfer,
                        SourceTransferId: state.TransferId,
                        SnapshotGeneration: 0,
                        SourceCapturedUtc: DateTimeOffset.UtcNow);
                    return true;
                }

                if (positiveSnapshotEvidence is not null)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=initial_tuna_positive_readiness_shadowed; session_id={SanitizeLogToken(normalizedSessionId)}; transfer_id={SanitizeLogToken(normalizedTransferId)}; active_transaction_generation={state.TransactionGeneration}; active_offer_generation={state.OfferGeneration}; active_lease_generation={leaseGeneration}; active_lease_current={(leaseCurrent ? 1 : 0)}; active_listener_ready={(listenerReady ? 1 : 0)}; active_peer_visible_proof={(state.HasPeerVisibleProof ? 1 : 0)}; active_answer_received={(state.AnswerReceived ? 1 : 0)}; snapshot_lease_generation={positiveSnapshotEvidence.LeaseGeneration}; snapshot_offer_generation={positiveSnapshotEvidence.OfferGeneration}; decision_reason=using_current_positive_readiness_snapshot");
                    evidence = positiveSnapshotEvidence;
                    return true;
                }

                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=initial_tuna_readiness_unavailable; session_id={SanitizeLogToken(normalizedSessionId)}; transfer_id={SanitizeLogToken(normalizedTransferId)}; transaction_generation={state.TransactionGeneration}; offer_generation={state.OfferGeneration}; lease_generation={leaseGeneration}; lease_current={(leaseCurrent ? 1 : 0)}; listener_ready={(listenerReady ? 1 : 0)}; peer_visible_proof={(state.HasPeerVisibleProof ? 1 : 0)}; answer_received={(state.AnswerReceived ? 1 : 0)}; decision_reason=positive_readiness_missing");
                return false;
            }

            if (positiveSnapshotEvidence is not null)
            {
                var preservedSnapshot = initialTunaReadinessState;
                if (preservedSnapshot is not null &&
                    !string.IsNullOrWhiteSpace(preservedSnapshot.SourceTransferId) &&
                    DateTimeOffset.UtcNow - preservedSnapshot.CapturedUtc > InitialTunaReadinessPositiveSnapshotTtl)
                {
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=initial_tuna_session_reactivation_readiness_preserved; session_id={SanitizeLogToken(normalizedSessionId)}; transfer_id={SanitizeLogToken(normalizedTransferId)}; source_transfer_id={SanitizeLogToken(preservedSnapshot.SourceTransferId ?? "(none)")}; snapshot_generation={positiveSnapshotEvidence.SnapshotGeneration}; source_captured_utc_ms={positiveSnapshotEvidence.SourceCapturedUtc.ToUnixTimeMilliseconds()}; evidence_captured_utc_ms={positiveSnapshotEvidence.CapturedUtc.ToUnixTimeMilliseconds()}; offer_generation={positiveSnapshotEvidence.OfferGeneration}; tuna_path_lease_generation={positiveSnapshotEvidence.LeaseGeneration}; decision_reason=session_reactivation_readiness_current_from_live_tuna_lane");
                }

                evidence = positiveSnapshotEvidence;
                return true;
            }

            if (consumedSnapshotForOtherTransfer is not null)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=initial_tuna_readiness_consumed; session_id={SanitizeLogToken(normalizedSessionId)}; transfer_id={SanitizeLogToken(normalizedTransferId)}; consumed_transfer_id={SanitizeLogToken(consumedSnapshotForOtherTransfer.ConsumedTransferId ?? "(none)")}; snapshot_generation={consumedSnapshotForOtherTransfer.Generation}; offer_generation={consumedSnapshotForOtherTransfer.OfferGeneration}; tuna_path_lease_generation={consumedSnapshotForOtherTransfer.LeaseGeneration}; decision_reason=positive_readiness_already_consumed");
            }

            return false;
        }
    }

    void IRuntimeUnlockRouteCommitProofProvider.NotifyRuntimeUnlockRouteCommitResult(
        string sessionId,
        string transferId,
        FileTransferDirection direction,
        long transactionGeneration,
        long offerGeneration,
        bool accepted,
        string reason)
    {
        if (string.IsNullOrWhiteSpace(sessionId) ||
            transactionGeneration <= 0 ||
            offerGeneration <= 0)
        {
            return;
        }

        RuntimeUnlockTransactionDecision? decision;
        var normalizedReason = string.IsNullOrWhiteSpace(reason)
            ? (accepted ? "route_commit_accepted" : "route_commit_rejected")
            : reason.Trim();
        lock (accelerationGate)
        {
            var current = runtimeUnlockTransactionState;
            if (current.IsTerminal ||
                current.TransactionGeneration != transactionGeneration ||
                current.OfferGeneration != offerGeneration ||
                !string.Equals(current.SessionId, sessionId.Trim(), StringComparison.Ordinal))
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    "event=runtime_unlock_transaction_commit_result_stale; " +
                    $"session_id={SanitizeLogToken(sessionId)}; transfer_id={SanitizeLogToken(transferId)}; " +
                    $"transaction_generation={transactionGeneration}; offer_generation={offerGeneration}; " +
                    $"current_transaction_generation={current.TransactionGeneration}; current_offer_generation={current.OfferGeneration}; " +
                    $"current_state={current.State.ToString().ToLowerInvariant()}; accepted={(accepted ? 1 : 0)}; " +
                    $"reason={SanitizeLogToken(normalizedReason)}");
                return;
            }

            decision = ApplyRuntimeUnlockTransactionUnsafe(
                accepted
                    ? RuntimeUnlockTransactionEventKind.RouteCommitted
                    : RuntimeUnlockTransactionEventKind.Failed,
                sessionId.Trim(),
                offerGeneration,
                accepted ? normalizedReason : $"route_commit_rejected_{normalizedReason}",
                transactionGeneration: transactionGeneration);
            if (accepted)
            {
                ClearRuntimeUnlockBrokenStateRetryBudgetUnsafe(sessionId);
                RefreshInitialTunaReadinessFromAcceptedRuntimeUnlockCommitUnsafe(
                    current,
                    direction,
                    normalizedReason);
                MarkRuntimeUnlockPublishedRouteCommitUnsafe(
                    current.SessionId,
                    current.TransactionGeneration,
                    current.OfferGeneration,
                    normalizedReason);
            }
        }

        if (accepted)
        {
            ObserveFileTransferRouteHintEvidence(
                transferId,
                FileTransferRouteResolver.FileTunaV4Token,
                FileTransferProtocol.ProtocolVersionV4,
                "runtime_unlock_route_commit_accepted",
                normalizedReason);
        }

        LogRuntimeUnlockTransactionDecision(
            accepted
                ? RuntimeUnlockTransactionEventKind.RouteCommitted
                : RuntimeUnlockTransactionEventKind.Failed,
            decision);
        NotifyTransportAccelerationStateChanged(normalizedReason);
    }

    private RuntimeUnlockTransactionDecision StartRuntimeUnlockTransactionForOfferUnsafe(
        string sessionId,
        long offerGeneration,
        string reason)
    {
        var current = runtimeUnlockTransactionState;
        var transactionGeneration =
            current is
            {
                IsTerminal: false,
            } &&
            string.Equals(current.SessionId, sessionId.Trim(), StringComparison.Ordinal)
                ? current.TransactionGeneration
                : ++runtimeUnlockTransactionNextGeneration;
        if (transactionGeneration <= 0)
        {
            transactionGeneration = ++runtimeUnlockTransactionNextGeneration;
        }

        return ApplyRuntimeUnlockTransactionUnsafe(
            RuntimeUnlockTransactionEventKind.OfferGenerationCreated,
            sessionId,
            offerGeneration,
            reason,
            transactionGeneration: transactionGeneration);
    }

    private void ApplyRuntimeUnlockTransaction(
        RuntimeUnlockTransactionEventKind kind,
        string? sessionId,
        long offerGeneration,
        string reason,
        string? observedLane = null)
    {
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return;
        }

        RuntimeUnlockTransactionDecision? decision;
        lock (accelerationGate)
        {
            decision = ApplyRuntimeUnlockTransactionUnsafe(
                kind,
                sessionId.Trim(),
                offerGeneration,
                reason,
                observedLane: observedLane);
        }

        LogRuntimeUnlockTransactionDecision(kind, decision);
    }

    private RuntimeUnlockTransactionDecision ApplyRuntimeUnlockTransactionUnsafe(
        RuntimeUnlockTransactionEventKind kind,
        string sessionId,
        long offerGeneration,
        string reason,
        long transactionGeneration = 0,
        string? observedLane = null,
        string? pathProbeId = null,
        FileTransferTransportKind pathProbeTransport = FileTransferTransportKind.Unknown)
    {
        var effectiveTransactionGeneration = transactionGeneration > 0
            ? transactionGeneration
            : runtimeUnlockTransactionState.TransactionGeneration;
        var decision = RuntimeUnlockTransaction.Apply(
            new RuntimeUnlockTransactionEvent(
                kind,
                sessionId,
                TransferId: null,
                effectiveTransactionGeneration,
                offerGeneration,
                SanitizeLogToken(reason),
                UtcMs: DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                ObservedLane: observedLane,
                PathProbeId: pathProbeId,
                PathProbeTransport: pathProbeTransport),
            runtimeUnlockTransactionState);
        var stateWithLease = AttachRuntimeUnlockTunaPathLeaseUnsafe(decision.State);
        runtimeUnlockTransactionState = stateWithLease;
        if (kind is RuntimeUnlockTransactionEventKind.OfferGenerationCreated or
            RuntimeUnlockTransactionEventKind.Failed or
            RuntimeUnlockTransactionEventKind.Retired or
            RuntimeUnlockTransactionEventKind.RouteCommitted)
        {
            ClearRuntimeUnlockPublishedRouteCommitUnsafe();
            ClearRuntimeUnlockPreCommitProbeLaunchUnsafe();
        }

        return decision with { State = stateWithLease };
    }

    private void MarkRuntimeUnlockPublishedRouteCommitUnsafe(
        string sessionId,
        long transactionGeneration,
        long offerGeneration,
        string reason)
    {
        if (string.IsNullOrWhiteSpace(sessionId) ||
            transactionGeneration <= 0 ||
            offerGeneration <= 0)
        {
            return;
        }

        runtimeUnlockPublishedRouteCommitSessionId = sessionId.Trim();
        runtimeUnlockPublishedRouteCommitTransactionGeneration = transactionGeneration;
        runtimeUnlockPublishedRouteCommitOfferGeneration = offerGeneration;
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_paired_route_commit_publication_enabled; session_id={SanitizeLogToken(runtimeUnlockPublishedRouteCommitSessionId)}; transaction_generation={transactionGeneration}; offer_generation={offerGeneration}; reason={SanitizeLogToken(reason)}");
    }

    private void ClearRuntimeUnlockPublishedRouteCommitUnsafe()
    {
        runtimeUnlockPublishedRouteCommitSessionId = null;
        runtimeUnlockPublishedRouteCommitTransactionGeneration = 0;
        runtimeUnlockPublishedRouteCommitOfferGeneration = 0;
    }

    private void ClearRuntimeUnlockPreCommitProbeLaunchUnsafe()
    {
        if (runtimeUnlockPreCommitProbeLaunchSessionId is null &&
            runtimeUnlockPreCommitProbeLaunchTransferId is null &&
            runtimeUnlockPreCommitProbeLaunchTransactionGeneration == 0 &&
            runtimeUnlockPreCommitProbeLaunchOfferGeneration == 0 &&
            runtimeUnlockPreCommitProbeLaunchSnapshot is null &&
            runtimeUnlockPreCommitProbeStartedSnapshot is null &&
            runtimeUnlockAcceptedPreCommitSnapshot is null)
        {
            return;
        }

        runtimeUnlockPreCommitProbeLaunchSessionId = null;
        runtimeUnlockPreCommitProbeLaunchTransferId = null;
        runtimeUnlockPreCommitProbeLaunchTransactionGeneration = 0;
        runtimeUnlockPreCommitProbeLaunchOfferGeneration = 0;
        runtimeUnlockPreCommitProbeLaunchSnapshot = null;
        runtimeUnlockPreCommitProbeStartedSnapshot = null;
        runtimeUnlockAcceptedPreCommitSnapshot = null;
        runtimeUnlockPreCommitProbeLaunchGeneration++;
        runtimeUnlockPreCommitProbeLaunchTimeoutScheduled = false;
        ClearRuntimeUnlockPreCommitProbeLaunchHoldUnsafe();
    }

    private void ClearRuntimeUnlockPreCommitProbeLaunchHoldUnsafe()
    {
        runtimeUnlockPreCommitProbeLaunchHeldByCoordinatorDenial = false;
        runtimeUnlockPreCommitProbeLaunchHeldReason = null;
        runtimeUnlockPreCommitProbeLaunchHeldAdmissionReason = null;
        runtimeUnlockPreCommitProbeLaunchHeldDirection = null;
    }

    private bool HasRuntimeUnlockPublishedRouteCommitUnsafe(string? sessionId)
    {
        var state = runtimeUnlockTransactionState;
        return !string.IsNullOrWhiteSpace(sessionId) &&
               state.RouteCommitted &&
               state.TransactionGeneration > 0 &&
               state.OfferGeneration > 0 &&
               string.Equals(state.SessionId, sessionId.Trim(), StringComparison.Ordinal) &&
               string.Equals(runtimeUnlockPublishedRouteCommitSessionId, state.SessionId, StringComparison.Ordinal) &&
               runtimeUnlockPublishedRouteCommitTransactionGeneration == state.TransactionGeneration &&
               runtimeUnlockPublishedRouteCommitOfferGeneration == state.OfferGeneration;
    }

    private RuntimeUnlockTransactionSnapshot AttachRuntimeUnlockTunaPathLeaseUnsafe(
        RuntimeUnlockTransactionSnapshot state)
    {
        var lease = runtimeUnlockTunaPathLeaseState;
        if (!RuntimeUnlockTunaPathLease.IsApplicableToOffer(
                lease,
                state.SessionId,
                state.TransactionGeneration,
                state.OfferGeneration))
        {
            return state with
            {
                TunaPathLeaseGeneration = 0,
                TunaPathLeaseState = RuntimeUnlockTunaPathLeaseState.None,
                TunaPathLeaseListenerRunId = null,
                TunaPathLeaseCurrent = false,
                TunaPathLeaseFailureReason = null,
            };
        }

        return state with
        {
            TunaPathLeaseGeneration = lease.LeaseGeneration,
            TunaPathLeaseState = lease.State,
            TunaPathLeaseListenerRunId = lease.ListenerRunId,
            TunaPathLeaseCurrent = lease.IsCurrent,
            TunaPathLeaseFailureReason = lease.FailureReason,
        };
    }

    private void LogRuntimeUnlockTransactionDecision(
        RuntimeUnlockTransactionEventKind kind,
        RuntimeUnlockTransactionDecision? decision)
    {
        if (decision is null)
        {
            return;
        }

        var state = decision.State;
        var parentRetryDispatchAuthorityId = GetRuntimeUnlockRetryDispatchParentAuthorityId(
            state.SessionId,
            state.OfferGeneration);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_transaction_{GetRuntimeUnlockTransactionEventName(kind)}; session_id={SanitizeLogToken(state.SessionId)}; transaction_generation={state.TransactionGeneration}; offer_generation={state.OfferGeneration}; parent_runtime_unlock_retry_authority_id={SanitizeLogToken(parentRetryDispatchAuthorityId)}; state={state.State.ToString().ToLowerInvariant()}; peer_visible_proof={(state.HasPeerVisibleProof ? 1 : 0)}; peer_received={(state.PeerReceived ? 1 : 0)}; answer_received={(state.AnswerReceived ? 1 : 0)}; path_probe_id={SanitizeLogToken(state.PathProbeId ?? "(none)")}; path_probe_state={state.PathProbeState.ToString().ToLowerInvariant()}; path_probe_transport={FormatFileTransferTransportKindForLog(state.PathProbeTransport)}; path_probe_acked_utc_ms={state.PathProbeAckedUtcMs}; path_probe_failure_reason={SanitizeLogToken(state.PathProbeFailureReason ?? "(none)")}; route_commit_pending={(state.RouteCommitPending ? 1 : 0)}; route_committed={(state.RouteCommitted ? 1 : 0)}; failure_reason={SanitizeLogToken(state.FailureReason ?? "(none)")}; retired_reason={SanitizeLogToken(state.RetiredReason ?? "(none)")}; tuna_path_lease_generation={state.TunaPathLeaseGeneration}; tuna_path_lease_state={state.TunaPathLeaseState.ToString().ToLowerInvariant()}; tuna_path_lease_current={(state.TunaPathLeaseCurrent ? 1 : 0)}; tuna_path_lease_listener_run_id={SanitizeLogToken(state.TunaPathLeaseListenerRunId ?? "(none)")}; tuna_path_lease_failure_reason={SanitizeLogToken(state.TunaPathLeaseFailureReason ?? "(none)")}; reason={SanitizeLogToken(decision.Reason)}");
    }

    private string GetRuntimeUnlockRetryDispatchParentAuthorityId(string sessionId, long offerGeneration)
    {
        var contract = runtimeUnlockRecoveryRetryState?.DispatchContract;
        return contract is not null &&
               string.Equals(contract.Authority.SessionId, sessionId, StringComparison.Ordinal) &&
               (offerGeneration <= 0 || contract.MatchesOfferAlias(offerGeneration))
            ? contract.Authority.AuthorityId.ToString()
            : "(none)";
    }

    private static string GetRuntimeUnlockTransactionEventName(RuntimeUnlockTransactionEventKind kind)
        => kind switch
        {
            RuntimeUnlockTransactionEventKind.ListenerReady => "listener_ready",
            RuntimeUnlockTransactionEventKind.ListenerUnavailable => "listener_unavailable",
            RuntimeUnlockTransactionEventKind.OfferGenerationCreated => "offer_generation_created",
            RuntimeUnlockTransactionEventKind.ObservedSend => "observed_send",
            RuntimeUnlockTransactionEventKind.PeerReceived => "peer_received",
            RuntimeUnlockTransactionEventKind.AnswerReceived => "answer_received",
            RuntimeUnlockTransactionEventKind.PathProbeStarted => "path_probe_started",
            RuntimeUnlockTransactionEventKind.PathProbeAcked => "path_probe_acked",
            RuntimeUnlockTransactionEventKind.PathProbeFailed => "path_probe_failed",
            RuntimeUnlockTransactionEventKind.Timeout => "timeout",
            RuntimeUnlockTransactionEventKind.BridgeRecoveryStarted => "bridge_recovery_started",
            RuntimeUnlockTransactionEventKind.BridgeRecoverySettled => "bridge_recovery_settled",
            RuntimeUnlockTransactionEventKind.BridgeRecoveryExhausted => "bridge_recovery_exhausted",
            RuntimeUnlockTransactionEventKind.LivenessDeadline => "liveness_deadline",
            RuntimeUnlockTransactionEventKind.RouteCommitted => "route_committed",
            RuntimeUnlockTransactionEventKind.Terminalized => "terminalized",
            RuntimeUnlockTransactionEventKind.Failed => "failed",
            RuntimeUnlockTransactionEventKind.Retired => "retired",
            _ => kind.ToString().ToLowerInvariant(),
        };

    private static string GetRuntimeUnlockProbeEventName(RuntimeUnlockTransactionEventKind kind)
        => kind switch
        {
            RuntimeUnlockTransactionEventKind.PathProbeStarted => "runtime_unlock_probe_started",
            RuntimeUnlockTransactionEventKind.PathProbeAcked => "runtime_unlock_probe_acked",
            RuntimeUnlockTransactionEventKind.PathProbeFailed => "runtime_unlock_probe_failed",
            _ => "runtime_unlock_probe_event",
        };

    private bool IsFileTransferRuntimeUnlockContextObserved(string sessionId)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            return false;
        }

        lock (gate)
        {
            if (fileTransferRuntimeUnlockAuthorityRequirements.ContainsKey(normalizedSessionId))
            {
                return true;
            }
        }

        lock (accelerationGate)
        {
            if (runtimeUnlockRecoveryRetryState is { } state &&
                state.ContractState is not (SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed) &&
                string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                (!string.IsNullOrWhiteSpace(state.TransferId) ||
                 !string.IsNullOrWhiteSpace(state.RegularV4RecoveryBlockedTransferId)))
            {
                return true;
            }

            if (fileTransferRegularV4RecoveryLivenessState is { } liveness &&
                string.Equals(liveness.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                !liveness.Completed)
            {
                return true;
            }
        }

        if (HasActiveFileTransferDataSessionForSession(normalizedSessionId))
        {
            return true;
        }

        lock (gate)
        {
            return fileTransferRoutePublicationAuthorities.Any(pair =>
                string.Equals(pair.Key.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                string.Equals(
                    pair.Value.SessionId,
                    normalizedSessionId,
                    StringComparison.Ordinal));
        }
    }

    private bool TryCaptureCurrentRuntimeUnlockFileTransferOwnerAuthority(
        string sessionId,
        out FileTransferRoutePublicationAuthority authority,
        out string rejectionReason)
    {
        authority = null!;
        rejectionReason = "unknown";
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            rejectionReason = "missing_session_id";
            return false;
        }

        var (expectedTransferId, expectedDirection) =
            ResolveExpectedRuntimeUnlockFileTransferOwner(normalizedSessionId);

        List<FileTransferRoutePublicationAuthority> candidates;
        var hasSessionRoutePublicationAuthority = false;
        lock (gate)
        {
            hasSessionRoutePublicationAuthority = fileTransferRoutePublicationAuthorities.Any(pair =>
                string.Equals(pair.Key.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                string.Equals(
                    pair.Value.SessionId,
                    normalizedSessionId,
                    StringComparison.Ordinal));
            candidates = fileTransferRoutePublicationAuthorities
                .Where(pair =>
                    IsCurrentRuntimeUnlockFileTransferOwnerAuthority(
                        pair.Key,
                        pair.Value,
                        normalizedSessionId,
                        expectedTransferId,
                        expectedDirection))
                .Select(pair => pair.Value)
                .ToList();
        }

        if (candidates.Count == 0)
        {
            rejectionReason = hasSessionRoutePublicationAuthority
                ? "current_filetransfer_owner_authority_mismatch"
                : "missing_current_filetransfer_route_publication_authority";
            return false;
        }

        var distinctTransferIds = candidates
            .Select(candidate => candidate.TransferId)
            .Distinct(StringComparer.Ordinal)
            .ToArray();
        if (distinctTransferIds.Length != 1)
        {
            rejectionReason = "ambiguous_current_filetransfer_owner_authority";
            return false;
        }

        authority = candidates
            .OrderByDescending(candidate => candidate.Direction == FileTransferDirection.Outbound)
            .ThenByDescending(candidate => candidate.RoutePublicationGeneration)
            .First();
        rejectionReason = "accepted";
        return true;
    }

    private bool TryCaptureCurrentRuntimeUnlockFileTransferOwnerAndDataSession(
        string sessionId,
        out FileTransferRoutePublicationAuthority authority,
        out long dataSessionGeneration,
        out string rejectionReason)
    {
        authority = null!;
        dataSessionGeneration = 0;
        rejectionReason = "unknown";
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? string.Empty
            : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            rejectionReason = "missing_session_id";
            return false;
        }

        var (expectedTransferId, expectedDirection) =
            ResolveExpectedRuntimeUnlockFileTransferOwner(normalizedSessionId);

        lock (gate)
        {
            var candidates = fileTransferRoutePublicationAuthorities
                .Where(pair =>
                    IsCurrentRuntimeUnlockFileTransferOwnerAuthority(
                        pair.Key,
                        pair.Value,
                        normalizedSessionId,
                        expectedTransferId,
                        expectedDirection))
                .Select(pair => pair.Value)
                .ToList();
            if (candidates.Count == 0)
            {
                rejectionReason = fileTransferRoutePublicationAuthorities.Any(pair =>
                    string.Equals(pair.Key.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                    string.Equals(pair.Value.SessionId, normalizedSessionId, StringComparison.Ordinal))
                    ? "current_filetransfer_owner_authority_mismatch"
                    : "missing_current_filetransfer_route_publication_authority";
                return false;
            }

            if (candidates
                    .Select(candidate => candidate.TransferId)
                    .Distinct(StringComparer.Ordinal)
                    .Skip(1)
                    .Any())
            {
                rejectionReason = "ambiguous_current_filetransfer_owner_authority";
                return false;
            }

            authority = candidates
                .OrderByDescending(candidate => candidate.Direction == FileTransferDirection.Outbound)
                .ThenByDescending(candidate => candidate.RoutePublicationGeneration)
                .First();
            if (!fileTransferDataSessions.TryGetValue(authority.TransferId, out var session) ||
                session.IsDisposed ||
                !string.Equals(session.SessionId, authority.SessionId, StringComparison.Ordinal) ||
                session.Generation <= 0)
            {
                authority = null!;
                rejectionReason = "current_filetransfer_data_session_missing";
                return false;
            }

            dataSessionGeneration = session.Generation;
            rejectionReason = "accepted";
            return true;
        }
    }

    private (string? TransferId, FileTransferDirection? Direction) ResolveExpectedRuntimeUnlockFileTransferOwner(
        string sessionId)
    {
        string? expectedTransferId = null;
        FileTransferDirection? expectedDirection = null;
        lock (accelerationGate)
        {
            if (runtimeUnlockRecoveryRetryState is { } state &&
                state.ContractState is not (SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed) &&
                string.Equals(state.SessionId, sessionId, StringComparison.Ordinal))
            {
                expectedTransferId = string.IsNullOrWhiteSpace(state.TransferId)
                    ? state.RegularV4RecoveryBlockedTransferId
                    : state.TransferId;
                expectedDirection = state.RegularV4RecoveryDirection ??
                    GetRuntimeUnlockRetryExpectedDispatchDirection(state);
            }

            if (string.IsNullOrWhiteSpace(expectedTransferId) &&
                fileTransferRegularV4RecoveryLivenessState is { } liveness &&
                string.Equals(liveness.SessionId, sessionId, StringComparison.Ordinal) &&
                !liveness.Completed)
            {
                expectedTransferId = liveness.TransferId;
                expectedDirection = liveness.Direction;
            }
        }

        expectedTransferId = string.IsNullOrWhiteSpace(expectedTransferId)
            ? ResolveSingleActiveFileTransferDataSessionTransferId(sessionId, transferId: null)
            : expectedTransferId.Trim();
        var hasActiveFileTransferDataSession = HasActiveFileTransferDataSessionForSession(sessionId);

        lock (gate)
        {
            if (fileTransferRuntimeUnlockAuthorityRequirements.TryGetValue(sessionId, out var requirement) &&
                ((!string.IsNullOrWhiteSpace(expectedTransferId) &&
                  string.Equals(expectedTransferId, requirement.TransferId, StringComparison.Ordinal)) ||
                 (string.IsNullOrWhiteSpace(expectedTransferId) && !hasActiveFileTransferDataSession)))
            {
                if (string.IsNullOrWhiteSpace(expectedTransferId))
                {
                    expectedTransferId = requirement.TransferId;
                }

                expectedDirection ??= requirement.Direction;
            }
        }

        return (expectedTransferId, expectedDirection);
    }

    private static bool IsCurrentRuntimeUnlockFileTransferOwnerAuthority(
        FileTransferRouteHintKey key,
        FileTransferRoutePublicationAuthority authority,
        string sessionId,
        string? expectedTransferId,
        FileTransferDirection? expectedDirection)
    {
        if (!string.Equals(key.SessionId, sessionId, StringComparison.Ordinal) ||
            !string.Equals(authority.SessionId, sessionId, StringComparison.Ordinal) ||
            !string.Equals(key.TransferId, authority.TransferId, StringComparison.Ordinal) ||
            key.Direction != authority.Direction ||
            (!string.IsNullOrWhiteSpace(expectedTransferId) &&
             !string.Equals(authority.TransferId, expectedTransferId, StringComparison.Ordinal)) ||
            (expectedDirection.HasValue && authority.Direction != expectedDirection.Value) ||
            authority.RuntimeGeneration <= 0 ||
            authority.LegGeneration <= 0 ||
            authority.RoutePublicationGeneration <= 0)
        {
            return false;
        }

        return (string.Equals(authority.RouteToken, FileTransferRouteResolver.RegularNknV4FastToken, StringComparison.Ordinal) &&
                authority.ProtocolVersion == FileTransferProtocol.ProtocolVersionV4 &&
                authority.TargetTransport == FileTransferTransportKind.RegularNkn) ||
               (string.Equals(authority.RouteToken, FileTransferRouteResolver.PostTunaFallbackV6Token, StringComparison.Ordinal) &&
                authority.ProtocolVersion == FileTransferProtocol.ProtocolVersionV6 &&
                authority.TargetTransport == FileTransferTransportKind.RegularNkn);
    }

    private static void LogRuntimeUnlockFileTransferOwnerAcceptedBeforePathLease(
        FileTransferRoutePublicationAuthority authority,
        string trigger)
        => LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_filetransfer_owner_accepted_before_path_lease; session_id={SanitizeLogToken(authority.SessionId)}; transfer_id={SanitizeLogToken(authority.TransferId)}; direction={authority.Direction.ToString().ToLowerInvariant()}; route={SanitizeLogToken(authority.RouteToken)}; protocol_version={authority.ProtocolVersion}; live_route_epoch={authority.LiveRouteEpoch}; runtime_generation={authority.RuntimeGeneration}; terminal_generation={authority.TerminalGeneration}; leg_generation={authority.LegGeneration}; route_publication_generation={authority.RoutePublicationGeneration}; route_commit_generation={authority.RouteCommitGeneration ?? 0}; target_route={SanitizeLogToken(authority.TargetRouteToken)}; target_protocol_version={authority.TargetProtocolVersion}; target_transport={FormatFileTransferTransportKindForLog(authority.TargetTransport)}; trigger={SanitizeLogToken(trigger)}; decision_reason=current_coordinator_route_publication_authority");

    private void LogRuntimeUnlockFileTransferOwnerRejectedBeforePathLease(
        string sessionId,
        string trigger,
        string rejectionReason)
    {
        var normalizedSessionId = SanitizeLogToken(sessionId);
        var normalizedTrigger = SanitizeLogToken(trigger);
        var normalizedReason = SanitizeLogToken(rejectionReason);
        var (expectedTransferId, expectedDirection) =
            ResolveExpectedRuntimeUnlockFileTransferOwner(sessionId);
        var normalizedTransferId = SanitizeLogToken(expectedTransferId ?? "(none)");
        var normalizedDirection = expectedDirection?.ToString().ToLowerInvariant() ?? "(none)";
        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=runtime_unlock_filetransfer_owner_missing_before_path_lease; session_id={normalizedSessionId}; transfer_id={normalizedTransferId}; direction={normalizedDirection}; trigger={normalizedTrigger}; rejection_reason={normalizedReason}; decision_reason=coordinator_filetransfer_owner_required");
        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=runtime_unlock_filetransfer_path_lease_rejected_no_current_owner; session_id={normalizedSessionId}; transfer_id={normalizedTransferId}; direction={normalizedDirection}; trigger={normalizedTrigger}; rejection_reason={normalizedReason}; decision_reason=no_listener_or_path_lease_effect");
    }

    private static void LogRuntimeUnlockFileTransferOwnerRejectedBeforeOfferDispatch(
        string sessionId,
        string? transferId,
        string trigger,
        string rejectionReason)
        => LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=runtime_unlock_filetransfer_owner_stale_before_offer_dispatch; session_id={SanitizeLogToken(sessionId)}; transfer_id={SanitizeLogToken(transferId ?? "(none)")}; trigger={SanitizeLogToken(trigger)}; rejection_reason={SanitizeLogToken(rejectionReason)}; decision_reason=no_offer_or_route_effect");

    private RuntimeUnlockTunaPathLeaseSnapshot StartRuntimeUnlockTunaPathLeaseUnsafe(
        string sessionId,
        string? transferId,
        long payerDecisionId,
        string reason)
    {
        var leaseGeneration = ++runtimeUnlockTunaPathLeaseNextGeneration;
        var listenerRunId = $"listener-start-{leaseGeneration.ToString(CultureInfo.InvariantCulture)}";
        var lease = RuntimeUnlockTunaPathLease.Start(
            sessionId,
            transferId,
            leaseGeneration,
            listenerRunId,
            payerDecisionId,
            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
        runtimeUnlockTunaPathLeaseState = lease;
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_path_lease_started; session_id={SanitizeLogToken(lease.SessionId)}; transfer_id={SanitizeLogToken(lease.TransferId ?? "(none)")}; transaction_generation={lease.TransactionGeneration}; offer_generation={lease.OfferGeneration}; lease_generation={lease.LeaseGeneration}; listener_run_id={SanitizeLogToken(lease.ListenerRunId ?? "(none)")}; payer_decision_id={lease.PayerDecisionId}; state={lease.State.ToString().ToLowerInvariant()}; reason={SanitizeLogToken(reason)}");
        return lease;
    }

    private RuntimeUnlockTunaPathLeaseSnapshot BindRuntimeUnlockTunaPathLeaseToOfferUnsafe(
        RuntimeUnlockTunaPathLeaseSnapshot lease,
        long transactionGeneration,
        long offerGeneration,
        long payerDecisionId,
        string reason)
    {
        if (lease.LeaseGeneration <= 0 ||
            runtimeUnlockTunaPathLeaseState.LeaseGeneration != lease.LeaseGeneration)
        {
            return runtimeUnlockTunaPathLeaseState;
        }

        var bound = RuntimeUnlockTunaPathLease.BindOffer(
            runtimeUnlockTunaPathLeaseState,
            transactionGeneration,
            offerGeneration,
            payerDecisionId,
            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
        runtimeUnlockTunaPathLeaseState = bound;
        runtimeUnlockTransactionState = AttachRuntimeUnlockTunaPathLeaseUnsafe(runtimeUnlockTransactionState);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_path_lease_listener_starting; session_id={SanitizeLogToken(bound.SessionId)}; transfer_id={SanitizeLogToken(bound.TransferId ?? "(none)")}; transaction_generation={bound.TransactionGeneration}; offer_generation={bound.OfferGeneration}; lease_generation={bound.LeaseGeneration}; listener_run_id={SanitizeLogToken(bound.ListenerRunId ?? "(none)")}; payer_decision_id={bound.PayerDecisionId}; state={bound.State.ToString().ToLowerInvariant()}; reason={SanitizeLogToken(reason)}");
        return bound;
    }

    private void MarkRuntimeUnlockTunaPathLeaseListenerReady(
        RuntimeUnlockTunaPathLeaseSnapshot lease,
        string sessionId,
        string reason)
    {
        RuntimeUnlockTunaPathLeaseSnapshot? loggedLease = null;
        RuntimeUnlockTunaPathLeaseSnapshot? staleLease = null;
        RuntimeUnlockTransactionDecision? transactionDecision = null;
        lock (accelerationGate)
        {
            if (RuntimeUnlockTunaPathLease.TryMarkListenerReady(
                    runtimeUnlockTunaPathLeaseState,
                    sessionId,
                    lease.LeaseGeneration,
                    lease.ListenerRunId,
                    DateTimeOffset.UtcNow.ToUnixTimeMilliseconds(),
                    out var updated))
            {
                runtimeUnlockTunaPathLeaseState = updated;
                if (!runtimeUnlockTransactionState.IsTerminal &&
                    string.Equals(runtimeUnlockTransactionState.SessionId, updated.SessionId, StringComparison.Ordinal))
                {
                    transactionDecision = ApplyRuntimeUnlockTransactionUnsafe(
                        RuntimeUnlockTransactionEventKind.ListenerReady,
                        updated.SessionId,
                        runtimeUnlockTransactionState.OfferGeneration,
                        reason);
                }

                runtimeUnlockTransactionState = AttachRuntimeUnlockTunaPathLeaseUnsafe(runtimeUnlockTransactionState);
                loggedLease = updated;
            }
            else if (lease.LeaseGeneration > 0)
            {
                staleLease = lease;
            }
        }

        if (transactionDecision is not null)
        {
            LogRuntimeUnlockTransactionDecision(RuntimeUnlockTransactionEventKind.ListenerReady, transactionDecision);
        }

        if (loggedLease is not null)
        {
            LogRuntimeUnlockTunaPathLease("tuna_path_lease_listener_ready", loggedLease.Value, reason);
        }
        else if (staleLease is not null)
        {
            LogRuntimeUnlockTunaPathLease("tuna_path_lease_stale_listener_event_ignored", staleLease.Value, reason);
        }
    }

    private bool FailRuntimeUnlockTunaPathProbeForSidecarDropIfActive(string? sessionId, string sidecarReason)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        var normalizedSidecarReason = SanitizeLogToken(sidecarReason);
        RuntimeUnlockTransactionSnapshot? previous = null;
        RuntimeUnlockTransactionDecision? decision = null;
        lock (accelerationGate)
        {
            var current = runtimeUnlockTransactionState;
            if (current.IsTerminal ||
                current.PathProbeState != RuntimeUnlockPathProbeState.Started ||
                string.IsNullOrWhiteSpace(current.PathProbeId) ||
                (!string.IsNullOrWhiteSpace(normalizedSessionId) &&
                 !string.Equals(current.SessionId, normalizedSessionId, StringComparison.Ordinal)))
            {
                return false;
            }

            previous = current;
            decision = ApplyRuntimeUnlockTransactionUnsafe(
                RuntimeUnlockTransactionEventKind.PathProbeFailed,
                current.SessionId,
                current.OfferGeneration,
                "runtime_unlock_tuna_probe_sidecar_closed",
                transactionGeneration: current.TransactionGeneration,
                pathProbeId: current.PathProbeId,
                pathProbeTransport: current.PathProbeTransport == FileTransferTransportKind.Unknown
                    ? FileTransferTransportKind.Tuna
                    : current.PathProbeTransport);
        }

        if (previous is null || decision is null)
        {
            return false;
        }

        var probeTransport = previous.PathProbeTransport == FileTransferTransportKind.Unknown
            ? FileTransferTransportKind.Tuna
            : previous.PathProbeTransport;
        LogRuntimeUnlockTransactionDecision(RuntimeUnlockTransactionEventKind.PathProbeFailed, decision);
        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=runtime_unlock_tuna_probe_sidecar_failure; session_id={SanitizeLogToken(previous.SessionId)}; transfer_id={SanitizeLogToken(previous.TransferId ?? "(none)")}; transaction_generation={previous.TransactionGeneration}; offer_generation={previous.OfferGeneration}; tuna_path_lease_generation={previous.TunaPathLeaseGeneration}; probe_id={SanitizeLogToken(previous.PathProbeId ?? "(none)")}; target_transport={FormatFileTransferTransportKindForLog(probeTransport)}; sidecar_reason={normalizedSidecarReason}; reason=runtime_unlock_tuna_probe_sidecar_closed");
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_probe_failed; session_id={SanitizeLogToken(previous.SessionId)}; transfer_id={SanitizeLogToken(previous.TransferId ?? "(none)")}; transaction_generation={decision.State.TransactionGeneration}; offer_generation={decision.State.OfferGeneration}; probe_id={SanitizeLogToken(previous.PathProbeId ?? "(none)")}; target_transport={FormatFileTransferTransportKindForLog(probeTransport)}; transport_epoch=0; acked=0; state={decision.State.PathProbeState.ToString().ToLowerInvariant()}; reason=runtime_unlock_tuna_probe_sidecar_closed; sidecar_reason={normalizedSidecarReason}");
        NotifyTransportAccelerationStateChanged("runtime_unlock_tuna_probe_sidecar_closed");
        return true;
    }

    private bool FailRuntimeUnlockTunaPathLeaseIfCurrent(
        string? sessionId,
        long offerGeneration,
        string reason,
        bool failTransaction)
    {
        RuntimeUnlockTunaPathLeaseSnapshot? failedLease = null;
        RuntimeUnlockTransactionDecision? transactionDecision = null;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        lock (accelerationGate)
        {
            var lease = runtimeUnlockTunaPathLeaseState;
            if (lease.LeaseGeneration <= 0 ||
                lease.State is RuntimeUnlockTunaPathLeaseState.Failed or RuntimeUnlockTunaPathLeaseState.Retired ||
                (!string.IsNullOrWhiteSpace(normalizedSessionId) &&
                 !string.Equals(lease.SessionId, normalizedSessionId, StringComparison.Ordinal)) ||
                (offerGeneration > 0 && lease.OfferGeneration > 0 && lease.OfferGeneration != offerGeneration))
            {
                return false;
            }

            var failed = RuntimeUnlockTunaPathLease.Fail(
                lease,
                reason,
                DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
            runtimeUnlockTunaPathLeaseState = failed;
            if (initialTunaReadinessState is { } initial &&
                string.Equals(initial.SessionId, failed.SessionId, StringComparison.Ordinal) &&
                initial.OfferGeneration == failed.OfferGeneration &&
                initial.LeaseGeneration == failed.LeaseGeneration)
            {
                initialTunaReadinessState = null;
            }

            runtimeUnlockTransactionState = AttachRuntimeUnlockTunaPathLeaseUnsafe(runtimeUnlockTransactionState);
            if (failTransaction &&
                !runtimeUnlockTransactionState.IsTerminal &&
                string.Equals(runtimeUnlockTransactionState.SessionId, failed.SessionId, StringComparison.Ordinal))
            {
                transactionDecision = ApplyRuntimeUnlockTransactionUnsafe(
                    RuntimeUnlockTransactionEventKind.Failed,
                    failed.SessionId,
                    runtimeUnlockTransactionState.OfferGeneration,
                    reason);
            }

            failedLease = failed;
        }

        if (transactionDecision is not null)
        {
            LogRuntimeUnlockTransactionDecision(RuntimeUnlockTransactionEventKind.Failed, transactionDecision);
        }

        if (failedLease is not null)
        {
            LogRuntimeUnlockTunaPathLease("tuna_path_lease_failed", failedLease.Value, reason);
            if (reason.Contains("sidecar", StringComparison.OrdinalIgnoreCase) ||
                reason.Contains("listener", StringComparison.OrdinalIgnoreCase) ||
                reason.Contains("tuna_path_lease_unavailable", StringComparison.OrdinalIgnoreCase))
            {
                LogRuntimeUnlockTunaPathLease("tuna_path_lease_sidecar_unavailable", failedLease.Value, reason);
            }
        }

        return failedLease is not null;
    }

    private bool IsRuntimeUnlockTunaPathLeaseUnavailableForAnswer(
        string sessionId,
        long offerGeneration,
        out string reason)
    {
        reason = "none";
        lock (accelerationGate)
        {
            var lease = runtimeUnlockTunaPathLeaseState;
            if (!RuntimeUnlockTunaPathLease.IsApplicableToOffer(
                    lease,
                    sessionId,
                    runtimeUnlockTransactionState.TransactionGeneration,
                    offerGeneration))
            {
                return false;
            }

            if (RuntimeUnlockTunaPathLease.CanSatisfyRouteCommit(lease))
            {
                return false;
            }

            reason = lease.State == RuntimeUnlockTunaPathLeaseState.Failed
                ? lease.FailureReason ?? "tuna_path_lease_failed"
                : "tuna_path_lease_unavailable";
            return true;
        }
    }

    private bool HasFailedRuntimeUnlockTunaPathLeaseForCurrentSession(string? sessionId)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? currentSessionSecurityState.SessionId?.Value ?? string.Empty : sessionId.Trim();
        lock (accelerationGate)
        {
            return runtimeUnlockTunaPathLeaseState.LeaseGeneration > 0 &&
                   runtimeUnlockTunaPathLeaseState.State == RuntimeUnlockTunaPathLeaseState.Failed &&
                   (string.IsNullOrWhiteSpace(normalizedSessionId) ||
                    string.Equals(runtimeUnlockTunaPathLeaseState.SessionId, normalizedSessionId, StringComparison.Ordinal));
        }
    }

