            $"event={SanitizeLogToken(eventName)}; session_id={SanitizeLogToken(stateSnapshot.SessionId)}; transfer_id={SanitizeLogToken(stateSnapshot.TransferId ?? "(none)")}; contract_generation={stateSnapshot.ContractGeneration}; offer_generation={(stateSnapshot.CurrentOfferGeneration > 0 ? stateSnapshot.CurrentOfferGeneration : stateSnapshot.RetiredOfferGeneration)}; retired_offer_generation={stateSnapshot.RetiredOfferGeneration}; kind=runtime_unlock_activation; state={SanitizeLogToken(stateSnapshot.ContractState.ToString().ToLowerInvariant())}; retry_reason={SanitizeLogToken(stateSnapshot.RetryReason)}; recovery_reason={SanitizeLogToken(stateSnapshot.RecoveryReason)}; recovery_pending={(!stateSnapshot.Settled ? 1 : 0)}; recovery_settled={(stateSnapshot.Settled ? 1 : 0)}; retry_required={(IsSessionRecoveryContractRetryRequired(stateSnapshot) ? 1 : 0)}; retry_dispatching={(stateSnapshot.RetryDispatching ? 1 : 0)}; retry_dispatched={(stateSnapshot.RetryDispatched ? 1 : 0)}; retry_observed={(stateSnapshot.RetryObserved ? 1 : 0)}; queued_behind_active_negotiation={(stateSnapshot.QueuedBehindActiveNegotiation ? 1 : 0)}; retry_authority_pending={(stateSnapshot.RetryAuthorityPending ? 1 : 0)}; retry_authority_granted={(stateSnapshot.RetryAuthorityGranted ? 1 : 0)}; observed_send_pending={(stateSnapshot.ObservedSendPending ? 1 : 0)}; authority_attempt={stateSnapshot.AuthorityAttempt}; dispatch_attempt_generation={stateSnapshot.DispatchAttemptGeneration}; missing_dispatch_successor_generation={stateSnapshot.MissingDispatchSuccessorGeneration}; missing_dispatch_successor_limit={FileTransferCoordinator.RuntimeUnlockRetryMissingDispatchSuccessorLimit}; authorized_observed_lane={SanitizeLogToken(stateSnapshot.AuthorizedObservedLane ?? "(none)")}; authority_failure_reason={SanitizeLogToken(stateSnapshot.AuthorityFailureReason ?? "(none)")}; dispatch_authority_granted={(stateSnapshot.DispatchAuthorityGranted ? 1 : 0)}; dispatch_authority_rejected={(stateSnapshot.DispatchAuthorityRejected ? 1 : 0)}; dispatch_observed={(stateSnapshot.DispatchObserved ? 1 : 0)}; dispatch_decision_status={SanitizeLogToken(stateSnapshot.DispatchDecisionStatus?.ToString() ?? "(none)")}; dispatch_decision_reason={SanitizeLogToken(stateSnapshot.DispatchDecisionReason ?? "(none)")}; requires_local_listener_retry={(stateSnapshot.RequiresLocalListenerRetry ? 1 : 0)}; listener_rearm_completed={(stateSnapshot.ListenerRearmCompleted ? 1 : 0)}; cutthrough_pending={(stateSnapshot.CutThroughPending ? 1 : 0)}; cutthrough_active={(stateSnapshot.CutThroughActive ? 1 : 0)}; cutthrough_offer_sent={(stateSnapshot.CutThroughOfferSent ? 1 : 0)}; cutthrough_peer_received={(stateSnapshot.CutThroughPeerReceived ? 1 : 0)}; cutthrough_completed={(stateSnapshot.CutThroughCompleted ? 1 : 0)}; cutthrough_attempt={stateSnapshot.CutThroughAttempt}; regular_v4_activation_window_started={(stateSnapshot.RegularV4ActivationWindowStarted ? 1 : 0)}; regular_v4_activation_window_peer_visible={(stateSnapshot.RegularV4ActivationWindowPeerVisible ? 1 : 0)}; regular_v4_activation_window_failed={(stateSnapshot.RegularV4ActivationWindowFailed ? 1 : 0)}; blocked_by_regular_v4_receive_recovery={(stateSnapshot.BlockedByRegularV4ReceiveRecovery ? 1 : 0)}; regular_v4_liveness_generation={stateSnapshot.RegularV4RecoveryLivenessGeneration}; regular_v4_blocked_transfer_id={SanitizeLogToken(stateSnapshot.RegularV4RecoveryBlockedTransferId ?? "(none)")}; regular_v4_blocked_route={SanitizeLogToken(stateSnapshot.RegularV4RecoveryRouteToken ?? "(none)")}; regular_v4_blocked_protocol_version={stateSnapshot.RegularV4RecoveryProtocolVersion}; regular_v4_blocked_live_route_epoch={stateSnapshot.RegularV4RecoveryLiveRouteEpoch}; regular_v4_blocked_bridge_decision_generation={stateSnapshot.RegularV4RecoveryBridgeDecisionGeneration}; regular_v4_blocker_reason={SanitizeLogToken(stateSnapshot.RegularV4RecoveryBlockerReason ?? "(none)")}; broken_state_fresh_retry_attempt={stateSnapshot.BrokenStateFreshRetryAttempt}; broken_state_fresh_retry_limit={stateSnapshot.BrokenStateFreshRetryLimit}; broken_state_finalized={(stateSnapshot.BrokenStateFinalized ? 1 : 0)}; broken_state_failure_reason={SanitizeLogToken(stateSnapshot.BrokenStateFailureReason ?? "(none)")}; observed_send_deadline_utc_ms={stateSnapshot.ObservedSendDeadlineUtcMs}; retry_deadline_utc_ms={stateSnapshot.RetryDeadlineUtcMs}; dispatch_deadline_utc_ms={stateSnapshot.DispatchDeadlineUtcMs}; liveness_deferral_deadline_utc_ms={stateSnapshot.LivenessDeferralDeadlineUtcMs}");
    }

    private void LogRuntimeUnlockRetryDispatchProof(
        string eventName,
        RuntimeUnlockRecoveryRetryState state,
        string decisionReason,
        RoutePublicationToken? coordinatorCurrentPublication = null)
    {
        var contract = state.DispatchContract;
        if (contract is not null)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event={SanitizeLogToken(eventName)}; {FormatRuntimeUnlockRetryDispatchAuthorityTuple(contract.Authority)}; offer_generation={contract.OfferGeneration}; offer_nonce={SanitizeLogToken(contract.OfferNonce ?? "(none)")}; queued_behind_active_negotiation={(state.QueuedBehindActiveNegotiation ? 1 : 0)}; decision_reason={SanitizeLogToken(decisionReason)}");
            if (contract.Lifecycle.SettlementOutcome is { } currentSettlementOutcome)
            {
                LogRuntimeUnlockRetryDispatchContractSettled(
                    contract,
                    currentSettlementOutcome,
                    contract.Lifecycle.SettlementReason ?? decisionReason);
            }
            return;
        }

        var route = string.IsNullOrWhiteSpace(state.DispatchRoute)
            ? state.RegularV4RecoveryRouteToken ?? "(none)"
            : state.DispatchRoute;
        var protocolVersion = state.DispatchProtocolVersion > 0
            ? state.DispatchProtocolVersion
            : state.RegularV4RecoveryProtocolVersion;
        var liveRouteEpoch = state.DispatchLiveRouteEpoch >= 0
            ? state.DispatchLiveRouteEpoch
            : state.RegularV4RecoveryLiveRouteEpoch;
        var requestTuple = state.PendingDispatchAuthorityRequest is { } pendingRequest
            ? $"; request_tuple_present=1; {FormatRuntimeUnlockRetryDispatchAuthorityRequestTuple(pendingRequest)}"
            : "; request_tuple_present=0";

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event={SanitizeLogToken(eventName)}; session_id={SanitizeLogToken(state.SessionId)}; transfer_id={SanitizeLogToken(state.TransferId ?? "(none)")}; contract_generation={state.ContractGeneration}; retired_generation={state.RetiredOfferGeneration}; offer_generation={(state.CurrentOfferGeneration > 0 ? state.CurrentOfferGeneration : state.RetiredOfferGeneration)}; route={SanitizeLogToken(route)}; protocol_version={protocolVersion}; live_route_epoch={liveRouteEpoch}; runtime_generation={state.DispatchRuntimeGeneration}; terminal_generation={state.DispatchTerminalGeneration}; leg_generation={state.DispatchLegGeneration}; regular_v4_liveness_generation={state.RegularV4RecoveryLivenessGeneration}; bridge_decision_generation={state.RegularV4RecoveryBridgeDecisionGeneration}; queued_behind_active_negotiation={(state.QueuedBehindActiveNegotiation ? 1 : 0)}; decision_reason={SanitizeLogToken(decisionReason)}{requestTuple}{FormatRuntimeUnlockRetrySourcePublicationDiagnosticSuffix(state.PendingDispatchAuthorityRequest?.SourcePublicationAuthority ?? state.SourcePublicationAuthority, FileTransferCoordinator.CreateRoutePublicationAuthority(coordinatorCurrentPublication))}");

    }

    private static string FormatRuntimeUnlockRetrySourcePublicationDiagnosticSuffix(
        FileTransferRoutePublicationAuthority? attempted,
        FileTransferRoutePublicationAuthority? current)
    {
        static string Tuple(string prefix, FileTransferRoutePublicationAuthority? authority)
            => $"; {prefix}_session_id={SanitizeLogToken(authority?.SessionId ?? "(none)")}; {prefix}_transfer_id={SanitizeLogToken(authority?.TransferId ?? "(none)")}; {prefix}_direction={FormatFileTransferDirection(authority?.Direction)}; {prefix}_route={SanitizeLogToken(authority?.RouteToken ?? "(none)")}; {prefix}_protocol_version={authority?.ProtocolVersion ?? 0}; {prefix}_live_route_epoch={authority?.LiveRouteEpoch ?? 0}; {prefix}_runtime_generation={authority?.RuntimeGeneration ?? 0}; {prefix}_terminal_generation={authority?.TerminalGeneration ?? 0}; {prefix}_leg_generation={authority?.LegGeneration ?? 0}; {prefix}_route_publication_generation={authority?.RoutePublicationGeneration ?? 0}; {prefix}_route_commit_generation={authority?.RouteCommitGeneration ?? 0}; {prefix}_target_route={SanitizeLogToken(authority?.TargetRouteToken ?? "(none)")}; {prefix}_target_protocol_version={authority?.TargetProtocolVersion ?? 0}; {prefix}_target_transport={FormatFileTransferTransportKindForLog(authority?.TargetTransport ?? FileTransferTransportKind.Unknown)}; {prefix}_route_publication_action_kind={SanitizeLogToken(authority?.RoutePublicationActionKind ?? "(none)")}";

        return Tuple("attempted_source_publication", attempted) +
               Tuple("current_source_publication", current);
    }

    private void ScheduleRuntimeUnlockRetryDispatchAuthoritySettlementCheck(
        RuntimeUnlockRecoveryRetryState state)
    {
        if (!state.DispatchAuthorityGranted ||
            state.DispatchAuthorityRejected ||
            state.DispatchObserved)
        {
            return;
        }

        var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        var deadlineUtcMs = state.DispatchDeadlineUtcMs > nowMs
            ? state.DispatchDeadlineUtcMs
            : nowMs + (long)(RuntimeUnlockRetryAuthorityDeadlineOverrideForTests ?? RuntimeUnlockRetryAuthorityDeadline).TotalMilliseconds;
        var delayMs = Math.Clamp(deadlineUtcMs - nowMs + 50, 50, 60_000);
        var sessionId = state.SessionId;
        var transferId = state.TransferId;
        var contractGeneration = state.ContractGeneration;
        var retiredOfferGeneration = state.RetiredOfferGeneration;
        var dispatchRoute = state.DispatchRoute;
        var dispatchProtocolVersion = state.DispatchProtocolVersion;
        var dispatchLiveRouteEpoch = state.DispatchLiveRouteEpoch;
        var dispatchRuntimeGeneration = state.DispatchRuntimeGeneration;
        var dispatchTerminalGeneration = state.DispatchTerminalGeneration;
        var dispatchLegGeneration = state.DispatchLegGeneration;

        _ = Task.Run(
            async () =>
            {
                await Task.Delay(TimeSpan.FromMilliseconds(delayMs), CancellationToken.None)
                    .ConfigureAwait(false);
                SettleRuntimeUnlockRetryDispatchAuthorityIfUnobserved(
                    sessionId,
                    transferId,
                    contractGeneration,
                    retiredOfferGeneration,
                    dispatchRoute,
                    dispatchProtocolVersion,
                    dispatchLiveRouteEpoch,
                    dispatchRuntimeGeneration,
                    dispatchTerminalGeneration,
                    dispatchLegGeneration);
            },
            CancellationToken.None);
    }

    private void SettleRuntimeUnlockRetryDispatchAuthorityIfUnobserved(
        string sessionId,
        string? transferId,
        long contractGeneration,
        long retiredOfferGeneration,
        string? dispatchRoute,
        int dispatchProtocolVersion,
        int dispatchLiveRouteEpoch,
        int dispatchRuntimeGeneration,
        int dispatchTerminalGeneration,
        long dispatchLegGeneration)
    {
        RuntimeUnlockRecoveryRetryState? missingDispatchState = null;
        RuntimeUnlockRecoveryRetryState? rescheduleState = null;
        RuntimeUnlockRetryDispatchContract? settledContract = null;
        RuntimeUnlockRetryDispatchSettlementReport settlementReport = default;
        var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.ContractGeneration != contractGeneration ||
                state.RetiredOfferGeneration != retiredOfferGeneration ||
                !string.Equals(state.SessionId, sessionId, StringComparison.Ordinal) ||
                !string.Equals(state.TransferId ?? string.Empty, transferId ?? string.Empty, StringComparison.Ordinal) ||
                !string.Equals(state.DispatchRoute ?? string.Empty, dispatchRoute ?? string.Empty, StringComparison.Ordinal) ||
                state.DispatchProtocolVersion != dispatchProtocolVersion ||
                state.DispatchLiveRouteEpoch != dispatchLiveRouteEpoch ||
                state.DispatchRuntimeGeneration != dispatchRuntimeGeneration ||
                state.DispatchTerminalGeneration != dispatchTerminalGeneration ||
                state.DispatchLegGeneration != dispatchLegGeneration ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                state.DispatchAuthorityRejected ||
                state.DispatchObserved ||
                !state.DispatchAuthorityGranted)
            {
                return;
            }

            if (state.ObservedSendPending)
            {
                var inFlightDeadlineUtcMs = state.ObservedSendDeadlineUtcMs > 0
                    ? state.ObservedSendDeadlineUtcMs + (long)RuntimeUnlockRetryAuthorityInFlightSendGrace.TotalMilliseconds
                    : 0;
                if (inFlightDeadlineUtcMs > nowMs)
                {
                    state.DispatchDeadlineUtcMs = Math.Max(state.DispatchDeadlineUtcMs, inFlightDeadlineUtcMs);
                    rescheduleState = state;
                }
            }

            if (rescheduleState is null)
            {
                var contract = state.DispatchContract;
                if (contract is null ||
                    contract.Authority.RecoveryContractGeneration != contractGeneration ||
                    !contract.TrySettle(
                        RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch,
                        "runtime_unlock_retry_dispatch_missing_after_authority_granted"))
                {
                    return;
                }

                if (!TryCaptureRuntimeUnlockRetryDispatchSettlementReportUnsafe(
                        state,
                        contract,
                        new RuntimeUnlockRetryDispatchSettlementConsequence(
                            contract.OfferGeneration > 0
                                ? contract.OfferGeneration
                                : retiredOfferGeneration,
                            "runtime_unlock_offer_send_not_observed",
                            "runtime_unlock_retry_dispatch_missing_after_authority_granted",
                            state.RequiresLocalListenerRetry,
                            RequestSuccessor: true,
                            ObservedLane: null),
                        out settlementReport))
                {
                    return;
                }
                settledContract = contract;
                missingDispatchState = state;
            }
        }

        if (rescheduleState is not null)
        {
            ScheduleRuntimeUnlockRetryDispatchAuthoritySettlementCheck(rescheduleState);
            return;
        }

        if (missingDispatchState is null)
        {
            return;
        }

        LogRuntimeUnlockRetryDispatchProof(
            "runtime_unlock_retry_dispatch_missing_after_authority_granted",
            missingDispatchState,
            missingDispatchState.DispatchDecisionReason ?? "runtime_unlock_retry_dispatch_missing_after_authority_granted");
        if (settledContract is not null)
        {
            LogRuntimeUnlockRetryDispatchContractSettled(
                settledContract,
                RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch,
                "runtime_unlock_retry_dispatch_missing_after_authority_granted");
        }
        _ = PublishRuntimeUnlockRetryDispatchSettlementReport(settlementReport);
    }

    private bool IsActiveRegularV4FileTransferRouteHint(string? sessionId, string? transferId)
        => IsActiveRegularV4FileTransferRouteHint(sessionId, transferId, null);

    private bool IsActiveRegularV4FileTransferRouteHint(
        string? sessionId,
        string? transferId,
        FileTransferDirection? direction)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        var normalizedTransferId = string.IsNullOrWhiteSpace(transferId) ? string.Empty : transferId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId) ||
            string.IsNullOrWhiteSpace(normalizedTransferId))
        {
            return false;
        }

        lock (gate)
        {
            if (!fileTransferDataSessions.TryGetValue(normalizedTransferId, out var session) ||
                session.IsDisposed ||
                !string.Equals(session.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return false;
            }

            FileTransferRouteHint routeHint;
            var routeHintFound = direction.HasValue
                ? TryGetFileTransferRouteHintUnsafe(normalizedSessionId, normalizedTransferId, direction.Value, out routeHint)
                : TryGetFileTransferRouteHintUnsafe(normalizedSessionId, normalizedTransferId, out routeHint);
            return !routeHintFound ||
                   routeHint.Route == FileTransferRoute.RegularNknV4Fast;
        }
    }

    private bool TryRequestFileTransferTunaActivationOfferSendRecovery(
        string purpose,
        string? activationSessionId,
        string trigger,
        string offerNonce,
        long offerPayerDecisionId,
        long offerGeneration,
        string retryReason,
        string joinRecoveryReason,
        out string? recoveryReason,
        out string? recoverySessionId,
        out RuntimeUnlockRegularV4RecoveryRetryJoinIntent? retryJoinIntent)
    {
        retryJoinIntent = null;
        if (TryCaptureRuntimeUnlockRegularV4RecoveryRetryJoinIntent(
                purpose,
                activationSessionId,
                trigger,
                offerNonce,
                offerPayerDecisionId,
                offerGeneration,
                retryReason,
                joinRecoveryReason,
                out var capturedIntent,
                out var duplicate))
        {
            retryJoinIntent = capturedIntent;
            recoveryReason = capturedIntent.RecoveryReason;
            recoverySessionId = capturedIntent.OfferSessionId;
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_activation_control_send_recovery_requested; session_id={SanitizeLogToken(capturedIntent.OfferSessionId)}; purpose={SanitizeLogToken(purpose)}; trigger={SanitizeLogToken(trigger)}; reason={SanitizeLogToken(capturedIntent.RecoveryReason)}; bridge_reason=runtime_unlock_retry_authority_offer_blocked; post_tuna_fallback_offer_recovery=0; accepted=0; joined_existing=1");
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_activation_control_send_recovery_joined_existing; session_id={SanitizeLogToken(capturedIntent.OfferSessionId)}; purpose={SanitizeLogToken(purpose)}; trigger={SanitizeLogToken(trigger)}; reason={SanitizeLogToken(capturedIntent.RecoveryReason)}; existing_recovery=1; join_reason=regular_v4_recovery_lease_closure_awaiting_local_proof; join_generation={capturedIntent.JoinGeneration}; disposition={(duplicate ? "Idempotent" : "Accepted")}");
            return true;
        }

        return TryRequestFileTransferTunaActivationOfferSendRecovery(
            purpose,
            activationSessionId,
            trigger,
            out recoveryReason,
            out recoverySessionId);
    }

    private bool TryCaptureRuntimeUnlockRegularV4RecoveryRetryJoinIntent(
        string purpose,
        string? activationSessionId,
        string trigger,
        string offerNonce,
        long offerPayerDecisionId,
        long offerGeneration,
        string retryReason,
        string recoveryReason,
        out RuntimeUnlockRegularV4RecoveryRetryJoinIntent intent,
        out bool duplicate)
        => TryCaptureRuntimeUnlockRegularV4RecoveryRetryJoinIntent(
            purpose,
            activationSessionId,
            trigger,
            offerNonce,
            offerPayerDecisionId,
            offerGeneration,
            expectedInstallReceipt: null,
            retryReason,
            recoveryReason,
            out intent,
            out duplicate);

    private bool TryCaptureRuntimeUnlockRegularV4RecoveryRetryJoinIntent(
        string purpose,
        string? activationSessionId,
        string trigger,
        string offerNonce,
        long offerPayerDecisionId,
        long offerGeneration,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt,
        string retryReason,
        string recoveryReason,
        out RuntimeUnlockRegularV4RecoveryRetryJoinIntent intent,
        out bool duplicate)
    {
        intent = null!;
        duplicate = false;
        if (purpose is not ("offer_answer" or "offer_peer_response" or "offer") ||
            string.IsNullOrWhiteSpace(activationSessionId) ||
            string.IsNullOrWhiteSpace(offerNonce) ||
            offerPayerDecisionId <= 0 ||
            offerGeneration <= 0)
        {
            return false;
        }

        var normalizedSessionId = activationSessionId.Trim();
        var normalizedRetryReason = SanitizeLogToken(retryReason);
        var normalizedRecoveryReason = SanitizeLogToken(recoveryReason);
        var normalizedPurpose = SanitizeLogToken(purpose);
        var normalizedTrigger = SanitizeLogToken(trigger);
        FileTransferRegularV4RecoveryLivenessState? stateSnapshot;
        RuntimeUnlockRegularV4RecoveryLeaseClosureContinuationProof continuationProof;
        RuntimeUnlockRegularV4RecoveryLeaseClosureReceipt receipt;
        lock (fileTransferFallbackProofGate)
        {
            var state = fileTransferRegularV4RecoveryLivenessState;
            var nowUtcMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            if (state is null ||
                !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
                state.Direction != FileTransferDirection.Outbound ||
                !string.Equals(state.RouteToken, FileTransferRouteResolver.RegularNknV4FastToken, StringComparison.Ordinal) ||
                state.ProtocolVersion != FileTransferProtocol.ProtocolVersionV4 ||
                !state.BridgeRecoveryCompleted ||
                state.RecoveryExhausted ||
                state.LeaseClosureConsumed ||
                state.LeaseClosureReceipt is not { } currentReceipt ||
                !TryGetRuntimeUnlockRegularV4RecoveryRetryJoinContinuationProofUnsafe(
                    state,
                    nowUtcMs,
                    out continuationProof))
            {
                return false;
            }

            receipt = currentReceipt;
            stateSnapshot = state;
        }

        if (!TryCaptureCurrentRuntimeUnlockFileTransferOwnerAndDataSession(
                normalizedSessionId,
                out var sourcePublicationAuthority,
                out var dataSessionGeneration,
                out _) ||
            !IsRuntimeUnlockRegularV4RecoveryRetryJoinPublicationCurrent(
                receipt,
                sourcePublicationAuthority))
        {
            return false;
        }

        lock (fileTransferFallbackProofGate)
        {
            var state = fileTransferRegularV4RecoveryLivenessState;
            var nowUtcMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            if (!ReferenceEquals(state, stateSnapshot) ||
                state!.LeaseClosureReceipt != receipt ||
                !TryGetRuntimeUnlockRegularV4RecoveryRetryJoinContinuationProofUnsafe(
                    state,
                    nowUtcMs,
                    out var currentProof) ||
                currentProof != continuationProof)
            {
                return false;
            }
        }

        RuntimeUnlockRetryDispatchBoundedClosureReceipt? boundedClosureReceipt = null;
        lock (accelerationGate)
        {
            var retryState = runtimeUnlockRecoveryRetryState;
            if (string.Equals(normalizedPurpose, "offer", StringComparison.Ordinal) &&
                retryState?.BoundedDispatchClosureReceipt is { } boundedCandidate &&
                TryGetRuntimeUnlockRetryDispatchBoundedClosureHistoryUnsafe(
                    retryState,
                    boundedCandidate,
                    out _))
            {
                boundedClosureReceipt = boundedCandidate;
            }

            if (string.Equals(normalizedPurpose, "offer", StringComparison.Ordinal))
            {
                var offer = runtimeUnlockOfferProofState;
                if (boundedClosureReceipt is not { } bounded ||
                    expectedInstallReceipt is not { } installReceipt ||
                    installReceipt != bounded.PredecessorInstallReceipt ||
                    bounded.PredecessorOfferGeneration != offerGeneration ||
                    bounded.RejectedSuccessorRequest.RetiredOfferGeneration != offerGeneration ||
                    !string.Equals(
                        bounded.PredecessorOfferNonce,
                        offerNonce,
                        StringComparison.Ordinal) ||
                    bounded.RejectedSuccessorRequest.SourcePublicationAuthority !=
                        sourcePublicationAuthority ||
                    bounded.DataSessionGeneration != dataSessionGeneration ||
                    offer is null ||
                    offer.Retired ||
                    offer.Generation != offerGeneration ||
                    offer.PayerDecisionId != offerPayerDecisionId ||
                    !string.Equals(offer.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
                    !string.Equals(offer.Nonce, offerNonce, StringComparison.Ordinal))
                {
                    return false;
                }
            }
        }

        var candidate = new RuntimeUnlockRegularV4RecoveryRetryJoinIntent(
            normalizedSessionId,
            offerNonce,
            offerPayerDecisionId,
            offerGeneration,
            continuationProof,
            receipt.Report.RecoveryAuthority,
            receipt.RetiredLease,
            sourcePublicationAuthority,
            dataSessionGeneration,
            normalizedRetryReason,
            normalizedRecoveryReason,
            normalizedPurpose,
            normalizedTrigger,
            boundedClosureReceipt,
            0);
        RuntimeUnlockRegularV4RecoveryRetryJoinIntent? displacedIntent = null;
        lock (accelerationGate)
        {
            if (pendingRuntimeUnlockRegularV4RecoveryRetryJoinIntent is { } existing &&
                IsSameRuntimeUnlockRegularV4RecoveryRetryJoin(existing, candidate))
            {
                intent = existing;
                duplicate = true;
            }
            else if (runtimeUnlockRecoveryRetryState?.RegularV4RecoveryRetryJoinIntent is { } armed &&
                     IsSameRuntimeUnlockRegularV4RecoveryRetryJoin(armed, candidate))
            {
                intent = armed;
                duplicate = true;
            }
            else
            {
                displacedIntent = pendingRuntimeUnlockRegularV4RecoveryRetryJoinIntent;
                intent = candidate with
                {
                    JoinGeneration = ++runtimeUnlockRegularV4RecoveryRetryJoinNextGeneration,
                };
                pendingRuntimeUnlockRegularV4RecoveryRetryJoinIntent = intent;
            }
        }

        if (displacedIntent is not null)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=runtime_unlock_regular_v4_recovery_lease_closure_offer_timeout_join_discarded; {FormatRuntimeUnlockRegularV4RecoveryRetryJoinIntent(displacedIntent)}; replacement_join_generation={intent.JoinGeneration}; decision_reason=retry_join_intent_replaced");
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_regular_v4_recovery_lease_closure_offer_timeout_joined; {FormatRuntimeUnlockRegularV4RecoveryRetryJoinIntent(intent)}; disposition={(duplicate ? "Idempotent" : "Accepted")}; decision_reason=regular_v4_recovery_lease_closure_awaiting_local_proof");
        return true;
    }

    private static bool IsRuntimeUnlockRegularV4RecoveryRetryJoinPublicationCurrent(
        RuntimeUnlockRegularV4RecoveryLeaseClosureReceipt receipt,
        FileTransferRoutePublicationAuthority publication)
    {
        var authority = receipt.Report.Authority;
        return string.Equals(publication.SessionId, authority.SessionId, StringComparison.Ordinal) &&
               string.Equals(publication.TransferId, authority.TransferId, StringComparison.Ordinal) &&
               publication.Direction == FileTransferDirection.Outbound &&
               publication.Direction == authority.Direction &&
               string.Equals(publication.RouteToken, authority.RouteToken, StringComparison.Ordinal) &&
               publication.ProtocolVersion == authority.ProtocolVersion &&
               publication.LiveRouteEpoch == authority.LiveRouteEpoch &&
               publication.RuntimeGeneration == authority.RuntimeGeneration &&
               publication.TerminalGeneration == authority.TerminalGeneration &&
               publication.LegGeneration == authority.TransferLegGeneration &&
               string.Equals(publication.TargetRouteToken, FileTransferRouteResolver.RegularNknV4FastToken, StringComparison.Ordinal) &&
               publication.TargetProtocolVersion == FileTransferProtocol.ProtocolVersionV4 &&
               publication.TargetTransport == FileTransferTransportKind.RegularNkn;
    }

    private static string FormatRuntimeUnlockRegularV4RecoveryRetryJoinIntent(
        RuntimeUnlockRegularV4RecoveryRetryJoinIntent intent)
    {
        var receipt = new RuntimeUnlockRegularV4RecoveryLeaseClosureReceipt(
            intent.ContinuationProof.LifecycleReport,
            intent.ContinuationProof.RetiredRecoveryLivenessLease,
            intent.ContinuationProof.DecisionStatus,
            intent.ContinuationProof.DecisionReason);
        var publication = intent.SourcePublicationAuthority;
        var authority = intent.RecoveryAuthority.BridgeRecoveryAuthority;
        var owner = intent.RetiredLease.RuntimeOwner;
        var bounded = intent.BoundedClosureReceipt;
        return $"{FormatRuntimeUnlockRegularV4RecoveryLeaseClosureReceipt(receipt)}; recovery_kind={SanitizeLogToken(authority.RecoveryKind)}; recovery_authority_reason={SanitizeLogToken(authority.Reason)}; lease_reason={SanitizeLogToken(intent.RetiredLease.Reason)}; runtime_owner_session_id={SanitizeLogToken(owner.SessionId)}; runtime_owner_transfer_id={SanitizeLogToken(owner.TransferId)}; runtime_owner_direction={owner.Direction.ToString().ToLowerInvariant()}; runtime_owner_route={SanitizeLogToken(owner.RouteToken)}; runtime_owner_route_kind={SanitizeLogToken(owner.Route.ToString())}; runtime_owner_protocol_version={owner.ProtocolVersion}; runtime_owner_live_route_epoch={owner.LiveRouteEpoch}; runtime_owner_runtime_generation={owner.RuntimeGeneration}; runtime_owner_terminal_generation={owner.TerminalGeneration}; runtime_owner_family={SanitizeLogToken(owner.RuntimeFamily)}; runtime_owner_created_reason={SanitizeLogToken(owner.CreatedReason)}; offer_session_id={SanitizeLogToken(intent.OfferSessionId)}; offer_nonce={SanitizeLogToken(intent.OfferNonce)}; payer_decision_id={intent.OfferPayerDecisionId}; offer_generation={intent.OfferGeneration}; join_generation={intent.JoinGeneration}; data_session_generation={intent.DataSessionGeneration}; retry_reason={SanitizeLogToken(intent.RetryReason)}; recovery_reason={SanitizeLogToken(intent.RecoveryReason)}; timeout_purpose={SanitizeLogToken(intent.TimeoutPurpose)}; timeout_trigger={SanitizeLogToken(intent.TimeoutTrigger)}; bounded_closure_present={(bounded is null ? 0 : 1)}; bounded_closure_generation={bounded?.ReceiptGeneration ?? 0}; bounded_predecessor_authority_id={SanitizeLogToken(bounded?.SettlementReport.Authority.AuthorityId.ToString() ?? "(none)")}; bounded_install_generation={bounded?.PredecessorInstallReceipt.InstallGeneration ?? 0}; bounded_successor_attempt_generation={bounded?.RejectedSuccessorRequest.DispatchAttemptGeneration ?? 0}; bounded_successor_missing_dispatch_generation={bounded?.RejectedSuccessorRequest.MissingDispatchSuccessorGeneration ?? 0}; source_publication_session_id={SanitizeLogToken(publication.SessionId)}; source_publication_transfer_id={SanitizeLogToken(publication.TransferId)}; source_publication_direction={publication.Direction.ToString().ToLowerInvariant()}; source_publication_route={SanitizeLogToken(publication.RouteToken)}; source_publication_protocol_version={publication.ProtocolVersion}; source_publication_live_route_epoch={publication.LiveRouteEpoch}; source_publication_runtime_generation={publication.RuntimeGeneration}; source_publication_terminal_generation={publication.TerminalGeneration}; source_publication_leg_generation={publication.LegGeneration}; source_publication_route_publication_generation={publication.RoutePublicationGeneration}; source_publication_route_commit_generation={publication.RouteCommitGeneration ?? 0}; source_publication_target_route={SanitizeLogToken(publication.TargetRouteToken)}; source_publication_target_protocol_version={publication.TargetProtocolVersion}; source_publication_target_transport={FormatFileTransferTransportKindForLog(publication.TargetTransport)}; source_publication_action_kind={SanitizeLogToken(publication.RoutePublicationActionKind)}; source_publication_coordinator_reason={SanitizeLogToken(publication.CoordinatorDecisionReason)}";
    }

    private bool TryRevalidateRuntimeUnlockRegularV4RecoveryRetryJoinIntent(
        RuntimeUnlockRegularV4RecoveryRetryJoinIntent intent,
        out bool closureAlreadyAdopted,
        out string rejectionReason)
    {
        closureAlreadyAdopted = false;
        rejectionReason = "accepted";
        lock (accelerationGate)
        {
            var pendingMatches =
                pendingRuntimeUnlockRegularV4RecoveryRetryJoinIntent is { } pending &&
                IsSameRuntimeUnlockRegularV4RecoveryRetryJoin(pending, intent);
            var armedMatches =
                runtimeUnlockRecoveryRetryState?.RegularV4RecoveryRetryJoinIntent is { } armed &&
                IsSameRuntimeUnlockRegularV4RecoveryRetryJoin(armed, intent);
            if (!pendingMatches && !armedMatches)
            {
                rejectionReason = "regular_v4_recovery_retry_join_intent_replaced";
                return false;
            }
        }

        lock (fileTransferFallbackProofGate)
        {
            var state = fileTransferRegularV4RecoveryLivenessState;
            var nowUtcMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            if (intent.ContinuationProof.MaximumLivenessDeferralDeadlineUtc
                    .ToUnixTimeMilliseconds() <= nowUtcMs)
            {
                rejectionReason = "regular_v4_recovery_lease_closure_deadline_expired";
                return false;
            }

            if (state is null ||
                state.RecoveryAuthority != intent.RecoveryAuthority ||
                state.LeaseClosureReceipt is not { } receipt ||
                receipt.Report.RecoveryAuthority != intent.RecoveryAuthority ||
                receipt.RetiredLease != intent.RetiredLease ||
                state.LeaseClosureConsumed ||
                state.RecoveryExhausted)
            {
                rejectionReason = state is null
                    ? "regular_v4_recovery_state_missing"
                    : state.LeaseClosureConsumed
                        ? "regular_v4_recovery_lease_closure_already_consumed"
                        : "regular_v4_recovery_lease_closure_stale";
                return false;
            }

            var proofDeadlineUtcMs = intent.ContinuationProof
                .MaximumLivenessDeferralDeadlineUtc
                .ToUnixTimeMilliseconds();
            if (state.LivenessDeferralDeadlineUtcMs != proofDeadlineUtcMs ||
                state.LivenessDeferralDeadlineUtcMs <= nowUtcMs)
            {
                rejectionReason = "regular_v4_recovery_lease_closure_deadline_expired";
                return false;
            }

            closureAlreadyAdopted = state.LeaseClosureAdopted;
            if (!closureAlreadyAdopted &&
                (!TryGetRuntimeUnlockRegularV4RecoveryLeaseClosureContinuationProofUnsafe(
                     state,
                     nowUtcMs,
                     out var proof) ||
                 proof != intent.ContinuationProof))
            {
                rejectionReason = "regular_v4_recovery_lease_closure_stale";
                return false;
            }
        }

        if (!TryCaptureCurrentRuntimeUnlockFileTransferOwnerAndDataSession(
                intent.OfferSessionId,
                out var publication,
                out var dataSessionGeneration,
                out rejectionReason) ||
            publication != intent.SourcePublicationAuthority ||
            dataSessionGeneration != intent.DataSessionGeneration ||
            !IsRuntimeUnlockRegularV4RecoveryRetryJoinPublicationCurrent(
                new RuntimeUnlockRegularV4RecoveryLeaseClosureReceipt(
                    intent.ContinuationProof.LifecycleReport,
                    intent.ContinuationProof.RetiredRecoveryLivenessLease,
                    intent.ContinuationProof.DecisionStatus,
                    intent.ContinuationProof.DecisionReason),
                publication))
        {
            rejectionReason = string.Equals(rejectionReason, "accepted", StringComparison.Ordinal)
                ? "regular_v4_recovery_route_publication_replaced"
                : rejectionReason;
            return false;
        }

        var authority = intent.RecoveryAuthority.BridgeRecoveryAuthority;
        if (!IsActiveRegularV4FileTransferRouteHint(
                authority.SessionId,
                authority.TransferId,
                authority.Direction))
        {
            rejectionReason = "regular_v4_recovery_route_replaced";
            return false;
        }

        return true;
    }

    private bool IsRuntimeUnlockRegularV4RecoveryRetryJoinClosureConsumed(
        RuntimeUnlockRegularV4RecoveryRetryJoinIntent intent)
    {
        lock (fileTransferFallbackProofGate)
        {
            var state = fileTransferRegularV4RecoveryLivenessState;
            var receipt = state?.LeaseClosureReceipt;
            return state is not null &&
                   state.LeaseClosureAdopted &&
                   state.LeaseClosureConsumed &&
                   !state.RecoveryExhausted &&
                   state.RecoveryAuthority == intent.RecoveryAuthority &&
                   receipt is not null &&
                   receipt.Report == intent.ContinuationProof.LifecycleReport &&
                   receipt.RetiredLease == intent.RetiredLease &&
                   receipt.DecisionStatus == intent.ContinuationProof.DecisionStatus &&
                   string.Equals(
                       receipt.DecisionReason,
                       intent.ContinuationProof.DecisionReason,
                       StringComparison.Ordinal);
        }
    }

    private static bool IsRuntimeUnlockRegularV4RecoveryRetryJoinCommittedUnsafe(
        RuntimeUnlockRecoveryRetryState state,
        RuntimeUnlockRegularV4RecoveryRetryJoinIntent intent,
        bool closureConsumed)
    {
        if (!closureConsumed ||
            state.ContractState is SessionRecoveryContractState.Completed or
                SessionRecoveryContractState.Failed ||
            state.DispatchAuthorityRejected ||
            state.RegularV4RecoveryRetryJoinIntent is not { } installedIntent ||
            !IsSameRuntimeUnlockRegularV4RecoveryRetryJoin(installedIntent, intent) ||
            state.DispatchContract is not { } contract)
        {
            return false;
        }

        var authority = contract.Authority;
        var sourcePublication = intent.SourcePublicationAuthority;
        if (authority.ReleaseKind !=
                RuntimeUnlockRetryReleaseKind.ReceiveRecoveryLeaseClosure ||
            authority.ReleaseAuthorityId != intent.RetiredLease.AuthorityId ||
            authority.ReleaseGeneration != intent.RetiredLease.LeaseGeneration ||
            authority.RecoveryContractGeneration != state.ContractGeneration ||
            authority.DispatchAttemptGeneration <= 0 ||
            authority.MissingDispatchSuccessorGeneration < 0 ||
            (authority.DispatchAttemptGeneration == 1
                ? authority.PredecessorAuthorityId is not null ||
                  authority.MissingDispatchSuccessorGeneration != 0
                : authority.PredecessorAuthorityId is null) ||
            state.SourcePublicationAuthority != sourcePublication ||
            !string.Equals(authority.SessionId, sourcePublication.SessionId, StringComparison.Ordinal) ||
            !string.Equals(authority.TransferId, sourcePublication.TransferId, StringComparison.Ordinal) ||
            authority.Direction != sourcePublication.Direction ||
            !string.Equals(authority.RouteToken, sourcePublication.RouteToken, StringComparison.Ordinal) ||
            authority.ProtocolVersion != sourcePublication.ProtocolVersion ||
            authority.LiveRouteEpoch != sourcePublication.LiveRouteEpoch ||
            authority.RuntimeGeneration != sourcePublication.RuntimeGeneration ||
            authority.TerminalGeneration != sourcePublication.TerminalGeneration ||
            authority.LegGeneration != sourcePublication.LegGeneration ||
            authority.RoutePublicationGeneration != sourcePublication.RoutePublicationGeneration ||
            authority.RouteCommitGeneration != sourcePublication.RouteCommitGeneration ||
            contract.RegularV4LivenessGeneration !=
                intent.RecoveryAuthority.RecoveryLivenessLease.LeaseGeneration ||
            contract.RequestBridgeDecisionGeneration !=
                intent.RecoveryAuthority.BridgeRecoveryAuthority.BridgeDecisionGeneration)
        {
            return false;
        }

        if (!contract.Lifecycle.IsSettled)
        {
            return state.DispatchAuthorityGranted &&
                   state.DispatchDecisionStatus ==
                       RuntimeUnlockRetryDispatchDecisionStatus.Granted;
        }

        var outcome = contract.Lifecycle.SettlementOutcome;
        if (outcome is not (
                RuntimeUnlockRetryDispatchSettlementOutcome.DispatchObserved or
                RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch))
        {
            return false;
        }

        var settlementAppliedOrPending =
            state.LastAppliedDispatchSettlementReport is { } applied &&
            applied.Authority == authority &&
            applied.Outcome == outcome ||
            state.PendingDispatchSettlementReport is { } pending &&
            pending.Authority == authority &&
            pending.Outcome == outcome;
        if (!settlementAppliedOrPending)
        {
            return false;
        }

        return outcome == RuntimeUnlockRetryDispatchSettlementOutcome.DispatchObserved
            ? state.DispatchObserved &&
              state.ContractState == SessionRecoveryContractState.RetryDispatched
            : state.ContractState == SessionRecoveryContractState.RecoverySettled &&
              state.PendingDispatchSuccessorIntent is { } successor &&
              successor.PredecessorAuthorityId == authority.AuthorityId;
    }

    private static bool TryGetRuntimeUnlockRetryDispatchBoundedClosureHistoryUnsafe(
        RuntimeUnlockRecoveryRetryState state,
        RuntimeUnlockRetryDispatchBoundedClosureReceipt receipt,
        out RuntimeUnlockRetryDispatchHistoricalSettlement history)
    {
        history = null!;
        var report = receipt.SettlementReport;
        var authority = report.Authority;
        var rejectedRequest = receipt.RejectedSuccessorRequest;
        var installReceipt = receipt.PredecessorInstallReceipt;
        if (receipt.ReceiptGeneration <= 0 ||
            state.BoundedDispatchClosureReceipt != receipt ||
            state.ContractState != SessionRecoveryContractState.Failed ||
            !state.Settled ||
            !state.BrokenStateFinalized ||
            !string.Equals(
                state.BrokenStateFailureReason,
                receipt.SuccessorDecisionReason,
                StringComparison.Ordinal) ||
            state.LastAppliedDispatchSettlementReport != report ||
            state.LastAppliedDispatchSettlementDecisionStatus !=
                receipt.SettlementDecisionStatus ||
            !string.Equals(
                SanitizeLogToken(state.LastAppliedDispatchSettlementDecisionReason ?? string.Empty),
                receipt.SettlementDecisionReason,
                StringComparison.Ordinal) ||
            report.Outcome != RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch ||
            receipt.SettlementDecisionStatus is not (
                RuntimeUnlockRetryDispatchSettlementDecisionStatus.Accepted or
                RuntimeUnlockRetryDispatchSettlementDecisionStatus.Idempotent) ||
            receipt.SuccessorDecisionStatus != RuntimeUnlockRetryDispatchDecisionStatus.Rejected ||
            !string.Equals(
                receipt.SuccessorDecisionReason,
                "retry_dispatch_missing_successor_limit_exhausted",
                StringComparison.Ordinal) ||
            installReceipt.InstallGeneration <= 0 ||
            installReceipt.Authority != authority ||
            installReceipt.Request.IsDefault ||
            !FileTransferCoordinator.TryValidateRuntimeUnlockRetryDispatchBinding(
                authority,
                installReceipt.Request,
                out _) ||
            rejectedRequest.IsDefault ||
            rejectedRequest.PredecessorAuthorityId != authority.AuthorityId ||
            rejectedRequest.RecoveryContractGeneration != authority.RecoveryContractGeneration ||
            rejectedRequest.RetiredOfferGeneration != receipt.PredecessorOfferGeneration ||
            rejectedRequest.DispatchAttemptGeneration !=
                authority.DispatchAttemptGeneration + 1 ||
            rejectedRequest.MissingDispatchSuccessorGeneration !=
                authority.MissingDispatchSuccessorGeneration + 1 ||
            rejectedRequest.RequestActivePredecessorSupersession ||
            rejectedRequest.SourcePublicationAuthority != installReceipt.Request.SourcePublicationAuthority ||
            receipt.PredecessorOfferGeneration <= 0 ||
            string.IsNullOrWhiteSpace(receipt.PredecessorOfferNonce) ||
            receipt.DataSessionGeneration <= 0 ||
            state.SourceDataSessionGeneration != receipt.DataSessionGeneration ||
            state.DispatchContract is not null ||
            state.DispatchPredecessorContract is not null ||
            state.PendingDispatchAuthorityRequest is not null ||
            state.PendingDispatchSuccessorIntent is not null)
        {
            return false;
        }

        history = new RuntimeUnlockRetryDispatchHistoricalSettlement(
            report,
            receipt.SettlementDecisionStatus,
            receipt.SettlementDecisionReason,
            authority.RecoveryContractGeneration,
            receipt.ClosedUtcMs);
        return true;
    }

    private bool TryGetRuntimeUnlockRegularV4RecoveryRetryJoinHistoryUnsafe(
        RuntimeUnlockRecoveryRetryState state,
        RuntimeUnlockRegularV4RecoveryRetryJoinIntent intent,
        out RuntimeUnlockRetryDispatchHistoricalSettlement history)
    {
        if (intent.BoundedClosureReceipt is { } boundedReceipt)
        {
            var offer = runtimeUnlockOfferProofState;
            if (!string.Equals(intent.TimeoutPurpose, "offer", StringComparison.Ordinal) ||
                offer is null ||
                !offer.Retired ||
                !string.Equals(offer.RetiredReason, "offer_send_not_observed", StringComparison.Ordinal) ||
                offer.Generation != intent.OfferGeneration ||
                offer.PayerDecisionId != intent.OfferPayerDecisionId ||
                !string.Equals(offer.SessionId, intent.OfferSessionId, StringComparison.Ordinal) ||
                !string.Equals(offer.Nonce, intent.OfferNonce, StringComparison.Ordinal) ||
                !string.Equals(
                    retiredAccelerationOfferSessionId,
                    intent.OfferSessionId,
                    StringComparison.Ordinal) ||
                !string.Equals(
                    retiredAccelerationOfferNonce,
                    intent.OfferNonce,
                    StringComparison.Ordinal) ||
                retiredAccelerationOfferPayerDecisionId != intent.OfferPayerDecisionId ||
                retiredAccelerationOfferInstallReceipt !=
                    boundedReceipt.PredecessorInstallReceipt ||
                retiredAccelerationOfferExpiresUtcMs <=
                    DateTimeOffset.UtcNow.ToUnixTimeMilliseconds())
            {
                history = null!;
                return false;
            }

            return TryGetRuntimeUnlockRetryDispatchBoundedClosureHistoryUnsafe(
                state,
                boundedReceipt,
                out history);
        }

        history = null!;
        if (state.DispatchContract is not { Lifecycle.IsSettled: true } contract ||
            contract.Lifecycle.SettlementOutcome !=
                RuntimeUnlockRetryDispatchSettlementOutcome.DispatchObserved ||
            state.LastAppliedDispatchSettlementReport is not { } report ||
            report.Authority != contract.Authority ||
            report.Outcome != RuntimeUnlockRetryDispatchSettlementOutcome.DispatchObserved ||
            state.LastAppliedDispatchSettlementDecisionStatus is not (
                RuntimeUnlockRetryDispatchSettlementDecisionStatus.Accepted or
                RuntimeUnlockRetryDispatchSettlementDecisionStatus.Idempotent))
        {
            return false;
        }

        history = new RuntimeUnlockRetryDispatchHistoricalSettlement(
            report,
            state.LastAppliedDispatchSettlementDecisionStatus.Value,
            SanitizeLogToken(
                state.LastAppliedDispatchSettlementDecisionReason ??
                "retry_dispatch_settlement_accepted"),
            state.ContractGeneration,
            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
        return true;
    }

    private static bool IsSameRuntimeUnlockRegularV4RecoveryRetryJoin(
        RuntimeUnlockRegularV4RecoveryRetryJoinIntent left,
        RuntimeUnlockRegularV4RecoveryRetryJoinIntent right)
        => left.OfferGeneration == right.OfferGeneration &&
           left.OfferPayerDecisionId == right.OfferPayerDecisionId &&
           string.Equals(left.OfferSessionId, right.OfferSessionId, StringComparison.Ordinal) &&
           string.Equals(left.OfferNonce, right.OfferNonce, StringComparison.Ordinal) &&
           left.ContinuationProof == right.ContinuationProof &&
           left.RecoveryAuthority == right.RecoveryAuthority &&
           left.RetiredLease == right.RetiredLease &&
           left.SourcePublicationAuthority == right.SourcePublicationAuthority &&
           left.DataSessionGeneration == right.DataSessionGeneration &&
           string.Equals(left.RetryReason, right.RetryReason, StringComparison.Ordinal) &&
           string.Equals(left.RecoveryReason, right.RecoveryReason, StringComparison.Ordinal) &&
           string.Equals(left.TimeoutPurpose, right.TimeoutPurpose, StringComparison.Ordinal) &&
           string.Equals(left.TimeoutTrigger, right.TimeoutTrigger, StringComparison.Ordinal) &&
           left.BoundedClosureReceipt == right.BoundedClosureReceipt;

    private bool TryRequestFileTransferTunaActivationOfferSendRecovery(
        string purpose,
        string? activationSessionId,
        string trigger,
        out string? recoveryReason,
        out string? recoverySessionId)
    {
        recoveryReason = null;
        recoverySessionId = null;
        if (!IsTunaActivationOfferSendPurpose(purpose))
        {
            return false;
        }

        var hasActivationPause = TryGetActiveFileTransferTunaActivationPause(activationSessionId, out var sessionId);
        var postTunaFallbackOfferRecovery = false;
        var regularV4RuntimeUnlockOfferRecovery = false;
        var activeFileTransferRuntimeUnlockOfferRecovery = false;
        var answerTimeoutRuntimeUnlockOfferRecovery = false;
        var peerResponseTimeoutRuntimeUnlockOfferRecovery = false;
        if (!hasActivationPause)
        {
            postTunaFallbackOfferRecovery =
                TryGetPostTunaFallbackRuntimeUnlockOfferRecoverySession(activationSessionId, out sessionId);
        }

        if (!hasActivationPause &&
            !postTunaFallbackOfferRecovery)
        {
            regularV4RuntimeUnlockOfferRecovery =
                TryGetRegularV4RuntimeUnlockOfferRecoverySession(activationSessionId, out sessionId);
        }

        if (!hasActivationPause &&
            !postTunaFallbackOfferRecovery &&
            !regularV4RuntimeUnlockOfferRecovery)
        {
            activeFileTransferRuntimeUnlockOfferRecovery =
                TryGetRuntimeUnlockOfferActiveFileTransferRecoverySession(activationSessionId, out sessionId);
        }

        if (!hasActivationPause &&
            !postTunaFallbackOfferRecovery &&
            !regularV4RuntimeUnlockOfferRecovery &&
            !activeFileTransferRuntimeUnlockOfferRecovery &&
            string.Equals(purpose, "offer_answer", StringComparison.OrdinalIgnoreCase))
        {
            sessionId = string.IsNullOrWhiteSpace(activationSessionId)
                ? currentSessionSecurityState.SessionId?.Value
                : activationSessionId.Trim();
            answerTimeoutRuntimeUnlockOfferRecovery =
                !string.IsNullOrWhiteSpace(sessionId) &&
                (HasActiveRegularV4FileTransferRouteHint(sessionId) ||
                 HasActivePostTunaFallbackFileTransferRouteHint(sessionId) ||
                 HasActiveFileTransferDataSessionForSession(sessionId));
        }

        if (!hasActivationPause &&
            !postTunaFallbackOfferRecovery &&
            !regularV4RuntimeUnlockOfferRecovery &&
            !activeFileTransferRuntimeUnlockOfferRecovery &&
            !answerTimeoutRuntimeUnlockOfferRecovery &&
            string.Equals(purpose, "offer_peer_response", StringComparison.OrdinalIgnoreCase))
        {
            sessionId = string.IsNullOrWhiteSpace(activationSessionId)
                ? currentSessionSecurityState.SessionId?.Value
                : activationSessionId.Trim();
            peerResponseTimeoutRuntimeUnlockOfferRecovery =
                !string.IsNullOrWhiteSpace(sessionId) &&
                (HasActiveRegularV4FileTransferRouteHint(sessionId) ||
                 HasActivePostTunaFallbackFileTransferRouteHint(sessionId) ||
                 HasActiveFileTransferDataSessionForSession(sessionId));
        }

        if (!hasActivationPause &&
            !postTunaFallbackOfferRecovery &&
            !regularV4RuntimeUnlockOfferRecovery &&
            !activeFileTransferRuntimeUnlockOfferRecovery &&
            !answerTimeoutRuntimeUnlockOfferRecovery &&
            !peerResponseTimeoutRuntimeUnlockOfferRecovery)
        {
            return false;
        }

        var normalizedPurpose = SanitizeLogToken(purpose);
        var reason =
            string.Equals(purpose, "offer_replay", StringComparison.OrdinalIgnoreCase)
                ? "tuna_activation_offer_replay_send_timeout"
                : string.Equals(purpose, "offer_answer", StringComparison.OrdinalIgnoreCase)
                    ? "tuna_activation_offer_answer_timeout"
                    : string.Equals(purpose, "offer_peer_response", StringComparison.OrdinalIgnoreCase)
                        ? "tuna_activation_offer_peer_response_timeout"
                        : "tuna_activation_offer_send_timeout";
        var bridgeRecoveryReason = reason;
        if (postTunaFallbackOfferRecovery)
        {
            bridgeRecoveryReason = $"post_tuna_fallback_{reason}";
        }
        else if (regularV4RuntimeUnlockOfferRecovery &&
                 TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(out _))
        {
            bridgeRecoveryReason = "runtime_unlock_retry_authority_offer_blocked";
            MarkRuntimeUnlockRecoveryContractAuthorityBlocked(bridgeRecoveryReason);
        }
        else if (answerTimeoutRuntimeUnlockOfferRecovery ||
                 peerResponseTimeoutRuntimeUnlockOfferRecovery)
        {
            bridgeRecoveryReason = "runtime_unlock_retry_authority_offer_blocked";
            MarkRuntimeUnlockRecoveryContractAuthorityBlocked(bridgeRecoveryReason);
        }

        recoveryReason = reason;
        recoverySessionId = sessionId;
        var accepted = RuntimeUnlockOfferSendRecoveryRequestOverrideForTests?.Invoke(this, reason, sessionId);
        if (accepted is null)
        {
            if (client is not RealNknClientAdapter)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=tuna_activation_control_send_recovery_request_unsupported; session_id={SanitizeLogToken(sessionId ?? "none")}; purpose={normalizedPurpose}; trigger={SanitizeLogToken(trigger)}; reason={SanitizeLogToken(reason)}");
                return false;
            }

            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=nkn_bridge_receive_stall_recovery_rejected_no_filetransfer_authority; session_id={SanitizeLogToken(sessionId ?? "none")}; transfer_id=runtime_unlock; direction=outbound; reason={SanitizeLogToken(bridgeRecoveryReason)}; rejection_reason=transport_callback_without_coordinator_authority; purpose={normalizedPurpose}; trigger={SanitizeLogToken(trigger)}");
            accepted = false;
        }

        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=tuna_activation_control_send_recovery_requested; session_id={SanitizeLogToken(sessionId ?? "none")}; purpose={normalizedPurpose}; trigger={SanitizeLogToken(trigger)}; reason={SanitizeLogToken(reason)}; bridge_reason={SanitizeLogToken(bridgeRecoveryReason)}; post_tuna_fallback_offer_recovery={(postTunaFallbackOfferRecovery ? 1 : 0)}; accepted={(accepted.Value ? 1 : 0)}");
        if (!accepted.Value &&
            ShouldJoinExistingRegularV4ReceiveStallRecoveryForRuntimeUnlock(
                regularV4RuntimeUnlockOfferRecovery,
                activeFileTransferRuntimeUnlockOfferRecovery,
                answerTimeoutRuntimeUnlockOfferRecovery,
                peerResponseTimeoutRuntimeUnlockOfferRecovery,
                sessionId))
        {
            MarkFileTransferTunaActivationBridgeRecoveryStarted(reason);
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_activation_control_send_recovery_joined_existing; session_id={SanitizeLogToken(sessionId ?? "none")}; purpose={normalizedPurpose}; trigger={SanitizeLogToken(trigger)}; reason={SanitizeLogToken(reason)}; existing_recovery=1; join_reason=regular_v4_receive_stall_recovery_in_progress");
            return true;
        }

        if (!accepted.Value &&
            ShouldJoinExistingFileTransferTunaActivationOfferSendRecovery(
                hasActivationPause,
                regularV4RuntimeUnlockOfferRecovery,
                activeFileTransferRuntimeUnlockOfferRecovery,
                postTunaFallbackOfferRecovery,
                activationSessionId,
                sessionId))
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_activation_control_send_recovery_joined_existing; session_id={SanitizeLogToken(sessionId ?? "none")}; purpose={normalizedPurpose}; trigger={SanitizeLogToken(trigger)}; reason={SanitizeLogToken(reason)}; existing_recovery=1");
            return true;
        }

        if (!accepted.Value)
        {
            return false;
        }

        MarkFileTransferTunaActivationBridgeRecoveryStarted(reason);
        return true;
    }

    private bool ShouldJoinExistingRegularV4ReceiveStallRecoveryForRuntimeUnlock(
        bool regularV4RuntimeUnlockOfferRecovery,
        bool activeFileTransferRuntimeUnlockOfferRecovery,
        bool answerTimeoutRuntimeUnlockOfferRecovery,
        bool peerResponseTimeoutRuntimeUnlockOfferRecovery,
        string? sessionId)
    {
        if (!regularV4RuntimeUnlockOfferRecovery &&
            !activeFileTransferRuntimeUnlockOfferRecovery &&
            !answerTimeoutRuntimeUnlockOfferRecovery &&
            !peerResponseTimeoutRuntimeUnlockOfferRecovery)
        {
            return false;
        }

        if (string.IsNullOrWhiteSpace(sessionId) ||
            !HasActiveRegularV4FileTransferRouteHint(sessionId))
        {
            return false;
        }

        return client is RealNknClientAdapter realClient &&
               realClient.TryGetFileTransferRegularV4ActivationSendBlocker(
                   out var blockerReason,
                   out _,
                   includeRegularV4Pressure: false) &&
               IsReceiveStallRecoveryInProgressActivationSendBlocker(blockerReason);
    }

    private bool ShouldJoinExistingFileTransferTunaActivationOfferSendRecovery(
        bool hasActivationPause,
        bool regularV4RuntimeUnlockOfferRecovery,
        bool activeFileTransferRuntimeUnlockOfferRecovery,
        bool postTunaFallbackOfferRecovery,
        string? activationSessionId,
        string? recoverySessionId)
    {
        if (!IsFileTransferTunaActivationBridgeRecoveryActive())
        {
            return false;
        }

        if (hasActivationPause)
        {
            return true;
        }

        if (regularV4RuntimeUnlockOfferRecovery &&
            TryGetRegularV4RuntimeUnlockOfferRecoverySession(activationSessionId, out var regularSessionId))
        {
            return string.IsNullOrWhiteSpace(recoverySessionId) ||
                   string.Equals(regularSessionId, recoverySessionId, StringComparison.Ordinal);
        }

        if (activeFileTransferRuntimeUnlockOfferRecovery &&
            TryGetRuntimeUnlockOfferActiveFileTransferRecoverySession(activationSessionId, out var activeFileTransferSessionId))
        {
            return string.IsNullOrWhiteSpace(recoverySessionId) ||
                   string.Equals(activeFileTransferSessionId, recoverySessionId, StringComparison.Ordinal);
        }

        if (postTunaFallbackOfferRecovery)
        {
            var postTunaFallbackSessionId = string.IsNullOrWhiteSpace(activationSessionId)
                ? currentSessionSecurityState.SessionId?.Value
                : activationSessionId.Trim();
            return string.IsNullOrWhiteSpace(recoverySessionId) ||
                   string.Equals(postTunaFallbackSessionId, recoverySessionId, StringComparison.Ordinal);
        }

        if (!TryGetActivePostTunaFallbackRuntimeUnlockOfferRecoverySession(activationSessionId, out var activeSessionId) &&
            !TryGetPostTunaFallbackRuntimeUnlockOfferRecoverySession(activationSessionId, out activeSessionId))
        {
            return false;
        }

        return string.IsNullOrWhiteSpace(recoverySessionId) ||
               string.Equals(activeSessionId, recoverySessionId, StringComparison.Ordinal);
    }

    private bool TryGetActivePostTunaFallbackRuntimeUnlockOfferRecoverySession(
        string? requestedSessionId,
        out string? sessionId)
    {
        sessionId = string.IsNullOrWhiteSpace(requestedSessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : requestedSessionId.Trim();
        if (string.IsNullOrWhiteSpace(sessionId) ||
            !IsCurrentRuntimeUnlockActivationOffer())
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce) ||
                !IsRuntimeUnlockActivationReason(outboundAccelerationOfferTrigger) ||
                IsAccelerationNegotiatedAndHealthyUnsafe(sessionId))
            {
                return false;
            }
        }

        return TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out var pendingEpoch) &&
               IsPostTunaFallbackRegularNknEpoch(pendingEpoch) &&
               ShouldAllowRuntimeUnlockRetryForActivePostTunaFallbackRepair(pendingEpoch);
    }

    private bool TryGetPostTunaFallbackRuntimeUnlockOfferRecoverySession(
        string? requestedSessionId,
        out string? sessionId)
    {
        sessionId = string.IsNullOrWhiteSpace(requestedSessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : requestedSessionId.Trim();
        if (string.IsNullOrWhiteSpace(sessionId) ||
            !IsCurrentRuntimeUnlockActivationOffer())
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce) ||
                !IsRuntimeUnlockActivationReason(outboundAccelerationOfferTrigger) ||
                IsAccelerationNegotiatedAndHealthyUnsafe(sessionId))
            {
                return false;
            }
        }

        if (TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out var pendingEpoch) &&
            IsPostTunaFallbackRegularNknEpoch(pendingEpoch))
        {
            return true;
        }

        return HasActivePostTunaFallbackFileTransferRouteHint(sessionId);
    }

    private bool TryGetRuntimeUnlockOfferActiveFileTransferRecoverySession(
        string? requestedSessionId,
        out string? sessionId)
    {
        sessionId = string.IsNullOrWhiteSpace(requestedSessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : requestedSessionId.Trim();
        if (string.IsNullOrWhiteSpace(sessionId) ||
            !IsCurrentRuntimeUnlockActivationOffer())
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce) ||
                !IsRuntimeUnlockActivationReason(outboundAccelerationOfferTrigger) ||
                IsAccelerationNegotiatedAndHealthyUnsafe(sessionId))
            {
                return false;
            }
        }

        lock (gate)
        {
            foreach (var session in fileTransferDataSessions.Values)
            {
                if (!session.IsDisposed &&
                    string.Equals(session.SessionId, sessionId, StringComparison.Ordinal))
                {
                    return true;
                }
            }
        }

        return client is RealNknClientAdapter realClient &&
               realClient.HasActiveFileTransferRuntimeForActivationSend();
    }

    private bool TryGetRegularV4RuntimeUnlockOfferRecoverySession(
        string? requestedSessionId,
        out string? sessionId)
    {
        sessionId = string.IsNullOrWhiteSpace(requestedSessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : requestedSessionId.Trim();
        if (string.IsNullOrWhiteSpace(sessionId) ||
            !IsCurrentRuntimeUnlockActivationOffer())
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce) ||
                !IsRuntimeUnlockActivationReason(outboundAccelerationOfferTrigger) ||
                IsAccelerationNegotiatedAndHealthyUnsafe(sessionId))
            {
                return false;
            }
        }

        if (!HasActiveRegularV4FileTransferRouteHint(sessionId))
        {
            return false;
        }

        if (RuntimeUnlockOfferQueueAcceptedPressureOverrideForTests?.Invoke(this) == true)
        {
            return true;
        }

        return client is RealNknClientAdapter realClient &&
               realClient.TryGetFileTransferRegularV4ActivationSendBlocker(out var blockerReason, out _) &&
               (IsRegularV4PressureActivationSendBlocker(blockerReason) ||
                IsReceiveStallActivationSendBlocker(blockerReason));
    }

    private bool HasActiveRegularV4FileTransferRouteHint(string sessionId)
    {
        lock (gate)
        {
            foreach (var session in fileTransferDataSessions.Values)
            {
                if (session.IsDisposed ||
                    !string.Equals(session.SessionId, sessionId, StringComparison.Ordinal))
                {
                    continue;
                }

                if (!TryGetFileTransferRouteHintUnsafe(session.SessionId, session.TransferId, out var routeHint))
                {
                    return true;
                }

                if (routeHint.Route == FileTransferRoute.RegularNknV4Fast)
                {
                    return true;
                }
            }
        }

        return false;
    }

    private bool HasActiveFileTunaV4FileTransferRouteHint(string? sessionId)
    {
        return TryGetLatestFileTransferRouteHintForSession(sessionId, out var routeHint) &&
               routeHint.Route == FileTransferRoute.FileTunaV4;
    }

    private bool HasAuthorizedRegularV4FileTransferRouteHint(string? sessionId)
    {
        return TryGetLatestFileTransferRouteHintForSession(sessionId, out var routeHint) &&
               routeHint.Route == FileTransferRoute.RegularNknV4Fast &&
               routeHint.ProtocolVersion == FileTransferProtocol.ProtocolVersionV4;
    }

    private bool HasAuthorizedRegularV4FileTransferRouteHint(
        string? sessionId,
        string? transferId,
        FileTransferDirection direction)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        var normalizedTransferId = string.IsNullOrWhiteSpace(transferId) ? string.Empty : transferId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId) ||
            string.IsNullOrWhiteSpace(normalizedTransferId))
        {
            return false;
        }

        lock (gate)
        {
            return TryGetFileTransferRouteHintUnsafe(
                       normalizedSessionId,
                       normalizedTransferId,
                       direction,
                       out var routeHint) &&
                   routeHint.Route == FileTransferRoute.RegularNknV4Fast &&
                   routeHint.ProtocolVersion == FileTransferProtocol.ProtocolVersionV4;
        }
    }

    private bool TryGetLatestFileTransferRouteHintForSession(
        string? sessionId,
        out FileTransferRouteHint routeHint)
    {
        routeHint = default;
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        var found = false;
        lock (gate)
        {
            foreach (var candidate in fileTransferRouteHints.Values)
            {
                if (!string.Equals(candidate.SessionId, normalizedSessionId, StringComparison.Ordinal))
                {
                    continue;
                }

                if (!found ||
                    candidate.RecordedUtc > routeHint.RecordedUtc ||
                    (candidate.RecordedUtc == routeHint.RecordedUtc &&
                     candidate.RoutePublicationGeneration > routeHint.RoutePublicationGeneration))
                {
                    routeHint = candidate;
                    found = true;
                }
            }
        }

        return found;
    }

    private bool ShouldSuppressUncommittedRuntimeUnlockFileFallback(
        string normalizedReason,
        string? sessionId,
        NknAccelerationLaneKind lanes,
        out bool activeRegularV4Route,
        out bool activeFileTunaV4Route,
        out bool activePostTunaFallbackRoute,
        out string suppressReason)
    {
        activeRegularV4Route = false;
        activeFileTunaV4Route = false;
        activePostTunaFallbackRoute = false;
        suppressReason = "none";

        if ((lanes & NknAccelerationLaneKind.File) != NknAccelerationLaneKind.File ||
            string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        var sidecarDropReason = IsRuntimeUnlockListenerRearmSidecarDropReason(normalizedReason);
        var activeTransactionReason = IsRuntimeUnlockActiveTransactionFileFallbackSuppressionReason(normalizedReason);
        var hasActiveUncommittedTransaction = false;
        var hasRecentUncommittedFallout = false;
        if (!sidecarDropReason &&
            !activeTransactionReason)
        {
            return false;
        }

        if (activeTransactionReason)
        {
            hasActiveUncommittedTransaction =
                HasActiveUncommittedRuntimeUnlockTransactionForSession(normalizedSessionId);
            hasRecentUncommittedFallout =
                HasRecentUncommittedRuntimeUnlockFallbackFalloutSuppression(
                    normalizedSessionId,
                    normalizedReason);
            if (!hasActiveUncommittedTransaction &&
                !hasRecentUncommittedFallout)
            {
                return false;
            }
        }

        activeRegularV4Route = HasActiveRegularV4FileTransferRouteHint(normalizedSessionId);
        activeFileTunaV4Route = HasActiveFileTunaV4FileTransferRouteHint(normalizedSessionId);
        activePostTunaFallbackRoute = HasActivePostTunaFallbackFileTransferRouteHint(normalizedSessionId);

        if (activeFileTunaV4Route)
        {
            return false;
        }

        if (activeRegularV4Route && !activePostTunaFallbackRoute)
        {
            suppressReason = hasRecentUncommittedFallout && !hasActiveUncommittedTransaction
                ? "recent_uncommitted_regular_v4_runtime_unlock_fallout"
                : "uncommitted_regular_v4_runtime_unlock";
            ArmUncommittedRuntimeUnlockFallbackFalloutSuppression(normalizedSessionId);
            return true;
        }

        if (activePostTunaFallbackRoute &&
            TryGetPostTunaFallbackRuntimeUnlockAdmissionDeniedRouteHint(
                normalizedSessionId,
                out var fallbackAdmissionDeniedReason))
        {
            suppressReason = fallbackAdmissionDeniedReason;
            ArmUncommittedRuntimeUnlockFallbackFalloutSuppression(normalizedSessionId);
            return true;
        }

        return false;
    }

    private bool HasRecentUncommittedRuntimeUnlockFallbackFalloutSuppression(
        string sessionId,
        string reason)
    {
        if (!IsRuntimeUnlockPairedFallbackFalloutReason(reason))
        {
            return false;
        }

        lock (accelerationGate)
        {
            var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            if (runtimeUnlockUncommittedFallbackFalloutSuppressionExpiresUtcMs <= nowMs)
            {
                runtimeUnlockUncommittedFallbackFalloutSuppressionSessionId = null;
                runtimeUnlockUncommittedFallbackFalloutSuppressionExpiresUtcMs = 0;
                return false;
            }

            return string.Equals(
                runtimeUnlockUncommittedFallbackFalloutSuppressionSessionId,
                sessionId,
                StringComparison.Ordinal);
        }
    }

    private void ArmUncommittedRuntimeUnlockFallbackFalloutSuppression(string sessionId)
    {
        lock (accelerationGate)
        {
            runtimeUnlockUncommittedFallbackFalloutSuppressionSessionId = sessionId;
            runtimeUnlockUncommittedFallbackFalloutSuppressionExpiresUtcMs = DateTimeOffset.UtcNow
                .Add(RuntimeUnlockUncommittedFallbackFalloutSuppressionTtl)
                .ToUnixTimeMilliseconds();
        }
    }

    private void StartTunaFallbackProofAndRebindIfAllowed(
        string reason,
        string? sessionId,
        NknAccelerationLaneKind lanes)
    {
        var normalizedReason = SanitizeLogToken(reason);
        if (ShouldSuppressUncommittedRuntimeUnlockFileFallback(
                normalizedReason,
                sessionId,
                lanes,
                out var activeRegularV4Route,
                out var activeFileTunaV4Route,
                out var activePostTunaFallbackRoute,
                out var runtimeUnlockFallbackSuppressReason))
        {
            var remainingLanes = lanes & ~NknAccelerationLaneKind.File;
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_uncommitted_file_fallback_suppressed; reason={normalizedReason}; session_id={SanitizeLogToken(sessionId ?? "none")}; lanes={FormatAccelerationLanesForLog(lanes)}; remaining_lanes={FormatAccelerationLanesForLog(remainingLanes)}; suppress_reason={SanitizeLogToken(runtimeUnlockFallbackSuppressReason)}; active_regular_v4_route={(activeRegularV4Route ? 1 : 0)}; active_file_tuna_v4_route={(activeFileTunaV4Route ? 1 : 0)}; active_post_tuna_fallback_route={(activePostTunaFallbackRoute ? 1 : 0)}");
            return;
        }

        StartTunaFallbackProofAndRebindIfNeeded(reason, sessionId, lanes);
    }

    private bool HasActiveUncommittedRuntimeUnlockTransactionForSession(string sessionId)
    {
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        lock (accelerationGate)
        {
            var snapshot = runtimeUnlockTransactionState;
            return snapshot.TransactionGeneration > 0 &&
                   !snapshot.IsTerminal &&
                   !snapshot.RouteCommitted &&
                   snapshot.State != RuntimeUnlockTransactionState.Committed &&
                   string.Equals(snapshot.SessionId, sessionId, StringComparison.Ordinal);
        }
    }

    private static bool IsRuntimeUnlockActiveTransactionFileFallbackSuppressionReason(string? reason)
    {
        var normalized = SanitizeLogToken(reason);
        return normalized is
            "tuna_unavailable_before_send" or
            "tuna_send_invalidated_after_queue" or
            "tuna_send_rejected" or
            "tuna_send_failed" or
            "remote_remote_closed";
    }

    private static bool IsRuntimeUnlockPairedFallbackFalloutReason(string? reason)
        => string.Equals(
            SanitizeLogToken(reason),
            "remote_remote_closed",
            StringComparison.Ordinal);

    private static bool IsRegularV4PressureActivationSendBlocker(string? reason)
        => string.Equals(reason, "regular_v4_activation_send_pressure", StringComparison.OrdinalIgnoreCase) ||
           string.Equals(reason, "regular_v4_control_feedback_pressure", StringComparison.OrdinalIgnoreCase);

    private bool TryGetCurrentRegularV4RepairPressureBlocker(
        FileTransferRegularV4RecoveryLivenessSnapshot livenessSnapshot,
        out string blockerReason,
        out long blockerEvidenceAgeMs)
    {
        blockerReason = string.Empty;
        blockerEvidenceAgeMs = 0;
        var overrideBlocker = RuntimeUnlockRegularV4RepairPressureBlockerOverrideForTests?.Invoke(this);
        if (overrideBlocker is { HasBlocker: true } &&
            string.Equals(
                SanitizeLogToken(overrideBlocker.Value.Reason),
                "regular_v4_control_feedback_pressure",
            StringComparison.OrdinalIgnoreCase))
        {
            blockerReason = SanitizeLogToken(overrideBlocker.Value.Reason);
            blockerEvidenceAgeMs = Math.Max(0, overrideBlocker.Value.EvidenceAgeMs);
            return true;
        }

        return client is RealNknClientAdapter realClient &&
               realClient.TryGetCurrentRegularV4FrontierRepairPressureBlocker(
                   livenessSnapshot.SessionId,
                   livenessSnapshot.TransferId,
                   livenessSnapshot.Direction,
                   livenessSnapshot.RouteToken,
                   livenessSnapshot.ProtocolVersion,
                   livenessSnapshot.LiveRouteEpoch,
                   livenessSnapshot.TransferLegGeneration,
                   livenessSnapshot.TransportEpoch,
                   livenessSnapshot.BridgeRecoveryGeneration,
                   livenessSnapshot.BridgeDecisionGeneration,
                   out blockerReason,
                   out blockerEvidenceAgeMs);
    }

    private static bool IsReceiveStallActivationSendBlocker(string? reason)
        => string.Equals(reason, "receive_stall_recovery_in_progress", StringComparison.OrdinalIgnoreCase) ||
           string.Equals(reason, "receive_stall_recovery_awaiting_receive_proof", StringComparison.OrdinalIgnoreCase);

    private static bool IsReceiveStallRecoveryInProgressActivationSendBlocker(string? reason)
        => string.Equals(reason, "receive_stall_recovery_in_progress", StringComparison.OrdinalIgnoreCase);

    private static bool ShouldDeferRuntimeUnlockSoftSettleForReceiveStallBlocker(string? reason, long remainingMs)
        => IsReceiveStallActivationSendBlocker(reason) && remainingMs > 0;

    private static bool ShouldBypassRuntimeUnlockReceiveStallAfterBoundedWait(string? reason)
        => string.Equals(reason, "receive_stall_recovery_awaiting_receive_proof", StringComparison.OrdinalIgnoreCase);

    private static string FormatElapsedMilliseconds(long startedTick)
    {
        if (startedTick <= 0)
        {
            return "-1";
        }

        return Math.Max(0, (long)Stopwatch.GetElapsedTime(startedTick).TotalMilliseconds)
            .ToString(CultureInfo.InvariantCulture);
    }

    private void ScheduleFileTransferTunaActivationPauseExpiryObservation(
        string sessionId,
        long generation)
    {
        _ = Task.Run(
            async () =>
            {
                try
                {
                    await Task.Delay(FileTransferTunaActivationPauseMax, CancellationToken.None).ConfigureAwait(false);
                    var observationCurrent = false;
                    lock (accelerationGate)
                    {
                        observationCurrent =
                            generation == fileTransferTunaActivationPauseGeneration &&
                            string.Equals(fileTransferTunaActivationPauseSessionId, sessionId, StringComparison.Ordinal) &&
                            !IsAccelerationNegotiatedAndHealthyUnsafe(sessionId);
                    }

                    if (observationCurrent)
                    {
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=filetransfer_tuna_activation_negotiation_pause_expiry_observed; session_id={SanitizeLogToken(sessionId)}; pause_generation={generation}; reason=tuna_activation_negotiation_pause_expired; authority_effect=none");
                    }
                }
                catch (Exception ex) when (ex is not OperationCanceledException)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=filetransfer_tuna_activation_negotiation_pause_expiry_observation_failed; session_id={SanitizeLogToken(sessionId)}; pause_generation={generation}; error={ex.GetType().Name}");
                }
            },
            CancellationToken.None);
    }

    private bool IsAccelerationNegotiatedAndHealthyUnsafe(string? sessionId)
        => accelerationLane?.IsAvailable == true &&
           accelerationNegotiatedLanes != NknAccelerationLaneKind.None &&
           !string.IsNullOrWhiteSpace(accelerationSessionId) &&
           string.Equals(accelerationSessionId, sessionId, StringComparison.Ordinal);

    private void RebindScreenShareDataSessionsForTunaFallback(
        string reason,
        string? sessionId,
        NknAccelerationLaneKind lanes)
    {
        if ((lanes & NknAccelerationLaneKind.Screen) != NknAccelerationLaneKind.Screen ||
            string.IsNullOrWhiteSpace(sessionId))
        {
            return;
        }

        var normalizedReason = SanitizeLogToken(reason);
        MarkTunaFallbackLaneState(
            sessionId,
            lane: NknAccelerationLaneKind.Screen,
            state: TunaFallbackLaneState.Pending,
            reason: normalizedReason);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=screenshare_tuna_handoff_started; session_id={sessionId}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}");
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_disable_handoff_screen_started; session_id={sessionId}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}");
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_disable_handoff_media_pending; session_id={sessionId}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}");
        ScheduleScreenTunaHandoffWaitingMarker(sessionId, normalizedReason);
    }

    private void CompleteTunaFallbackProof(string reason)
    {
        TunaFallbackProofState? state;
        var normalizedReason = SanitizeLogToken(reason);
        var deferredPendingFileRoute = false;
        lock (accelerationGate)
        {
            state = tunaFallbackProofState;
            if (state is not null &&
                ShouldDeferTunaFallbackProofCompletionForPendingFileRouteUnsafe(state, normalizedReason))
            {
                deferredPendingFileRoute = true;
            }
            else
            {
                tunaFallbackProofState = null;
            }
        }

        if (state is null)
        {
            return;
        }

        var elapsedMs = Math.Max(0, (long)(DateTimeOffset.UtcNow - state.StartedUtc).TotalMilliseconds);
        if (deferredPendingFileRoute)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_fallback_summary_deferred; session_id={state.SessionId}; fallback_epoch={state.Epoch}; reason={state.Reason}; deferred_reason={normalizedReason}; elapsed_ms={elapsedMs}; lanes={FormatAccelerationLanesForLog(state.Lanes)}; screen_state={FormatTunaFallbackLaneState(state.ScreenState)}; file_state={FormatTunaFallbackLaneState(state.FileState)}; file_v6_epoch_state={FormatTunaFallbackFileV6EpochState(state)}; file_v6_transport_epoch={state.FileV6TransportEpoch}; pending_file_route=1");
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_fallback_summary; session_id={state.SessionId}; fallback_epoch={state.Epoch}; reason={state.Reason}; completed_reason={normalizedReason}; elapsed_ms={elapsedMs}; lanes={FormatAccelerationLanesForLog(state.Lanes)}; screen_state={FormatTunaFallbackLaneState(state.ScreenState)}; file_state={FormatTunaFallbackLaneState(state.FileState)}; screen_nkn_frames_sent={state.ScreenNknFramesSent}; screen_nkn_frames_received={state.ScreenNknFramesReceived}; screen_frames_applied={state.ScreenFramesApplied}; file_nkn_frames_sent={state.FileNknFramesSent}; file_nkn_frames_received={state.FileNknFramesReceived}; control_nkn_messages_sent={state.ControlNknMessagesSent}; acceleration_used_after_fallback={(state.AccelerationUsedAfterFallback ? 1 : 0)}");
        if (IsMixedFallbackLaneSet(state.Lanes))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_mixed_handoff_summary; session_id={state.SessionId}; fallback_epoch={state.Epoch}; reason={state.Reason}; completed_reason={normalizedReason}; elapsed_ms={elapsedMs}; screen_state={FormatTunaFallbackLaneState(state.ScreenState)}; file_state={FormatTunaFallbackLaneState(state.FileState)}; screen_frames_applied={state.ScreenFramesApplied}; file_nkn_frames_sent={state.FileNknFramesSent}; file_nkn_frames_received={state.FileNknFramesReceived}; control_nkn_messages_sent={state.ControlNknMessagesSent}");
        }

        NotifyTransportAccelerationStateChanged(reason);
    }

    private bool ShouldDeferTunaFallbackProofCompletionForPendingFileRouteUnsafe(
        TunaFallbackProofState state,
        string normalizedReason)
    {
        if ((state.Lanes & NknAccelerationLaneKind.File) != NknAccelerationLaneKind.File ||
            state.FileState is TunaFallbackLaneState.None or TunaFallbackLaneState.Recovered ||
            IsFinalTunaFallbackProofCompletionReason(normalizedReason))
        {
            return false;
        }

        return IsUserRequestedAccelerationStopReason(normalizedReason) ||
               IsRemoteUserRequestedAccelerationStopReason(normalizedReason) ||
               (!string.IsNullOrWhiteSpace(state.SessionId) &&
                (string.Equals(accelerationUserStoppedSessionId, state.SessionId, StringComparison.Ordinal) ||
                 string.Equals(accelerationPeerUserStoppedSessionId, state.SessionId, StringComparison.Ordinal)));
    }

    private static bool IsFinalTunaFallbackProofCompletionReason(string normalizedReason)
        => normalizedReason is "tuna_activation_started" or
            "dispose" or
            "disposed" or
            "reset_session_tracking" or
            "session_security_state_not_eligible";

    private void ConsumePostTunaFileFallbackRoute(string? sessionId, string? transferId, string reason)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : sessionId.Trim();
        var normalizedTransferId = string.IsNullOrWhiteSpace(transferId) ? "none" : transferId.Trim();
        var normalizedReason = SanitizeLogToken(reason);
        TunaFallbackProofState? snapshot;
        TunaFallbackLaneState previousFileState;
        V6TransportEpochState? previousFileV6EpochState;
        long previousFileV6TransportEpoch;
        bool clearedState;

        lock (accelerationGate)
        {
            if (!TryConsumePostTunaFileFallbackRouteUnsafe(
                    normalizedSessionId,
                    out snapshot,
                    out previousFileState,
                    out previousFileV6EpochState,
                    out previousFileV6TransportEpoch,
                    out clearedState))
            {
                return;
            }
        }

        LogConsumedPostTunaFileFallbackRoute(
            normalizedSessionId,
            normalizedTransferId,
            normalizedReason,
            snapshot!,
            previousFileState,
            previousFileV6EpochState,
            previousFileV6TransportEpoch,
            clearedState);
    }

    private bool TryConsumePostTunaFileFallbackRouteUnsafe(
        string? normalizedSessionId,
        out TunaFallbackProofState? snapshot,
        out TunaFallbackLaneState previousFileState,
        out V6TransportEpochState? previousFileV6EpochState,
        out long previousFileV6TransportEpoch,
        out bool clearedState)
    {
        snapshot = null;
        previousFileState = TunaFallbackLaneState.None;
        previousFileV6EpochState = null;
        previousFileV6TransportEpoch = 0;
        clearedState = false;
        if (tunaFallbackProofState is not { } state ||
            string.IsNullOrWhiteSpace(normalizedSessionId) ||
            !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
            (state.Lanes & NknAccelerationLaneKind.File) != NknAccelerationLaneKind.File ||
            state.FileState == TunaFallbackLaneState.None)
        {
            return false;
        }

        previousFileState = state.FileState;
        previousFileV6EpochState = state.FileV6EpochState;
        previousFileV6TransportEpoch = state.FileV6TransportEpoch;
        state.FileState = TunaFallbackLaneState.None;
        state.FileV6EpochState = null;
        state.FileV6TransportEpoch = 0;
        ClearRuntimeUnlockPublishedRouteCommitUnsafe();
        snapshot = state;

        var screenLaneStillNeedsProof =
            (state.Lanes & NknAccelerationLaneKind.Screen) == NknAccelerationLaneKind.Screen &&
            state.ScreenState is TunaFallbackLaneState.Pending or
                TunaFallbackLaneState.MediaReady or
                TunaFallbackLaneState.WaitingForRegularNkn;
        if (!screenLaneStillNeedsProof)
        {
            tunaFallbackProofState = null;
            clearedState = true;
        }

        return true;
    }

    private void LogConsumedPostTunaFileFallbackRoute(
        string? normalizedSessionId,
        string normalizedTransferId,
        string normalizedReason,
        TunaFallbackProofState snapshot,
        TunaFallbackLaneState previousFileState,
        V6TransportEpochState? previousFileV6EpochState,
        long previousFileV6TransportEpoch,
        bool clearedState)
    {
        var previousFileV6EpochStateToken = previousFileV6EpochState is { } epochState
            ? FormatFileTransferV6TransportEpochStateForLog(epochState)
            : "none";
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_post_tuna_fallback_v6_route_consumed; session_id={SanitizeLogToken(normalizedSessionId ?? "none")}; transfer_id={SanitizeLogToken(normalizedTransferId)}; fallback_epoch={snapshot.Epoch}; reason={normalizedReason}; previous_file_state={FormatTunaFallbackLaneState(previousFileState)}; previous_file_v6_epoch_state={SanitizeLogToken(previousFileV6EpochStateToken)}; previous_file_v6_transport_epoch={previousFileV6TransportEpoch}; cleared_state={(clearedState ? 1 : 0)}; next_file_route={ResolveFileRouteAfterPostTunaFallbackClearedForLog()}");
        NotifyTransportAccelerationStateChanged(normalizedReason);
    }

    private RuntimeUnlockPostTunaFallbackActivationIntent?
        RetainRuntimeUnlockPostTunaFallbackActivationIntent(
            FileTransferRouteHintNotification notification)
    {
        if (notification.PublicationAuthority is not { } authority ||
            authority.Direction != FileTransferDirection.Outbound ||
            !notification.RuntimeUnlockAdmissionGranted ||
            !string.Equals(
                authority.RouteToken,
                FileTransferRouteResolver.PostTunaFallbackV6Token,
                StringComparison.Ordinal) ||
            authority.ProtocolVersion != FileTransferProtocol.ProtocolVersionV6)
        {
            return null;
        }

        var key = CreateFileTransferRouteHintKey(
            authority.SessionId,
            authority.TransferId,
            authority.Direction);
        RuntimeUnlockPostTunaFallbackActivationIntent candidate;
        lock (gate)
        {
            if (!fileTransferRoutePublicationAuthorities.TryGetValue(key, out var currentAuthority) ||
                currentAuthority != authority ||
                !fileTransferRouteHints.TryGetValue(key, out var currentHint) ||
                !currentHint.RuntimeUnlockAdmissionGranted ||
                !fileTransferDataSessions.TryGetValue(authority.TransferId, out var dataSession) ||
                dataSession.IsDisposed ||
                !string.Equals(dataSession.SessionId, authority.SessionId, StringComparison.Ordinal))
            {
                return null;
            }

            candidate = new RuntimeUnlockPostTunaFallbackActivationIntent(
                authority,
                authority.SessionId,
                authority.TransferId,
                authority.Direction,
                authority.RouteToken,
                authority.ProtocolVersion,
                currentHint.RuntimeUnlockAdmissionGranted,
                currentHint.RuntimeUnlockAdmissionReason,
                currentHint.FallbackLegState,
                currentHint.FallbackLegCanSendData,
                currentHint.FallbackLegGeneration,
                currentHint.FallbackCheckpointRequestId,
                currentHint.FallbackTransportEpoch,
                currentHint.FallbackBridgeRecoveryGeneration,
                dataSession,
                dataSession.Generation,
                IntentGeneration: 0);
        }

        RuntimeUnlockPostTunaFallbackActivationIntent retained;
        var duplicate = false;
        RuntimeUnlockPostTunaFallbackActivationIntent? replaced = null;
        lock (accelerationGate)
        {
            if (runtimeUnlockPostTunaFallbackActivationIntent is { } current &&
                IsSameRuntimeUnlockPostTunaFallbackActivationScope(current, candidate))
            {
                retained = current;
                duplicate = true;
            }
            else
            {
                replaced = runtimeUnlockPostTunaFallbackActivationIntent;
                retained = candidate with
                {
                    IntentGeneration = ++runtimeUnlockPostTunaFallbackActivationIntentNextGeneration,
                };
                runtimeUnlockPostTunaFallbackActivationIntent = retained;
                pendingRuntimeUnlockPostTunaFallbackActivationRecheck = null;
                if (runtimeUnlockRecoveryRetryState is { } state &&
                    state.PostTunaFallbackActivationIntent is { } linked &&
                    (replaced is null || linked.IntentGeneration == replaced.IntentGeneration))
                {
                    _ = InvalidateRuntimeUnlockRetryDispatchDecisionStageUnsafe(
                        state,
                        "retry_dispatch_install_stage_invalidated_post_tuna_fallback_activation_intent_replaced");
                }
            }
        }

        if (replaced is not null)
        {
            LogRuntimeUnlockPostTunaFallbackActivationIntent(
                "runtime_unlock_post_tuna_fallback_activation_intent_invalidated",
                replaced,
                "route_hint_authority_replaced");
        }

        LogRuntimeUnlockPostTunaFallbackActivationIntent(
            "runtime_unlock_post_tuna_fallback_activation_intent_retained",
            retained,
            duplicate ? "exact_intent_duplicate" : "fallback_paired_tail_yield_admission");
        return retained;
    }

    private static bool IsSameRuntimeUnlockPostTunaFallbackActivationScope(
        RuntimeUnlockPostTunaFallbackActivationIntent left,
        RuntimeUnlockPostTunaFallbackActivationIntent right)
        => left.SourcePublicationAuthority == right.SourcePublicationAuthority &&
           string.Equals(left.SessionId, right.SessionId, StringComparison.Ordinal) &&
           string.Equals(left.TransferId, right.TransferId, StringComparison.Ordinal) &&
           left.Direction == right.Direction &&
           string.Equals(left.RouteToken, right.RouteToken, StringComparison.Ordinal) &&
           left.ProtocolVersion == right.ProtocolVersion &&
           left.AdmissionGranted == right.AdmissionGranted &&
           string.Equals(left.AdmissionReason, right.AdmissionReason, StringComparison.Ordinal) &&
           string.Equals(left.FallbackLegState, right.FallbackLegState, StringComparison.Ordinal) &&
           left.FallbackLegCanSendData == right.FallbackLegCanSendData &&
           left.FallbackLegGeneration == right.FallbackLegGeneration &&
           string.Equals(
               left.FallbackCheckpointRequestId,
               right.FallbackCheckpointRequestId,
               StringComparison.Ordinal) &&
           left.FallbackTransportEpoch == right.FallbackTransportEpoch &&
           left.FallbackBridgeRecoveryGeneration == right.FallbackBridgeRecoveryGeneration &&
           ReferenceEquals(left.DataSession, right.DataSession) &&
           left.DataSessionGeneration == right.DataSessionGeneration;

    private bool IsRuntimeUnlockPostTunaFallbackActivationIntentCurrent(
        RuntimeUnlockPostTunaFallbackActivationIntent intent,
        out string rejectionReason)
    {
        lock (gate)
        {
            if (!IsRuntimeUnlockPostTunaFallbackActivationIntentCurrentUnderGateUnsafe(
                    intent,
                    out rejectionReason))
            {
                return false;
            }
        }

        lock (accelerationGate)
        {
            if (runtimeUnlockPostTunaFallbackActivationIntent != intent)
            {
                rejectionReason = "activation_intent_replaced";
                return false;
            }
        }

        rejectionReason = "current";
        return true;
    }

    private bool IsRuntimeUnlockPostTunaFallbackActivationIntentCurrentUnderGateUnsafe(
        RuntimeUnlockPostTunaFallbackActivationIntent intent,
        out string rejectionReason)
    {
        var key = CreateFileTransferRouteHintKey(
            intent.SessionId,
            intent.TransferId,
            intent.Direction);
        if (!fileTransferDataSessions.TryGetValue(intent.TransferId, out var dataSession) ||
            dataSession.IsDisposed ||
            !ReferenceEquals(dataSession, intent.DataSession) ||
            dataSession.Generation != intent.DataSessionGeneration ||
            !string.Equals(dataSession.SessionId, intent.SessionId, StringComparison.Ordinal))
        {
            rejectionReason = "data_session_replaced";
            return false;
        }

        if (!fileTransferRoutePublicationAuthorities.TryGetValue(key, out var authority) ||
            authority != intent.SourcePublicationAuthority)
        {
            rejectionReason = "route_publication_replaced";
            return false;
        }

        if (!fileTransferRouteHints.TryGetValue(key, out var hint) ||
            hint.Route != FileTransferRoute.PostTunaFallbackV6 ||
            hint.ProtocolVersion != FileTransferProtocol.ProtocolVersionV6 ||
            !hint.RuntimeUnlockAdmissionGranted ||
            !string.Equals(hint.RuntimeUnlockAdmissionReason, intent.AdmissionReason, StringComparison.Ordinal) ||
            !string.Equals(hint.FallbackLegState, intent.FallbackLegState, StringComparison.Ordinal) ||
            hint.FallbackLegCanSendData != intent.FallbackLegCanSendData ||
            hint.FallbackLegGeneration != intent.FallbackLegGeneration ||
            !string.Equals(
                hint.FallbackCheckpointRequestId,
                intent.FallbackCheckpointRequestId,
                StringComparison.Ordinal) ||
            hint.FallbackTransportEpoch != intent.FallbackTransportEpoch ||
            hint.FallbackBridgeRecoveryGeneration != intent.FallbackBridgeRecoveryGeneration)
        {
            rejectionReason = "runtime_unlock_admission_replaced";
            return false;
        }

        rejectionReason = "current";
        return true;
    }

    private bool QueueRuntimeUnlockPostTunaFallbackActivationRecheck(
        RuntimeUnlockPostTunaFallbackActivationIntent intent,
        string trigger,
        TimeSpan delay)
    {
        RuntimeUnlockPostTunaFallbackActivationRecheck recheck;
        var normalizedTrigger = SanitizeLogToken(trigger);
        lock (accelerationGate)
        {
            if (runtimeUnlockPostTunaFallbackActivationIntent != intent)
            {
                return false;
            }

            if (pendingRuntimeUnlockPostTunaFallbackActivationRecheck is { } pending &&
                pending.Intent == intent &&
                string.Equals(pending.Trigger, normalizedTrigger, StringComparison.Ordinal))
            {
                return true;
            }

            recheck = new RuntimeUnlockPostTunaFallbackActivationRecheck(
                intent,
                normalizedTrigger,
                ++runtimeUnlockPostTunaFallbackActivationRecheckNextGeneration);
            pendingRuntimeUnlockPostTunaFallbackActivationRecheck = recheck;
        }

        LogRuntimeUnlockPostTunaFallbackActivationRecheck(
            "runtime_unlock_post_tuna_fallback_activation_intent_recheck_requested",
            recheck,
            "queued");

        lock (runtimeUnlockPostTunaFallbackActivationRecheckGate)
        {
            var predecessor = runtimeUnlockPostTunaFallbackActivationRecheckTail;
            runtimeUnlockPostTunaFallbackActivationRecheckTail = Task.Run(
                async () =>
                {
                    await predecessor.ConfigureAwait(false);
                    if (delay > TimeSpan.Zero)
                    {
                        await Task.Delay(delay, CancellationToken.None).ConfigureAwait(false);
                    }

                    if (RuntimeUnlockPostTunaFallbackActivationRecheckBarrierForTests is { } barrier)
                    {
                        await barrier().ConfigureAwait(false);
                    }

                    if (delay > TimeSpan.Zero)
                    {
                        LocalOperationalLog.Info(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_retry_fired; reason={SanitizeLogToken(recheck.Trigger)}; listener_ready_reuse=0");
                    }

                    RecheckRuntimeUnlockPostTunaFallbackActivationIntent(recheck);
                },
                CancellationToken.None);
        }

        return true;
    }

    private bool QueueCurrentRuntimeUnlockPostTunaFallbackActivationRecheck(
        string trigger,
        TimeSpan delay)
    {
        RuntimeUnlockPostTunaFallbackActivationIntent? intent;
        lock (accelerationGate)
        {
            intent = runtimeUnlockPostTunaFallbackActivationIntent;
        }

        return intent is not null &&
               QueueRuntimeUnlockPostTunaFallbackActivationRecheck(intent, trigger, delay);
    }

    internal Task DrainRuntimeUnlockPostTunaFallbackActivationRechecksForTestsAsync()
    {
        lock (runtimeUnlockPostTunaFallbackActivationRecheckGate)
        {
            return runtimeUnlockPostTunaFallbackActivationRecheckTail;
        }
    }

    private void RecheckRuntimeUnlockPostTunaFallbackActivationIntent(
        RuntimeUnlockPostTunaFallbackActivationRecheck recheck)
    {
        try
        {
            lock (accelerationGate)
            {
                if (pendingRuntimeUnlockPostTunaFallbackActivationRecheck != recheck ||
                    runtimeUnlockPostTunaFallbackActivationIntent != recheck.Intent)
                {
                    LogRuntimeUnlockPostTunaFallbackActivationIntent(
                        "runtime_unlock_post_tuna_fallback_activation_intent_invalidated",
                        recheck.Intent,
                        "queued_recheck_replaced",
                        recheck.RecheckGeneration,
                        recheck.Trigger);
                    return;
                }
            }

            if (!IsRuntimeUnlockPostTunaFallbackActivationIntentCurrent(
                    recheck.Intent,
                    out var currentnessReason))
            {
                InvalidateRuntimeUnlockPostTunaFallbackActivationIntent(
                    recheck.Intent.SessionId,
                    recheck.Intent.TransferId,
                    recheck.Intent.Direction,
                    currentnessReason);
                return;
            }

            if (TryGetUnresolvedFileTransferV6TransportEpochForCurrentSession(out var pendingEpoch) &&
                string.Equals(pendingEpoch.SessionId, recheck.Intent.SessionId, StringComparison.Ordinal) &&
                string.Equals(pendingEpoch.TransferId, recheck.Intent.TransferId, StringComparison.Ordinal) &&
                pendingEpoch.Direction == recheck.Intent.Direction &&
                pendingEpoch.IsUnresolved)
            {
                LogRuntimeUnlockPostTunaFallbackActivationIntent(
                    "runtime_unlock_post_tuna_fallback_activation_intent_held",
                    recheck.Intent,
                    "fallback_proof_replay_pending",
                    recheck.RecheckGeneration,
                    recheck.Trigger);
                LogRuntimeUnlockPostTunaFallbackActivationRecheck(
                    "runtime_unlock_post_tuna_fallback_activation_intent_recheck_decided",
                    recheck,
                    "fallback_proof_replay_pending",
                    "Held");
                return;
            }

            if (!ArmRuntimeUnlockRetryFromPostTunaFallbackActivationIntent(
                    recheck.Intent,
                    recheck.Trigger,
                    out var armReason))
            {
                LogRuntimeUnlockPostTunaFallbackActivationIntent(
                    "runtime_unlock_post_tuna_fallback_activation_intent_held",
                    recheck.Intent,
                    armReason,
                    recheck.RecheckGeneration,
                    recheck.Trigger);
                LogRuntimeUnlockPostTunaFallbackActivationRecheck(
                    "runtime_unlock_post_tuna_fallback_activation_intent_recheck_decided",
                    recheck,
                    armReason,
                    "Held");
            }
            else
            {
                LogRuntimeUnlockPostTunaFallbackActivationRecheck(
                    "runtime_unlock_post_tuna_fallback_activation_intent_recheck_decided",
                    recheck,
                    "coordinator_authority_recheck_completed",
                    "Accepted");
            }
        }
        finally
        {
            lock (accelerationGate)
            {
                if (pendingRuntimeUnlockPostTunaFallbackActivationRecheck == recheck)
                {
                    pendingRuntimeUnlockPostTunaFallbackActivationRecheck = null;
                }
            }
        }
    }

    private bool ArmRuntimeUnlockRetryFromPostTunaFallbackActivationIntent(
        RuntimeUnlockPostTunaFallbackActivationIntent intent,
        string trigger,
        out string decisionReason)
    {
        RuntimeUnlockRecoveryRetryState? stateToRequest = null;
        RuntimeUnlockRetryDispatchSettlementReport? historicalReport = null;
        var requestHeldDecision = false;
        lock (accelerationGate)
        {
            if (runtimeUnlockPostTunaFallbackActivationIntent != intent)
            {
                decisionReason = "activation_intent_replaced";
                return false;
            }

            var current = runtimeUnlockRecoveryRetryState;
            if (current?.PostTunaFallbackActivationIntent == intent &&
                current.ContractState is not (
                    SessionRecoveryContractState.Completed or
                    SessionRecoveryContractState.Failed))
            {
                if (current.DispatchContract is { Lifecycle.IsSettled: false } ||
                    current.LastCommittedDispatchInstallReceipt is not null)
                {
                    decisionReason = "activation_authority_already_installed";
                    return true;
                }

                stateToRequest = current;
                requestHeldDecision = current.DispatchDecisionStatus ==
                    RuntimeUnlockRetryDispatchDecisionStatus.Held;
            }
            else if (current?.DispatchContract is { Lifecycle.IsSettled: false } activeContract &&
                     current.ContractState is not (
                         SessionRecoveryContractState.Completed or
                         SessionRecoveryContractState.Failed))
            {
                current.PostTunaFallbackActivationIntent = intent;
                current.PendingDispatchSuccessorIntent ??= new RuntimeUnlockRetrySuccessorIntent(
                    activeContract.OfferGeneration > 0
                        ? activeContract.OfferGeneration
                        : activeContract.Authority.RetiredOfferGeneration,
                    activeContract.Authority.DispatchAttemptGeneration + 1,
                    activeContract.Authority.MissingDispatchSuccessorGeneration,
                    intent.SessionId,
                    "runtime_unlock_after_fallback_tail_quiescent",
                    "post_tuna_fallback_activation_intent",
                    RequiresLocalListenerRetry: false,
                    activeContract.Authority.AuthorityId,
                    RequestActivePredecessorSupersession: true);
                stateToRequest = current;
            }
            else if (current?.DispatchContract is { Lifecycle.IsSettled: true } settledContract &&
                     settledContract.Lifecycle.SettlementOutcome ==
                         RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch &&
                     current.ContractState is not SessionRecoveryContractState.Failed)
            {
                current.PostTunaFallbackActivationIntent = intent;
                if (current.PendingDispatchSuccessorIntent is null)
                {
                    _ = PrepareRuntimeUnlockRetryMissingDispatchSuccessorUnsafe(
                        current,
                        settledContract,
                        settledContract.OfferGeneration > 0
                            ? settledContract.OfferGeneration
                            : settledContract.Authority.RetiredOfferGeneration,
                        "runtime_unlock_after_fallback_tail_quiescent",
                        "post_tuna_fallback_activation_intent",
                        requiresLocalListenerRetry: false,
                        out _,
                        out _);
                }
                stateToRequest = current;
                requestHeldDecision = current.PendingDispatchSuccessorRequestHeld;
            }
            else
            {
                if (current?.LastAppliedDispatchSettlementReport is
                        { Outcome: RuntimeUnlockRetryDispatchSettlementOutcome.DispatchObserved } appliedReport &&
                    current.DispatchContract?.Authority == appliedReport.Authority &&
                    current.LastAppliedDispatchSettlementDecisionStatus is (
                        RuntimeUnlockRetryDispatchSettlementDecisionStatus.Accepted or
                        RuntimeUnlockRetryDispatchSettlementDecisionStatus.Idempotent))
                {
                    historicalReport = appliedReport;
                    runtimeUnlockRetryDispatchHistoricalSettlement =
                        new RuntimeUnlockRetryDispatchHistoricalSettlement(
                            appliedReport,
                            current.LastAppliedDispatchSettlementDecisionStatus.Value,
                            SanitizeLogToken(
                                current.LastAppliedDispatchSettlementDecisionReason ??
                                "retry_dispatch_settlement_accepted"),
                            current.ContractGeneration,
                            DateTimeOffset.UtcNow.ToUnixTimeMilliseconds());
                }

                if (current is not null)
                {
                    _ = InvalidateRuntimeUnlockRetryDispatchDecisionStageUnsafe(
                        current,
                        "retry_dispatch_install_stage_invalidated_post_tuna_fallback_fresh_contract");
                }

                var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
                var retiredOfferGeneration = Math.Max(
                    outboundAccelerationOfferGeneration,
                    Math.Max(
                        current?.CurrentOfferGeneration ?? 0,
                        current?.RetiredOfferGeneration ?? 0));
                stateToRequest = new RuntimeUnlockRecoveryRetryState
                {
                    ContractGeneration = ++runtimeUnlockRecoveryContractNextGeneration,
                    RetiredOfferGeneration = retiredOfferGeneration,
                    SessionId = intent.SessionId,
                    TransferId = intent.TransferId,
                    RetryReason = "runtime_unlock_after_fallback_tail_quiescent",
                    RecoveryReason = "post_tuna_fallback_activation_intent",
                    CreatedUtcMs = nowMs,
                    RetryDeadlineUtcMs = 0,
                    LivenessDeferralDeadlineUtcMs = 0,
                    DispatchAttemptGeneration = 1,
                    MissingDispatchSuccessorGeneration = 0,
                    SourcePublicationAuthority = intent.SourcePublicationAuthority,
                    SourceDataSessionGeneration = intent.DataSessionGeneration,
                    PostTunaFallbackActivationIntent = intent,
                };
                runtimeUnlockRecoveryRetryState = stateToRequest;
            }
        }

        if (stateToRequest is null)
        {
            decisionReason = "activation_retry_state_missing";
            return false;
        }

        LogRuntimeUnlockPostTunaFallbackActivationIntent(
            "runtime_unlock_post_tuna_fallback_activation_authority_requested",
            intent,
            historicalReport is null
                ? "coordinator_authority_requested"
                : "fresh_independent_retry_after_dispatch_observed",
            trigger: trigger,
            state: stateToRequest);

        var subscriberPresent = runtimeUnlockRetryDispatchAuthorityRequested is not null ||
                                RuntimeUnlockRetryDispatchAuthorityDecisionOverrideForTests is not null;
        RequestRuntimeUnlockRetryDispatchAuthority(
            intent.SessionId,
            "post_tuna_fallback_activation_intent",
            retryHeldSuccessor: requestHeldDecision);
        if (!subscriberPresent)
        {
            decisionReason = "retry_dispatch_authority_subscriber_missing";
            return false;
        }

        decisionReason = "coordinator_authority_requested";
        return true;
    }

    private void InvalidateRuntimeUnlockPostTunaFallbackActivationIntent(
        string? sessionId,
        string? transferId,
        FileTransferDirection? direction,
        string reason)
    {
        RuntimeUnlockPostTunaFallbackActivationIntent? invalidated = null;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? null : sessionId.Trim();
        var normalizedTransferId = string.IsNullOrWhiteSpace(transferId) ? null : transferId.Trim();
        lock (accelerationGate)
        {
            var current = runtimeUnlockPostTunaFallbackActivationIntent;
            if (current is null ||
                normalizedSessionId is not null &&
                !string.Equals(current.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
                normalizedTransferId is not null &&
                !string.Equals(current.TransferId, normalizedTransferId, StringComparison.Ordinal) ||
                direction is not null && current.Direction != direction)
            {
                return;
            }

            invalidated = current;
            runtimeUnlockPostTunaFallbackActivationIntent = null;
            if (pendingRuntimeUnlockPostTunaFallbackActivationRecheck?.Intent == current)
            {
                pendingRuntimeUnlockPostTunaFallbackActivationRecheck = null;
            }

            if (runtimeUnlockRecoveryRetryState is { } state &&
                state.PostTunaFallbackActivationIntent == current)
            {
                _ = InvalidateRuntimeUnlockRetryDispatchDecisionStageUnsafe(
                    state,
                    $"retry_dispatch_install_stage_invalidated_{SanitizeLogToken(reason)}");
                state.PostTunaFallbackActivationIntent = null;
                if (state.LastCommittedDispatchInstallReceipt is not null)
                {
                    state.LastCommittedDispatchInstallReceipt = null;
                    state.DispatchAuthorityGranted = false;
                    state.RetryAuthorityGranted = false;
                    state.RetryQueued = false;
                    state.RetryDispatching = false;
                    state.RetryDispatched = false;
                    state.ObservedSendPending = false;
                    state.RetryDeadlineUtcMs = 0;
                    state.DispatchDeadlineUtcMs = 0;
                    state.ObservedSendDeadlineUtcMs = 0;
                    state.LivenessDeferralDeadlineUtcMs = 0;
                    state.AuthorityFailureReason = SanitizeLogToken(reason);
                }
            }
        }

        if (invalidated is not null)
        {
            LogRuntimeUnlockPostTunaFallbackActivationIntent(
                "runtime_unlock_post_tuna_fallback_activation_intent_invalidated",
                invalidated,
                reason);
        }
    }

    private static string FormatRuntimeUnlockPostTunaFallbackActivationIntent(
        RuntimeUnlockPostTunaFallbackActivationIntent intent)
    {
        var authority = intent.SourcePublicationAuthority;
        return $"intent_generation={intent.IntentGeneration}; session_id={SanitizeLogToken(intent.SessionId)}; transfer_id={SanitizeLogToken(intent.TransferId)}; direction={intent.Direction.ToString().ToLowerInvariant()}; route={SanitizeLogToken(intent.RouteToken)}; protocol_version={intent.ProtocolVersion}; live_route_epoch={authority.LiveRouteEpoch}; runtime_generation={authority.RuntimeGeneration}; terminal_generation={authority.TerminalGeneration}; leg_generation={authority.LegGeneration}; route_publication_generation={authority.RoutePublicationGeneration}; route_commit_generation={authority.RouteCommitGeneration ?? 0}; target_route={SanitizeLogToken(authority.TargetRouteToken)}; target_protocol_version={authority.TargetProtocolVersion}; target_transport={FormatFileTransferTransportKindForLog(authority.TargetTransport)}; fallback_leg_state={SanitizeLogToken(intent.FallbackLegState)}; fallback_leg_can_send_data={(intent.FallbackLegCanSendData ? 1 : 0)}; fallback_leg_generation={intent.FallbackLegGeneration}; fallback_transport_epoch={intent.FallbackTransportEpoch}; fallback_bridge_recovery_generation={intent.FallbackBridgeRecoveryGeneration}; fallback_checkpoint_request_id={SanitizeLogToken(intent.FallbackCheckpointRequestId ?? "(none)")}; data_session_generation={intent.DataSessionGeneration}; admission_granted={(intent.AdmissionGranted ? 1 : 0)}; admission_reason={SanitizeLogToken(intent.AdmissionReason)}";
    }

    private static void LogRuntimeUnlockPostTunaFallbackActivationRecheck(
        string eventName,
        RuntimeUnlockPostTunaFallbackActivationRecheck recheck,
        string decisionReason,
        string decisionStatus = "Pending")
    {
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event={SanitizeLogToken(eventName)}; {FormatRuntimeUnlockPostTunaFallbackActivationIntent(recheck.Intent)}; recheck_generation={recheck.RecheckGeneration}; trigger={SanitizeLogToken(recheck.Trigger)}; decision_status={SanitizeLogToken(decisionStatus)}; decision_reason={SanitizeLogToken(decisionReason)}");
    }

    private static void LogRuntimeUnlockPostTunaFallbackActivationIntent(
        string eventName,
        RuntimeUnlockPostTunaFallbackActivationIntent intent,
        string decisionReason,
        long recheckGeneration = 0,
        string? trigger = null,
        RuntimeUnlockRecoveryRetryState? state = null)
    {
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event={SanitizeLogToken(eventName)}; {FormatRuntimeUnlockPostTunaFallbackActivationIntent(intent)}; recheck_generation={recheckGeneration}; contract_generation={state?.ContractGeneration ?? 0}; dispatch_attempt_generation={state?.DispatchAttemptGeneration ?? 0}; missing_dispatch_successor_generation={state?.MissingDispatchSuccessorGeneration ?? 0}; predecessor_authority_id={SanitizeLogToken(state?.PendingDispatchAuthorityRequest?.PredecessorAuthorityId?.ToString() ?? "(none)")}; trigger={SanitizeLogToken(trigger ?? "(none)")}; decision_reason={SanitizeLogToken(decisionReason)}");
    }

    private void ScheduleRuntimeUnlockAfterPostTunaFallbackYield(
        string transferId,
        string fallbackYieldRetryKey,
        string reason)
    {
        var normalizedTransferId = string.IsNullOrWhiteSpace(transferId)
            ? "none"
            : transferId.Trim();
        var normalizedReason = SanitizeLogToken(reason);
        if (string.IsNullOrWhiteSpace(fallbackYieldRetryKey) ||
            normalizedTransferId.Length == 0 ||
            normalizedTransferId == "none" ||
            normalizedReason is not ("fallback_tail_quiescent" or "fallback_quiescent"))
        {
            return;
        }

        var firstForOwner = false;
        lock (gate)
        {
            firstForOwner = fileTransferPostTunaFallbackYieldRuntimeUnlockRetries.Add(fallbackYieldRetryKey);
        }

        if (!firstForOwner)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_after_post_tuna_fallback_yield_retry_suppressed; transfer_id={SanitizeLogToken(normalizedTransferId)}; owner_key={SanitizeLogToken(fallbackYieldRetryKey)}; reason={normalizedReason}");
            return;
        }

        RuntimeUnlockPostTunaFallbackActivationIntent? intent;
        lock (accelerationGate)
        {
            intent = runtimeUnlockPostTunaFallbackActivationIntent is { } current &&
                     string.Equals(current.TransferId, normalizedTransferId, StringComparison.Ordinal)
                ? current
                : null;
        }
        var scheduled = intent is not null &&
                        QueueRuntimeUnlockPostTunaFallbackActivationRecheck(
                            intent,
                            "runtime_unlock_after_fallback_tail_quiescent",
                            AccelerationNegotiationRetryBaseDelay);
        if (scheduled)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_retry_scheduled; reason=runtime_unlock_after_fallback_tail_quiescent; attempt=1; max_attempts={RuntimeUnlockAccelerationNegotiationMaxRetryAttempts}; delay_ms={(int)AccelerationNegotiationRetryBaseDelay.TotalMilliseconds}; listener_ready_reuse=0");
        }
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_after_post_tuna_fallback_yield_retry_scheduled; transfer_id={SanitizeLogToken(normalizedTransferId)}; owner_key={SanitizeLogToken(fallbackYieldRetryKey)}; source_reason={normalizedReason}; scheduled={(scheduled ? 1 : 0)}");
    }

    private string ResolveFileRouteAfterPostTunaFallbackClearedForLog()
        => FileTransferRouteResolver.Resolve(new FileTransferRouteResolverInput(
            IsFileTunaActive: IsFileTransferAccelerationPublishedAndHealthy(),
            IsPostTunaFileFallbackActive: false,
            IsDiagnosticRegularNknV6RouteEnabled: IsDiagnosticRegularNknV6RouteEnabledCore(),
            HandoffKind: FileTransferTransportHandoffKind.None,
            TransportProfileKind: FileTransferTransportProfileKind.Default)).TelemetryToken;

    private void MarkTunaFallbackAccelerationUsedAfterProof()
    {
        lock (accelerationGate)
        {
            if (tunaFallbackProofState is { } state)
            {
                state.AccelerationUsedAfterFallback = true;
            }
        }
    }

    private void RecordTunaFallbackNknFrameSent(MsgType messageType, NknBridgeChannel channel, int payloadBytes)
        => RecordTunaFallbackNknFrame(
            direction: "sent",
            messageType,
            channel,
            payloadBytes,
            currentSessionSecurityState.SessionId?.Value);

    private void RecordTunaFallbackNknFrameReceived(MsgType messageType, NknBridgeChannel channel, int payloadBytes, string? sessionId)
    {
        if (handlingTunaAcceleratedInboundMessage)
        {
            return;
        }

        RecordTunaFallbackNknFrame("received", messageType, channel, payloadBytes, sessionId);
    }

    private void RecordTunaFallbackFileTransferDataFrameSent(
        ReadOnlySpan<byte> payload,
        NknBridgeChannel channel,
        int payloadBytes,
        string? sessionId)
    {
        RecordTunaFallbackNknFrame("sent", MsgType.FileTransferDataFrame, channel, payloadBytes, sessionId);
        if (!TryDeserializeFileTransferDataFrameFromWire(payload, out var frame) ||
            frame is null)
        {
            return;
        }

        RecordPostTunaFallbackReceiverFrontierProofHint(frame, "sent", sessionId);

        if (!IsFileTransferFallbackNknProofPending() ||
            !TryMapPostTunaFileTransferFallbackNknProofKind(frame, "sent", out var proofKind))
        {
            return;
        }

        _ = CompleteFileTransferFallbackNknProofIfPending(proofKind, sessionId);
    }

    private void RecordTunaFallbackFileTransferDataFrameReceived(FileTransferDataFrame frame, NknBridgeChannel channel, int payloadBytes, string? sessionId)
    {
        if (handlingTunaAcceleratedInboundMessage)
        {
            return;
        }

        RecordTunaFallbackNknFrame("received", MsgType.FileTransferDataFrame, channel, payloadBytes, sessionId);
        RecordPostTunaFallbackReceiverFrontierProofHint(frame, "received", sessionId);
        if (TryMapFileTransferFallbackNknProofKind(frame, out var proofKind))
        {
            _ = CompleteFileTransferFallbackNknProofIfPending(proofKind, sessionId, frame);
        }
    }

    private void RecordPostTunaFallbackReceiverFrontierProofHint(
        FileTransferDataFrame frame,
        string direction,
        string? sessionId)
    {
        if (!TryMapPostTunaFallbackReceiverFrontierProofKind(frame, out var proofKind))
        {
            return;
        }

        var normalizedTransferId = string.IsNullOrWhiteSpace(frame.TransferId)
            ? null
            : frame.TransferId.Trim();
        var normalizedSessionId = !string.IsNullOrWhiteSpace(frame.SessionId)
            ? frame.SessionId.Trim()
            : string.IsNullOrWhiteSpace(sessionId)
                ? null
                : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedTransferId) ||
            string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            return;
        }

        lock (gate)
        {
            if (!fileTransferDataSessions.TryGetValue(normalizedTransferId, out var session) ||
                session.IsDisposed ||
                !string.Equals(session.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
                !TryGetFileTransferRouteHintUnsafe(normalizedSessionId, normalizedTransferId, out var routeHint) ||
                routeHint.Route != FileTransferRoute.PostTunaFallbackV6)
            {
                return;
            }

            fileTransferPostTunaFallbackRepairProofHints[normalizedTransferId] =
                new FileTransferPostTunaFallbackRepairProofHint(
                    normalizedSessionId,
                    normalizedTransferId,
                    proofKind,
                    SanitizeLogToken(direction),
                    DateTimeOffset.UtcNow);
        }
    }

    private void RecordPostTunaFallbackControlPlaneProofHint(
        FileTransferControlPlaneDeliveryRequest request,
        LifecycleDeliveryResult result)
    {
        if (!result.AcceptedAny ||
            !result.PeerVisibleAny ||
            request.AuthorityId.IsDefault ||
            request.AuthoritySchema != FileTransferAuthoritySchema.Current ||
            request.ControlPlaneGeneration <= 0 ||
            request.Kind is not (FileTransferControlPlaneKind.ReceiverState or FileTransferControlPlaneKind.FrontierRequest) ||
            !string.Equals(request.RouteToken, FileTransferRouteResolver.PostTunaFallbackV6Token, StringComparison.Ordinal) ||
            request.ProtocolVersion != FileTransferProtocol.ProtocolVersionV6 ||
            request.TransferLegGeneration <= 0 ||
            request.LiveRouteEpoch <= 0 ||
            request.Frame is not { } frame)
        {
            return;
        }

        var normalizedTransferId = string.IsNullOrWhiteSpace(frame.TransferId)
            ? null
            : frame.TransferId.Trim();
        var normalizedSessionId = string.IsNullOrWhiteSpace(frame.SessionId)
            ? null
            : frame.SessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedTransferId) ||
            string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            return;
        }

        var proofKind = request.Kind == FileTransferControlPlaneKind.ReceiverState
            ? "receiver_state_control_plane"
            : "frontier_request_control_plane";
        var proofDirection = request.Direction?.ToString().ToLowerInvariant() ?? "unknown";

        lock (gate)
        {
            if (!fileTransferDataSessions.TryGetValue(normalizedTransferId, out var session) ||
                session.IsDisposed ||
                !string.Equals(session.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
                !TryGetFileTransferRouteHintUnsafe(normalizedSessionId, normalizedTransferId, out var routeHint) ||
                routeHint.Route != FileTransferRoute.PostTunaFallbackV6)
            {
                return;
            }

            fileTransferPostTunaFallbackRepairProofHints[normalizedTransferId] =
                new FileTransferPostTunaFallbackRepairProofHint(
                    normalizedSessionId,
                    normalizedTransferId,
                    proofKind,
                    proofDirection,
                    DateTimeOffset.UtcNow);
        }

        MarkFileTransferFallbackLegAuthorityCompleted(
            normalizedSessionId,
            normalizedTransferId,
            request.RouteToken,
            request.ProtocolVersion,
            request.LiveRouteEpoch,
            request.TransferLegGeneration,
            request.BridgeRecoveryGeneration,
            request.TransportEpoch,
            request.CheckpointRequestId,
            request.Reason,
            proofKind,
            proofDirection);
    }

    private static bool TryMapPostTunaFallbackReceiverFrontierProofKind(
        FileTransferDataFrame frame,
        out string proofKind)
    {
        proofKind = frame switch
        {
            FileTransferReceiverStateFrameV6 => "receiver_state",
            FileTransferFrontierRequestFrameV6 => "frontier_request",
            _ => string.Empty,
        };

        return proofKind.Length > 0;
    }

    private void RecordTunaFallbackNknControlSent(MsgType messageType)
    {
        if (messageType is MsgType.ScreenShareFrame or MsgType.FileTransferDataFrame)
        {
            return;
        }

        lock (accelerationGate)
        {
            if (TryGetCurrentTunaFallbackProofStateUnsafe(currentSessionSecurityState.SessionId?.Value, out var state))
            {
                state.ControlNknMessagesSent++;
            }
        }
    }

    private void RecordTunaFallbackNknControlReceived(MsgType messageType, string? sessionId, int payloadBytes = 0)
    {
        if (messageType is MsgType.ScreenShareFrame or MsgType.FileTransferDataFrame)
        {
            return;
        }

        _ = CompleteFileTransferFallbackNknProofIfPending(
            $"nkn_control_{MapSecureMessageTypeForProof(messageType)}_received",
            sessionId);
    }

    private void RecordTunaFallbackNknFrame(
        string direction,
        MsgType messageType,
        NknBridgeChannel channel,
        int payloadBytes,
        string? sessionId)
    {
        if (!IsTunaFallbackProofFrame(messageType, channel))
        {
            return;
        }

        TunaFallbackProofState? snapshot;
        bool shouldLog;
        bool shouldLogScreenHandoffFrame = false;
        lock (accelerationGate)
        {
            if (!TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out var state))
            {
                shouldLog = false;
                snapshot = null;
            }
            else
            {
                if (direction == "sent")
                {
                    if (messageType == MsgType.ScreenShareFrame)
                    {
                        state.ScreenNknFramesSent++;
                    }
                    else
                    {
                        state.FileNknFramesSent++;
                    }
                }
                else
                {
                    if (messageType == MsgType.ScreenShareFrame)
                    {
                        state.ScreenNknFramesReceived++;
                    }
                    else
                    {
                        state.FileNknFramesReceived++;
                    }
                }

                if (messageType == MsgType.ScreenShareFrame)
                {
                    shouldLogScreenHandoffFrame = true;
                    if (state.ScreenState is TunaFallbackLaneState.Pending or TunaFallbackLaneState.WaitingForRegularNkn)
                    {
                        state.ScreenState = TunaFallbackLaneState.MediaReady;
                    }
                }

                shouldLog = ShouldLogTunaFallbackProofMarkerUnsafe(state, $"{direction}:{messageType}:{channel}", DateTimeOffset.UtcNow);
                snapshot = state;
            }
        }

        if (shouldLog && snapshot is not null)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_fallback_nkn_frame_{direction}; message_type={MapTunaFallbackProofMessageType(messageType)}; channel={MapBridgeChannel(channel)}; session_id={snapshot.SessionId}; fallback_epoch={snapshot.Epoch}; payload_bytes={Math.Max(0, payloadBytes)}; reason={snapshot.Reason}");
            if (shouldLogScreenHandoffFrame && messageType == MsgType.ScreenShareFrame)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=screenshare_tuna_handoff_nkn_frame_{direction}; session_id={snapshot.SessionId}; fallback_epoch={snapshot.Epoch}; payload_bytes={Math.Max(0, payloadBytes)}; reason={snapshot.Reason}");
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=tuna_disable_handoff_media_ready; session_id={snapshot.SessionId}; reason={snapshot.Reason}; proof=screen_nkn_frame_{direction}; lanes={FormatAccelerationLanesForLog(snapshot.Lanes)}");
                LogMixedFallbackLaneState(snapshot, "screen_media_ready");
            }
        }
    }

    private void MarkFileTransferFallbackNknProofPending(
        string reason,
        string? sessionId,
        NknAccelerationLaneKind lanes,
        FileTransferReceiveRecoveryRequest? authorityRequest = null)
    {
        if ((lanes & NknAccelerationLaneKind.File) != NknAccelerationLaneKind.File)
        {
            return;
        }

        var normalizedReason = SanitizeLogToken(reason);
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : sessionId.Trim();
        RuntimeUnlockRouteCommitSnapshot? acceptedPreCommitSnapshot;
        lock (accelerationGate)
        {
            acceptedPreCommitSnapshot = runtimeUnlockAcceptedPreCommitSnapshot;
        }

        lock (fileTransferFallbackProofGate)
        {
            fileTransferFallbackProofPending = true;
            fileTransferFallbackProofReason = normalizedReason;
            fileTransferFallbackProofSessionId = normalizedSessionId;
            fileTransferFallbackProofLanes = lanes;
            fileTransferFallbackProofGeneration++;
            fileTransferFallbackProofProbeScheduled = false;
            fileTransferFallbackBulkProofObserved = false;
            fileTransferFallbackControlProofObserved = false;
            fileTransferFallbackProofTransferId = authorityRequest?.TransferId;
            fileTransferFallbackProofDirection = authorityRequest?.Direction;
            fileTransferFallbackProofRouteToken = authorityRequest?.RouteToken;
            fileTransferFallbackProofProtocolVersion = authorityRequest?.ProtocolVersion ?? 0;
            fileTransferFallbackProofLiveRouteEpoch = authorityRequest?.LiveRouteEpoch ?? 0;
            fileTransferFallbackProofLegGeneration = authorityRequest?.TransferLegGeneration ?? 0;
            fileTransferFallbackProofBridgeRecoveryGeneration = authorityRequest?.BridgeRecoveryGeneration ?? 0;
            fileTransferFallbackProofTransportEpoch = authorityRequest?.TransportEpoch ?? 0;
            fileTransferFallbackProofCheckpointRequestId = authorityRequest?.CheckpointRequestId;
            fileTransferFallbackProofAuthorityReason = authorityRequest?.AuthorityReason;
            fileTransferFallbackProofPreCommitSnapshot = acceptedPreCommitSnapshot;
        }

        var authorityFields = authorityRequest is null
            ? string.Empty
            : FormatFileTransferFallbackLegAuthorityFields(authorityRequest);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_fallback_nkn_proof_pending; session_id={SanitizeLogToken(normalizedSessionId ?? "none")}; reason={normalizedReason}; lanes={FormatAccelerationLanesForLog(lanes)}{authorityFields}");
    }

    private bool ShouldUseFileTransferV6EpochForRegularNknRecovery(string? sessionId)
    {
        if (!HasActiveFileTransferDataSessionsForRecovery())
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out var state) &&
                (state.Lanes & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File &&
                state.FileState != TunaFallbackLaneState.Recovered)
            {
                return true;
            }
        }

        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        lock (fileTransferV6TransportEpochGate)
        {
            return fileTransferV6RegularNknEpochScopes.Values.Any(scope =>
                scope.CurrentRecoveredBoundary is { } recovered &&
                scope.LatestSnapshot is { State: V6TransportEpochState.Recovered } latest &&
                latest.TransportEpoch == recovered.TransportEpoch &&
                string.Equals(recovered.SessionId, sessionId.Trim(), StringComparison.Ordinal));
        }
    }

    private bool IsFileTransferFallbackNknProofPending()
    {
        lock (fileTransferFallbackProofGate)
        {
            return fileTransferFallbackProofPending;
        }
    }

    private void CompleteFileTransferFallbackProofUnsafe()
    {
        fileTransferFallbackProofPending = false;
        fileTransferFallbackProofReason = "none";
        fileTransferFallbackProofSessionId = null;
        fileTransferFallbackProofLanes = NknAccelerationLaneKind.None;
        fileTransferFallbackProofGeneration++;
        fileTransferFallbackProofProbeScheduled = false;
        fileTransferFallbackBulkProofObserved = false;
        fileTransferFallbackControlProofObserved = false;
        ClearFileTransferFallbackProofAuthorityUnsafe();
    }

    private bool TryCreateRuntimeUnlockUncommittedTunaFallbackProofBoundary(
        string sessionId,
        string transferId,
        long proofGeneration,
        string proofKind,
        string reason,
        PostTunaFallbackPeerProofFrameIdentity frameIdentity,
        RuntimeUnlockRouteCommitSnapshot? retainedPreCommitSnapshot,
        out RuntimeUnlockUncommittedTunaFallbackProofBoundary boundary,
        out string decisionReason)
    {
        boundary = null!;
        decisionReason = "accepted_precommit_scope_unavailable";
        TransportFileTransferDataSession? dataSession;
        lock (gate)
        {
            if (!fileTransferDataSessions.TryGetValue(transferId, out dataSession) ||
                dataSession.IsDisposed ||
                !string.Equals(dataSession.SessionId, sessionId, StringComparison.Ordinal))
            {
                decisionReason = "data_session_scope_unavailable";
                return false;
            }
        }

        RuntimeUnlockRouteCommitSnapshot snapshot = retainedPreCommitSnapshot!;
        if (snapshot is null &&
            !((IRuntimeUnlockRouteCommitProofProvider)this)
                .TryGetRuntimeUnlockRouteCommitProof(
                    dataSession.SessionId,
                    dataSession.TransferId,
                    out snapshot))
        {
            lock (accelerationGate)
            {
                snapshot = runtimeUnlockPreCommitProbeStartedSnapshot!;
                if (snapshot is null ||
                    !string.Equals(snapshot.SessionId, dataSession.SessionId, StringComparison.Ordinal) ||
                    !string.Equals(snapshot.TransferId, dataSession.TransferId, StringComparison.Ordinal) ||
                    !string.Equals(
                        snapshot.PathProbeState,
                        RuntimeUnlockPathProbeState.Acked.ToString(),
                        StringComparison.OrdinalIgnoreCase))
                {
                    decisionReason = "accepted_precommit_snapshot_unavailable";
                    return false;
                }
            }
        }

        var peerProof = new PostTunaFallbackPeerProofEvidence(
            dataSession.SessionId,
            dataSession.TransferId,
            FileTransferDirection.Outbound,
            proofGeneration,
            frameIdentity.TransportEpoch,
            proofKind,
            reason,
            frameIdentity);
        boundary = new RuntimeUnlockUncommittedTunaFallbackProofBoundary(
            peerProof,
            snapshot);
        decisionReason = boundary.IsComplete
            ? "accepted_precommit_scope_bound"
            : "accepted_precommit_snapshot_incomplete";
        return boundary.IsComplete;
    }

    private static void LogRuntimeUnlockUncommittedTunaFallbackPeerProofBindingDecision(
        string? sessionId,
        string? transferId,
        long proofGeneration,
        long proofTransportEpoch,
        string status,
        string reason)
        => LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_uncommitted_tuna_fallback_peer_proof_binding_decided; session_id={SanitizeLogToken(sessionId ?? "none")}; transfer_id={SanitizeLogToken(transferId ?? "none")}; direction=outbound; proof_generation={proofGeneration}; proof_transport_epoch={proofTransportEpoch}; binding_status={SanitizeLogToken(status)}; decision_reason={SanitizeLogToken(reason)}");

    private bool HasCurrentFileTunaV4Publication(string sessionId, string transferId)
    {
        lock (gate)
        {
            return TryGetFileTransferRouteHintUnsafe(
                       sessionId,
                       transferId,
                       FileTransferDirection.Outbound,
                       out var hint) &&
                   hint.Route == FileTransferRoute.FileTunaV4 &&
                   hint.ProtocolVersion == FileTransferProtocol.ProtocolVersionV4;
        }
    }

    private bool CompleteFileTransferFallbackNknProofIfPending(
        string proofKind,
        string? sessionId,
        FileTransferDataFrame? proofFrame = null)
    {
        string reason;
        string? pendingSessionId;
        NknAccelerationLaneKind lanes;
        bool bulkProofObserved;
        bool controlProofObserved;
        bool shouldLogUnconfirmed = false;
        bool requiresV6EpochRecovery = false;
        bool completed = false;
        string? authorityTransferId = null;
        FileTransferDirection? authorityDirection = null;
        long authorityProofGeneration = 0;
        string? authorityRouteToken = null;
        int authorityProtocolVersion = 0;
        int authorityLiveRouteEpoch = 0;
        int authorityLegGeneration = 0;
        int authorityBridgeRecoveryGeneration = 0;
        long authorityTransportEpoch = 0;
        string? authorityCheckpointRequestId = null;
        string? authorityReason = null;
        bool needsUncommittedBoundaryBinding = false;
        RuntimeUnlockUncommittedTunaFallbackProofBoundary? uncommittedProofBoundary = null;
        var uncommittedProofBoundaryDecisionReason = "accepted_precommit_scope_unavailable";
        RuntimeUnlockRouteCommitSnapshot? retainedPreCommitSnapshot = null;
        var normalizedProofKind = SanitizeLogToken(proofKind);
        var authoritativeProof = IsAuthoritativeFileTransferFallbackNknProof(normalizedProofKind);
        PostTunaFallbackPeerProofFrameIdentity? proofFrameIdentity = null;
        if (IsPostTunaFileTransferFallbackNknProof(normalizedProofKind) &&
            proofFrame is not null &&
            !PostTunaFallbackPeerProofFrameIdentity.TryCreate(proofFrame, out proofFrameIdentity))
        {
            return false;
        }

        lock (fileTransferFallbackProofGate)
        {
            if (!fileTransferFallbackProofPending)
            {
                return false;
            }

            var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? null : sessionId.Trim();
            if (!string.IsNullOrWhiteSpace(fileTransferFallbackProofSessionId) &&
                !string.IsNullOrWhiteSpace(normalizedSessionId) &&
                !string.Equals(fileTransferFallbackProofSessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                return false;
            }

            var requiresSessionBoundProofFrame =
                !string.IsNullOrWhiteSpace(fileTransferFallbackProofTransferId) &&
                fileTransferFallbackProofDirection == FileTransferDirection.Outbound &&
                fileTransferFallbackProofGeneration > 0 &&
                fileTransferFallbackProofTransportEpoch > 0;
            if (IsPostTunaFileTransferFallbackNknProof(normalizedProofKind) &&
                requiresSessionBoundProofFrame &&
                (proofFrameIdentity is null ||
                 !IsExactPendingPostTunaFallbackProofFrameUnsafe(proofFrame, normalizedSessionId)))
            {
                return false;
            }

            if (!authoritativeProof)
            {
                reason = fileTransferFallbackProofReason;
                pendingSessionId = fileTransferFallbackProofSessionId ?? normalizedSessionId;
                lanes = fileTransferFallbackProofLanes;
                shouldLogUnconfirmed = !fileTransferFallbackBulkProofObserved;
                fileTransferFallbackBulkProofObserved = true;
                bulkProofObserved = fileTransferFallbackBulkProofObserved;
                controlProofObserved = fileTransferFallbackControlProofObserved;
            }
            else
            {
                reason = fileTransferFallbackProofReason;
                pendingSessionId = fileTransferFallbackProofSessionId ?? normalizedSessionId;
                lanes = fileTransferFallbackProofLanes;
                fileTransferFallbackControlProofObserved = true;
                requiresV6EpochRecovery =
                    (lanes & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File &&
                    !IsPostTunaFileTransferFallbackNknProof(normalizedProofKind);
                bulkProofObserved = fileTransferFallbackBulkProofObserved;
                controlProofObserved = fileTransferFallbackControlProofObserved;
                if (requiresV6EpochRecovery)
                {
                    shouldLogUnconfirmed = true;
                }
                else
                {
                    authorityTransferId = fileTransferFallbackProofTransferId;
                    authorityDirection = fileTransferFallbackProofDirection;
                    authorityProofGeneration = fileTransferFallbackProofGeneration;
                    authorityRouteToken = fileTransferFallbackProofRouteToken;
                    authorityProtocolVersion = fileTransferFallbackProofProtocolVersion;
                    authorityLiveRouteEpoch = fileTransferFallbackProofLiveRouteEpoch;
                    authorityLegGeneration = fileTransferFallbackProofLegGeneration;
                    authorityBridgeRecoveryGeneration = fileTransferFallbackProofBridgeRecoveryGeneration;
                    authorityTransportEpoch = fileTransferFallbackProofTransportEpoch;
                    authorityCheckpointRequestId = fileTransferFallbackProofCheckpointRequestId;
                    authorityReason = fileTransferFallbackProofAuthorityReason;
                    retainedPreCommitSnapshot = fileTransferFallbackProofPreCommitSnapshot;
                    needsUncommittedBoundaryBinding =
                        IsPostTunaFileTransferFallbackNknProof(normalizedProofKind) &&
                        string.IsNullOrWhiteSpace(authorityTransferId);
                    if (!needsUncommittedBoundaryBinding)
                    {
                        CompleteFileTransferFallbackProofUnsafe();
                        completed = true;
                    }
                }
            }
        }

        if (needsUncommittedBoundaryBinding)
        {
            if (proofFrame is not null &&
                !string.IsNullOrWhiteSpace(pendingSessionId) &&
                !string.IsNullOrWhiteSpace(proofFrame.TransferId) &&
                string.Equals(proofFrame.SessionId, pendingSessionId, StringComparison.Ordinal) &&
                HasCurrentFileTunaV4Publication(pendingSessionId, proofFrame.TransferId.Trim()))
            {
                lock (fileTransferFallbackProofGate)
                {
                    if (fileTransferFallbackProofPending &&
                        fileTransferFallbackProofGeneration == authorityProofGeneration &&
                        string.Equals(
                            fileTransferFallbackProofSessionId,
                            pendingSessionId,
                            StringComparison.Ordinal))
                    {
                        CompleteFileTransferFallbackProofUnsafe();
                        completed = true;
                    }
                }
            }

            if (completed)
            {
                needsUncommittedBoundaryBinding = false;
            }
            else if (proofFrameIdentity is null ||
                string.IsNullOrWhiteSpace(pendingSessionId) ||
                proofFrame is null ||
                string.IsNullOrWhiteSpace(proofFrame.TransferId) ||
                !string.Equals(proofFrame.SessionId, pendingSessionId, StringComparison.Ordinal) ||
                !TryCreateRuntimeUnlockUncommittedTunaFallbackProofBoundary(
                    pendingSessionId,
                    proofFrame.TransferId.Trim(),
                    authorityProofGeneration,
                    normalizedProofKind,
                    reason,
                    proofFrameIdentity,
                    retainedPreCommitSnapshot,
                    out uncommittedProofBoundary,
                    out uncommittedProofBoundaryDecisionReason))
            {
                LogRuntimeUnlockUncommittedTunaFallbackPeerProofBindingDecision(
                    pendingSessionId,
                    proofFrame?.TransferId ?? authorityTransferId,
                    authorityProofGeneration,
                    proofFrameIdentity?.TransportEpoch ?? 0,
                    "Held",
                    uncommittedProofBoundaryDecisionReason);
                return false;
            }

            if (needsUncommittedBoundaryBinding)
            {
                lock (fileTransferFallbackProofGate)
                {
                    if (!fileTransferFallbackProofPending ||
                        fileTransferFallbackProofGeneration != authorityProofGeneration ||
                        !string.Equals(
                            fileTransferFallbackProofSessionId,
                            pendingSessionId,
                            StringComparison.Ordinal))
                    {
                        LogRuntimeUnlockUncommittedTunaFallbackPeerProofBindingDecision(
                            pendingSessionId,
                            uncommittedProofBoundary!.PeerProofEvidence.TransferId,
                            authorityProofGeneration,
                            uncommittedProofBoundary.PeerProofEvidence.TransportEpoch,
                            "Invalidated",
                            "pending_proof_scope_replaced");
                        return false;
                    }

                    CompleteFileTransferFallbackProofUnsafe();
                    completed = true;
                }

                LogRuntimeUnlockUncommittedTunaFallbackPeerProofBindingDecision(
                    pendingSessionId,
                    uncommittedProofBoundary!.PeerProofEvidence.TransferId,
                    authorityProofGeneration,
                    uncommittedProofBoundary.PeerProofEvidence.TransportEpoch,
                    "Bound",
                    "accepted_precommit_scope_bound");
            }
        }

        if (!completed)
        {
            if (shouldLogUnconfirmed)
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=filetransfer_fallback_nkn_proof_unconfirmed; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={normalizedProofKind}; lanes={FormatAccelerationLanesForLog(lanes)}; requires_control_proof={(controlProofObserved ? 0 : 1)}; requires_v6_epoch_recovery={(requiresV6EpochRecovery ? 1 : 0)}; bulk_seen={(bulkProofObserved ? 1 : 0)}; control_seen={(controlProofObserved ? 1 : 0)}");
                if (requiresV6EpochRecovery)
                {
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=filetransfer_fallback_nkn_proof_waiting_for_v6_epoch; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={normalizedProofKind}; lanes={FormatAccelerationLanesForLog(lanes)}");
                }
            }

            return false;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_fallback_nkn_proof_observed; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={normalizedProofKind}; lanes={FormatAccelerationLanesForLog(lanes)}; bulk_seen={(bulkProofObserved ? 1 : 0)}; control_seen={(controlProofObserved ? 1 : 0)}");
        if (authorityLegGeneration > 0)
        {
            MarkFileTransferFallbackLegAuthorityCompleted(
                pendingSessionId,
                authorityTransferId,
                authorityRouteToken,
                authorityProtocolVersion,
                authorityLiveRouteEpoch,
                authorityLegGeneration,
                authorityBridgeRecoveryGeneration,
                authorityTransportEpoch,
                authorityCheckpointRequestId,
                authorityReason,
                normalizedProofKind);
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_disable_handoff_nkn_ready; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={normalizedProofKind}; lanes={FormatAccelerationLanesForLog(lanes)}");
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_disable_handoff_completed; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={normalizedProofKind}; lanes={FormatAccelerationLanesForLog(lanes)}");

        if ((lanes & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File)
        {
            PostTunaFallbackHandoffEvidence? postTunaFallbackHandoffEvidence = null;
            if (IsPostTunaFileTransferFallbackNknProof(normalizedProofKind))
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=filetransfer_post_tuna_fallback_nkn_proved; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; transfer_id={SanitizeLogToken(uncommittedProofBoundary?.PeerProofEvidence.TransferId ?? authorityTransferId ?? "none")}; direction={FormatFileTransferDirection(uncommittedProofBoundary?.PeerProofEvidence.Direction ?? authorityDirection)}; reason={reason}; proof={normalizedProofKind}; proof_generation={uncommittedProofBoundary?.PeerProofEvidence.ProofGeneration ?? authorityProofGeneration}; proof_transport_epoch={uncommittedProofBoundary?.PeerProofEvidence.TransportEpoch ?? authorityTransportEpoch}; proof_frame_identity={SanitizeLogToken(uncommittedProofBoundary?.PeerProofEvidence.FrameIdentity?.Sha256 ?? proofFrameIdentity?.Sha256 ?? "none")}; transaction_generation={uncommittedProofBoundary?.PreCommitSnapshot.TransactionGeneration ?? 0}; offer_generation={uncommittedProofBoundary?.PreCommitSnapshot.OfferGeneration ?? 0}; tuna_path_lease_generation={uncommittedProofBoundary?.PreCommitSnapshot.TunaPathLeaseGeneration ?? 0}; launch_generation={uncommittedProofBoundary?.PreCommitSnapshot.LaunchGeneration ?? 0}; probe_id={SanitizeLogToken(uncommittedProofBoundary?.PreCommitSnapshot.PathProbeId ?? "none")}; binding_status={(uncommittedProofBoundary is null ? "legacy" : "bound")}; lanes={FormatAccelerationLanesForLog(lanes)}");
                if (!string.IsNullOrWhiteSpace(pendingSessionId) &&
                    !string.IsNullOrWhiteSpace(authorityTransferId) &&
                    authorityDirection == FileTransferDirection.Outbound &&
                    authorityProofGeneration > 0 &&
                    string.Equals(
                        authorityRouteToken!,
                        FileTransferRouteResolver.PostTunaFallbackV6Token,
                        StringComparison.Ordinal) &&
                    authorityProtocolVersion == FileTransferProtocol.ProtocolVersionV6 &&
                    authorityLiveRouteEpoch > 0 &&
                    authorityLegGeneration > 0 &&
                    authorityBridgeRecoveryGeneration > 0 &&
                    authorityTransportEpoch > 0 &&
                    !string.IsNullOrWhiteSpace(authorityCheckpointRequestId) &&
                    !string.IsNullOrWhiteSpace(authorityReason))
                {
                    postTunaFallbackHandoffEvidence = new PostTunaFallbackHandoffEvidence(
                        pendingSessionId.Trim(),
                        authorityTransferId.Trim(),
                        authorityDirection.Value,
                        authorityProofGeneration,
                        authorityRouteToken!,
                        authorityProtocolVersion,
                        authorityLiveRouteEpoch,
                        authorityLegGeneration,
                        authorityBridgeRecoveryGeneration,
                        authorityTransportEpoch,
                        authorityCheckpointRequestId!,
                        normalizedProofKind,
                        authorityReason!,
                        proofFrameIdentity);
                }
            }

            MarkTunaFallbackLaneState(
                pendingSessionId,
                lane: NknAccelerationLaneKind.File,
                state: TunaFallbackLaneState.Recovered,
                reason: reason);
            SetFileTransferDataSessionsAvailability(
                isAvailable: true,
                reason: "transport_recovered",
                requiresResumeRequest: true,
                handoffKind: FileTransferTransportHandoffKind.TunaToNormalFallback,
                targetTransport: FileTransferTransportKind.RegularNkn,
                postTunaFallbackHandoffEvidence,
                uncommittedProofBoundary);
            if (IsPostTunaFileTransferFallbackNknProof(normalizedProofKind))
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=filetransfer_post_tuna_fallback_cleanup_completed; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={normalizedProofKind}; lanes={FormatAccelerationLanesForLog(lanes)}");
            }
        }

        _ = QueueCurrentRuntimeUnlockPostTunaFallbackActivationRecheck(
            "fallback_control_proof_observed",
            TimeSpan.Zero);

        return true;
    }

    private bool CompleteFileTransferFallbackNknProofFromV6Epoch(FileTransferV6TransportEpochSnapshot snapshot)
    {
        var reason = SanitizeLogToken(snapshot.Reason);
        var pendingSessionId = snapshot.SessionId;
        var lanes = NknAccelerationLaneKind.File;
        var bulkProofObserved = false;
        var controlProofObserved = true;
        var completedPendingProof = false;
        var awaitingExactPeerFrame = false;
        string? authorityTransferId = null;
        FileTransferDirection? authorityDirection = null;
        long authorityProofGeneration = 0;
        string? authorityRouteToken = null;
        int authorityProtocolVersion = 0;
        int authorityLiveRouteEpoch = 0;
        int authorityLegGeneration = 0;
        int authorityBridgeRecoveryGeneration = 0;
        long authorityTransportEpoch = 0;
        string? authorityCheckpointRequestId = null;
        string? authorityReason = null;
        lock (fileTransferFallbackProofGate)
        {
            if (fileTransferFallbackProofPending &&
                (fileTransferFallbackProofLanes & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File)
            {
                var normalizedSessionId = snapshot.SessionId.Trim();
                if (!string.IsNullOrWhiteSpace(fileTransferFallbackProofSessionId) &&
                    !string.Equals(fileTransferFallbackProofSessionId, normalizedSessionId, StringComparison.Ordinal))
                {
                    return false;
                }

                var hasBoundFallbackAuthority =
                    !string.IsNullOrWhiteSpace(fileTransferFallbackProofTransferId) ||
                    fileTransferFallbackProofDirection is not null ||
                    fileTransferFallbackProofTransportEpoch > 0;
                if (hasBoundFallbackAuthority &&
                    (!string.Equals(
                         fileTransferFallbackProofTransferId,
                         snapshot.TransferId,
                         StringComparison.Ordinal) ||
                     fileTransferFallbackProofDirection != snapshot.Direction ||
                     snapshot.HandoffKind != FileTransferTransportHandoffKind.TunaToNormalFallback ||
                     snapshot.SourceTransport != FileTransferTransportKind.Tuna ||
                     snapshot.TargetTransport != FileTransferTransportKind.RegularNkn ||
                     snapshot.TransportEpoch != fileTransferFallbackProofTransportEpoch))
                {
                    return false;
                }

                var requiresExactPeerFrame =
                    !string.IsNullOrWhiteSpace(fileTransferFallbackProofTransferId) &&
                    fileTransferFallbackProofDirection == FileTransferDirection.Outbound &&
                    fileTransferFallbackProofGeneration > 0 &&
                    fileTransferFallbackProofTransportEpoch > 0;
                if (requiresExactPeerFrame)
                {
                    // The recovered epoch is a scope boundary, not the exact peer frame
                    // that authorizes the uncommitted-Tuna fallback adoption. Preserve the
                    // pending proof until the matching state/frontier frame binds it.
                    awaitingExactPeerFrame = true;
                }
                else
                {
                    reason = fileTransferFallbackProofReason;
                    pendingSessionId = fileTransferFallbackProofSessionId ?? normalizedSessionId;
                    lanes = fileTransferFallbackProofLanes;
                    bulkProofObserved = fileTransferFallbackBulkProofObserved;
                    authorityTransferId = fileTransferFallbackProofTransferId;
                    authorityDirection = fileTransferFallbackProofDirection;
                    authorityProofGeneration = fileTransferFallbackProofGeneration;
                    authorityRouteToken = fileTransferFallbackProofRouteToken;
                    authorityProtocolVersion = fileTransferFallbackProofProtocolVersion;
                    authorityLiveRouteEpoch = fileTransferFallbackProofLiveRouteEpoch;
                    authorityLegGeneration = fileTransferFallbackProofLegGeneration;
                    authorityBridgeRecoveryGeneration = fileTransferFallbackProofBridgeRecoveryGeneration;
                    authorityTransportEpoch = fileTransferFallbackProofTransportEpoch;
                    authorityCheckpointRequestId = fileTransferFallbackProofCheckpointRequestId;
                    authorityReason = fileTransferFallbackProofAuthorityReason;
                    completedPendingProof = true;
                    fileTransferFallbackProofPending = false;
                    fileTransferFallbackProofReason = "none";
                    fileTransferFallbackProofSessionId = null;
                    fileTransferFallbackProofLanes = NknAccelerationLaneKind.None;
                    fileTransferFallbackProofGeneration++;
                    fileTransferFallbackProofProbeScheduled = false;
                    fileTransferFallbackBulkProofObserved = false;
                    fileTransferFallbackControlProofObserved = false;
                    ClearFileTransferFallbackProofAuthorityUnsafe();
                }
            }
        }

        if (awaitingExactPeerFrame)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_fallback_nkn_proof_waiting_for_exact_peer_frame; session_id={SanitizeLogToken(snapshot.SessionId)}; transfer_id={SanitizeLogToken(snapshot.TransferId)}; direction={snapshot.Direction.ToString().ToLowerInvariant()}; transport_epoch={snapshot.TransportEpoch}; reason={reason}");
        }

        const string proofKind = "filetransfer_v6_epoch_recovered";
        PostTunaFallbackHandoffEvidence? postTunaFallbackHandoffEvidence = null;
        if (completedPendingProof)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_fallback_nkn_proof_observed; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={proofKind}; lanes={FormatAccelerationLanesForLog(lanes)}; bulk_seen={(bulkProofObserved ? 1 : 0)}; control_seen={(controlProofObserved ? 1 : 0)}");
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_disable_handoff_nkn_ready; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={proofKind}; lanes={FormatAccelerationLanesForLog(lanes)}");
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_disable_handoff_completed; session_id={SanitizeLogToken(pendingSessionId ?? "none")}; reason={reason}; proof={proofKind}; lanes={FormatAccelerationLanesForLog(lanes)}");
            if (authorityLegGeneration > 0)
            {
                MarkFileTransferFallbackLegAuthorityCompleted(
                    pendingSessionId,
                    authorityTransferId,
                    authorityRouteToken,
                    authorityProtocolVersion,
                    authorityLiveRouteEpoch,
                    authorityLegGeneration,
                    authorityBridgeRecoveryGeneration,
                    authorityTransportEpoch,
                    authorityCheckpointRequestId,
                    authorityReason,
                    proofKind);
            }

            if (!string.IsNullOrWhiteSpace(pendingSessionId) &&
                !string.IsNullOrWhiteSpace(authorityTransferId) &&
                authorityDirection == FileTransferDirection.Outbound &&
                authorityProofGeneration > 0 &&
                string.Equals(
                    authorityRouteToken!,
                    FileTransferRouteResolver.PostTunaFallbackV6Token,
                    StringComparison.Ordinal) &&
                authorityProtocolVersion == FileTransferProtocol.ProtocolVersionV6 &&
                authorityLiveRouteEpoch > 0 &&
                authorityLegGeneration > 0 &&
                authorityBridgeRecoveryGeneration > 0 &&
                authorityTransportEpoch > 0 &&
                !string.IsNullOrWhiteSpace(authorityCheckpointRequestId) &&
                !string.IsNullOrWhiteSpace(authorityReason))
            {
                postTunaFallbackHandoffEvidence = new PostTunaFallbackHandoffEvidence(
                    pendingSessionId.Trim(),
                    authorityTransferId.Trim(),
                    authorityDirection.Value,
                    authorityProofGeneration,
                    authorityRouteToken!,
                    authorityProtocolVersion,
                    authorityLiveRouteEpoch,
                    authorityLegGeneration,
                    authorityBridgeRecoveryGeneration,
                    authorityTransportEpoch,
                    authorityCheckpointRequestId!,
                    proofKind,
                    authorityReason!);
            }
        }

        EnsureFileTransferFallbackRecoveredStateFromV6Epoch(snapshot, reason);
        MarkTunaFallbackLaneState(
            pendingSessionId,
            lane: NknAccelerationLaneKind.File,
            state: TunaFallbackLaneState.Recovered,
            reason: reason);
        SetFileTransferDataSessionsAvailability(
            isAvailable: true,
            reason: "transport_recovered",
            requiresResumeRequest: false,
            handoffKind: snapshot.HandoffKind,
            targetTransport: FileTransferTransportKind.RegularNkn,
            postTunaFallbackHandoffEvidence);
        _ = QueueCurrentRuntimeUnlockPostTunaFallbackActivationRecheck(
            "fallback_v6_epoch_recovered",
            TimeSpan.Zero);
        return completedPendingProof;
    }

    private static void ClearRuntimeUnlockRetryFallbackTailUnblockRecheckUnsafe(
        RuntimeUnlockRecoveryRetryState state,
        RuntimeUnlockRetryFallbackTailUnblockRecheckIntent? expectedIntent = null)
    {
        if (expectedIntent is not null &&
            state.PendingFallbackTailUnblockRecheckIntent != expectedIntent)
        {
            return;
        }

        state.PendingFallbackTailUnblockRecheckIntent = null;
        state.PendingFallbackTailUnblockRecheckPhase =
            RuntimeUnlockRetryFallbackTailUnblockRecheckPhase.None;
        if (expectedIntent is null)
        {
            state.PendingFallbackTailUnblockRecheckNextIntent = null;
            state.FallbackTailUnblockRecheckWorkerActive = false;
        }
    }

    private static void ClearRuntimeUnlockRetryFallbackTailUnblockRecheckEligibilityUnsafe(
        RuntimeUnlockRecoveryRetryState state)
    {
        state.FallbackTailUnblockRecheckEligibleRequest = null;
        state.FallbackTailUnblockRecheckOriginalHoldReason = null;
    }

    private static bool IsRuntimeUnlockRetryFallbackTailUnblockRecheckHoldEligibleUnsafe(
        RuntimeUnlockRecoveryRetryState state,
        RuntimeUnlockRetryDispatchAuthorityRequest request)
    {
        if (state.DispatchDecisionStatus != RuntimeUnlockRetryDispatchDecisionStatus.Held)
        {
            return false;
        }

        var currentReason = SanitizeLogToken(state.DispatchDecisionReason ?? string.Empty);
        return string.Equals(
                   currentReason,
                   RuntimeUnlockFallbackPairedTailYieldPendingReason,
                   StringComparison.Ordinal) ||
               state.FallbackTailUnblockRecheckEligibleRequest == request &&
               string.Equals(
                   state.FallbackTailUnblockRecheckOriginalHoldReason,
                   RuntimeUnlockFallbackPairedTailYieldPendingReason,
                   StringComparison.Ordinal);
    }

    private static string CreateRuntimeUnlockRetryFallbackTailUnblockBoundaryIdentity(
        FileTransferV6TransportEpochSnapshot snapshot,
        long fallbackEpoch)
        => string.Join(
            '|',
            fallbackEpoch.ToString(CultureInfo.InvariantCulture),
            snapshot.SessionId.Trim(),
            snapshot.TransferId.Trim(),
            snapshot.Direction.ToString(),
            snapshot.RecoveryBoundaryGeneration.ToString(CultureInfo.InvariantCulture));

    private void QueueRuntimeUnlockRetryFallbackTailUnblockRecheck(
        FileTransferV6TransportEpochSnapshot snapshot)
    {
        if (disposed ||
            snapshot.State != V6TransportEpochState.Recovered ||
            snapshot.TargetTransport != FileTransferTransportKind.RegularNkn ||
            snapshot.HandoffKind is not FileTransferTransportHandoffKind.TunaToNormalFallback and
                not FileTransferTransportHandoffKind.RegularNknRecovery)
        {
            return;
        }

        if (!IsCurrentFileTransferV6RegularNknRecoveryBoundary(snapshot))
        {
            return;
        }

        RuntimeUnlockRetryFallbackTailUnblockRecheckIntent? intent = null;
        var startWorker = false;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            var request = state?.PendingDispatchAuthorityRequest;
            var currentSessionId = currentSessionSecurityState.SessionId?.Value;
            var fallbackEpoch = TryGetCurrentTunaFallbackProofStateUnsafe(
                snapshot.SessionId,
                out var fallbackState)
                ? fallbackState.Epoch
                : 0;
            var boundaryIdentity = CreateRuntimeUnlockRetryFallbackTailUnblockBoundaryIdentity(
                snapshot,
                fallbackEpoch);
            if (disposed ||
                state is null ||
                request is not { } pendingRequest ||
                string.IsNullOrWhiteSpace(currentSessionId) ||
                !string.Equals(currentSessionId.Trim(), state.SessionId, StringComparison.Ordinal) ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                state.RetryQueued ||
                state.RetryDispatching ||
                state.RetryDispatched ||
                state.ObservedSendPending ||
                !IsRuntimeUnlockRetryFallbackTailUnblockRecheckHoldEligibleUnsafe(
                    state,
                    pendingRequest) ||
                snapshot.RecoveryBoundaryGeneration <=
                    state.LastFallbackTailUnblockRecheckBoundaryGeneration ||
                !IsRuntimeUnlockRetryFallbackTailUnblockRequestCurrentUnsafe(
                    state,
                    pendingRequest,
                    snapshot,
                    out _))
            {
                return;
            }

            if (string.Equals(
                    SanitizeLogToken(state.DispatchDecisionReason ?? string.Empty),
                    RuntimeUnlockFallbackPairedTailYieldPendingReason,
                    StringComparison.Ordinal))
            {
                state.FallbackTailUnblockRecheckEligibleRequest = pendingRequest;
                state.FallbackTailUnblockRecheckOriginalHoldReason =
                    RuntimeUnlockFallbackPairedTailYieldPendingReason;
            }

            intent = new RuntimeUnlockRetryFallbackTailUnblockRecheckIntent(
                pendingRequest,
                pendingRequest.RecoveryContractGeneration,
                pendingRequest.RetiredOfferGeneration,
                pendingRequest.DispatchAttemptGeneration,
                pendingRequest.MissingDispatchSuccessorGeneration,
                pendingRequest.PredecessorAuthorityId,
                pendingRequest.SessionId,
                pendingRequest.TransferId,
                pendingRequest.Direction,
                snapshot.TransportEpoch,
                snapshot.HandoffKind,
                snapshot.SourceTransport,
                snapshot.TargetTransport,
                fallbackEpoch,
                snapshot.RecoveryBoundaryGeneration,
                SanitizeLogToken(snapshot.Reason),
                boundaryIdentity,
                snapshot.ObservationCompleted,
                ++runtimeUnlockFallbackTailUnblockRecheckNextGeneration);
            if (state.PendingFallbackTailUnblockRecheckIntent is { } currentIntent)
            {
                if (currentIntent.Request != pendingRequest ||
                    snapshot.RecoveryBoundaryGeneration <= currentIntent.RecoveryBoundaryGeneration ||
                    state.PendingFallbackTailUnblockRecheckNextIntent is { } queuedIntent &&
                    snapshot.RecoveryBoundaryGeneration <= queuedIntent.RecoveryBoundaryGeneration)
                {
                    return;
                }

                state.PendingFallbackTailUnblockRecheckNextIntent = intent;
            }
            else
            {
                state.PendingFallbackTailUnblockRecheckIntent = intent;
                state.PendingFallbackTailUnblockRecheckPhase =
                    RuntimeUnlockRetryFallbackTailUnblockRecheckPhase.Captured;
            }

            state.LastFallbackTailUnblockRecheckBoundaryGeneration =
                snapshot.RecoveryBoundaryGeneration;

            if (!state.FallbackTailUnblockRecheckWorkerActive)
            {
                state.FallbackTailUnblockRecheckWorkerActive = true;
                startWorker = true;
            }
        }

        if (startWorker)
        {
            _ = Task.Run(ProcessRuntimeUnlockRetryFallbackTailUnblockRechecksAsync);
        }
    }

    private async Task ProcessRuntimeUnlockRetryFallbackTailUnblockRechecksAsync()
    {
        while (true)
        {
            RuntimeUnlockRetryFallbackTailUnblockRecheckIntent? intent;
            RuntimeUnlockRetryFallbackTailUnblockRecheckIntent? supersededIntent = null;
            lock (accelerationGate)
            {
                var state = runtimeUnlockRecoveryRetryState;
                if (state is null ||
                    !state.FallbackTailUnblockRecheckWorkerActive)
                {
                    return;
                }

                intent = state.PendingFallbackTailUnblockRecheckIntent;
                if (intent is not null &&
                    state.PendingFallbackTailUnblockRecheckNextIntent is { } nextIntent &&
                    nextIntent.RecoveryBoundaryGeneration > intent.RecoveryBoundaryGeneration)
                {
                    supersededIntent = intent;
                    state.PendingFallbackTailUnblockRecheckIntent = nextIntent;
                    state.PendingFallbackTailUnblockRecheckNextIntent = null;
                    state.PendingFallbackTailUnblockRecheckPhase =
                        RuntimeUnlockRetryFallbackTailUnblockRecheckPhase.Captured;
                    intent = nextIntent;
                }

                if (intent is null)
                {
                    state.FallbackTailUnblockRecheckWorkerActive = false;
                    return;
                }
            }

            if (supersededIntent is not null)
            {
                LogRuntimeUnlockRetryFallbackTailUnblockRecheck(
                    "runtime_unlock_retry_dispatch_fallback_tail_unblock_recheck_discarded",
                    supersededIntent,
                    null,
                    "recheck_boundary_superseded");
            }

            try
            {
                // Core completes this signal only after Observe has returned. This is the
                // lock-order boundary before the authority bridge may re-enter Core.
                await intent.ObservationCompleted.ConfigureAwait(false);
                if (RuntimeUnlockRetryFallbackTailUnblockRecheckBarrierForTests is { } testBarrier)
                {
                    await testBarrier().ConfigureAwait(false);
                }

                var promoteNewerBoundary = false;
                lock (accelerationGate)
                {
                    var state = runtimeUnlockRecoveryRetryState;
                    if (state?.PendingFallbackTailUnblockRecheckIntent == intent &&
                        state.PendingFallbackTailUnblockRecheckNextIntent is { } nextIntent &&
                        nextIntent.RecoveryBoundaryGeneration > intent.RecoveryBoundaryGeneration)
                    {
                        state.PendingFallbackTailUnblockRecheckIntent = nextIntent;
                        state.PendingFallbackTailUnblockRecheckNextIntent = null;
                        state.PendingFallbackTailUnblockRecheckPhase =
                            RuntimeUnlockRetryFallbackTailUnblockRecheckPhase.Captured;
                        promoteNewerBoundary = true;
                    }
                }

                if (promoteNewerBoundary)
                {
                    LogRuntimeUnlockRetryFallbackTailUnblockRecheck(
                        "runtime_unlock_retry_dispatch_fallback_tail_unblock_recheck_discarded",
                        intent,
                        null,
                        "recheck_boundary_superseded");
                    continue;
                }

                PublishRuntimeUnlockRetryFallbackTailUnblockRecheck(intent);
            }
            catch (Exception ex)
            {
                lock (accelerationGate)
                {
                    var state = runtimeUnlockRecoveryRetryState;
                    if (state?.PendingFallbackTailUnblockRecheckIntent == intent)
                    {
                        ClearRuntimeUnlockRetryFallbackTailUnblockRecheckUnsafe(state, intent);
                    }
                }

                LogRuntimeUnlockRetryFallbackTailUnblockRecheck(
                    "runtime_unlock_retry_dispatch_fallback_tail_unblock_recheck_discarded",
                    intent,
                    null,
                    $"recheck_async_callback_failed_{SanitizeLogToken(ex.GetType().Name)}");
            }

            lock (accelerationGate)
            {
                var state = runtimeUnlockRecoveryRetryState;
                if (state is null || !state.FallbackTailUnblockRecheckWorkerActive)
                {
                    return;
                }

                if (state.PendingFallbackTailUnblockRecheckIntent is null &&
                    state.PendingFallbackTailUnblockRecheckNextIntent is { } nextIntent &&
                    state.PendingDispatchAuthorityRequest == nextIntent.Request &&
                    IsRuntimeUnlockRetryFallbackTailUnblockRecheckHoldEligibleUnsafe(
                        state,
                        nextIntent.Request))
                {
                    state.PendingFallbackTailUnblockRecheckIntent = nextIntent;
                    state.PendingFallbackTailUnblockRecheckNextIntent = null;
                    state.PendingFallbackTailUnblockRecheckPhase =
                        RuntimeUnlockRetryFallbackTailUnblockRecheckPhase.Captured;
                }

                if (state.PendingFallbackTailUnblockRecheckIntent is null)
                {
                    state.PendingFallbackTailUnblockRecheckNextIntent = null;
                    state.FallbackTailUnblockRecheckWorkerActive = false;
                    return;
                }
            }
        }
    }

    private static bool IsRuntimeUnlockRetryFallbackTailUnblockRequestCurrentUnsafe(
        RuntimeUnlockRecoveryRetryState state,
        RuntimeUnlockRetryDispatchAuthorityRequest request,
        FileTransferV6TransportEpochSnapshot snapshot,
        out string rejectionReason)
    {
        rejectionReason = "accepted";
        if (request.IsDefault ||
            request.RecoveryContractGeneration != state.ContractGeneration ||
            request.RetiredOfferGeneration != state.RetiredOfferGeneration ||
            request.DispatchAttemptGeneration != state.DispatchAttemptGeneration ||
            request.MissingDispatchSuccessorGeneration != state.MissingDispatchSuccessorGeneration)
        {
            rejectionReason = "retry_request_generation_replaced";
            return false;
        }

        if (!string.Equals(request.SessionId, state.SessionId, StringComparison.Ordinal) ||
            !string.Equals(request.TransferId, state.TransferId, StringComparison.Ordinal) ||
            !string.Equals(request.SessionId, snapshot.SessionId.Trim(), StringComparison.Ordinal) ||
            !string.Equals(request.TransferId, snapshot.TransferId.Trim(), StringComparison.Ordinal) ||
            request.Direction != snapshot.Direction)
        {
            rejectionReason = "retry_request_transfer_tuple_replaced";
            return false;
        }

        if (state.SourcePublicationAuthority is not { } publication ||
            request.SourcePublicationAuthority != publication ||
            !string.Equals(
                publication.RouteToken,
                FileTransferRouteResolver.PostTunaFallbackV6Token,
                StringComparison.Ordinal) ||
            publication.ProtocolVersion != FileTransferProtocol.ProtocolVersionV6 ||
            !string.Equals(publication.SessionId, request.SessionId, StringComparison.Ordinal) ||
            !string.Equals(publication.TransferId, request.TransferId, StringComparison.Ordinal) ||
            publication.Direction != request.Direction)
        {
            rejectionReason = "retry_request_source_publication_replaced";
            return false;
        }

        var successorIntent = state.PendingDispatchSuccessorIntent;
        if (successorIntent is null)
        {
            if (request.PredecessorAuthorityId is not null ||
                request.RequestActivePredecessorSupersession)
            {
                rejectionReason = "retry_request_predecessor_replaced";
                return false;
            }

        }
        else if (request.PredecessorAuthorityId != successorIntent.PredecessorAuthorityId ||
                 request.RequestActivePredecessorSupersession !=
                     successorIntent.RequestActivePredecessorSupersession ||
                 request.DispatchAttemptGeneration != successorIntent.DispatchAttemptGeneration ||
                 request.MissingDispatchSuccessorGeneration !=
                     successorIntent.MissingDispatchSuccessorGeneration ||
                 request.RetiredOfferGeneration != successorIntent.RetiredOfferGeneration)
        {
            rejectionReason = "retry_request_predecessor_replaced";
            return false;
        }

        return true;
    }

    private bool IsExactPendingPostTunaFallbackProofFrameUnsafe(
        FileTransferDataFrame? frame,
        string? observedSessionId)
    {
        if (frame is null ||
            string.IsNullOrWhiteSpace(fileTransferFallbackProofSessionId) ||
            string.IsNullOrWhiteSpace(fileTransferFallbackProofTransferId) ||
            fileTransferFallbackProofDirection != FileTransferDirection.Outbound ||
            fileTransferFallbackProofTransportEpoch <= 0 ||
            !string.Equals(
                frame.SessionId,
                fileTransferFallbackProofSessionId,
                StringComparison.Ordinal) ||
            !string.Equals(
                frame.TransferId,
                fileTransferFallbackProofTransferId,
                StringComparison.Ordinal) ||
            (!string.IsNullOrWhiteSpace(observedSessionId) &&
             !string.Equals(
                 observedSessionId,
                 fileTransferFallbackProofSessionId,
                 StringComparison.Ordinal)))
        {
            return false;
        }

        var transportEpoch = frame switch
        {
            IFileTransferTransportMetadataFrame metadata => metadata.TransportEpoch,
            FileTransferTransportEpochFrameV6 transportEpochFrame => transportEpochFrame.TransportEpoch,
            FileTransferFrontierRequestFrameV6 frontier => frontier.TransportEpoch,
            FileTransferRepairProofFrameV6 repairProof => repairProof.TransportEpoch,
            _ => 0,
        };
        return transportEpoch == fileTransferFallbackProofTransportEpoch;
    }

    private void PublishRuntimeUnlockRetryFallbackTailUnblockRecheck(
        RuntimeUnlockRetryFallbackTailUnblockRecheckIntent intent)
    {
        EventHandler<RuntimeUnlockRetryDispatchAuthorityRequestedEventArgs>? subscriber = null;
        Func<RuntimeUnlockRetryDispatchAuthorityRequest, RuntimeUnlockRetryDispatchDecision>? testDecision = null;
        string? discardReason = null;
        var currentRejectionReason = "recheck_request_replaced";
        var boundarySnapshot = new FileTransferV6TransportEpochSnapshot(
            intent.SessionId,
            intent.TransferId,
            intent.Direction,
            intent.RecoveredTransportEpoch,
            intent.HandoffKind,
            intent.BoundarySourceTransport,
            intent.BoundaryTargetTransport,
            V6TransportEpochState.Recovered,
            intent.BoundaryReason,
            IsUnresolved: false)
        {
            RecoveryBoundaryGeneration = intent.RecoveryBoundaryGeneration,
        };
        var hasCurrentRecoveredBoundary =
            TryGetCurrentFileTransferV6RegularNknRecoveryBoundary(
                intent.SessionId,
                intent.TransferId,
                intent.Direction,
                out var currentRecoveredBoundary);
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            var currentSessionId = currentSessionSecurityState.SessionId?.Value;
            if (disposed)
            {
                if (state?.PendingFallbackTailUnblockRecheckIntent == intent)
                {
                    ClearRuntimeUnlockRetryFallbackTailUnblockRecheckUnsafe(state, intent);
                }
                discardReason = "recheck_transport_disposed";
            }
            else if (state is null ||
                state.PendingFallbackTailUnblockRecheckIntent != intent ||
                state.PendingFallbackTailUnblockRecheckPhase !=
                    RuntimeUnlockRetryFallbackTailUnblockRecheckPhase.Captured)
            {
                discardReason = "recheck_state_replaced";
            }
            else if (string.IsNullOrWhiteSpace(currentSessionId))
            {
                ClearRuntimeUnlockRetryFallbackTailUnblockRecheckUnsafe(state, intent);
                discardReason = "recheck_session_missing";
            }
            else if (!string.Equals(currentSessionId.Trim(), state.SessionId, StringComparison.Ordinal))
            {
                ClearRuntimeUnlockRetryFallbackTailUnblockRecheckUnsafe(state, intent);
                discardReason = "recheck_session_replaced";
            }
            else if (state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed)
            {
                ClearRuntimeUnlockRetryFallbackTailUnblockRecheckUnsafe(state, intent);
                discardReason = "recheck_state_terminal";
            }
            else if (!hasCurrentRecoveredBoundary ||
                     currentRecoveredBoundary.RecoveryBoundaryGeneration !=
                         intent.RecoveryBoundaryGeneration ||
                     !IsSameFileTransferV6RecoveryBoundaryTuple(
                         currentRecoveredBoundary,
                         boundarySnapshot) ||
                     (TryGetCurrentTunaFallbackProofStateUnsafe(
                          intent.SessionId,
                          out var fallbackState)
                          ? fallbackState.Epoch
                          : 0) != intent.FallbackEpoch)
            {
                ClearRuntimeUnlockRetryFallbackTailUnblockRecheckUnsafe(state, intent);
                discardReason = "recheck_boundary_replaced";
            }
            else if (state.PendingDispatchAuthorityRequest is not { } pendingRequest ||
                     pendingRequest != intent.Request ||
                     !IsRuntimeUnlockRetryFallbackTailUnblockRecheckHoldEligibleUnsafe(
                         state,
                         intent.Request) ||
                     !IsRuntimeUnlockRetryFallbackTailUnblockRequestCurrentUnsafe(
                         state,
                         intent.Request,
                         boundarySnapshot,
                         out currentRejectionReason))
            {
                ClearRuntimeUnlockRetryFallbackTailUnblockRecheckUnsafe(state, intent);
                discardReason = currentRejectionReason;
            }
            else
            {
                subscriber = runtimeUnlockRetryDispatchAuthorityRequested;
                testDecision = RuntimeUnlockRetryDispatchAuthorityDecisionOverrideForTests;
                if (subscriber is null && testDecision is null)
                {
                    ClearRuntimeUnlockRetryFallbackTailUnblockRecheckUnsafe(state, intent);
                    discardReason = "recheck_subscriber_missing";
                }
                else
                {
                    state.PendingFallbackTailUnblockRecheckPhase =
                        RuntimeUnlockRetryFallbackTailUnblockRecheckPhase.Requested;
                }
            }
        }

        if (discardReason is not null)
        {
            LogRuntimeUnlockRetryFallbackTailUnblockRecheck(
                "runtime_unlock_retry_dispatch_fallback_tail_unblock_recheck_discarded",
                intent,
                null,
                discardReason);
            return;
        }

        LogRuntimeUnlockRetryFallbackTailUnblockRecheck(
            "runtime_unlock_retry_dispatch_fallback_tail_unblock_recheck_requested",
            intent,
            null,
            "recheck_requested");
        var previousPublishingTransport = publishingRuntimeUnlockFallbackTailUnblockRecheckTransport;
        var previousPublishingGeneration = publishingRuntimeUnlockFallbackTailUnblockRecheckGeneration;
        try
        {
            publishingRuntimeUnlockFallbackTailUnblockRecheckTransport = this;
            publishingRuntimeUnlockFallbackTailUnblockRecheckGeneration = intent.RecheckGeneration;
            if (subscriber is not null)
            {
                subscriber.Invoke(
                    this,
                    new RuntimeUnlockRetryDispatchAuthorityRequestedEventArgs(intent.Request));
            }
            else if (testDecision is not null)
            {
                _ = ApplyRuntimeUnlockRetryDispatchDecisionForTests(
                    testDecision(intent.Request));
            }
        }
        catch (Exception ex)
        {
            lock (accelerationGate)
            {
                var state = runtimeUnlockRecoveryRetryState;
                if (state?.PendingFallbackTailUnblockRecheckIntent == intent)
                {
                    ClearRuntimeUnlockRetryFallbackTailUnblockRecheckUnsafe(state, intent);
                }
            }

            LogRuntimeUnlockRetryFallbackTailUnblockRecheck(
                "runtime_unlock_retry_dispatch_fallback_tail_unblock_recheck_discarded",
                intent,
                null,
                $"recheck_callback_failed_{SanitizeLogToken(ex.GetType().Name)}");
            return;
        }
        finally
        {
            publishingRuntimeUnlockFallbackTailUnblockRecheckTransport = previousPublishingTransport;
            publishingRuntimeUnlockFallbackTailUnblockRecheckGeneration = previousPublishingGeneration;
        }

        var decisionMissing = false;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state?.PendingFallbackTailUnblockRecheckIntent == intent)
            {
                ClearRuntimeUnlockRetryFallbackTailUnblockRecheckUnsafe(state, intent);
                decisionMissing = true;
            }
        }

        if (decisionMissing)
        {
            LogRuntimeUnlockRetryFallbackTailUnblockRecheck(
                "runtime_unlock_retry_dispatch_fallback_tail_unblock_recheck_discarded",
                intent,
                null,
                "recheck_decision_missing");
        }
    }

    private static string FormatRuntimeUnlockRetryDispatchAuthorityRequestTuple(
        RuntimeUnlockRetryDispatchAuthorityRequest request)
    {
        var publication = request.SourcePublicationAuthority;
        var routeCommitGeneration = publication.RouteCommitGeneration is { } commitGeneration
            ? commitGeneration.ToString(CultureInfo.InvariantCulture)
            : "(none)";
        return $"session_id={SanitizeLogToken(request.SessionId)}; transfer_id={SanitizeLogToken(request.TransferId)}; direction={request.Direction.ToString().ToLowerInvariant()}; contract_generation={request.RecoveryContractGeneration}; retired_generation={request.RetiredOfferGeneration}; dispatch_attempt_generation={request.DispatchAttemptGeneration}; missing_dispatch_successor_generation={request.MissingDispatchSuccessorGeneration}; predecessor_authority_id={SanitizeLogToken(request.PredecessorAuthorityId?.ToString() ?? "(none)")}; request_active_predecessor_supersession={(request.RequestActivePredecessorSupersession ? 1 : 0)}; retry_reason={SanitizeLogToken(request.RetryReason)}; recovery_reason={SanitizeLogToken(request.RecoveryReason)}; regular_v4_liveness_generation={request.RegularV4LivenessGeneration}; bridge_decision_generation={request.BridgeDecisionGeneration}; source_session_id={SanitizeLogToken(publication.SessionId)}; source_transfer_id={SanitizeLogToken(publication.TransferId)}; source_direction={publication.Direction.ToString().ToLowerInvariant()}; source_route={SanitizeLogToken(publication.RouteToken)}; source_protocol_version={publication.ProtocolVersion}; source_live_route_epoch={publication.LiveRouteEpoch}; source_runtime_generation={publication.RuntimeGeneration}; source_terminal_generation={publication.TerminalGeneration}; source_leg_generation={publication.LegGeneration}; source_route_publication_generation={publication.RoutePublicationGeneration}; source_route_commit_generation={routeCommitGeneration}; source_route_commit_generation_present={(publication.RouteCommitGeneration.HasValue ? 1 : 0)}; source_target_route={SanitizeLogToken(publication.TargetRouteToken)}; source_target_protocol_version={publication.TargetProtocolVersion}; source_target_transport={FormatFileTransferTransportKindForLog(publication.TargetTransport)}; source_route_publication_action_kind={SanitizeLogToken(publication.RoutePublicationActionKind)}; source_coordinator_decision_reason={SanitizeLogToken(publication.CoordinatorDecisionReason)}";
    }

    private static void LogRuntimeUnlockRetryFallbackTailUnblockRecheck(
        string eventName,
        RuntimeUnlockRetryFallbackTailUnblockRecheckIntent intent,
        RuntimeUnlockRetryDispatchDecisionStatus? decisionStatus,
        string decisionReason,
        bool decisionValid = false)
    {
        var request = intent.Request;
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event={SanitizeLogToken(eventName)}; {FormatRuntimeUnlockRetryDispatchAuthorityRequestTuple(request)}; recovered_transport_epoch={intent.RecoveredTransportEpoch}; recovery_boundary_generation={intent.RecoveryBoundaryGeneration}; handoff_kind={FormatFileTransferTransportHandoffKindForLog(intent.HandoffKind)}; boundary_source_transport={FormatFileTransferTransportKindForLog(intent.BoundarySourceTransport)}; boundary_target_transport={FormatFileTransferTransportKindForLog(intent.BoundaryTargetTransport)}; fallback_epoch={intent.FallbackEpoch}; boundary_reason={SanitizeLogToken(intent.BoundaryReason)}; boundary_identity={SanitizeLogToken(intent.BoundaryIdentity)}; original_hold_reason={RuntimeUnlockFallbackPairedTailYieldPendingReason}; recheck_generation={intent.RecheckGeneration}; decision_status={SanitizeLogToken(decisionStatus?.ToString() ?? "Pending")}; decision_valid={(decisionValid ? 1 : 0)}; decision_reason={SanitizeLogToken(decisionReason)}");
    }

    private bool EnsureFileTransferFallbackRecoveredStateFromV6Epoch(
        FileTransferV6TransportEpochSnapshot snapshot,
        string reason)
    {
        if (snapshot.HandoffKind != FileTransferTransportHandoffKind.TunaToNormalFallback ||
            snapshot.TargetTransport != FileTransferTransportKind.RegularNkn)
        {
            return false;
        }

        var sessionId = string.IsNullOrWhiteSpace(snapshot.SessionId)
            ? null
            : snapshot.SessionId.Trim();
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        if (!HasActiveFileTransferDataSessionsForRecovery())
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_v6_fallback_recovered_state_synthesis_suppressed_no_active_transfer; session_id={SanitizeLogToken(sessionId)}; transfer_id={SanitizeLogToken(snapshot.TransferId)}; transport_epoch={snapshot.TransportEpoch}; reason={SanitizeLogToken(reason)}");
            return false;
        }

        TunaFallbackProofState? stateToLog = null;
        lock (accelerationGate)
        {
            if (TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out _))
            {
                return false;
            }

            var epoch = Interlocked.Increment(ref tunaFallbackProofNextEpoch);
            tunaFallbackProofState = new TunaFallbackProofState
            {
                Epoch = epoch,
                SessionId = sessionId,
                Reason = SanitizeLogToken(reason),
                StartedUtc = DateTimeOffset.UtcNow,
                Lanes = NknAccelerationLaneKind.File,
                FileState = TunaFallbackLaneState.Recovered,
                FileV6EpochState = V6TransportEpochState.Recovered,
                FileV6TransportEpoch = snapshot.TransportEpoch,
            };
            stateToLog = tunaFallbackProofState;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_v6_fallback_recovered_state_synthesized; session_id={SanitizeLogToken(sessionId)}; fallback_epoch={stateToLog.Epoch}; reason={stateToLog.Reason}; transport_epoch={snapshot.TransportEpoch}; file_state={FormatTunaFallbackLaneState(stateToLog.FileState)}; file_v6_epoch_state={FormatTunaFallbackFileV6EpochState(stateToLog)}");
        NotifyTransportAccelerationStateChanged(reason);
        return true;
    }

    private bool TryGetFileTransferFallbackControlProofPendingSnapshot(out string? sessionId, out string reason, out NknAccelerationLaneKind lanes)
    {
        lock (fileTransferFallbackProofGate)
        {
            if (!fileTransferFallbackProofPending ||
                (fileTransferFallbackProofLanes & NknAccelerationLaneKind.File) != NknAccelerationLaneKind.File ||
                fileTransferFallbackControlProofObserved)
            {
                sessionId = null;
                reason = "none";
                lanes = NknAccelerationLaneKind.None;
                return false;
            }

            sessionId = fileTransferFallbackProofSessionId;
            reason = fileTransferFallbackProofReason;
            lanes = fileTransferFallbackProofLanes;
            return true;
        }
    }

    private static bool TryMapFileTransferFallbackNknProofKind(FileTransferDataFrame frame, out string proofKind)
    {
        proofKind = frame switch
        {
            FileTransferManifestFrameV4 and not FileTransferManifestFrameV6 => "file_transfer_v4_manifest_received",
            FileTransferStateFrameV4 and not FileTransferReceiverStateFrameV6 => "file_transfer_v4_state_frame_received",
            FileTransferChunkBatchFrameV4 and not FileTransferChunkBatchFrameV6 => "file_transfer_v4_bulk_frame_received",
            FileTransferPauseControlFrameV4 and not FileTransferPauseControlFrameV6 => "file_transfer_v4_pause_control_frame_received",
            FileTransferCompleteFrameV4 and not FileTransferCompleteFrameV6 => "file_transfer_v4_complete_frame_received",
            FileTransferCancelFrameV4 and not FileTransferCancelFrameV6 => "file_transfer_v4_cancel_frame_received",
            FileTransferErrorFrameV4 and not FileTransferErrorFrameV6 => "file_transfer_v4_error_frame_received",
            FileTransferReceiverStateFrameV6 => "file_transfer_v6_state_frame_received",
            FileTransferTransportEpochFrameV6 => "file_transfer_v6_transport_epoch_frame_received",
            FileTransferFrontierRequestFrameV6 => "file_transfer_v6_frontier_request_frame_received",
            FileTransferRepairProofFrameV6 => "file_transfer_v6_repair_proof_frame_received",
            FileTransferPauseControlFrameV6 => "file_transfer_v6_pause_control_frame_received",
            FileTransferCompleteFrameV6 => "file_transfer_v6_complete_frame_received",
            FileTransferCancelFrameV6 => "file_transfer_v6_cancel_frame_received",
            FileTransferErrorFrameV6 => "file_transfer_v6_error_frame_received",
            FileTransferChunkBatchFrameV6 => "file_transfer_bulk_frame_received",
            _ => string.Empty,
        };

        return proofKind.Length > 0;
    }

    private static bool TryMapPostTunaFileTransferFallbackNknProofKind(
        FileTransferDataFrame frame,
        string direction,
        out string proofKind)
    {
        var suffix = string.Equals(direction, "sent", StringComparison.Ordinal)
            ? "sent"
            : "received";
        proofKind = frame switch
        {
            FileTransferManifestFrameV4 and not FileTransferManifestFrameV6 => $"file_transfer_v4_manifest_{suffix}",
            FileTransferStateFrameV4 and not FileTransferReceiverStateFrameV6 => $"file_transfer_v4_state_frame_{suffix}",
            FileTransferChunkBatchFrameV4 and not FileTransferChunkBatchFrameV6 => $"file_transfer_v4_bulk_frame_{suffix}",
            FileTransferPauseControlFrameV4 and not FileTransferPauseControlFrameV6 => $"file_transfer_v4_pause_control_frame_{suffix}",
            FileTransferCompleteFrameV4 and not FileTransferCompleteFrameV6 => $"file_transfer_v4_complete_frame_{suffix}",
            FileTransferCancelFrameV4 and not FileTransferCancelFrameV6 => $"file_transfer_v4_cancel_frame_{suffix}",
            FileTransferErrorFrameV4 and not FileTransferErrorFrameV6 => $"file_transfer_v4_error_frame_{suffix}",
            _ => string.Empty,
        };

        return proofKind.Length > 0;
    }

    private static bool IsAuthoritativeFileTransferFallbackNknProof(string proofKind)
        => proofKind.StartsWith("nkn_control_", StringComparison.Ordinal) ||
           proofKind is
               "file_transfer_v4_manifest_received" or
               "file_transfer_v4_manifest_sent" or
               "file_transfer_v4_state_frame_received" or
               "file_transfer_v4_state_frame_sent" or
               "file_transfer_v4_bulk_frame_received" or
               "file_transfer_v4_bulk_frame_sent" or
               "file_transfer_v4_pause_control_frame_received" or
               "file_transfer_v4_pause_control_frame_sent" or
               "file_transfer_v4_complete_frame_received" or
               "file_transfer_v4_complete_frame_sent" or
               "file_transfer_v4_cancel_frame_received" or
               "file_transfer_v4_cancel_frame_sent" or
               "file_transfer_v4_error_frame_received" or
               "file_transfer_v4_error_frame_sent" or
               "file_transfer_v6_state_frame_received" or
               "file_transfer_v6_transport_epoch_frame_received" or
               "file_transfer_v6_frontier_request_frame_received" or
               "file_transfer_v6_repair_proof_frame_received" or
               "file_transfer_v6_pause_control_frame_received" or
               "file_transfer_v6_complete_frame_received" or
               "file_transfer_v6_cancel_frame_received" or
               "file_transfer_v6_error_frame_received";

    private static bool IsPostTunaFileTransferFallbackNknProof(string proofKind)
        => proofKind is
            "file_transfer_v6_state_frame_received" or
            "file_transfer_v6_transport_epoch_frame_received" or
            "file_transfer_v6_frontier_request_frame_received" or
            "file_transfer_v6_repair_proof_frame_received" or
            "file_transfer_v6_pause_control_frame_received" or
            "file_transfer_v6_complete_frame_received" or
            "file_transfer_v6_cancel_frame_received" or
            "file_transfer_v6_error_frame_received";

    private static string MapSecureMessageTypeForProof(MsgType messageType)
        => messageType switch
        {
            MsgType.Chat => "chat",
            MsgType.Ack => "ack",
            MsgType.SessionEnd => "session_end",
            MsgType.FileTransferCancel => "file_transfer_cancel",
            MsgType.FileTransferError => "file_transfer_error",
            MsgType.FileTransferComplete => "file_transfer_complete",
            MsgType.FileTransferPauseControl => "file_transfer_pause_control",
            MsgType.FileTransferHeartbeat => "file_transfer_heartbeat",
            MsgType.FileTransferTransportEpoch => "file_transfer_transport_epoch",
            MsgType.FileTransferTransportProbe => "file_transfer_transport_probe",
            MsgType.FileTransferRepairProof => "file_transfer_repair_proof",
            MsgType.FileTransferOffer => "file_transfer_offer",
            MsgType.FileTransferAccept => "file_transfer_accept",
            MsgType.FileTransferDecline => "file_transfer_decline",
            MsgType.FileTransferStart => "file_transfer_start",
            MsgType.FileTransferSessionOpen => "file_transfer_session_open",
            _ => SanitizeLogToken(messageType.ToString()).ToLowerInvariant(),
        };

    private void ScheduleFileTransferFallbackNknProbeIfPending(string trigger)
    {
        long generation;
        string reason;
        string? sessionId;
        NknAccelerationLaneKind lanes;
        lock (fileTransferFallbackProofGate)
        {
            if (!fileTransferFallbackProofPending ||
                fileTransferFallbackProofProbeScheduled ||
                (fileTransferFallbackProofLanes & NknAccelerationLaneKind.File) != NknAccelerationLaneKind.File)
            {
                return;
            }

            fileTransferFallbackProofProbeScheduled = true;
            generation = fileTransferFallbackProofGeneration;
            reason = fileTransferFallbackProofReason;
            sessionId = fileTransferFallbackProofSessionId;
            lanes = fileTransferFallbackProofLanes;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=filetransfer_fallback_nkn_probe_scheduled; session_id={SanitizeLogToken(sessionId ?? "none")}; reason={SanitizeLogToken(reason)}; trigger={SanitizeLogToken(trigger)}; delay_ms={(long)FileTransferFallbackUnprovenProbeDelay.TotalMilliseconds}; lanes={FormatAccelerationLanesForLog(lanes)}");
        ArmPostTunaFallbackProofSendWindow(reason, trigger, sessionId);

        _ = Task.Run(
            async () =>
            {
                try
                {
                    await Task.Delay(FileTransferFallbackUnprovenProbeDelay).ConfigureAwait(false);
                    if (disposed)
                    {
                        return;
                    }

                    string probeReason;
                    string? probeSessionId;
                    NknAccelerationLaneKind probeLanes;
                    lock (fileTransferFallbackProofGate)
                    {
                        if (!fileTransferFallbackProofPending ||
                            fileTransferFallbackProofGeneration != generation ||
                            (fileTransferFallbackProofLanes & NknAccelerationLaneKind.File) != NknAccelerationLaneKind.File)
                        {
                            return;
                        }

                        probeReason = fileTransferFallbackProofReason;
                        probeSessionId = fileTransferFallbackProofSessionId;
                        probeLanes = fileTransferFallbackProofLanes;
                    }

                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=filetransfer_fallback_nkn_probe_started; session_id={SanitizeLogToken(probeSessionId ?? "none")}; reason={SanitizeLogToken(probeReason)}; trigger={SanitizeLogToken(trigger)}; delay_ms={(long)FileTransferFallbackUnprovenProbeDelay.TotalMilliseconds}; lanes={FormatAccelerationLanesForLog(probeLanes)}");
                    ArmPostTunaFallbackProofSendWindow(probeReason, $"probe_started:{trigger}", probeSessionId);
                    SetFileTransferDataSessionsAvailability(
                        isAvailable: false,
                        reason: "transport_recovered_unproven",
                        requiresResumeRequest: true,
                        handoffKind: ResolveFileTransferFallbackProbeHandoffKind(probeReason, trigger),
                        targetTransport: FileTransferTransportKind.RegularNkn);
                }
                catch (Exception ex)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=filetransfer_fallback_nkn_probe_failed; reason={SanitizeLogToken(reason)}; trigger={SanitizeLogToken(trigger)}; error={SanitizeLogToken(ex.GetType().Name)}");
                }
            });
    }

    private void ArmPostTunaFallbackProofSendWindow(string reason, string trigger, string? sessionId)
    {
        if (client is RealNknClientAdapter realClient)
        {
            realClient.ArmPostTunaFallbackProofSendWindow(reason, trigger, sessionId);
        }
    }

    private static FileTransferTransportHandoffKind ResolveFileTransferFallbackProbeHandoffKind(string? reason, string? trigger)
    {
        var normalizedReason = SanitizeLogToken(reason);
        var normalizedTrigger = SanitizeLogToken(trigger);
        return IsRegularNknRecoveryProbeToken(normalizedReason) ||
               IsRegularNknRecoveryProbeToken(normalizedTrigger)
            ? FileTransferTransportHandoffKind.RegularNknRecovery
            : FileTransferTransportHandoffKind.TunaToNormalFallback;
    }

    private static bool IsRegularNknRecoveryProbeToken(string? value)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            return false;
        }

        return value is "receive_stall_recovery"
            or "receive_resumed_unproven"
            or "bridge_ready_unproven"
            or "bulk_receive_stalled"
            or "control_receive_stalled"
            or "all_channels_zero_receive" ||
            value.Contains("receive_stall", StringComparison.OrdinalIgnoreCase);
    }

    private bool TryGetCurrentTunaFallbackProofStateUnsafe(string? sessionId, out TunaFallbackProofState state)
    {
        state = default!;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? currentSessionSecurityState.SessionId?.Value : sessionId.Trim();
        if (tunaFallbackProofState is null ||
            string.IsNullOrWhiteSpace(normalizedSessionId) ||
            !string.Equals(tunaFallbackProofState.SessionId, normalizedSessionId, StringComparison.Ordinal))
        {
            return false;
        }

        state = tunaFallbackProofState;
        return true;
    }

    private void RecordPendingFileTransferTunaFallbackReason(string? sessionId, string reason)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            return;
        }

        var normalizedReason = SanitizeLogToken(reason);
        if (string.IsNullOrWhiteSpace(normalizedReason) ||
            normalizedReason == "none")
        {
            return;
        }

        lock (accelerationGate)
        {
            pendingFileTransferTunaFallbackReasonSessionId = normalizedSessionId;
            pendingFileTransferTunaFallbackReason = normalizedReason;
            pendingFileTransferTunaFallbackReasonUtcMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        }
    }

    private bool TryGetRequiredTunaBulkUnavailableFallbackReasonForSession(string? sessionId, out string reason)
    {
        reason = string.Empty;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId)
            ? currentSessionSecurityState.SessionId?.Value
            : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            return false;
        }

        lock (accelerationGate)
        {
            if (tunaFallbackProofState is { } fallbackState &&
                string.Equals(fallbackState.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                (fallbackState.Lanes & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File &&
                fallbackState.FileState != TunaFallbackLaneState.None &&
                !string.IsNullOrWhiteSpace(fallbackState.Reason))
            {
                reason = fallbackState.Reason;
                return true;
            }

            if (!string.Equals(pendingFileTransferTunaFallbackReasonSessionId, normalizedSessionId, StringComparison.Ordinal) ||
                string.IsNullOrWhiteSpace(pendingFileTransferTunaFallbackReason) ||
                pendingFileTransferTunaFallbackReasonUtcMs <= 0)
            {
                return false;
            }

            var ageMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds() - pendingFileTransferTunaFallbackReasonUtcMs;
            if (ageMs >= 0 &&
                ageMs <= RequiredTunaBulkFallbackReasonGrace.TotalMilliseconds)
            {
                reason = pendingFileTransferTunaFallbackReason;
                return true;
            }

            pendingFileTransferTunaFallbackReasonSessionId = null;
            pendingFileTransferTunaFallbackReason = null;
            pendingFileTransferTunaFallbackReasonUtcMs = 0;
            return false;
        }
    }

    private void MarkTunaFallbackLaneState(
        string? sessionId,
        NknAccelerationLaneKind lane,
        TunaFallbackLaneState state,
        string reason)
    {
        TunaFallbackProofState? snapshot = null;
        var changed = false;
        lock (accelerationGate)
        {
            if (!TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out var current))
            {
                return;
            }

            if ((lane & NknAccelerationLaneKind.Screen) == NknAccelerationLaneKind.Screen &&
                current.ScreenState != state)
            {
                current.ScreenState = state;
                changed = true;
            }

            if ((lane & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File &&
                current.FileState != state)
            {
                current.FileState = state;
                changed = true;
            }

            snapshot = current;
        }

        if (changed && snapshot is not null)
        {
            LogMixedFallbackLaneState(snapshot, lane == NknAccelerationLaneKind.Screen
                ? "screen_" + FormatTunaFallbackLaneState(state)
                : "file_" + FormatTunaFallbackLaneState(state));
            NotifyTransportAccelerationStateChanged(reason);
        }
    }

    private void MarkTunaFallbackFileV6EpochState(
        string? sessionId,
        long transportEpoch,
        V6TransportEpochState state,
        string reason)
    {
        TunaFallbackProofState? snapshot = null;
        var changed = false;
        lock (accelerationGate)
        {
            if (!TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out var current))
            {
                return;
            }

            if (IsFileTransferFallbackFinalForLanes(current, NknAccelerationLaneKind.File) &&
                current.FileV6TransportEpoch > 0 &&
                transportEpoch > 0 &&
                transportEpoch < current.FileV6TransportEpoch)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=filetransfer_v6_epoch_state_ignored_final_fallback; session_id={SanitizeLogToken(sessionId ?? "none")}; transport_epoch={transportEpoch}; state={FormatFileTransferV6TransportEpochStateForLog(state)}; reason={SanitizeLogToken(reason)}; file_state={FormatTunaFallbackLaneState(current.FileState)}; file_v6_epoch_state={FormatTunaFallbackFileV6EpochState(current)}; file_v6_transport_epoch={current.FileV6TransportEpoch}");
                return;
            }

            if (IsFileTransferFallbackFinalForLanes(current, NknAccelerationLaneKind.File) &&
                state == V6TransportEpochState.TargetProofPending &&
                current.FileV6EpochState != state)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=filetransfer_v6_epoch_state_ignored_final_fallback; session_id={SanitizeLogToken(sessionId ?? "none")}; transport_epoch={transportEpoch}; state={FormatFileTransferV6TransportEpochStateForLog(state)}; reason={SanitizeLogToken(reason)}; file_state={FormatTunaFallbackLaneState(current.FileState)}; file_v6_epoch_state={FormatTunaFallbackFileV6EpochState(current)}; file_v6_transport_epoch={current.FileV6TransportEpoch}");
                return;
            }

            if (current.FileV6EpochState != state ||
                current.FileV6TransportEpoch != transportEpoch)
            {
                current.FileV6EpochState = state;
                current.FileV6TransportEpoch = transportEpoch;
                changed = true;
            }

            snapshot = current;
        }

        if (changed && snapshot is not null)
        {
            LogMixedFallbackLaneState(snapshot, "file_v6_epoch_" + FormatFileTransferV6TransportEpochStateForLog(state));
        }
    }

    private void ScheduleScreenTunaHandoffWaitingMarker(string sessionId, string reason)
    {
        var fallbackEpoch = 0L;
        lock (accelerationGate)
        {
            if (!TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out var state) ||
                (state.Lanes & NknAccelerationLaneKind.Screen) != NknAccelerationLaneKind.Screen)
            {
                return;
            }

            fallbackEpoch = state.Epoch;
        }

        _ = Task.Run(
            async () =>
            {
                try
                {
                    await Task.Delay(TimeSpan.FromSeconds(30)).ConfigureAwait(false);
                    TunaFallbackProofState? snapshot = null;
                    var shouldLog = false;
                    lock (accelerationGate)
                    {
                        if (TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out var state) &&
                            state.Epoch == fallbackEpoch &&
                            state.ScreenState is TunaFallbackLaneState.Pending or TunaFallbackLaneState.MediaReady)
                        {
                            state.ScreenState = TunaFallbackLaneState.WaitingForRegularNkn;
                            snapshot = state;
                            shouldLog = true;
                        }
                    }

                    if (!shouldLog || snapshot is null)
                    {
                        return;
                    }

                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=screenshare_tuna_handoff_waiting_for_regular_nkn; session_id={snapshot.SessionId}; fallback_epoch={snapshot.Epoch}; reason={SanitizeLogToken(reason)}; screen_state={FormatTunaFallbackLaneState(snapshot.ScreenState)}");
                    LogMixedFallbackLaneState(snapshot, "screen_waiting_for_regular_nkn");
                }
                catch
                {
                    // Best-effort diagnostics only.
                }
            },
            CancellationToken.None);
    }

    private void MarkScreenTunaHandoffFrameApplied(ScreenShareVideoFrameReadyEventArgs e)
    {
        TunaFallbackProofState? snapshot = null;
        var recovered = false;
        lock (accelerationGate)
        {
            if (!TryGetCurrentTunaFallbackProofStateUnsafe(e.SessionId, out var state) ||
                (state.Lanes & NknAccelerationLaneKind.Screen) != NknAccelerationLaneKind.Screen)
            {
                return;
            }

            state.ScreenFramesApplied++;
            if (state.ScreenState != TunaFallbackLaneState.Recovered)
            {
                state.ScreenState = TunaFallbackLaneState.Recovered;
                recovered = true;
            }

            snapshot = state;
        }

        if (snapshot is null)
        {
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=screenshare_tuna_handoff_nkn_frame_applied; session_id={snapshot.SessionId}; fallback_epoch={snapshot.Epoch}; stream_epoch={e.StreamEpoch}; frame_id={e.FrameId}; is_keyframe={(e.IsKeyFrame ? 1 : 0)}; reason={snapshot.Reason}");
        if (recovered)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=screenshare_tuna_handoff_recovered; session_id={snapshot.SessionId}; fallback_epoch={snapshot.Epoch}; stream_epoch={e.StreamEpoch}; frame_id={e.FrameId}; elapsed_ms={Math.Max(0, (long)(DateTimeOffset.UtcNow - snapshot.StartedUtc).TotalMilliseconds)}; reason={snapshot.Reason}");
            LogMixedFallbackLaneState(snapshot, "screen_recovered");
        }
    }

    private bool ShouldIgnoreAcceleratedScreenShareFrameDuringFallback(string? sessionId)
    {
        if (!handlingTunaAcceleratedInboundMessage || IsAccelerationNegotiatedAndHealthy())
        {
            return false;
        }

        lock (accelerationGate)
        {
            return TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out var state) &&
                   (state.Lanes & NknAccelerationLaneKind.Screen) == NknAccelerationLaneKind.Screen &&
                   state.ScreenState != TunaFallbackLaneState.None;
        }
    }

    private void LogAcceleratedScreenShareFrameIgnoredDuringFallback(string? sessionId, long streamEpoch, long frameId)
    {
        TunaFallbackProofState? snapshot = null;
        var shouldLog = false;
        lock (accelerationGate)
        {
            if (!TryGetCurrentTunaFallbackProofStateUnsafe(sessionId, out var state))
            {
                return;
            }

            shouldLog = ShouldLogTunaFallbackProofMarkerUnsafe(state, "stale_accelerated_screen_frame_ignored", DateTimeOffset.UtcNow);
            snapshot = state;
        }

        if (!shouldLog || snapshot is null)
        {
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=screenshare_tuna_handoff_stale_accelerated_frame_ignored; session_id={snapshot.SessionId}; fallback_epoch={snapshot.Epoch}; stream_epoch={streamEpoch}; frame_id={frameId}; screen_state={FormatTunaFallbackLaneState(snapshot.ScreenState)}; reason={snapshot.Reason}");
    }

    private static bool IsMixedFallbackLaneSet(NknAccelerationLaneKind lanes)
        => (lanes & NknAccelerationLaneKind.Screen) == NknAccelerationLaneKind.Screen &&
           (lanes & NknAccelerationLaneKind.File) == NknAccelerationLaneKind.File;

    private static string FormatTunaFallbackLaneState(TunaFallbackLaneState state)
        => state switch
        {
            TunaFallbackLaneState.Pending => "pending",
            TunaFallbackLaneState.MediaReady => "media_ready",
            TunaFallbackLaneState.Recovered => "recovered",
            TunaFallbackLaneState.WaitingForRegularNkn => "waiting_for_regular_nkn",
            _ => "none",
        };

    private static void LogMixedFallbackLaneState(TunaFallbackProofState state, string laneState)
    {
        if (!IsMixedFallbackLaneSet(state.Lanes))
        {
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_mixed_handoff_lane_state_changed; session_id={state.SessionId}; fallback_epoch={state.Epoch}; reason={state.Reason}; lane_state={SanitizeLogToken(laneState)}; screen_state={FormatTunaFallbackLaneState(state.ScreenState)}; file_state={FormatTunaFallbackLaneState(state.FileState)}; file_v6_epoch_state={FormatTunaFallbackFileV6EpochState(state)}; file_v6_transport_epoch={state.FileV6TransportEpoch}");
    }

    private static string FormatTunaFallbackFileV6EpochState(TunaFallbackProofState state)
        => state.FileV6EpochState is { } epochState
            ? FormatFileTransferV6TransportEpochStateForLog(epochState)
            : state.FileState == TunaFallbackLaneState.Recovered
                ? "unknown"
                : FormatTunaFallbackLaneState(state.FileState);

    private static bool ShouldLogTunaFallbackProofMarkerUnsafe(TunaFallbackProofState state, string key, DateTimeOffset now)
    {
        if (!state.LogStates.TryGetValue(key, out var logState))
        {
            state.LogStates[key] = new TunaFallbackProofLogState
            {
                LastLoggedUtc = now,
            };
            return true;
        }

        logState.CountSinceLastLog++;
        if (logState.CountSinceLastLog < TunaFallbackProofLogEveryFrames &&
            now - logState.LastLoggedUtc < TunaFallbackProofLogWindow)
        {
            return false;
        }

        logState.CountSinceLastLog = 0;
        logState.LastLoggedUtc = now;
        return true;
    }

    private static bool IsTunaFallbackProofFrame(MsgType messageType, NknBridgeChannel channel)
        => (messageType == MsgType.ScreenShareFrame && channel == NknBridgeChannel.Media) ||
           (messageType == MsgType.FileTransferDataFrame && channel == NknBridgeChannel.Bulk);

    private static string MapTunaFallbackProofMessageType(MsgType messageType)
        => messageType switch
        {
            MsgType.ScreenShareFrame => "screenshare_frame",
            MsgType.FileTransferDataFrame => "file_transfer_data_frame",
            _ => MapEnvelopeTypeForDiagnostics(messageType),
        };

    internal static bool ShouldStartTunaFallbackProofForResetReason(string? reason)
    {
        var normalized = SanitizeLogToken(reason);
        if (normalized is "(none)" or
            "dispose" or
            "disposed" or
            "reset_session_tracking" or
            "session_security_state_not_eligible")
        {
            return false;
        }

        if (IsRemoteUserRequestedAccelerationStopReason(normalized))
        {
            return false;
        }

        if (normalized.StartsWith("remote_", StringComparison.Ordinal))
        {
            return true;
        }

        if (IsUserRequestedAccelerationStopReason(normalized))
        {
            return false;
        }

        return normalized is
            "cap_reached" or
            "byte_cap_reached" or
            "duration_cap_reached" or
            "sidecar_read_failed" or
            "sidecar_write_failed" or
            "sidecar_remote_closed" or
            "sidecar_queue_overflow" or
            "sidecar_status_timeout" or
            "sidecar_invalid_status" or
            "sidecar_status_parse_failed" or
            "sidecar_local_ipc_eof" or
            "sidecar_tuna_stream_eof" or
            "sidecar_local_write_failed" or
            "sidecar_tuna_write_failed" or
            "sidecar_byte_cap_reached" or
            "sidecar_duration_cap_reached" or
            "sidecar_remote_byte_cap_reached" or
            "sidecar_remote_duration_cap_reached" or
            "sidecar_provider_timeout" or
            "sidecar_listener_exited" or
            "sidecar_dialer_exited" or
            "sidecar_process_exited" or
            "sidecar_unexpected_exit";
    }

    internal static string NormalizeAccelerationSidecarResetReason(string? reason)
    {
        var normalized = SanitizeLogToken(reason);
        return normalized.StartsWith("sidecar_", StringComparison.Ordinal)
            ? normalized
            : $"sidecar_{normalized}";
    }

    internal static bool ShouldStartImmediateFileTransferFallbackProbe(string? reason)
    {
        var normalized = SanitizeLogToken(reason);
        if (IsUserRequestedAccelerationStopReason(normalized) ||
            IsRemoteUserRequestedAccelerationStopReason(normalized))
        {
            return false;
        }

        return normalized is
            "cap_reached" or
            "byte_cap_reached" or
            "duration_cap_reached" or
            "sidecar_read_failed" or
            "sidecar_write_failed" or
            "sidecar_remote_closed" or
            "sidecar_queue_overflow" or
            "sidecar_status_timeout" or
            "sidecar_invalid_status" or
            "sidecar_status_parse_failed" or
            "sidecar_local_ipc_eof" or
            "sidecar_tuna_stream_eof" or
            "sidecar_local_write_failed" or
            "sidecar_tuna_write_failed" or
            "sidecar_provider_timeout" or
            "sidecar_listener_exited" or
            "sidecar_dialer_exited" or
            "sidecar_process_exited" or
            "sidecar_unexpected_exit" or
            "remote_cap_reached" or
            "remote_byte_cap_reached" or
            "remote_duration_cap_reached" or
            "remote_read_failed" or
            "remote_write_failed" or
            "remote_closed" or
            "remote_sidecar_read_failed" or
            "remote_sidecar_write_failed" or
            "remote_sidecar_remote_closed" or
            "remote_sidecar_local_ipc_eof" or
            "remote_sidecar_tuna_stream_eof" or
            "remote_sidecar_local_write_failed" or
            "remote_sidecar_tuna_write_failed" or
            "sidecar_byte_cap_reached" or
            "sidecar_duration_cap_reached" or
            "sidecar_remote_byte_cap_reached" or
            "sidecar_remote_duration_cap_reached" or
            "remote_sidecar_byte_cap_reached" or
            "remote_sidecar_duration_cap_reached";
    }

    internal static bool ShouldCompleteTunaFallbackProofForResetReason(string? reason)
    {
        var normalized = SanitizeLogToken(reason);
        return normalized is
            "dispose" or
            "disposed" or
            "reset_session_tracking" or
            "session_security_state_not_eligible";
    }

    private static INknAccelerationLane? CreateAccelerationLane(
        NknTunaAccelerationOptions options,
        INknTunaListenerSidecarSupervisor? listenerSupervisor = null)
    {
        if (options is null || !options.Enabled)
        {
            return null;
        }

        return new NknTunaAccelerationLane(options, listenerSupervisor);
    }

    private void OnAccelerationStateChanged(object? sender, AccelerationStateChangedEventArgs e)
    {
        var reason = SanitizeLogToken(e.Reason);
        var diagnostics = accelerationLane?.GetDiagnosticsSnapshot() ?? NknAccelerationLaneDiagnostics.Empty;
        var downSessionId = string.Empty;
        var downLanes = NknAccelerationLaneKind.None;
        var rearmSessionId = string.Empty;
        var rearmRetryReason = string.Empty;
        var rearmRecoveryReason = string.Empty;
        var shouldRearmRuntimeUnlockListener = !e.IsAvailable &&
                                               TryCaptureRuntimeUnlockListenerRearmAfterSidecarDrop(
                                                   e.Reason,
                                                   out rearmSessionId,
                                                   out rearmRetryReason,
                                                   out rearmRecoveryReason);
        var shouldNotifyRemoteDown = !e.IsAvailable &&
                                     ShouldNotifyRemoteAccelerationDown(e.Reason) &&
                                     TryCaptureAccelerationNegotiation(out downSessionId, out downLanes);
        var shouldRetryEarlyDrop = !e.IsAvailable &&
                                   ShouldRetryEarlyAccelerationDrop(e.Reason, diagnostics) &&
                                   TryCaptureAccelerationNegotiation(out _, out _);
        var fallbackSessionId = string.Empty;
        var fallbackLanes = NknAccelerationLaneKind.None;
        var shouldStartFileTransferFallback = !e.IsAvailable &&
                                              ShouldStartTunaFallbackProofForResetReason(e.Reason) &&
                                              TryCaptureAccelerationNegotiationForFallback(
                                                  out fallbackSessionId,
                                                  out fallbackLanes);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_state_changed; available={(e.IsAvailable ? 1 : 0)}; reason={reason}");
        if (!e.IsAvailable)
        {
            var resetReason = NormalizeAccelerationSidecarResetReason(e.Reason);
            FailRuntimeUnlockTunaPathLeaseIfCurrent(
                currentSessionSecurityState.SessionId?.Value,
                offerGeneration: 0,
                resetReason,
                failTransaction: false);
            FailRuntimeUnlockTunaPathProbeForSidecarDropIfActive(
                currentSessionSecurityState.SessionId?.Value,
                resetReason);
            ResetAccelerationNegotiation(resetReason);
            if (shouldStartFileTransferFallback)
            {
                StartTunaFallbackProofAndRebindIfAllowed(
                    resetReason,
                    fallbackSessionId,
                    fallbackLanes);
            }

            if (shouldNotifyRemoteDown)
            {
                ScheduleAccelerationDownNotification(downSessionId, downLanes, reason);
            }

            if (shouldRetryEarlyDrop)
            {
                ScheduleAccelerationEarlyDropRetry(reason, diagnostics);
            }

            if (shouldRearmRuntimeUnlockListener)
            {
                ScheduleRuntimeUnlockListenerRearmAfterSidecarDrop(
                    rearmSessionId,
                    rearmRetryReason,
                    rearmRecoveryReason,
                    reason);
            }

            return;
        }

        NotifyTransportAccelerationStateChanged(e.Reason);
    }

    private bool TryCaptureRuntimeUnlockListenerRearmAfterSidecarDrop(
        string? reason,
        out string sessionId,
        out string retryReason,
        out string recoveryReason)
    {
        sessionId = currentSessionSecurityState.SessionId?.Value ?? string.Empty;
        retryReason = "runtime_unlock_listener_sidecar_unavailable";
        recoveryReason = NormalizeAccelerationSidecarResetReason(reason);
        if (string.IsNullOrWhiteSpace(sessionId) ||
            !IsRuntimeUnlockListenerRearmSidecarDropReason(reason) ||
            IsAccelerationUserStoppedForCurrentSession() ||
            accelerationLane is not INknTunaAccelerationSession { CanOfferListener: true } ||
            !IsSessionAccelerationEligible(out _))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        lock (accelerationGate)
        {
            var transaction = runtimeUnlockTransactionState;
            if (transaction.PathProbeState == RuntimeUnlockPathProbeState.Started &&
                !string.IsNullOrWhiteSpace(transaction.PathProbeId) &&
                string.Equals(transaction.SessionId, normalizedSessionId, StringComparison.Ordinal))
            {
                retryReason = RuntimeUnlockProbeSidecarClosedRetryReason;
                recoveryReason = RuntimeUnlockProbeSidecarClosedRetryReason;
            }
        }

        return HasActiveRegularV4FileTransferRouteHint(normalizedSessionId) ||
               HasActivePostTunaFallbackFileTransferRouteHint(normalizedSessionId) ||
               HasActiveFileTransferDataSessionForSession(normalizedSessionId);
    }

    private static bool IsRuntimeUnlockListenerRearmSidecarDropReason(string? reason)
    {
        var normalized = SanitizeLogToken(reason);
        return normalized is
            "read_failed" or
            "write_failed" or
            "remote_closed" or
            "sidecar_read_failed" or
            "sidecar_write_failed" or
            "sidecar_remote_closed" or
            "sidecar_local_ipc_eof" or
            "sidecar_tuna_stream_eof" or
            "sidecar_local_write_failed" or
            "sidecar_tuna_write_failed" or
            "sidecar_listener_exited" or
            "sidecar_process_exited" or
            "sidecar_unexpected_exit";
    }

    private void ScheduleRuntimeUnlockListenerRearmAfterSidecarDrop(
        string sessionId,
        string retryReason,
        string recoveryReason,
        string trigger)
    {
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        if (string.IsNullOrWhiteSpace(normalizedSessionId))
        {
            return;
        }

        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=tuna_acceleration_runtime_unlock_listener_rearm_after_sidecar_drop; session_id={SanitizeLogToken(normalizedSessionId)}; retry_reason={SanitizeLogToken(retryReason)}; recovery_reason={SanitizeLogToken(recoveryReason)}; trigger={SanitizeLogToken(trigger)}");
        if (string.Equals(SanitizeLogToken(retryReason), RuntimeUnlockProbeSidecarClosedRetryReason, StringComparison.Ordinal))
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=runtime_unlock_precommit_probe_sidecar_rearm_scheduled; session_id={SanitizeLogToken(normalizedSessionId)}; retry_reason={SanitizeLogToken(retryReason)}; recovery_reason={SanitizeLogToken(recoveryReason)}; trigger={SanitizeLogToken(trigger)}; decision_reason=sidecar_closed_requires_listener_rearm");
        }

        RetirePendingAccelerationAnswerAckForRuntimeUnlockListenerRearm(
            normalizedSessionId,
            recoveryReason,
            trigger);
        ArmRuntimeUnlockRetryAfterRecovery(
            0,
            normalizedSessionId,
            retryReason,
            recoveryReason,
            requiresLocalListenerRetry: true);
    }

    private void ScheduleRuntimeUnlockPreCommitProbeSidecarListenerRearm(
        RuntimeUnlockRecoveryRetryState state,
        string trigger,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null)
    {
        if (!ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                expectedInstallReceipt,
                "listener_rearm_schedule"))
        {
            return;
        }

        var sessionId = string.IsNullOrWhiteSpace(state.SessionId) ? string.Empty : state.SessionId.Trim();
        var retryReason = SanitizeLogToken(state.RetryReason);
        var recoveryReason = SanitizeLogToken(state.RecoveryReason);
        var contractGeneration = state.ContractGeneration;
        var retiredOfferGeneration = state.RetiredOfferGeneration;
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_precommit_probe_sidecar_rearm_scheduled; session_id={SanitizeLogToken(sessionId)}; transfer_id={SanitizeLogToken(state.TransferId ?? "(none)")}; retired_generation={retiredOfferGeneration}; contract_generation={contractGeneration}; retry_reason={retryReason}; recovery_reason={recoveryReason}; trigger={SanitizeLogToken(trigger)}; decision_reason=listener_rearm_required_before_dispatch_authority");

        _ = Task.Run(
            async () =>
            {
                try
                {
                    await Task.Delay(AccelerationListenerReadyRetryDelay, CancellationToken.None).ConfigureAwait(false);
                    if (!ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                            expectedInstallReceipt,
                            "listener_rearm_delay"))
                    {
                        return;
                    }

                    if (disposed)
                    {
                        return;
                    }

                    if (!string.Equals(currentSessionSecurityState.SessionId?.Value, sessionId, StringComparison.Ordinal) ||
                        accelerationLane is not INknTunaAccelerationSession tunaSession ||
                        string.IsNullOrWhiteSpace(remoteEndpoint) ||
                        !IsSessionAccelerationEligible(out _))
                    {
                        FailRuntimeUnlockRecoveryContractIfActive(sessionId, RuntimeUnlockProbeSidecarClosedListenerRearmFailedReason);
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=session_recovery_contract_listener_rearm_failed; session_id={SanitizeLogToken(sessionId)}; reason={RuntimeUnlockProbeSidecarClosedListenerRearmFailedReason}; trigger=precommit_probe_sidecar_rearm; decision_reason=listener_rearm_context_unavailable");
                        return;
                    }

                    if (!TryCaptureCurrentRuntimeUnlockFileTransferOwnerAuthority(
                            sessionId,
                            out var listenerRearmOwnerAuthority,
                            out var listenerRearmOwnerRejectionReason) ||
                        (!string.IsNullOrWhiteSpace(state.TransferId) &&
                         !string.Equals(
                             state.TransferId,
                             listenerRearmOwnerAuthority.TransferId,
                             StringComparison.Ordinal)))
                    {
                        var rejectionReason = string.Equals(listenerRearmOwnerRejectionReason, "accepted", StringComparison.Ordinal)
                            ? "runtime_unlock_listener_rearm_transfer_owner_mismatch"
                            : listenerRearmOwnerRejectionReason;
                        LogRuntimeUnlockFileTransferOwnerRejectedBeforePathLease(
                            sessionId,
                            retryReason,
                            rejectionReason);
                        FailRuntimeUnlockRecoveryContractIfActive(
                            sessionId,
                            "runtime_unlock_filetransfer_owner_missing_before_path_lease");
                        return;
                    }

                    LogRuntimeUnlockFileTransferOwnerAcceptedBeforePathLease(
                        listenerRearmOwnerAuthority,
                        retryReason);

                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=runtime_unlock_precommit_probe_sidecar_rearm_started; session_id={SanitizeLogToken(sessionId)}; retired_generation={retiredOfferGeneration}; contract_generation={contractGeneration}; retry_reason={retryReason}; trigger={SanitizeLogToken(trigger)}; decision_reason=listener_rearm_required_before_dispatch_authority");

                    RuntimeUnlockTunaPathLeaseSnapshot lease;
                    lock (accelerationGate)
                    {
                        var current = runtimeUnlockRecoveryRetryState;
                        if (current is null ||
                            current.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                            current.ContractGeneration != contractGeneration ||
                            current.RetiredOfferGeneration != retiredOfferGeneration ||
                            current.ListenerRearmCompleted ||
                            !string.Equals(current.SessionId, sessionId, StringComparison.Ordinal))
                        {
                            return;
                        }

                        if (expectedInstallReceipt is { } receipt &&
                            !TryValidateRuntimeUnlockRetryDispatchInstallReceiptCurrentUnsafe(
                                current,
                                receipt,
                                out var receiptRejectionReason))
                        {
                            LogRuntimeUnlockRetryDispatchInstallRejected(
                                receipt,
                                CaptureRuntimeUnlockRetryDispatchInstallTelemetryUnsafe(current),
                                RuntimeUnlockRetryDispatchInstallStatus.Rejected,
                                $"{receiptRejectionReason}_listener_rearm_start");
                            return;
                        }

                        lease = StartRuntimeUnlockTunaPathLeaseUnsafe(
                            sessionId,
                            listenerRearmOwnerAuthority.TransferId,
                            ResolvePayerDecisionIdForNegotiation(retryReason),
                            retryReason);
                    }

                    if (!await tunaSession.EnsureListenerSidecarConnectedAsync(remoteEndpoint, CancellationToken.None).ConfigureAwait(false) ||
                        string.IsNullOrWhiteSpace(tunaSession.LocalTunaAddress))
                    {
                        FailRuntimeUnlockTunaPathLeaseIfCurrent(
                            sessionId,
                            offerGeneration: 0,
                            RuntimeUnlockProbeSidecarClosedListenerRearmFailedReason,
                            failTransaction: false);
                        FailRuntimeUnlockRecoveryContractIfActive(sessionId, RuntimeUnlockProbeSidecarClosedListenerRearmFailedReason);
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=session_recovery_contract_listener_rearm_failed; session_id={SanitizeLogToken(sessionId)}; reason={RuntimeUnlockProbeSidecarClosedListenerRearmFailedReason}; trigger=precommit_probe_sidecar_rearm; decision_reason=listener_sidecar_unavailable");
                        return;
                    }

                    if (!TryCaptureCurrentRuntimeUnlockFileTransferOwnerAuthority(
                            sessionId,
                            out var currentListenerRearmOwnerAuthority,
                            out var currentListenerRearmOwnerRejectionReason) ||
                        !Equals(currentListenerRearmOwnerAuthority, listenerRearmOwnerAuthority))
                    {
                        var rejectionReason = string.Equals(
                                currentListenerRearmOwnerRejectionReason,
                                "accepted",
                                StringComparison.Ordinal)
                            ? "current_filetransfer_owner_changed_after_listener_rearm"
                            : currentListenerRearmOwnerRejectionReason;
                        LogRuntimeUnlockFileTransferOwnerRejectedBeforeOfferDispatch(
                            sessionId,
                            listenerRearmOwnerAuthority.TransferId,
                            retryReason,
                            rejectionReason);
                        FailRuntimeUnlockTunaPathLeaseIfCurrent(
                            sessionId,
                            offerGeneration: 0,
                            rejectionReason,
                            failTransaction: false);
                        FailRuntimeUnlockRecoveryContractIfActive(sessionId, rejectionReason);
                        return;
                    }

                    if (!ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                            expectedInstallReceipt,
                            "listener_rearm_completion"))
                    {
                        return;
                    }

                    MarkRuntimeUnlockTunaPathLeaseListenerReady(lease, sessionId, retryReason);
                    MarkRuntimeUnlockRecoveryContractListenerRearmCompleted(sessionId, "precommit_probe_sidecar_rearm");
                    NotifyTransportAccelerationStateChanged("listener_ready");
                }
                catch (Exception ex) when (ex is not OperationCanceledException)
                {
                    FailRuntimeUnlockRecoveryContractIfActive(sessionId, RuntimeUnlockProbeSidecarClosedListenerRearmFailedReason);
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=session_recovery_contract_listener_rearm_failed; session_id={SanitizeLogToken(sessionId)}; reason={RuntimeUnlockProbeSidecarClosedListenerRearmFailedReason}; trigger=precommit_probe_sidecar_rearm; error={ex.GetType().Name}");
                }
            },
            CancellationToken.None);
    }

    private void OnAccelerationMessageReceived(object? sender, NknIncomingMessage e)
    {
        if (disposed || e.Payload.Length == 0)
        {
            return;
        }

        var source = ResolveSyntheticAccelerationSource(e.Channel);
        if (string.IsNullOrWhiteSpace(source))
        {
            NknRuntimeDiagnostics.SetLastEnvelopeDropReason("tuna_source_unavailable");
            LocalOperationalLog.Warn("NKN.Tuna", $"event=tuna_accelerated_frame_rejected; reason=source_unavailable; channel={MapBridgeChannel(e.Channel)}");
            return;
        }

        var previousAcceleratedInbound = handlingTunaAcceleratedInboundMessage;
        handlingTunaAcceleratedInboundMessage = true;
        try
        {
            OnClientMessageReceived(
                sender,
                new NknIncomingMessage(
                    source,
                    e.Payload,
                    isTopic: false,
                    topic: null,
                    channel: e.Channel,
                    bridgeIngressObservedUtcMs: e.BridgeIngressObservedUtcMs,
                    bridgeMessageObservedUtcMs: e.BridgeMessageObservedUtcMs,
                    binaryFrameDecodedUtcMs: e.BinaryFrameDecodedUtcMs,
                    socketDataEventEmittedUtcMs: e.SocketDataEventEmittedUtcMs,
                    wsReceiverWriteEnteredUtcMs: e.WsReceiverWriteEnteredUtcMs,
                    wsMessageEmittedUtcMs: e.WsMessageEmittedUtcMs,
                    sdkHandleMsgEnteredUtcMs: e.SdkHandleMsgEnteredUtcMs,
                    clientMessageDispatchUtcMs: e.ClientMessageDispatchUtcMs,
                    multiClientMessageDispatchUtcMs: e.MultiClientMessageDispatchUtcMs));
        }
        finally
        {
            handlingTunaAcceleratedInboundMessage = previousAcceleratedInbound;
        }
    }

    private string? ResolveSyntheticAccelerationSource(NknBridgeChannel channel)
        => channel switch
        {
            NknBridgeChannel.Media => ResolveExpectedRemoteMediaPeerAddressForCurrentSession(),
            NknBridgeChannel.Bulk => ResolveExpectedRemoteBulkPeerAddressForCurrentSession(),
            _ => ResolveExpectedRemotePeerAddressForCurrentSession(),
        };

    private void MarkPendingRuntimeUnlockAccelerationNegotiation(
        string reason,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null)
    {
        var normalizedReason = SanitizeLogToken(reason);
        lock (accelerationGate)
        {
            if (expectedInstallReceipt is { } receipt)
            {
                var state = runtimeUnlockRecoveryRetryState;
                var receiptRejectionReason = "retry_dispatch_install_state_missing";
                if (state is null ||
                    !TryValidateRuntimeUnlockRetryDispatchInstallReceiptCurrentUnsafe(
                        state,
                        receipt,
                        out receiptRejectionReason))
                {
                    LogRuntimeUnlockRetryDispatchInstallRejected(
                        receipt,
                        CaptureRuntimeUnlockRetryDispatchInstallTelemetryUnsafe(state),
                        RuntimeUnlockRetryDispatchInstallStatus.Rejected,
                        $"{receiptRejectionReason}_pending_negotiation_bind");
                    return;
                }
            }

            pendingRuntimeUnlockAccelerationNegotiationReason = IsRuntimeUnlockActivationReason(normalizedReason)
                ? normalizedReason
                : "runtime_unlock";
            if (expectedInstallReceipt is not null ||
                pendingRuntimeUnlockAccelerationNegotiationInstallReceipt is null)
            {
                pendingRuntimeUnlockAccelerationNegotiationInstallReceipt = expectedInstallReceipt;
            }
            pendingRuntimeUnlockAccelerationNegotiation = 1;
        }
    }

    private bool TryQueueRuntimeUnlockNegotiationBehindPendingGeneration(
        string reason,
        string waitReason,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null)
    {
        var normalizedReason = SanitizeLogToken(reason);
        if (!IsRuntimeUnlockActivationReason(normalizedReason))
        {
            return false;
        }

        bool hasOffer;
        bool hasAnswerAck;
        lock (accelerationGate)
        {
            hasOffer = !string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce);
            hasAnswerAck = !string.IsNullOrWhiteSpace(pendingAccelerationAnswerAckNonce);
            if (!hasOffer && !hasAnswerAck)
            {
                return false;
            }

            if (expectedInstallReceipt is { } receipt)
            {
                var state = runtimeUnlockRecoveryRetryState;
                var receiptRejectionReason = "retry_dispatch_install_state_missing";
                if (state is null ||
                    !TryValidateRuntimeUnlockRetryDispatchInstallReceiptCurrentUnsafe(
                        state,
                        receipt,
                        out receiptRejectionReason))
                {
                    LogRuntimeUnlockRetryDispatchInstallRejected(
                        receipt,
                        CaptureRuntimeUnlockRetryDispatchInstallTelemetryUnsafe(state),
                        RuntimeUnlockRetryDispatchInstallStatus.Rejected,
                        $"{receiptRejectionReason}_pending_generation_bind");
                    return false;
                }
            }

            pendingRuntimeUnlockAccelerationNegotiationReason = normalizedReason;
            if (expectedInstallReceipt is not null ||
                pendingRuntimeUnlockAccelerationNegotiationInstallReceipt is null)
            {
                pendingRuntimeUnlockAccelerationNegotiationInstallReceipt = expectedInstallReceipt;
            }
            pendingRuntimeUnlockAccelerationNegotiation = 1;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_runtime_unlock_queued_behind_pending_generation; reason={normalizedReason}; wait_reason={SanitizeLogToken(waitReason)}; has_offer={(hasOffer ? 1 : 0)}; has_answer_ack={(hasAnswerAck ? 1 : 0)}");
        return true;
    }

    private bool TryConsumePendingRuntimeUnlockAccelerationNegotiation(
        out string reason,
        out RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt)
    {
        reason = "runtime_unlock";
        lock (accelerationGate)
        {
            return TryConsumePendingRuntimeUnlockAccelerationNegotiationUnsafe(
                out reason,
                out expectedInstallReceipt);
        }
    }

    private bool TryConsumePendingRuntimeUnlockAccelerationNegotiationUnsafe(
        out string reason,
        out RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt)
    {
        reason = "runtime_unlock";
        expectedInstallReceipt = null;
        if (pendingRuntimeUnlockAccelerationNegotiation == 0)
        {
            return false;
        }

        pendingRuntimeUnlockAccelerationNegotiation = 0;
        if (!string.IsNullOrWhiteSpace(pendingRuntimeUnlockAccelerationNegotiationReason))
        {
            reason = pendingRuntimeUnlockAccelerationNegotiationReason;
        }

        expectedInstallReceipt = pendingRuntimeUnlockAccelerationNegotiationInstallReceipt;
        pendingRuntimeUnlockAccelerationNegotiationReason = null;
        pendingRuntimeUnlockAccelerationNegotiationInstallReceipt = null;
        return true;
    }

    private void SchedulePendingRuntimeUnlockAccelerationNegotiationAfterCurrentOperation(string trigger)
    {
        if (ShouldHoldPendingRuntimeUnlockAccelerationNegotiationForRegularV4FrontierRepair(out var holdReason, out var blockerReason, out var blockerEvidenceAgeMs))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_runtime_unlock_pending_negotiation_held_by_regular_v4_frontier_repair; reason={SanitizeLogToken(holdReason)}; trigger={SanitizeLogToken(trigger)}; blocker_reason={SanitizeLogToken(blockerReason)}; blocker_evidence_age_ms={blockerEvidenceAgeMs}; decision_reason=awaiting_regular_v4_frontier_repair_settlement");
            SchedulePendingRuntimeUnlockRegularV4FrontierRepairRecheck(
                holdReason,
                blockerReason,
                blockerEvidenceAgeMs,
                trigger);
            return;
        }

        if (!TryConsumePendingRuntimeUnlockAccelerationNegotiation(
                out var pendingReason,
                out var expectedInstallReceipt))
        {
            return;
        }

        ScheduleRuntimeUnlockAccelerationNegotiationWake(
            pendingReason,
            trigger,
            expectedInstallReceipt);
    }

    private void SchedulePendingRuntimeUnlockAccelerationNegotiationAfterCurrentOperationUnsafe(string trigger)
    {
        if (ShouldHoldPendingRuntimeUnlockAccelerationNegotiationForRegularV4FrontierRepair(out var holdReason, out var blockerReason, out var blockerEvidenceAgeMs))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_runtime_unlock_pending_negotiation_held_by_regular_v4_frontier_repair; reason={SanitizeLogToken(holdReason)}; trigger={SanitizeLogToken(trigger)}; blocker_reason={SanitizeLogToken(blockerReason)}; blocker_evidence_age_ms={blockerEvidenceAgeMs}; decision_reason=awaiting_regular_v4_frontier_repair_settlement");
            SchedulePendingRuntimeUnlockRegularV4FrontierRepairRecheck(
                holdReason,
                blockerReason,
                blockerEvidenceAgeMs,
                trigger);
            return;
        }

        if (!TryConsumePendingRuntimeUnlockAccelerationNegotiationUnsafe(
                out var pendingReason,
                out var expectedInstallReceipt))
        {
            return;
        }

        ScheduleRuntimeUnlockAccelerationNegotiationWake(
            pendingReason,
            trigger,
            expectedInstallReceipt);
    }

    private void ScheduleRuntimeUnlockAccelerationNegotiationWake(
        string pendingReason,
        string trigger,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt)
    {
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_runtime_unlock_pending_negotiation_wake_scheduled; reason={SanitizeLogToken(pendingReason)}; trigger={SanitizeLogToken(trigger)}");
        _ = Task.Run(
            () => ScheduleAccelerationNegotiationIfEligible(
                pendingReason,
                expectedInstallReceipt),
            CancellationToken.None);
    }

    private void SchedulePendingRuntimeUnlockRegularV4FrontierRepairRecheck(
        string pendingReason,
        string blockerReason,
        long blockerEvidenceAgeMs,
        string trigger)
    {
        if (!IsRuntimeUnlockActivationReason(pendingReason) ||
            !IsRegularV4PressureActivationSendBlocker(blockerReason))
        {
            return;
        }

        if (Interlocked.CompareExchange(ref pendingRuntimeUnlockRegularV4FrontierRepairRecheckScheduled, 1, 0) != 0)
        {
            return;
        }

        const long evidenceFreshnessWindowMs = 20_000;
        var evidenceFresh = blockerEvidenceAgeMs <= evidenceFreshnessWindowMs;
        var delayMs = evidenceFresh
            ? Math.Clamp(evidenceFreshnessWindowMs - blockerEvidenceAgeMs + 50, 50, 30_000)
            : 50;
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_runtime_unlock_pending_negotiation_recheck_scheduled; reason={SanitizeLogToken(pendingReason)}; trigger={SanitizeLogToken(trigger)}; blocker_reason={SanitizeLogToken(blockerReason)}; blocker_evidence_age_ms={Math.Max(0, blockerEvidenceAgeMs)}; blocker_evidence_fresh={(evidenceFresh ? 1 : 0)}; delay_ms={delayMs}; decision_reason=regular_v4_frontier_repair_blocker_bounded_recheck");

        _ = Task.Run(
            async () =>
            {
                try
                {
                    await Task.Delay(TimeSpan.FromMilliseconds(delayMs)).ConfigureAwait(false);
                }
                finally
                {
                    Interlocked.Exchange(ref pendingRuntimeUnlockRegularV4FrontierRepairRecheckScheduled, 0);
                }

                if (disposed)
                {
                    return;
                }

                SchedulePendingRuntimeUnlockAccelerationNegotiationAfterCurrentOperation(
                    "regular_v4_frontier_repair_blocker_recheck");
            },
            CancellationToken.None);
    }

    private bool ShouldHoldPendingRuntimeUnlockAccelerationNegotiationForRegularV4FrontierRepair(
        out string pendingReason,
        out string blockerReason,
        out long blockerEvidenceAgeMs)
    {
        pendingReason = "runtime_unlock";
        blockerReason = string.Empty;
        blockerEvidenceAgeMs = 0;

        lock (accelerationGate)
        {
            if (pendingRuntimeUnlockAccelerationNegotiation == 0)
            {
                return false;
            }

            if (!string.IsNullOrWhiteSpace(pendingRuntimeUnlockAccelerationNegotiationReason))
            {
                pendingReason = pendingRuntimeUnlockAccelerationNegotiationReason;
            }
        }

        if (!IsRuntimeUnlockActivationReason(pendingReason))
        {
            return false;
        }

        var sessionId = currentSessionSecurityState.SessionId?.Value;
        if (string.IsNullOrWhiteSpace(sessionId) ||
            !HasActiveRegularV4FileTransferRouteHint(sessionId) ||
            HasActivePostTunaFallbackFileTransferRouteHint(sessionId))
        {
            return false;
        }

        var overrideBlocker = RuntimeUnlockRegularV4RepairPressureBlockerOverrideForTests?.Invoke(this);
        if (overrideBlocker is { HasBlocker: true })
        {
            blockerReason = SanitizeLogToken(overrideBlocker.Value.Reason);
            blockerEvidenceAgeMs = Math.Max(0, overrideBlocker.Value.EvidenceAgeMs);
        }
        else if (client is not RealNknClientAdapter realClient ||
                 !realClient.TryGetFileTransferRegularV4ActivationSendBlocker(
                     out blockerReason,
                     out blockerEvidenceAgeMs,
                     includeRegularV4Pressure: true))
        {
            return false;
        }

        return IsRegularV4PressureActivationSendBlocker(blockerReason);
    }

    private void ClearPendingRuntimeUnlockAccelerationNegotiation()
    {
        lock (accelerationGate)
        {
            pendingRuntimeUnlockAccelerationNegotiation = 0;
            pendingRuntimeUnlockAccelerationNegotiationReason = null;
            pendingRuntimeUnlockAccelerationNegotiationInstallReceipt = null;
        }
    }

    private void ScheduleAccelerationNegotiationIfEligible(
        string reason,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null)
    {
        var isRuntimeUnlockActivation = IsRuntimeUnlockActivationReason(reason);
        if (isRuntimeUnlockActivation &&
            !ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                expectedInstallReceipt,
                "negotiation_schedule"))
        {
            return;
        }

        if (disposed ||
            accelerationLane is not INknTunaAccelerationSession ||
            IsAccelerationUserStoppedForCurrentSession() ||
            !IsSessionAccelerationEligible(out _))
        {
            return;
        }

        var currentSessionId = currentSessionSecurityState.SessionId?.Value;
        if (isRuntimeUnlockActivation &&
            !string.IsNullOrWhiteSpace(currentSessionId) &&
            ShouldKeepPostTunaFallbackDataSessionsAvailableDuringTunaActivation(
                currentSessionId,
                out var fallbackOwnerReason))
        {
            var evidenceDisposition = MarkRuntimeUnlockRecoveryContractDispatchDeferredForRegularV4ReceiveRecovery(
                currentSessionId,
                "fallback_owner_active");
            if (evidenceDisposition != RuntimeUnlockRetryEvidenceDisposition.ContinueWithCurrentAuthority)
            {
                if (evidenceDisposition == RuntimeUnlockRetryEvidenceDisposition.Hold)
                {
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=filetransfer_runtime_unlock_waiting_for_fallback_owner; session_id={SanitizeLogToken(currentSessionId)}; reason={SanitizeLogToken(reason)}; fallback_owner_reason={SanitizeLogToken(fallbackOwnerReason)}; source=negotiation_scheduler");
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=runtime_unlock_fallback_unavailable_suppressed; session_id={SanitizeLogToken(currentSessionId)}; reason={SanitizeLogToken(reason)}; fallback_owner_reason={SanitizeLogToken(fallbackOwnerReason)}; source=negotiation_scheduler");
                    NotifyTransportAccelerationStateChanged("runtime_unlock_waiting_for_fallback_owner");
                }

                return;
            }
        }

        if (HasPendingOutboundAccelerationOffer() || HasPendingAccelerationAnswerAck())
        {
            if (TryQueueRuntimeUnlockNegotiationBehindPendingGeneration(
                    reason,
                    "schedule_pending_generation",
                    expectedInstallReceipt))
            {
                return;
            }

            return;
        }

        if (Interlocked.CompareExchange(ref accelerationNegotiationScheduled, 1, 0) != 0)
        {
            if (isRuntimeUnlockActivation)
            {
                if (TrySupersedeStaleActiveNegotiationForRuntimeUnlockRecoveryContract(reason) &&
                    Interlocked.CompareExchange(ref accelerationNegotiationScheduled, 1, 0) == 0)
                {
                    var operationPayerDecisionId = ResolvePayerDecisionIdForNegotiation(reason);
                    var operationGeneration = Interlocked.Increment(
                        ref runtimeUnlockPostTunaFallbackActivationOperationNextGeneration);
                    var operationIntent = CaptureRuntimeUnlockPostTunaFallbackActivationIntentForOperation(
                        expectedInstallReceipt);
                    NotifyTransportAccelerationStateChanged($"negotiation_scheduled_{reason}");
                    LogRuntimeUnlockPostTunaFallbackActivationDisposition(
                        operationIntent,
                        operationGeneration,
                        operationPayerDecisionId,
                        reason,
                        expectedInstallReceipt,
                        "started",
                        "negotiation_task_queued");
                    _ = Task.Run(
                        async () =>
                        {
                            var disposition = "completed";
                            var dispositionReason = "negotiation_operation_completed";
                            try
                            {
                                if (!MarkRuntimeUnlockRecoveryContractRetryDispatched(
                                        reason,
                                        expectedInstallReceipt))
                                {
                                    (disposition, dispositionReason) =
                                        ResolveRuntimeUnlockPostTunaFallbackActivationDisposition(
                                            operationIntent,
                                            expectedInstallReceipt);
                                    return;
                                }

                                await TrySendAccelerationOfferAsync(
                                        reason,
                                        operationPayerDecisionId,
                                        CancellationToken.None,
                                        expectedInstallReceipt)
                                    .ConfigureAwait(false);
                                (disposition, dispositionReason) =
                                    ResolveRuntimeUnlockPostTunaFallbackActivationDispositionAfterOffer(
                                        operationIntent,
                                        expectedInstallReceipt);
                            }
                            catch (Exception ex) when (ex is not OperationCanceledException)
                            {
                                disposition = "rejected";
                                dispositionReason = $"negotiation_failed_{SanitizeLogToken(ex.GetType().Name)}";
                                LocalOperationalLog.Warn(
                                    "NKN.Tuna",
                                    $"event=tuna_acceleration_negotiation_failed; reason={SanitizeLogToken(reason)}; error={ex.GetType().Name}");
                            }
                            finally
                            {
                                LogRuntimeUnlockPostTunaFallbackActivationDisposition(
                                    operationIntent,
                                    operationGeneration,
                                    operationPayerDecisionId,
                                    reason,
                                    expectedInstallReceipt,
                                    disposition,
                                    dispositionReason);
                                Interlocked.Exchange(ref accelerationNegotiationScheduled, 0);
                                SchedulePendingRuntimeUnlockAccelerationNegotiationAfterCurrentOperation("negotiation_complete");
                            }
                        },
                        CancellationToken.None);
                    return;
                }

                MarkPendingRuntimeUnlockAccelerationNegotiation(
                    reason,
                    expectedInstallReceipt);
                MarkRuntimeUnlockRecoveryContractQueuedBehindActiveNegotiation(reason);
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_runtime_unlock_queued_behind_active_negotiation; reason={SanitizeLogToken(reason)}");
            }

            return;
        }

        var payerDecisionId = ResolvePayerDecisionIdForNegotiation(reason);
        var scheduledOperationGeneration = Interlocked.Increment(
            ref runtimeUnlockPostTunaFallbackActivationOperationNextGeneration);
        var scheduledOperationIntent = CaptureRuntimeUnlockPostTunaFallbackActivationIntentForOperation(
            expectedInstallReceipt);
        NotifyTransportAccelerationStateChanged($"negotiation_scheduled_{reason}");
        LogRuntimeUnlockPostTunaFallbackActivationDisposition(
            scheduledOperationIntent,
            scheduledOperationGeneration,
            payerDecisionId,
            reason,
            expectedInstallReceipt,
            "started",
            "negotiation_task_queued");
        _ = Task.Run(
            async () =>
            {
                var disposition = "completed";
                var dispositionReason = "negotiation_operation_completed";
                try
                {
                    if (!MarkRuntimeUnlockRecoveryContractRetryDispatched(
                            reason,
                            expectedInstallReceipt))
                    {
                        (disposition, dispositionReason) =
                            ResolveRuntimeUnlockPostTunaFallbackActivationDisposition(
                                scheduledOperationIntent,
                                expectedInstallReceipt);
                        return;
                    }

                    await TrySendAccelerationOfferAsync(
                            reason,
                            payerDecisionId,
                            CancellationToken.None,
                            expectedInstallReceipt)
                        .ConfigureAwait(false);
                    (disposition, dispositionReason) =
                        ResolveRuntimeUnlockPostTunaFallbackActivationDispositionAfterOffer(
                            scheduledOperationIntent,
                            expectedInstallReceipt);
                }
                catch (Exception ex) when (ex is not OperationCanceledException)
                {
                    disposition = "rejected";
                    dispositionReason = $"negotiation_failed_{SanitizeLogToken(ex.GetType().Name)}";
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_negotiation_failed; reason={SanitizeLogToken(reason)}; error={ex.GetType().Name}");
                }
                finally
                {
                    LogRuntimeUnlockPostTunaFallbackActivationDisposition(
                        scheduledOperationIntent,
                        scheduledOperationGeneration,
                        payerDecisionId,
                        reason,
                        expectedInstallReceipt,
                        disposition,
                        dispositionReason);
                    Interlocked.Exchange(ref accelerationNegotiationScheduled, 0);
                    SchedulePendingRuntimeUnlockAccelerationNegotiationAfterCurrentOperation("negotiation_complete");
                }
            },
            CancellationToken.None);
    }

    private RuntimeUnlockPostTunaFallbackActivationIntent?
        CaptureRuntimeUnlockPostTunaFallbackActivationIntentForOperation(
            RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt)
    {
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            var intent = state?.PostTunaFallbackActivationIntent;
            if (intent is null ||
                runtimeUnlockPostTunaFallbackActivationIntent != intent ||
                expectedInstallReceipt is not { } receipt ||
                state!.LastCommittedDispatchInstallReceipt != receipt)
            {
                return null;
            }

            return intent;
        }
    }

    private (string Disposition, string Reason)
        ResolveRuntimeUnlockPostTunaFallbackActivationDisposition(
            RuntimeUnlockPostTunaFallbackActivationIntent? expectedIntent,
            RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt)
    {
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (expectedIntent is null ||
                state?.PostTunaFallbackActivationIntent != expectedIntent ||
                runtimeUnlockPostTunaFallbackActivationIntent != expectedIntent ||
                expectedInstallReceipt is not { } receipt ||
                state.LastCommittedDispatchInstallReceipt != receipt)
            {
                return ("invalidated", "activation_intent_or_install_receipt_replaced");
            }

            if (state.DispatchDecisionStatus == RuntimeUnlockRetryDispatchDecisionStatus.Held ||
                state.BlockedByRegularV4ReceiveRecovery ||
                state.BlockedByRegularV4FrontierRepair)
            {
                return ("held", state.DispatchDecisionReason ?? "coordinator_authority_held");
            }

            if (state.DispatchAuthorityRejected ||
                state.ContractState == SessionRecoveryContractState.Failed)
            {
                return ("rejected", state.AuthorityFailureReason ?? "retry_dispatch_rejected");
            }

            return ("invalidated", state.DispatchDecisionReason ?? "retry_dispatch_not_current");
        }
    }

    private (string Disposition, string Reason)
        ResolveRuntimeUnlockPostTunaFallbackActivationDispositionAfterOffer(
            RuntimeUnlockPostTunaFallbackActivationIntent? expectedIntent,
            RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt)
    {
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (expectedIntent is null ||
                state?.PostTunaFallbackActivationIntent != expectedIntent ||
                runtimeUnlockPostTunaFallbackActivationIntent != expectedIntent ||
                expectedInstallReceipt is not { } receipt ||
                state.LastCommittedDispatchInstallReceipt != receipt)
            {
                return ("invalidated", "activation_intent_or_install_receipt_replaced_after_offer");
            }

            var currentOfferBound =
                outboundAccelerationOfferInstallReceipt == receipt &&
                !string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce);
            var retiredOfferBound =
                retiredAccelerationOfferInstallReceipt == receipt &&
                !string.IsNullOrWhiteSpace(retiredAccelerationOfferNonce);
            if (currentOfferBound || retiredOfferBound)
            {
                return (
                    "completed",
                    currentOfferBound
                        ? "committed_authority_bound_to_current_offer"
                        : "committed_authority_bound_to_retired_offer_proof");
            }

            if (state.DispatchAuthorityRejected ||
                state.ContractState == SessionRecoveryContractState.Failed)
            {
                return ("rejected", state.AuthorityFailureReason ?? "offer_flow_authority_rejected");
            }

            return ("held", state.DispatchDecisionReason ?? "committed_authority_produced_no_offer");
        }
    }

    private static void LogRuntimeUnlockPostTunaFallbackActivationDisposition(
        RuntimeUnlockPostTunaFallbackActivationIntent? intent,
        long operationGeneration,
        long payerDecisionId,
        string trigger,
        RuntimeUnlockRetryDispatchInstallReceipt? receipt,
        string disposition,
        string decisionReason)
    {
        if (intent is null)
        {
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_post_tuna_fallback_activation_disposition; {FormatRuntimeUnlockPostTunaFallbackActivationIntent(intent)}; operation_generation={operationGeneration}; payer_decision_id={payerDecisionId}; retry_authority_id={SanitizeLogToken(receipt?.Authority.AuthorityId.ToString() ?? "(none)")}; install_generation={receipt?.InstallGeneration ?? 0}; trigger={SanitizeLogToken(trigger)}; disposition={SanitizeLogToken(disposition)}; decision_reason={SanitizeLogToken(decisionReason)}");
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_negotiation_scheduling_{SanitizeLogToken(disposition)}; {FormatRuntimeUnlockPostTunaFallbackActivationIntent(intent)}; operation_generation={operationGeneration}; payer_decision_id={payerDecisionId}; retry_authority_id={SanitizeLogToken(receipt?.Authority.AuthorityId.ToString() ?? "(none)")}; install_generation={receipt?.InstallGeneration ?? 0}; trigger={SanitizeLogToken(trigger)}; decision_reason={SanitizeLogToken(decisionReason)}");
    }

    private async Task TrySendAccelerationOfferAsync(
        string reason,
        long payerDecisionId,
        CancellationToken ct,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null)
    {
        if (IsRuntimeUnlockActivationReason(reason) &&
            !ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                expectedInstallReceipt,
                "offer_preflight"))
        {
            return;
        }

        if (IsStaleLocalPayerDecision(payerDecisionId))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_negotiation_stale; stage=preflight; payer_decision_id={payerDecisionId}; current_payer_decision_id={Volatile.Read(ref accelerationPayerDecisionId)}; reason={SanitizeLogToken(reason)}");
            return;
        }

        if (accelerationLane is not INknTunaAccelerationSession tunaSession)
        {
            RejectAccelerationOfferPreflight(reason, "missing_tuna_session", retryable: false);
            return;
        }

        if (string.IsNullOrWhiteSpace(remoteEndpoint))
        {
            RejectAccelerationOfferPreflight(reason, "missing_remote_endpoint", retryable: true);
            return;
        }

        if (!IsSessionAccelerationEligible(out var eligibleLanes))
        {
            RejectAccelerationOfferPreflight(reason, "session_not_eligible", retryable: false);
            return;
        }

        var preflightLanes = eligibleLanes & tunaSession.ConfiguredLanes;
        if (preflightLanes == NknAccelerationLaneKind.None)
        {
            RejectAccelerationOfferPreflight(reason, "no_eligible_lane", retryable: false, eligibleLanes);
            NotifyTransportAccelerationStateChanged("no_eligible_lane");
            return;
        }

        var sessionId = currentSessionSecurityState.SessionId?.Value;
        if (string.IsNullOrWhiteSpace(sessionId) || !TryGetCurrentEnvelopeCode(out var envelopeCode))
        {
            RejectAccelerationOfferPreflight(reason, "missing_secure_session_context", retryable: true, preflightLanes);
            return;
        }

        var localRole = ResolveLocalSessionRole();
        var pausedForActivationNegotiation = false;
        void PauseActivationIfNeeded(string pauseTrigger)
        {
            if (pausedForActivationNegotiation)
            {
                return;
            }

            if (IsAccelerationNegotiatedAndHealthy())
            {
                return;
            }

            pausedForActivationNegotiation = PauseFileTransferDataSessionsForTunaActivationNegotiation(
                "activation_negotiation_pending",
                sessionId,
                pauseTrigger);
        }

        void ResumeActivationPauseIfNeeded(string resumeReason, string resumeTrigger)
        {
            if (!pausedForActivationNegotiation)
            {
                return;
            }

            if (string.Equals(resumeReason, "tuna_activation_failed_regular_v4_resumed", StringComparison.Ordinal))
            {
                ResumeFileTransferDataSessionsAfterTunaActivationFailure(
                    resumeTrigger,
                    sessionId,
                    resumeTrigger);
            }
            else
            {
                ResumeFileTransferDataSessionsAfterTunaActivationNegotiation(
                    resumeReason,
                    sessionId,
                    resumeTrigger);
            }

            pausedForActivationNegotiation = false;
        }

        var isRuntimeUnlockActivation = IsRuntimeUnlockActivationReason(reason);
        if (isRuntimeUnlockActivation &&
            !ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                expectedInstallReceipt,
                "payer_intent_preflight"))
        {
            return;
        }

        FileTransferRoutePublicationAuthority? runtimeUnlockFileTransferOwnerAuthority = null;
        FileTransferAuthorityId? runtimeUnlockDispatchAuthorityId = null;
        if (isRuntimeUnlockActivation &&
            IsFileTransferRuntimeUnlockContextObserved(sessionId))
        {
            if (!TryCaptureCurrentRuntimeUnlockFileTransferOwnerAuthority(
                    sessionId,
                    out var capturedOwnerAuthority,
                    out var ownerRejectionReason))
            {
                LogRuntimeUnlockFileTransferOwnerRejectedBeforePathLease(
                    sessionId,
                    reason,
                    ownerRejectionReason);
                RejectRuntimeUnlockRecoveryRetryBeforeDispatchIfActive(
                    sessionId,
                    "runtime_unlock_filetransfer_owner_missing_before_path_lease");
                return;
            }

            runtimeUnlockFileTransferOwnerAuthority = capturedOwnerAuthority;
            LogRuntimeUnlockFileTransferOwnerAcceptedBeforePathLease(
                capturedOwnerAuthority,
                reason);
        }
        if (isRuntimeUnlockActivation &&
            TryGetCurrentGrantedRuntimeUnlockRetryDispatchContract(
                sessionId,
                out _,
                out var capturedDispatchContract))
        {
            runtimeUnlockDispatchAuthorityId = capturedDispatchContract!.Authority.AuthorityId;
        }

        var requiresContractLocalListenerRetry = false;
        if (isRuntimeUnlockActivation &&
            ShouldPauseRegularNknV4FileTransferBeforeRuntimeUnlockPayerIntent(sessionId, reason))
        {
            pausedForActivationNegotiation = PauseRegularNknV4FileTransferForRuntimeUnlockMakeBeforeBreak(
                sessionId,
                "runtime_unlock_retry_dispatch_payer_intent",
                reason);
        }

        try
        {
            if (isRuntimeUnlockActivation &&
                !ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                    expectedInstallReceipt,
                    "payer_intent_send"))
            {
                return;
            }

            requiresContractLocalListenerRetry = isRuntimeUnlockActivation &&
                RequiresLocalListenerRetryForRuntimeUnlockRecoveryContract(sessionId, reason);
            if (requiresContractLocalListenerRetry && !tunaSession.CanOfferListener)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=session_recovery_contract_listener_rearm_required; session_id={SanitizeLogToken(sessionId)}; reason={SanitizeLogToken(reason)}; can_offer_listener=0");
            }

            var payerIntentQueued = await SendAccelerationPayerIntentAsync(
                    remoteEndpoint,
                    sessionId,
                    envelopeCode,
                    localRole,
                    preflightLanes,
                    tunaSession.CanOfferListener || requiresContractLocalListenerRetry,
                    reason,
                    payerDecisionId,
                    ct,
                    isRuntimeUnlockActivation ? expectedInstallReceipt : null)
                .ConfigureAwait(false);
            if (!payerIntentQueued)
            {
                var payerIntentRetryReason = isRuntimeUnlockActivation
                    ? "runtime_unlock_payer_intent_send_rejected"
                    : "payer_intent_send_rejected";
                ResumeActivationPauseIfNeeded("tuna_activation_failed_regular_v4_resumed", payerIntentRetryReason);
                if (isRuntimeUnlockActivation &&
                    TrySettleRuntimeUnlockRetryDispatchMissingBeforeOfferIfCurrent(
                        sessionId,
                        "runtime_unlock_payer_intent_send_rejected_before_retry_dispatch",
                        payerIntentRetryReason,
                        requiresContractLocalListenerRetry,
                        runtimeUnlockDispatchAuthorityId))
                {
                    return;
                }

                ScheduleAccelerationNegotiationRetry(
                    payerIntentRetryReason,
                    expectedInstallReceipt);
                return;
            }
        }
        catch
        {
            ResumeActivationPauseIfNeeded("tuna_activation_failed_regular_v4_resumed", "payer_intent_send_failed");
            throw;
        }

        if (isRuntimeUnlockActivation &&
            !ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                expectedInstallReceipt,
                "payer_intent_completion"))
        {
            return;
        }

        if (!tunaSession.CanOfferListener && !requiresContractLocalListenerRetry)
        {
            ResumeActivationPauseIfNeeded("tuna_activation_failed_regular_v4_resumed", "listener_unavailable");
            RejectAccelerationOfferPreflight(reason, "listener_unavailable", retryable: true, eligibleLanes);
            return;
        }

        NotifyTransportAccelerationStateChanged("checking_payer_priority");
        if (await ShouldSuppressLocalPaidOfferForHelpeePriorityAsync(localRole, reason, ct).ConfigureAwait(false))
        {
            ResumeActivationPauseIfNeeded("tuna_activation_failed_regular_v4_resumed", "payer_priority_suppressed");
            return;
        }

        if (IsStaleLocalPayerDecision(payerDecisionId))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_negotiation_stale; stage=after_payer_priority; payer_decision_id={payerDecisionId}; current_payer_decision_id={Volatile.Read(ref accelerationPayerDecisionId)}; reason={SanitizeLogToken(reason)}");
            ResumeActivationPauseIfNeeded("stale_payer_decision", "after_payer_priority_stale");
            return;
        }

        if (accelerationLane is not INknTunaAccelerationSession ||
            !IsSessionAccelerationEligible(out eligibleLanes))
        {
            ResumeActivationPauseIfNeeded("session_not_eligible_after_payer_priority", "session_not_eligible_after_payer_priority");
            RejectAccelerationOfferPreflight(reason, "session_not_eligible_after_payer_priority", retryable: false);
            return;
        }

        if (IsAccelerationUserStoppedForCurrentSession())
        {
            ResumeActivationPauseIfNeeded("user_stopped_tuna", "after_payer_priority_user_stopped");
            RejectAccelerationOfferPreflight(reason, "user_stopped_tuna", retryable: false, eligibleLanes);
            return;
        }

        preflightLanes = eligibleLanes & tunaSession.ConfiguredLanes;
        if (preflightLanes == NknAccelerationLaneKind.None)
        {
            ResumeActivationPauseIfNeeded("no_eligible_lane", "after_payer_priority_no_eligible_lane");
            RejectAccelerationOfferPreflight(reason, "no_eligible_lane", retryable: false, eligibleLanes);
            NotifyTransportAccelerationStateChanged("no_eligible_lane");
            return;
        }

        NotifyTransportAccelerationStateChanged("selected_payer_starting_listener");
        NotifyTransportAccelerationStateChanged("listener_starting");
        var runtimeUnlockTunaPathLease = RuntimeUnlockTunaPathLeaseSnapshot.None;
        if (isRuntimeUnlockActivation)
        {
            lock (accelerationGate)
            {
                runtimeUnlockTunaPathLease = StartRuntimeUnlockTunaPathLeaseUnsafe(
                    sessionId,
                    runtimeUnlockFileTransferOwnerAuthority?.TransferId,
                    payerDecisionId,
                    reason);
            }
        }

        if (isRuntimeUnlockActivation &&
            ShouldPauseRegularNknV4FileTransferForRuntimeUnlock(sessionId))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=filetransfer_tuna_activation_negotiation_regular_nkn_pause_deferred; session_id={SanitizeLogToken(sessionId)}; reason=runtime_unlock_listener_starting; trigger={SanitizeLogToken(reason)}");
        }

        if (!await tunaSession.EnsureListenerSidecarConnectedAsync(remoteEndpoint, ct).ConfigureAwait(false) ||
            string.IsNullOrWhiteSpace(tunaSession.LocalTunaAddress))
        {
            NotifyTransportAccelerationStateChanged("listener_sidecar_unavailable");
            if (isRuntimeUnlockActivation)
            {
                FailRuntimeUnlockTunaPathLeaseIfCurrent(
                    sessionId,
                    offerGeneration: 0,
                    "listener_sidecar_unavailable",
                    failTransaction: false);
            }

            ResumeActivationPauseIfNeeded("tuna_activation_failed_regular_v4_resumed", "listener_sidecar_unavailable");
            var listenerRetryReason = requiresContractLocalListenerRetry
                ? ResolveRuntimeUnlockListenerRearmFailedReason(sessionId)
                : "listener_sidecar_unavailable";
            if (requiresContractLocalListenerRetry)
            {
                MarkRuntimeUnlockRecoveryContractAuthorityBlocked(listenerRetryReason);
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=session_recovery_contract_listener_rearm_required; session_id={SanitizeLogToken(sessionId)}; reason={SanitizeLogToken(reason)}; can_offer_listener=0; failure_path=1");
                if (TryDeferRuntimeUnlockListenerRearmRetryForActiveRegularV4Recovery(
                        sessionId,
                        listenerRetryReason))
                {
                    return;
                }

                if (TrySettleRuntimeUnlockRetryDispatchMissingBeforeOfferIfCurrent(
                        sessionId,
                        listenerRetryReason,
                        listenerRetryReason,
                        requiresLocalListenerRetry: true,
                        expectedAuthorityId: runtimeUnlockDispatchAuthorityId))
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=session_recovery_contract_listener_rearm_failed; session_id={SanitizeLogToken(sessionId)}; reason={SanitizeLogToken(listenerRetryReason)}; trigger={SanitizeLogToken(reason)}; dispatch_successor_requested=1");
                    return;
                }

                FailRuntimeUnlockRecoveryContractIfActive(sessionId, listenerRetryReason);
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=session_recovery_contract_listener_rearm_failed; session_id={SanitizeLogToken(sessionId)}; reason={SanitizeLogToken(listenerRetryReason)}; trigger={SanitizeLogToken(reason)}");
                return;
            }

            if (!isRuntimeUnlockActivation ||
                !TrySettleRuntimeUnlockRetryDispatchMissingBeforeOfferIfCurrent(
                    sessionId,
                    listenerRetryReason,
                    listenerRetryReason,
                    requiresLocalListenerRetry: false,
                    expectedAuthorityId: runtimeUnlockDispatchAuthorityId))
            {
                ScheduleAccelerationNegotiationRetry(
                    listenerRetryReason,
                    expectedInstallReceipt);
            }
            return;
        }

        if (isRuntimeUnlockActivation)
        {
            if (!ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                    expectedInstallReceipt,
                    "listener_ready"))
            {
                return;
            }

            MarkRuntimeUnlockTunaPathLeaseListenerReady(
                runtimeUnlockTunaPathLease,
                sessionId,
                reason);
        }

        if (requiresContractLocalListenerRetry)
        {
            MarkRuntimeUnlockRecoveryContractListenerRearmCompleted(sessionId, reason);
        }

        NotifyTransportAccelerationStateChanged("listener_ready");
        if (IsStaleLocalPayerDecision(payerDecisionId))
        {
            NotifyTransportAccelerationStateChanged("suppressed_by_peer_payer");
            ResumeActivationPauseIfNeeded("stale_payer_decision", "listener_ready_stale_payer_decision");
            try
            {
                await tunaSession.StopAsync("stale_payer_decision", ct).ConfigureAwait(false);
            }
            catch (Exception ex) when (ex is not OperationCanceledException)
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_stop_failed; reason=stale_payer_decision; error={ex.GetType().Name}");
            }

            return;
        }

        if (IsAccelerationUserStoppedForCurrentSession())
        {
            NotifyTransportAccelerationStateChanged("user_stopped_tuna");
            ResumeActivationPauseIfNeeded("user_stopped_tuna", "listener_ready_user_stopped");
            try
            {
                await tunaSession.StopAsync("user_stopped_tuna", ct).ConfigureAwait(false);
            }
            catch (Exception ex) when (ex is not OperationCanceledException)
            {
                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_stop_failed; reason=user_stopped_tuna; error={ex.GetType().Name}");
            }

            return;
        }

        var offeredLanes = eligibleLanes & tunaSession.SupportedLanes;
        if (offeredLanes == NknAccelerationLaneKind.None)
        {
            NotifyTransportAccelerationStateChanged("no_supported_lane");
            ResumeActivationPauseIfNeeded("tuna_activation_failed_regular_v4_resumed", "no_supported_lane");
            if (!isRuntimeUnlockActivation ||
                !TrySettleRuntimeUnlockRetryDispatchMissingBeforeOfferIfCurrent(
                    sessionId,
                    "runtime_unlock_listener_no_supported_lane",
                    "runtime_unlock_listener_sidecar_unavailable",
                    requiresContractLocalListenerRetry,
                    runtimeUnlockDispatchAuthorityId))
            {
                ScheduleAccelerationNegotiationRetry(
                    "listener_sidecar_unavailable",
                    expectedInstallReceipt);
            }
            return;
        }

        if (isRuntimeUnlockActivation &&
            runtimeUnlockFileTransferOwnerAuthority is not null)
        {
            if (!TryCaptureCurrentRuntimeUnlockFileTransferOwnerAuthority(
                    sessionId,
                    out var currentOwnerAuthority,
                    out var currentOwnerRejectionReason) ||
                !Equals(currentOwnerAuthority, runtimeUnlockFileTransferOwnerAuthority))
            {
                var rejectionReason = string.Equals(currentOwnerRejectionReason, "accepted", StringComparison.Ordinal)
                    ? "current_filetransfer_owner_changed_after_listener_start"
                    : currentOwnerRejectionReason;
                LogRuntimeUnlockFileTransferOwnerRejectedBeforeOfferDispatch(
                    sessionId,
                    runtimeUnlockFileTransferOwnerAuthority.TransferId,
                    reason,
                    rejectionReason);
                FailRuntimeUnlockTunaPathLeaseIfCurrent(
                    sessionId,
                    offerGeneration: 0,
                    rejectionReason,
                    failTransaction: false);
                RejectRuntimeUnlockRecoveryRetryBeforeDispatchIfActive(
                    sessionId,
                    rejectionReason);
                ResumeActivationPauseIfNeeded(
                    "tuna_activation_failed_regular_v4_resumed",
                    rejectionReason);
                return;
            }
        }

        RuntimeUnlockRecoveryRetryState? grantedRetryDispatchState = null;
        var hasCurrentGrantedRetryDispatchContract = isRuntimeUnlockActivation &&
            TryGetCurrentGrantedRuntimeUnlockRetryDispatchContract(
                sessionId,
                out grantedRetryDispatchState,
                out _);
        if (!hasCurrentGrantedRetryDispatchContract)
        {
            if (isRuntimeUnlockActivation &&
                TryDeferRuntimeUnlockOfferDispatchForRegularV4ReceiveRecovery(
                    sessionId,
                    reason,
                    payerDecisionId,
                    out _,
                    out _))
            {
                ResumeActivationPauseIfNeeded(
                    "tuna_activation_failed_regular_v4_resumed",
                    "regular_v4_receive_recovery_pending");
                return;
            }

            if (isRuntimeUnlockActivation &&
                TryDeferRuntimeUnlockOfferDispatchForRegularV4FrontierRepair(
                    sessionId,
                    reason,
                    payerDecisionId,
                    out _,
                    out _))
            {
                ResumeActivationPauseIfNeeded(
                    "tuna_activation_failed_regular_v4_resumed",
                    "regular_v4_frontier_repair_pending");
                return;
            }
        }
        else
        {
            LogRuntimeUnlockRetryDispatchProof(
                "runtime_unlock_retry_dispatch_evidence_ignored_after_authority_granted",
                grantedRetryDispatchState!,
                "coordinator_dispatch_authority_current");
        }

        if (isRuntimeUnlockActivation)
        {
            if (!ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                    expectedInstallReceipt,
                    "offer_creation"))
            {
                return;
            }

            var dispatchAuthorityResult = TryGrantRuntimeUnlockRecoveryRetryDispatchAuthorityForOfferSend(reason, sessionId);
            if (dispatchAuthorityResult == RuntimeUnlockRetryDispatchAuthorityResult.Held)
            {
                ResumeActivationPauseIfNeeded(
                    "tuna_activation_failed_regular_v4_resumed",
                    "runtime_unlock_retry_dispatch_authority_held");
                return;
            }

            if (dispatchAuthorityResult == RuntimeUnlockRetryDispatchAuthorityResult.Rejected)
            {
                ResumeActivationPauseIfNeeded("tuna_activation_failed_regular_v4_resumed", "runtime_unlock_retry_dispatch_authority_rejected");
                return;
            }
        }

        var nonce = Convert.ToHexString(RandomNumberGenerator.GetBytes(16)).ToLowerInvariant();
        var sentAtUnixMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        var offer = new TransportAccelerationOfferPayload
        {
            SessionId = sessionId,
            SenderRole = localRole,
            TunaAddress = tunaSession.LocalTunaAddress,
            SupportedLanes = NknAccelerationLaneCodec.ToNames(offeredLanes),
            Trigger = SanitizeLogToken(reason),
            PayerDecisionId = payerDecisionId,
            SentAtUnixMs = sentAtUnixMs,
            ExpiresAtUnixMs = sentAtUnixMs + (long)AccelerationOfferLifetime.TotalMilliseconds,
            Nonce = nonce,
            SidecarProtocolVersion = TunaSidecarProtocolVersion,
        };
        var payload = CreateSecureControlPayload(
            MsgType.TransportAccelerationOffer,
            nonce,
            JsonSerializer.SerializeToUtf8Bytes(offer));
        var envelope = CreateEnvelope(envelopeCode, MsgType.TransportAccelerationOffer, payload, replyTo: null);
        long offerGeneration;
        RuntimeUnlockRecoveryRetryState? runtimeUnlockAuthorityGrantedSnapshot = null;
        RuntimeUnlockRecoveryRetryState? runtimeUnlockAuthorityOfferWindowSnapshot = null;
        RuntimeUnlockTransactionDecision? runtimeUnlockTransactionStarted = null;
        RuntimeUnlockRecoveryRetryState? runtimeUnlockAliasRejectedState = null;
        RuntimeUnlockRecoveryRetryState? terminalRecoveryStateToClear = null;
        var terminalRecoveryStateHadDispatchContract = false;
        RuntimeUnlockRetryDispatchSettlementReport terminalRecoverySettlementReport = default;
        lock (accelerationGate)
        {
            if (isRuntimeUnlockActivation &&
                expectedInstallReceipt is { } receipt)
            {
                var currentState = runtimeUnlockRecoveryRetryState;
                var receiptRejectionReason = "retry_dispatch_install_state_missing";
                if (currentState is null ||
                    !TryValidateRuntimeUnlockRetryDispatchInstallReceiptCurrentUnsafe(
                        currentState,
                        receipt,
                        out receiptRejectionReason))
                {
                    LogRuntimeUnlockRetryDispatchInstallRejected(
                        receipt,
                        CaptureRuntimeUnlockRetryDispatchInstallTelemetryUnsafe(currentState),
                        RuntimeUnlockRetryDispatchInstallStatus.Rejected,
                        $"{receiptRejectionReason}_offer_state_commit");
                    return;
                }
            }

            outboundAccelerationOfferNonce = nonce;
            outboundAccelerationOfferTrigger = SanitizeLogToken(reason);
            outboundAccelerationOfferInstallReceipt = isRuntimeUnlockActivation
                ? expectedInstallReceipt
                : null;
            outboundAccelerationOfferPayerDecisionId = payerDecisionId;
            offerGeneration = ++outboundAccelerationOfferGeneration;
            runtimeUnlockOfferProofState = isRuntimeUnlockActivation
                ? new RuntimeUnlockOfferProofState
                {
                    Generation = offerGeneration,
                    Nonce = nonce,
                    SessionId = sessionId,
                    PayerDecisionId = payerDecisionId,
                    Trigger = SanitizeLogToken(reason),
                    CreatedUtcMs = sentAtUnixMs,
                }
                : null;
            if (isRuntimeUnlockActivation)
            {
                var retryState = runtimeUnlockRecoveryRetryState is { } candidate &&
                                 candidate.ContractState is not (
                                     SessionRecoveryContractState.Completed or
                                     SessionRecoveryContractState.Failed) &&
                                 string.Equals(candidate.SessionId, sessionId, StringComparison.Ordinal)
                    ? candidate
                    : null;
                var requiresRetryDispatchContract = retryState is not null &&
                    RequiresRuntimeUnlockRetryDispatchProof(retryState);
                if (requiresRetryDispatchContract &&
                    (retryState!.DispatchContract is not { } dispatchContract ||
                     !dispatchContract.TryBindOfferAlias(offerGeneration, nonce)))
                {
                    retryState.AuthorityFailureReason = "runtime_unlock_retry_offer_alias_rejected";
                    retryState.DispatchDecisionReason = retryState.AuthorityFailureReason;
                    runtimeUnlockAliasRejectedState = retryState;
                    ClearOutboundAccelerationOfferLocked();
                    runtimeUnlockOfferProofState = null;
                }
                else
                {
                    runtimeUnlockTransactionStarted = StartRuntimeUnlockTransactionForOfferUnsafe(
                        sessionId,
                        offerGeneration,
                        reason);
                    if (runtimeUnlockTunaPathLease.LeaseGeneration > 0)
                    {
                        runtimeUnlockTunaPathLease = BindRuntimeUnlockTunaPathLeaseToOfferUnsafe(
                            runtimeUnlockTunaPathLease,
                            runtimeUnlockTransactionStarted.State.TransactionGeneration,
                            offerGeneration,
                            payerDecisionId,
                            reason);
                        runtimeUnlockTransactionStarted = runtimeUnlockTransactionStarted with
                        {
                            State = AttachRuntimeUnlockTunaPathLeaseUnsafe(runtimeUnlockTransactionStarted.State),
                        };
                    }

                    if (retryState is { } state)
                    {
                        state.CurrentOfferGeneration = offerGeneration;
                        if (!state.RetryAuthorityGranted &&
                            state.RetryDispatched)
                        {
                            GrantRuntimeUnlockRecoveryContractRetryAuthorityUnsafe(state);
                            runtimeUnlockAuthorityGrantedSnapshot = state;
                        }

                        if (state.RetryAuthorityGranted && state.RetryAuthorityPending)
                        {
                            RefreshRuntimeUnlockRecoveryContractOfferSendWindowUnsafe(state, sentAtUnixMs);
                            runtimeUnlockAuthorityOfferWindowSnapshot = state;
                        }
                    }
                    else if (runtimeUnlockRecoveryRetryState is
                             {
                                 ContractState: SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed
                             } terminalRecoveryState)
                    {
                        terminalRecoveryStateToClear = terminalRecoveryState;
                        _ = InvalidateRuntimeUnlockRetryDispatchDecisionStageUnsafe(
                            terminalRecoveryState,
                            "retry_dispatch_install_stage_invalidated_terminal_recovery_state_cleared");
                        terminalRecoveryStateHadDispatchContract = terminalRecoveryState.DispatchContract is not null;
                        _ = SettleRuntimeUnlockRetryDispatchContractUnsafe(
                            terminalRecoveryState,
                            terminalRecoveryState.ContractState == SessionRecoveryContractState.Completed
                                ? RuntimeUnlockRetryDispatchSettlementOutcome.TransferTerminal
                                : RuntimeUnlockRetryDispatchSettlementOutcome.AuthorityRejected,
                            "terminal_recovery_state_cleared",
                            out terminalRecoverySettlementReport);
                        if (!terminalRecoveryStateHadDispatchContract)
                        {
                            ClearRuntimeUnlockRetryFallbackTailUnblockRecheckUnsafe(terminalRecoveryState);
                            ClearRuntimeUnlockRetryFallbackTailUnblockRecheckEligibilityUnsafe(terminalRecoveryState);
                            runtimeUnlockRecoveryRetryState = null;
                        }
                    }

                    ClearRuntimeUnlockQueueAcceptedObservedEscapeLocked();
                }
            }
        }

        if (!terminalRecoverySettlementReport.IsDefault)
        {
            if (PublishRuntimeUnlockRetryDispatchSettlementReport(terminalRecoverySettlementReport))
            {
                lock (accelerationGate)
                {
                    if (ReferenceEquals(runtimeUnlockRecoveryRetryState, terminalRecoveryStateToClear))
                    {
                        ClearRuntimeUnlockRetryFallbackTailUnblockRecheckUnsafe(terminalRecoveryStateToClear!);
                        ClearRuntimeUnlockRetryFallbackTailUnblockRecheckEligibilityUnsafe(terminalRecoveryStateToClear!);
                        runtimeUnlockRecoveryRetryState = null;
                    }
                }
            }
        }

        if (runtimeUnlockAliasRejectedState is not null)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=runtime_unlock_retry_offer_alias_rejected; session_id={SanitizeLogToken(runtimeUnlockAliasRejectedState.SessionId)}; transfer_id={SanitizeLogToken(runtimeUnlockAliasRejectedState.TransferId ?? "(none)")}; contract_generation={runtimeUnlockAliasRejectedState.ContractGeneration}; retired_generation={runtimeUnlockAliasRejectedState.RetiredOfferGeneration}; dispatch_attempt_generation={runtimeUnlockAliasRejectedState.DispatchAttemptGeneration}; offer_generation={offerGeneration}; decision_reason=runtime_unlock_retry_offer_alias_rejected");
            ResumeActivationPauseIfNeeded(
                "tuna_activation_failed_regular_v4_resumed",
                "runtime_unlock_retry_offer_alias_rejected");
            return;
        }

        LogRuntimeUnlockTransactionDecision(
            RuntimeUnlockTransactionEventKind.OfferGenerationCreated,
            runtimeUnlockTransactionStarted);

        if (requiresContractLocalListenerRetry)
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_offer_dispatched_after_listener_rearm; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; trigger={SanitizeLogToken(reason)}");
        }

        if (runtimeUnlockAuthorityGrantedSnapshot is not null)
        {
            LogRuntimeUnlockRecoveryContract(
                "session_recovery_contract_retry_authority_granted",
                runtimeUnlockAuthorityGrantedSnapshot.SessionId);
        }

        if (runtimeUnlockAuthorityOfferWindowSnapshot is not null)
        {
            LogRuntimeUnlockRecoveryContract(
                "session_recovery_contract_retry_authority_offer_window_refreshed",
                runtimeUnlockAuthorityOfferWindowSnapshot.SessionId);
        }

        if (!isRuntimeUnlockActivation)
        {
            PauseActivationIfNeeded("offer_send_prepare");
        }
        else if (TryGetPostTunaFallbackRuntimeUnlockAdmissionDeniedRouteHint(
                     sessionId,
                     out var runtimeUnlockFallbackDenialReason))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=runtime_unlock_fallback_unavailable_suppressed; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; trigger=post_tuna_fallback_offer_send_prepare; reason=fallback_owner_active; fallback_owner_reason={SanitizeLogToken(runtimeUnlockFallbackDenialReason)}; source=post_tuna_fallback_offer_send_prepare");
        }

        var runtimeUnlockCutThroughStarted = isRuntimeUnlockActivation &&
            TryStartRuntimeUnlockCutThroughForCurrentOffer(
                sessionId,
                offerGeneration,
                reason);
        if (runtimeUnlockCutThroughStarted)
        {
            PauseActivationIfNeeded("runtime_unlock_cutthrough_offer_send_prepare");
        }

        void PauseRegularV4ForRuntimeUnlockActivationWindowOfferSend()
        {
            if (!isRuntimeUnlockActivation ||
                pausedForActivationNegotiation)
            {
                return;
            }

            if (!ShouldPauseRegularNknV4FileTransferForRuntimeUnlockActivationWindowOfferSend(
                    sessionId,
                    offerGeneration,
                    out _))
            {
                return;
            }

            pausedForActivationNegotiation = PauseRegularNknV4FileTransferForRuntimeUnlockMakeBeforeBreak(
                sessionId,
                "runtime_unlock_regular_v4_activation_window_offer_send",
                reason);
            if (pausedForActivationNegotiation)
            {
                LocalOperationalLog.Info(
                    "NKN.Tuna",
                    $"event=runtime_unlock_regular_v4_activation_window_quiesce_started; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; trigger={SanitizeLogToken(reason)}; reason=peer_visible_offer_send");
            }
        }

        AccelerationControlSendResult offerSend;
        try
        {
            offerSend = await SendAccelerationControlEnvelopeWithBulkBypassAsync(
                    remoteEndpoint,
                    envelope,
                    "offer",
                    ct,
                    requireObservedSend: true,
                    activationSessionId: sessionId,
                    onBeforeSend: PauseRegularV4ForRuntimeUnlockActivationWindowOfferSend,
                    onQueueAccepted: () =>
                    {
                        if (!isRuntimeUnlockActivation && ShouldPauseRuntimeUnlockOfferOnQueueAccepted())
                        {
                            PauseActivationIfNeeded("offer_queue_accepted");
                        }
                    },
                    onObservedSendWaitStarted: isRuntimeUnlockActivation
                        ? null
                        : () => PauseActivationIfNeeded("offer_queue_accepted"),
                    queueAcceptedAsObservedReason: isRuntimeUnlockActivation
                        ? GetRuntimeUnlockOfferQueueAcceptedObservedReason
                        : null,
                    observedSendFallbackAsync: isRuntimeUnlockActivation
                        ? () => TrySendRuntimeUnlockOfferViaPeerVisibleControlPlaneAsObservedAsync(
                            remoteEndpoint,
                            envelope,
                            sessionId,
                            payerDecisionId,
                            nonce,
                            offerGeneration,
                            reason,
                            expectedInstallReceipt)
                        : null,
                    expectedInstallReceipt: isRuntimeUnlockActivation
                        ? expectedInstallReceipt
                        : null)
                .ConfigureAwait(false);
        }
        catch
        {
            ResumeActivationPauseIfNeeded("tuna_activation_failed_regular_v4_resumed", "offer_send_failed");
            throw;
        }

        if (isRuntimeUnlockActivation &&
            offerSend.StaleCallbackIgnored)
        {
            return;
        }

        if (isRuntimeUnlockActivation &&
            IsRuntimeUnlockOfferGenerationRetired(nonce, payerDecisionId, offerGeneration))
        {
            LocalOperationalLog.Info(
                "NKN.Tuna",
                $"event=tuna_acceleration_offer_send_result_ignored; reason=retired_generation; trigger={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; observed_lane={SanitizeLogToken(offerSend.ObservedLane)}; succeeded={(offerSend.Succeeded ? 1 : 0)}");
            return;
        }

        if (isRuntimeUnlockActivation &&
            !offerSend.Succeeded &&
            await WaitForRuntimeUnlockPeerAnswerAsObservedSendAsync(
                sessionId,
                nonce,
                payerDecisionId,
                offerGeneration,
                ct).ConfigureAwait(false))
        {
            offerSend = AccelerationControlSendResult.Success(AccelerationObservedLanePeerAnswer);
        }

        if (offerSend.Succeeded)
        {
            if (isRuntimeUnlockActivation)
            {
                if (!ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                        expectedInstallReceipt,
                        "observed_send"))
                {
                    return;
                }

                if (!MarkRuntimeUnlockRecoveryContractRetryObserved(
                        sessionId,
                        offerGeneration,
                        offerSend.ObservedLane))
                {
                    return;
                }

                MarkRuntimeUnlockOfferObservedSendIfCurrent(
                    nonce,
                    payerDecisionId,
                    offerGeneration,
                    offerSend.ObservedLane);
                ApplyRuntimeUnlockTransaction(
                    RuntimeUnlockTransactionEventKind.ObservedSend,
                    sessionId,
                    offerGeneration,
                    "offer_observed_send",
                    observedLane: offerSend.ObservedLane);
                if (runtimeUnlockCutThroughStarted)
                {
                    MarkRuntimeUnlockCutThroughOfferSent(sessionId, offerGeneration, offerSend.ObservedLane);
                }

                var pausedAfterPeerVisibleOffer = PauseRegularNknV4FileTransferForRuntimeUnlockMakeBeforeBreak(
                    sessionId,
                    "runtime_unlock_offer_observed_waiting_for_answer",
                    reason);
                if (pausedAfterPeerVisibleOffer &&
                    string.Equals(
                        offerSend.ObservedLane,
                        AccelerationObservedLaneControlPlanePeerVisible,
                        StringComparison.OrdinalIgnoreCase))
                {
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=runtime_unlock_regular_v4_activation_window_quiesce_started; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; trigger={SanitizeLogToken(reason)}; reason=peer_visible_offer_send_after_proof");
                }

                if (!string.Equals(
                        offerSend.ObservedLane,
                        AccelerationObservedLaneControlPlanePeerVisible,
                        StringComparison.OrdinalIgnoreCase))
                {
                    ScheduleRuntimeUnlockPeerVisibleOfferDeliveryConfirmation(
                        remoteEndpoint,
                        envelope,
                        sessionId,
                        payerDecisionId,
                        nonce,
                        offerGeneration,
                        reason,
                        expectedInstallReceipt);
                }
            }
        }

        if (isRuntimeUnlockActivation && offerSend.UntrustedProbeSent)
        {
            LocalOperationalLog.Warn(
                "NKN.Tuna",
                $"event=tuna_acceleration_offer_probe_sent_untrusted; reason={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(sessionId)}; lanes={string.Join(",", offer.SupportedLanes)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; observed_lane={SanitizeLogToken(offerSend.ObservedLane)}; queue_local_only=0; replay_scheduled=0; answer_timeout_scheduled=1");
            NotifyTransportAccelerationStateChanged("waiting_for_answer_untrusted_probe");
            MarkRuntimeUnlockOfferAnswerTimeoutScheduledIfCurrent(nonce, payerDecisionId, offerGeneration);
            ScheduleAccelerationOfferAnswerTimeout(nonce, expectedInstallReceipt);
            return;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=tuna_acceleration_offer_{(offerSend.Succeeded ? "queued" : "rejected")}; reason={SanitizeLogToken(reason)}; session_id={sessionId}; lanes={string.Join(",", offer.SupportedLanes)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; observed_lane={SanitizeLogToken(offerSend.ObservedLane)}; queue_local_only=0; recovery_requested={(offerSend.RecoveryRequested ? 1 : 0)}; recovery_reason={SanitizeLogToken(offerSend.RecoveryReason)}");
        if (!offerSend.Succeeded)
        {
            if (isRuntimeUnlockActivation)
            {
                var missingDispatchSettled = TrySettleRuntimeUnlockRetryDispatchMissingCore(
                    sessionId,
                    offerGeneration,
                    "peer_visible_offer_send_not_observed",
                    requestSuccessor: false);
                var promoteSendBlockToCutThrough =
                    ShouldPromoteRuntimeUnlockAuthoritySendBlockToCutThrough(sessionId);
                var retryReason = promoteSendBlockToCutThrough
                    ? RuntimeUnlockCutThroughRetryReason
                    : "runtime_unlock_offer_send_not_observed";
                var effectiveRecoveryReason = promoteSendBlockToCutThrough
                    ? RuntimeUnlockCutThroughRecoveryReason
                    : offerSend.RecoveryReason ?? "tuna_activation_offer_send_timeout";
                RuntimeUnlockRegularV4RecoveryRetryJoinIntent? retryJoinIntent = null;
                var retryJoinDuplicate = false;
                if (!missingDispatchSettled)
                {
                    _ = TryCaptureRuntimeUnlockRegularV4RecoveryRetryJoinIntent(
                        "offer",
                        sessionId,
                        "offer_send_not_observed",
                        nonce,
                        payerDecisionId,
                        offerGeneration,
                        expectedInstallReceipt,
                        retryReason,
                        effectiveRecoveryReason,
                        out retryJoinIntent,
                        out retryJoinDuplicate);
                }

                if (missingDispatchSettled)
                {
                    RequestRuntimeUnlockRetryDispatchAuthority(
                        sessionId,
                        "predecessor_missing_dispatch_offer_retired");
                    _ = TryCaptureRuntimeUnlockRegularV4RecoveryRetryJoinIntent(
                        "offer",
                        sessionId,
                        "offer_send_not_observed",
                        nonce,
                        payerDecisionId,
                        offerGeneration,
                        expectedInstallReceipt,
                        retryReason,
                        effectiveRecoveryReason,
                        out retryJoinIntent,
                        out retryJoinDuplicate);
                }

                if (!missingDispatchSettled &&
                    retryJoinIntent is null &&
                    FailRuntimeUnlockRegularV4ActivationWindowIfUnproven(
                        sessionId,
                        offerGeneration,
                        "offer_send_not_observed",
                        "runtime_unlock_regular_v4_peer_visible_window_failed"))
                {
                    return;
                }

                var retired = RetireRuntimeUnlockOfferIfCurrent(
                    nonce,
                    payerDecisionId,
                    offerGeneration,
                    sessionId,
                    "offer_send_not_observed",
                    retryReason);
                var alreadyRetiredForRecovery = !retired &&
                    IsRuntimeUnlockOfferGenerationRetired(nonce, payerDecisionId, offerGeneration);
                var deferRetryUntilRecoverySettled =
                    (retryJoinIntent is not null || offerSend.RecoveryRequested) &&
                    (retired || alreadyRetiredForRecovery);
                var waitingForDispatchSuccessor =
                    missingDispatchSettled && retryJoinIntent is null;
                if (promoteSendBlockToCutThrough)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_runtime_unlock_authority_send_blocked_promoted_to_cutthrough; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; retry_reason={SanitizeLogToken(retryReason)}; recovery_reason={SanitizeLogToken(effectiveRecoveryReason)}; source_recovery_reason={SanitizeLogToken(offerSend.RecoveryReason)}");
                }

                LocalOperationalLog.Warn(
                    "NKN.Tuna",
                    $"event=tuna_acceleration_activation_offer_not_observed; trigger={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; late_answer_window_ms={(long)AccelerationOfferAnswerTimeout.TotalMilliseconds}; retry_scheduled={(!waitingForDispatchSuccessor && !deferRetryUntilRecoverySettled ? 1 : 0)}; retry_after_recovery_armed={(!waitingForDispatchSuccessor && deferRetryUntilRecoverySettled ? 1 : 0)}; dispatch_successor_requested={(missingDispatchSettled ? 1 : 0)}; replay_scheduled=0; answer_timeout_scheduled=0; pause_deferred={(pausedForActivationNegotiation ? 0 : 1)}; recovery_requested={(offerSend.RecoveryRequested || retryJoinIntent is not null ? 1 : 0)}; recovery_reason={SanitizeLogToken(retryJoinIntent?.RecoveryReason ?? effectiveRecoveryReason)}");
                NotifyTransportAccelerationStateChanged("activation_offer_not_observed");
                if (pausedForActivationNegotiation)
                {
                    ResumeActivationPauseIfNeeded(
                        "tuna_activation_failed_regular_v4_resumed",
                        "offer_send_not_observed");
                }

                if (retryJoinIntent is not null)
                {
                    LocalOperationalLog.Warn(
                        "NKN.Tuna",
                        $"event=tuna_activation_control_send_recovery_joined_existing; session_id={SanitizeLogToken(retryJoinIntent.OfferSessionId)}; purpose=offer; trigger=offer_send_not_observed; reason={SanitizeLogToken(retryJoinIntent.RecoveryReason)}; existing_recovery=1; join_reason=regular_v4_recovery_lease_closure_awaiting_local_proof; join_generation={retryJoinIntent.JoinGeneration}; disposition={(retryJoinDuplicate ? "Idempotent" : "Accepted")}");
                    ArmRuntimeUnlockRetryAfterRegularV4RecoveryClosureJoin(
                        retryJoinIntent,
                        requiresLocalListenerRetry: !promoteSendBlockToCutThrough ||
                                                    !ShouldUseListenerReadyFastRetry(RuntimeUnlockCutThroughRetryReason));
                }
                else if (missingDispatchSettled)
                {
                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_activation_offer_retry_waiting_for_dispatch_successor; trigger={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; predecessor_settlement_outcome=MissingDispatch; retry_scheduled=0; decision_reason=coordinator_successor_required");
                }
                else if (deferRetryUntilRecoverySettled)
                {
                    if (retired || (promoteSendBlockToCutThrough && alreadyRetiredForRecovery))
                    {
                        ArmRuntimeUnlockRetryAfterRecovery(
                            offerGeneration,
                            offerSend.RecoverySessionId ?? sessionId,
                            retryReason,
                            effectiveRecoveryReason,
                            requiresLocalListenerRetry: !promoteSendBlockToCutThrough ||
                                                        !ShouldUseListenerReadyFastRetry(RuntimeUnlockCutThroughRetryReason));
                    }
                    else
                    {
                        LocalOperationalLog.Info(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_activation_offer_recovery_joined_retired_generation; trigger={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; recovery_reason={SanitizeLogToken(effectiveRecoveryReason)}");
                    }
                }
                else
                {
                var retryScheduled = ScheduleAccelerationNegotiationRetry(
                    retryReason,
                    expectedInstallReceipt);
                    if (!retryScheduled)
                    {
                        LocalOperationalLog.Warn(
                            "NKN.Tuna",
                            $"event=tuna_acceleration_activation_offer_retry_not_scheduled; trigger={SanitizeLogToken(reason)}; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={offerGeneration}; retry_reason={SanitizeLogToken(retryReason)}");
                    }
                }
            }
            else
            {
                ClearOutboundAccelerationOfferIfCurrent(nonce, payerDecisionId, offerGeneration, "offer_send_not_observed");
                NotifyTransportAccelerationStateChanged("offer_queue_rejected");
                ResumeActivationPauseIfNeeded("offer_queue_rejected", "offer_queue_rejected");
                ScheduleAccelerationNegotiationRetry(
                    "offer_queue_rejected",
                    expectedInstallReceipt);
            }

            return;
        }

        if (!isRuntimeUnlockActivation)
        {
            PauseActivationIfNeeded("offer_sent");
        }

        NotifyTransportAccelerationStateChanged("waiting_for_answer");
        ScheduleAccelerationOfferReplay(
            remoteEndpoint,
            envelope,
            sessionId,
            nonce,
            payerDecisionId,
            offerGeneration,
            pauseOnQueueAccepted: !isRuntimeUnlockActivation,
            pauseAfterObservedSendOnly: false,
            expectedInstallReceipt: isRuntimeUnlockActivation ? expectedInstallReceipt : null);
        MarkRuntimeUnlockOfferAnswerTimeoutScheduledIfCurrent(nonce, payerDecisionId, offerGeneration);
        ScheduleAccelerationOfferAnswerTimeout(
            nonce,
            isRuntimeUnlockActivation ? expectedInstallReceipt : null);
        ScheduleRuntimeUnlockOfferPeerResponseTimeout(
            nonce,
            payerDecisionId,
            offerGeneration,
            sessionId,
            offerSend.ObservedLane,
            expectedInstallReceipt);
    }

    private void ScheduleAccelerationOfferReplay(
        string target,
        Envelope envelope,
        string sessionId,
        string nonce,
        long payerDecisionId,
        long generation,
        bool pauseOnQueueAccepted,
        bool pauseAfterObservedSendOnly,
        RuntimeUnlockRetryDispatchInstallReceipt? expectedInstallReceipt = null)
    {
        _ = Task.Run(
            async () =>
            {
                var delay = AccelerationOfferReplayDelayOverrideForTests ?? AccelerationOfferReplayDelay;
                var observedReplaySent = false;
                for (var attempt = 1; attempt <= AccelerationOfferReplayAttempts; attempt++)
                {
                    await Task.Delay(delay, CancellationToken.None).ConfigureAwait(false);
                    if (!ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                            expectedInstallReceipt,
                            "offer_replay_delay",
                            allowDispatchObservedSettlement: true))
                    {
                        return;
                    }

                    if (!IsOutboundAccelerationOfferPending(nonce, payerDecisionId, generation))
                    {
                        return;
                    }

                    var pausedForReplayAttempt = false;
                    void PauseReplayAttempt(string trigger)
                    {
                        pausedForReplayAttempt = PauseFileTransferDataSessionsForTunaActivationNegotiation(
                            "activation_negotiation_pending",
                            sessionId,
                            trigger);
                    }

                    var queued = await SendAccelerationControlEnvelopeWithBulkBypassAsync(
                            target,
                            envelope,
                            "offer_replay",
                        CancellationToken.None,
                        requireObservedSend: true,
                        activationSessionId: sessionId,
                        onQueueAccepted: () =>
                        {
                            if (pauseOnQueueAccepted && ShouldPauseRuntimeUnlockOfferOnQueueAccepted())
                            {
                                PauseReplayAttempt("offer_replay_queue_accepted");
                            }
                        },
                        onObservedSendWaitStarted: pauseAfterObservedSendOnly
                            ? () => PauseReplayAttempt("offer_replay_send_observed")
                            : null,
                        queueAcceptedAsObservedReason: GetRuntimeUnlockOfferQueueAcceptedObservedReason,
                        expectedInstallReceipt: expectedInstallReceipt,
                        allowDispatchObservedInstallReceipt: true)
                        .ConfigureAwait(false);
                    if (!ValidateRuntimeUnlockRetryDispatchInstallReceiptBoundary(
                            expectedInstallReceipt,
                            "offer_replay_completion",
                            allowDispatchObservedSettlement: true))
                    {
                        return;
                    }
                    if (queued.Succeeded)
                    {
                        MarkRuntimeUnlockOfferObservedSendIfCurrent(nonce, payerDecisionId, generation, queued.ObservedLane);
                    }

                    if (pauseAfterObservedSendOnly && queued.Succeeded)
                    {
                        observedReplaySent = true;
                        PauseReplayAttempt("offer_replay_sent");
                    }
                    else if (!queued.Succeeded && (pausedForReplayAttempt || (pauseAfterObservedSendOnly && !observedReplaySent)))
                    {
                        ResumeFileTransferDataSessionsAfterTunaActivationFailure(
                            "offer_replay_not_observed",
                            sessionId,
                            "offer_replay_not_observed");
                    }

                    LocalOperationalLog.Info(
                        "NKN.Tuna",
                        $"event=tuna_acceleration_offer_replay_{(queued.Succeeded ? "sent" : "rejected")}; attempt={attempt}; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; generation={generation}; observed_lane={SanitizeLogToken(queued.ObservedLane)}");
                }
            },
            CancellationToken.None);
    }

    private bool IsOutboundAccelerationOfferPending(string nonce, long payerDecisionId, long generation)
    {
        lock (accelerationGate)
        {
            return outboundAccelerationOfferGeneration == generation &&
                   outboundAccelerationOfferPayerDecisionId == payerDecisionId &&
                   string.Equals(outboundAccelerationOfferNonce, nonce, StringComparison.Ordinal);
        }
    }

    private bool TrySupersedeStaleActiveNegotiationForRuntimeUnlockRecoveryContract(string reason)
    {
        if (!IsRuntimeUnlockActivationReason(reason))
        {
            return false;
        }

        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.RetryObserved ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                !state.RetryQueued ||
                !state.QueuedBehindActiveNegotiation)
            {
                return false;
            }

            var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            var staleWindow = RuntimeUnlockRecoveryContractStaleNegotiationWindowOverrideForTests ??
                RuntimeUnlockRecoveryContractStaleNegotiationWindow;
            if (nowMs - state.CreatedUtcMs < (long)staleWindow.TotalMilliseconds)
            {
                return false;
            }

            if (!string.IsNullOrWhiteSpace(outboundAccelerationOfferNonce) ||
                !string.IsNullOrWhiteSpace(pendingAccelerationAnswerAckNonce))
            {
                return false;
            }

            if (runtimeUnlockOfferProofState is { Retired: false, ObservedSend: true })
            {
                return false;
            }

            state.ContractState = SessionRecoveryContractState.RetryDispatching;
            state.RetryDispatching = true;
            stateSnapshot = state;
        }

        ClearPendingRuntimeUnlockAccelerationNegotiation();
        Interlocked.Exchange(ref accelerationNegotiationScheduled, 0);
        LogRuntimeUnlockRecoveryContract(
            "session_recovery_contract_stale_negotiation_superseded",
            stateSnapshot!.SessionId);
        return true;
    }

    private void MarkRuntimeUnlockRecoveryContractQueuedBehindActiveNegotiation(string reason)
    {
        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.RetryObserved ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                !RequiresRuntimeUnlockRetryDispatchAuthority(state.RetryReason))
            {
                return;
            }

            state.QueuedBehindActiveNegotiation = true;
            state.RetryQueued = false;
            state.RetryDispatching = false;
            state.RetryDispatched = false;
            state.RetryAuthorityPending = state.DispatchContract is not null;
            state.RetryAuthorityGranted = state.DispatchContract is not null;
            state.ObservedSendPending = false;
            state.DispatchObserved = false;
            state.DispatchDecisionReason = "active_negotiation_pending";
            state.ContractState = state.Settled
                ? SessionRecoveryContractState.RecoverySettled
                : state.ContractState;
            stateSnapshot = state;
        }

        LogRuntimeUnlockRetryDispatchProof(
            "runtime_unlock_retry_dispatch_held_by_active_negotiation",
            stateSnapshot!,
            "active_negotiation_pending");
    }

    private void GrantRuntimeUnlockRecoveryContractRetryAuthorityUnsafe(RuntimeUnlockRecoveryRetryState state)
    {
        var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
        RefreshRuntimeUnlockRecoveryContractOfferSendWindowUnsafe(state, nowMs);
        state.AuthorityAttempt++;
    }

