    private static bool PrepareRuntimeUnlockRetryMissingDispatchSuccessorUnsafe(
        RuntimeUnlockRecoveryRetryState state,
        RuntimeUnlockRetryDispatchContract predecessor,
        long retiredOfferGeneration,
        string retryReason,
        string recoveryReason,
        bool requiresLocalListenerRetry,
        out RuntimeUnlockRetrySuccessorIntent intent,
        out bool created)
    {
        intent = null!;
        created = false;
        if (!ReferenceEquals(state.DispatchContract, predecessor) ||
            predecessor.Lifecycle.SettlementOutcome !=
                RuntimeUnlockRetryDispatchSettlementOutcome.MissingDispatch)
        {
            return false;
        }

        var failedOfferGeneration = Math.Max(
            0,
            retiredOfferGeneration > 0
                ? retiredOfferGeneration
                : predecessor.OfferGeneration > 0
                    ? predecessor.OfferGeneration
                    : predecessor.Authority.RetiredOfferGeneration);
        if (state.PendingDispatchSuccessorIntent is { } existingIntent &&
            !existingIntent.RequestActivePredecessorSupersession &&
            existingIntent.PredecessorAuthorityId == predecessor.Authority.AuthorityId &&
            existingIntent.DispatchAttemptGeneration ==
                predecessor.Authority.DispatchAttemptGeneration + 1 &&
            existingIntent.MissingDispatchSuccessorGeneration ==
                predecessor.Authority.MissingDispatchSuccessorGeneration + 1)
        {
            intent = existingIntent;
        }
        else
        {
            intent = new RuntimeUnlockRetrySuccessorIntent(
                failedOfferGeneration,
                predecessor.Authority.DispatchAttemptGeneration + 1,
                predecessor.Authority.MissingDispatchSuccessorGeneration + 1,
                predecessor.Authority.SessionId,
                SanitizeLogToken(retryReason),
                SanitizeLogToken(recoveryReason),
                requiresLocalListenerRetry,
                predecessor.Authority.AuthorityId,
                RequestActivePredecessorSupersession: false);
            state.PendingDispatchSuccessorIntent = intent;
            state.PendingDispatchAuthorityRequest = null;
            state.PendingDispatchSuccessorRequestIssued = false;
            state.PendingDispatchSuccessorRequestHeld = false;
            state.PendingDispatchSuccessorHeldLogged = false;
            created = true;
        }

        state.DispatchPredecessorContract = predecessor;
        state.DispatchAuthorityGranted = false;
        state.DispatchAuthorityRejected = false;
        state.DispatchObserved = false;
        state.DispatchDecisionReason = SanitizeLogToken(recoveryReason);
        state.RetryQueued = false;
        state.RetryDispatching = false;
        state.RetryDispatched = false;
        state.RetryAuthorityPending = true;
        state.RetryAuthorityGranted = false;
        state.ObservedSendPending = false;
        state.ObservedSendDeadlineUtcMs = 0;
        state.DispatchDeadlineUtcMs = 0;
        state.AuthorizedObservedLane = null;
        state.AuthorityFailureReason = SanitizeLogToken(recoveryReason);
        state.ContractState = SessionRecoveryContractState.RecoverySettled;
        return true;
    }

    private static bool RequiresRuntimeUnlockRetryDispatchProof(RuntimeUnlockRecoveryRetryState state)
        => state.DispatchAuthorityGranted ||
           state.DispatchAuthorityRejected ||
           (RequiresRuntimeUnlockRetryDispatchAuthority(state.RetryReason) &&
            (state.Settled ||
             state.RetryQueued ||
             state.RetryDispatching ||
             state.RetryDispatched ||
             state.ObservedSendPending));

    private static bool RequiresRuntimeUnlockRetryDispatchProofBeforeCompletion(RuntimeUnlockRecoveryRetryState state)
        => state.DispatchAuthorityGranted ||
           state.DispatchAuthorityRejected ||
           (RequiresRuntimeUnlockRetryDispatchAuthority(state.RetryReason) &&
            (state.RetryQueued ||
             state.RetryDispatching ||
             state.RetryDispatched ||
             state.ObservedSendPending));

    private static bool ShouldDeferRuntimeUnlockRetryCompletionUntilListenerRearm(
        RuntimeUnlockRecoveryRetryState state,
        out string decisionReason)
    {
        decisionReason = string.Empty;
        if (state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed)
        {
            return false;
        }

        if (state.RequiresLocalListenerRetry &&
            !state.ListenerRearmCompleted)
        {
            decisionReason = "listener_rearm_required_before_dispatch_completion";
            return true;
        }

        if (state.CutThroughPending &&
            !state.CutThroughActive &&
            !state.CutThroughCompleted &&
            !state.DispatchObserved)
        {
            decisionReason = "cutthrough_pending_before_dispatch_completion";
            return true;
        }

        return false;
    }

    private static bool RequiresRuntimeUnlockRetryDispatchAuthority(string? reason)
        => IsRuntimeUnlockActivationRetryReason(reason) ||
           string.Equals(
               SanitizeLogToken(reason),
               "runtime_unlock_offer_send_not_observed",
               StringComparison.Ordinal);

    private static bool IsPostTunaFallbackRuntimeUnlockRecoveryReason(string? reason)
    {
        var normalized = SanitizeLogToken(reason);
        return normalized.StartsWith("post_tuna_fallback", StringComparison.OrdinalIgnoreCase) ||
               normalized.Contains("fallback", StringComparison.OrdinalIgnoreCase);
    }

    private static bool IsRuntimeUnlockListenerOrSidecarRetryReason(string? reason)
        => SanitizeLogToken(reason) is
            "runtime_unlock_listener_sidecar_unavailable" or
            "runtime_unlock_sidecar_unavailable" or
            "runtime_unlock_sidecar_remote_closed" or
            "runtime_unlock_remote_sidecar_remote_closed" or
            RuntimeUnlockProbeSidecarClosedRetryReason;

    private static bool AllowsPostTunaFallbackRuntimeUnlockDispatch(RuntimeUnlockRecoveryRetryState state)
        => IsPostTunaFallbackRuntimeUnlockRecoveryReason(state.RecoveryReason) ||
           IsPostTunaFallbackRuntimeUnlockRecoveryReason(state.AuthorityFailureReason) ||
           IsRuntimeUnlockListenerOrSidecarRetryReason(state.RetryReason);

    private static int GetRuntimeUnlockRetryExpectedDispatchLiveRouteEpoch(RuntimeUnlockRecoveryRetryState state)
        => state.DispatchAuthorityGranted || state.DispatchAuthorityRejected
            ? state.DispatchLiveRouteEpoch
            : state.RegularV4RecoveryLiveRouteEpoch;

    private static FileTransferDirection GetRuntimeUnlockRetryExpectedDispatchDirection(RuntimeUnlockRecoveryRetryState state)
        => state.PendingDispatchAuthorityRequest?.Direction ??
           state.RegularV4RecoveryDirection ??
           FileTransferDirection.Outbound;

    private static bool IsRegularV4RecoveryLivenessSnapshotCurrentForRetryDispatch(
        FileTransferRegularV4RecoveryLivenessSnapshot snapshot,
        string? sessionId,
        string? transferId,
        FileTransferDirection expectedDirection,
        int expectedLiveRouteEpoch)
    {
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        var normalizedSessionId = SanitizeLogToken(sessionId);
        if (!string.Equals(snapshot.SessionId, normalizedSessionId, StringComparison.Ordinal) ||
            snapshot.Direction != expectedDirection)
        {
            return false;
        }

        if (snapshot.Completed ||
            snapshot.RecoveryExhausted)
        {
            return false;
        }

        if (!string.IsNullOrWhiteSpace(transferId) &&
            !string.Equals(snapshot.TransferId, SanitizeLogToken(transferId), StringComparison.Ordinal))
        {
            return false;
        }

        if (!string.Equals(snapshot.RouteToken, FileTransferRouteResolver.RegularNknV4FastToken, StringComparison.Ordinal) ||
            snapshot.ProtocolVersion != FileTransferProtocol.ProtocolVersionV4 ||
            snapshot.Generation <= 0)
        {
            return false;
        }

        return expectedLiveRouteEpoch <= 0 ||
               snapshot.LiveRouteEpoch == expectedLiveRouteEpoch;
    }

    private static bool IsRuntimeUnlockRetryDispatchAuthorityCaptureCurrent(
        RuntimeUnlockRecoveryRetryState state,
        long contractGeneration,
        long retiredOfferGeneration,
        string? sessionId,
        string? transferId,
        int expectedLiveRouteEpoch)
        => contractGeneration > 0 &&
           state.ContractGeneration == contractGeneration &&
           state.RetiredOfferGeneration == retiredOfferGeneration &&
           string.Equals(state.SessionId, sessionId, StringComparison.Ordinal) &&
           string.Equals(state.TransferId ?? string.Empty, transferId ?? string.Empty, StringComparison.Ordinal) &&
           GetRuntimeUnlockRetryExpectedDispatchLiveRouteEpoch(state) == expectedLiveRouteEpoch;

    private bool RejectRuntimeUnlockRetryDispatchAuthorityForCurrentContract(
        string? sessionId,
        string decisionReason)
    {
        RuntimeUnlockRecoveryRetryState? rejectedState = null;
        RuntimeUnlockRetryDispatchSettlementReport settlementReport = default;
        var rejectedHadDispatchContract = false;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.RetryObserved ||
                state.DispatchObserved ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                (!string.IsNullOrWhiteSpace(normalizedSessionId) &&
                 !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal)) ||
                !RequiresRuntimeUnlockRetryDispatchProof(state) ||
                (!state.Settled && !state.RetryQueued && !state.RetryDispatched && !state.RetryAuthorityGranted))
            {
                return false;
            }

            rejectedHadDispatchContract = state.DispatchContract is not null;
            _ = MarkRuntimeUnlockRetryDispatchAuthorityRejectedUnsafe(
                state,
                SanitizeLogToken(decisionReason),
                out settlementReport);
            rejectedState = state;
        }

        if (rejectedState is null ||
            !ConfirmRuntimeUnlockRetryDispatchRejection(
                rejectedState,
                rejectedHadDispatchContract,
                settlementReport))
        {
            return false;
        }

        LogRuntimeUnlockRetryDispatchProof(
            "runtime_unlock_retry_dispatch_authority_rejected",
            rejectedState!,
            rejectedState.DispatchDecisionReason ?? decisionReason);
        LogRuntimeUnlockRecoveryContract("session_recovery_contract_failed", rejectedState!.SessionId);
        return true;
    }

    private bool RejectRuntimeUnlockRecoveryRetryBeforeDispatchIfActive(
        string? sessionId,
        string decisionReason)
    {
        if (RejectRuntimeUnlockRetryDispatchAuthorityForCurrentContract(sessionId, decisionReason))
        {
            return true;
        }

        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        RuntimeUnlockRetryDispatchSettlementReport settlementReport = default;
        var normalizedSessionId = string.IsNullOrWhiteSpace(sessionId) ? string.Empty : sessionId.Trim();
        var normalizedReason = SanitizeLogToken(decisionReason);
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.RetryObserved ||
                state.RetryDispatched ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                (!string.IsNullOrWhiteSpace(normalizedSessionId) &&
                 !string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal)) ||
                !IsRuntimeUnlockActivationRetryReason(state.RetryReason) ||
                !IsSessionRecoveryContractRetryRequired(state))
            {
                return false;
            }

            stateSnapshot = state;
            if (state.DispatchContract is not null)
            {
                if (!SettleRuntimeUnlockRetryDispatchContractUnsafe(
                        state,
                        RuntimeUnlockRetryDispatchSettlementOutcome.TerminalRejected,
                        normalizedReason,
                        out settlementReport))
                {
                    return false;
                }
            }
            else
            {
                state.RetryQueued = false;
                state.RetryDispatching = false;
                state.RetryAuthorityPending = false;
                state.RetryAuthorityGranted = false;
                state.ObservedSendPending = false;
                state.AuthorityFailureReason = normalizedReason;
                state.RegularV4RecoveryRetryJoinIntent = null;
                ClearRuntimeUnlockRetryFallbackTailUnblockRecheckUnsafe(state);
                ClearRuntimeUnlockRetryFallbackTailUnblockRecheckEligibilityUnsafe(state);
                state.ContractState = SessionRecoveryContractState.Failed;
            }
        }

        if (!settlementReport.IsDefault &&
            !PublishRuntimeUnlockRetryDispatchSettlementReport(settlementReport))
        {
            return false;
        }

        LogRuntimeUnlockRecoveryContract("session_recovery_contract_failed", stateSnapshot!.SessionId);
        return true;
    }

    private void RefreshRuntimeUnlockRecoveryContractOfferSendWindowUnsafe(
        RuntimeUnlockRecoveryRetryState state,
        long nowMs)
    {
        var deadline = RuntimeUnlockRetryAuthorityDeadlineOverrideForTests ?? RuntimeUnlockRetryAuthorityDeadline;
        state.RetryAuthorityPending = true;
        state.RetryAuthorityGranted = true;
        state.ObservedSendPending = false;
        state.ObservedSendDeadlineUtcMs = nowMs + (long)deadline.TotalMilliseconds;
        state.RetryDeadlineUtcMs = Math.Max(
            state.RetryDeadlineUtcMs,
            nowMs + (long)RuntimeUnlockRecoveryContractRetryDeadline.TotalMilliseconds);
        state.LivenessDeferralDeadlineUtcMs = Math.Max(
            state.LivenessDeferralDeadlineUtcMs,
            nowMs + (long)RuntimeUnlockRecoveryContractLivenessDeferral.TotalMilliseconds);
        state.AuthorizedObservedLane = null;
        if (!string.Equals(state.AuthorityFailureReason, RuntimeUnlockPostTunaFallbackFinalProbeReason, StringComparison.Ordinal) &&
            !string.Equals(state.AuthorityFailureReason, RuntimeUnlockRegularV4AuthorityProbeReason, StringComparison.Ordinal))
        {
            state.AuthorityFailureReason = null;
        }
    }

    private bool IsRuntimeUnlockRetryAuthorityActiveUnsafe(RuntimeUnlockRecoveryRetryState state, long nowMs)
        => state.RetryAuthorityGranted &&
           state.RetryAuthorityPending &&
           state.DispatchContract is { Lifecycle.IsSettled: false } &&
           state.ContractState is not (SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed) &&
           !ShouldExpireRuntimeUnlockRetryAuthorityUnsafe(state, nowMs);

    private static bool HasRuntimeUnlockRetryDispatchWindow(RuntimeUnlockRecoveryRetryState? state)
        => state is { RetryAuthorityGranted: true, RetryAuthorityPending: true } &&
           state.DispatchContract is { } contract &&
           (!contract.Lifecycle.IsSettled ||
            (contract.Lifecycle.SettlementOutcome == RuntimeUnlockRetryDispatchSettlementOutcome.DispatchObserved &&
             state.ObservedSendPending)) &&
           (state.RetryDispatching || state.RetryDispatched);

    private static bool ShouldExpireRuntimeUnlockRetryAuthorityUnsafe(
        RuntimeUnlockRecoveryRetryState state,
        long nowMs)
    {
        if (!state.RetryAuthorityGranted ||
            !state.RetryAuthorityPending ||
            state.ObservedSendDeadlineUtcMs <= 0 ||
            nowMs <= state.ObservedSendDeadlineUtcMs)
        {
            return false;
        }

        if (state.ObservedSendPending &&
            nowMs <= state.ObservedSendDeadlineUtcMs + (long)RuntimeUnlockRetryAuthorityInFlightSendGrace.TotalMilliseconds)
        {
            return false;
        }

        if (state.CutThroughPending &&
            !state.CutThroughActive &&
            !state.ObservedSendPending &&
            state.CurrentOfferGeneration <= state.RetiredOfferGeneration)
        {
            return false;
        }

        if ((state.RequiresLocalListenerRetry || state.CutThroughPending) &&
            !state.ListenerRearmCompleted &&
            !state.CutThroughActive &&
            !state.ObservedSendPending)
        {
            return false;
        }

        return !(state.RequiresLocalListenerRetry || state.CutThroughPending) ||
               state.ListenerRearmCompleted ||
               state.ObservedSendPending ||
               state.CurrentOfferGeneration > state.RetiredOfferGeneration;
    }

    private bool RequiresLocalListenerRetryForRuntimeUnlockRecoveryContract(string? sessionId, string reason)
    {
        if (!IsRuntimeUnlockActivationReason(reason) ||
            string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            return state is not null &&
                   state.RequiresLocalListenerRetry &&
                   !state.ListenerRearmCompleted &&
                   state.DispatchContract is { Lifecycle.IsSettled: false } &&
                   (IsSessionRecoveryContractRetryRequired(state) ||
                    state.ContractState == SessionRecoveryContractState.RetryDispatched ||
                    state.RetryAuthorityPending) &&
                   state.ContractState is not (SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed) &&
                   string.Equals(state.SessionId, sessionId.Trim(), StringComparison.Ordinal);
        }
    }

    private bool HasRuntimeUnlockRecoveryContractPendingCutThrough(string? sessionId)
    {
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            return state is not null &&
                   state.CutThroughPending &&
                   !state.CutThroughActive &&
                   !state.RetryObserved &&
                   state.DispatchContract is { Lifecycle.IsSettled: false } &&
                   state.ContractState is not (SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed) &&
                   string.Equals(state.SessionId, sessionId.Trim(), StringComparison.Ordinal);
        }
    }

    private bool ShouldPauseRegularNknV4FileTransferBeforeRuntimeUnlockPayerIntent(
        string? sessionId,
        string reason)
    {
        if (string.IsNullOrWhiteSpace(sessionId) ||
            !IsRuntimeUnlockActivationReason(reason) ||
            !ShouldPauseRegularNknV4FileTransferForRuntimeUnlock(sessionId))
        {
            return false;
        }

        var normalizedSessionId = sessionId.Trim();
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            return state is not null &&
                   state.ContractState is not (SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed) &&
                   !state.RetryObserved &&
                   !state.BlockedByRegularV4ReceiveRecovery &&
                   string.Equals(
                       state.RegularV4FrontierRepairTrigger,
                       "regular_v4_frontier_repair_settlement",
                       StringComparison.Ordinal) &&
                   IsRuntimeUnlockActivationRetryReason(state.RetryReason) &&
                   string.Equals(state.SessionId, normalizedSessionId, StringComparison.Ordinal) &&
                   (state.Settled ||
                    state.RetryQueued ||
                    state.RetryAuthorityGranted ||
                    state.DispatchAuthorityGranted);
        }
    }

    private bool TryGetRuntimeUnlockRetryAuthorityForCurrentOffer(
        out RuntimeUnlockRecoveryRetryState? stateSnapshot,
        string? sessionIdOverride = null)
    {
        stateSnapshot = null;
        var sessionId = string.IsNullOrWhiteSpace(sessionIdOverride)
            ? currentSessionSecurityState.SessionId?.Value
            : sessionIdOverride;
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        FileTransferAuthorityId? expiredAuthorityId = null;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.RetryObserved ||
                !string.Equals(state.SessionId, sessionId.Trim(), StringComparison.Ordinal))
            {
                return false;
            }

            var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            if (IsRuntimeUnlockRetryAuthorityActiveUnsafe(state, nowMs))
            {
                stateSnapshot = state;
                return true;
            }

            if (ShouldExpireRuntimeUnlockRetryAuthorityUnsafe(state, nowMs))
            {
                expiredAuthorityId = state.DispatchContract?.Authority.AuthorityId;
            }
        }

        if (expiredAuthorityId is { IsDefault: false } expiredId)
        {
            _ = TrySettleRuntimeUnlockRetryDispatchMissingBeforeOfferIfCurrent(
                sessionId,
                "runtime_unlock_retry_authority_expired",
                "runtime_unlock_offer_send_not_observed",
                requiresLocalListenerRetry: false,
                expectedAuthorityId: expiredId);
        }

        return false;
    }

    private bool TryGetRuntimeUnlockObservedOfferReplayWindowForCurrentOffer(
        out RuntimeUnlockRecoveryRetryState? stateSnapshot,
        out RuntimeUnlockOfferProofState? offerSnapshot)
    {
        stateSnapshot = null;
        offerSnapshot = null;
        var sessionId = currentSessionSecurityState.SessionId?.Value;
        if (string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            var offer = runtimeUnlockOfferProofState;
            var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            var acceptedDispatchSettlement = state?.LastAppliedDispatchSettlementReport;
            var hasAcceptedDispatchSettlement =
                acceptedDispatchSettlement is
                {
                    Outcome: RuntimeUnlockRetryDispatchSettlementOutcome.DispatchObserved
                } dispatchSettlement &&
                state?.DispatchObserved == true &&
                state.DispatchContract?.Authority == dispatchSettlement.Authority;
            if (state is null ||
                offer is null ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                !string.Equals(state.SessionId, sessionId.Trim(), StringComparison.Ordinal) ||
                !state.RetryDispatched ||
                !hasAcceptedDispatchSettlement ||
                !state.ObservedSendPending ||
                state.ObservedSendDeadlineUtcMs <= 0 ||
                nowMs > state.ObservedSendDeadlineUtcMs ||
                offer.Retired ||
                !offer.ObservedSend ||
                offer.PeerReceived ||
                !offer.AnswerTimeoutScheduled ||
                outboundAccelerationOfferGeneration != offer.Generation ||
                outboundAccelerationOfferPayerDecisionId != offer.PayerDecisionId ||
                !string.Equals(outboundAccelerationOfferNonce, offer.Nonce, StringComparison.Ordinal) ||
                state.CurrentOfferGeneration != offer.Generation)
            {
                return false;
            }

            stateSnapshot = state;
            offerSnapshot = offer;
            return true;
        }
    }

    private bool TryGrantRuntimeUnlockRecoveryContractRetryAuthorityForReceiveStallBypass(
        string? sessionId,
        string purpose,
        string? blockerReason)
    {
        if (!IsTunaActivationOfferSendPurpose(purpose) ||
            string.IsNullOrWhiteSpace(sessionId))
        {
            return false;
        }

        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.RetryObserved ||
                state.RetryAuthorityGranted ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                !string.Equals(state.SessionId, sessionId.Trim(), StringComparison.Ordinal))
            {
                return false;
            }

            GrantRuntimeUnlockRecoveryContractRetryAuthorityUnsafe(state);
            if (state.RetryDispatched)
            {
                state.ContractState = SessionRecoveryContractState.RetryDispatched;
            }
            else if (state.RetryQueued)
            {
                state.ContractState = SessionRecoveryContractState.RetryQueued;
            }

            stateSnapshot = state;
        }

        LogRuntimeUnlockRecoveryContract("session_recovery_contract_retry_authority_granted", stateSnapshot!.SessionId);
        return true;
    }

    private void MarkRuntimeUnlockRecoveryContractAuthoritySendStarted(string purpose)
    {
        if (!IsTunaActivationOfferSendPurpose(purpose))
        {
            return;
        }

        var isOfferReplay = string.Equals(purpose, "offer_replay", StringComparison.OrdinalIgnoreCase);
        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                !state.RetryAuthorityGranted ||
                (!state.RetryAuthorityPending && !isOfferReplay) ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed)
            {
                return;
            }

            var nowMs = DateTimeOffset.UtcNow.ToUnixTimeMilliseconds();
            RefreshRuntimeUnlockRecoveryContractOfferSendWindowUnsafe(state, nowMs);
            state.ObservedSendPending = true;
            stateSnapshot = state;
        }

        LogRuntimeUnlockRecoveryContract("session_recovery_contract_retry_authority_send_started", stateSnapshot!.SessionId);
    }

    private bool TryStartRuntimeUnlockCutThroughForCurrentOffer(
        string sessionId,
        long offerGeneration,
        string trigger)
    {
        if (string.IsNullOrWhiteSpace(sessionId) ||
            offerGeneration <= 0)
        {
            return false;
        }

        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                state.RetryObserved ||
                !state.CutThroughPending ||
                !string.Equals(state.SessionId, sessionId.Trim(), StringComparison.Ordinal))
            {
                return false;
            }

            state.CutThroughPending = false;
            state.CutThroughActive = true;
            state.CutThroughOfferSent = false;
            state.CutThroughPeerReceived = false;
            state.CutThroughCompleted = false;
            state.CutThroughAttempt++;
            state.CurrentOfferGeneration = offerGeneration;
            state.AuthorityFailureReason = null;
            stateSnapshot = state;
        }

        LocalOperationalLog.Warn(
            "NKN.Tuna",
            $"event=runtime_unlock_cutthrough_started; session_id={SanitizeLogToken(sessionId)}; offer_generation={offerGeneration}; contract_generation={stateSnapshot!.ContractGeneration}; attempt={stateSnapshot.CutThroughAttempt}; trigger={SanitizeLogToken(trigger)}; reason=peer_response_timeout_under_regular_v4_recovery");
        LogRuntimeUnlockRecoveryContract("session_recovery_contract_cutthrough_started", stateSnapshot.SessionId);
        ScheduleRuntimeUnlockRetryDispatchAuthoritySettlementCheck(stateSnapshot);
        return true;
    }

    private void MarkRuntimeUnlockCutThroughOfferSent(
        string sessionId,
        long offerGeneration,
        string? observedLane)
    {
        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        lock (accelerationGate)
        {
            var state = runtimeUnlockRecoveryRetryState;
            if (state is null ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                !state.CutThroughActive ||
                !string.Equals(state.SessionId, sessionId.Trim(), StringComparison.Ordinal) ||
                state.CurrentOfferGeneration != offerGeneration)
            {
                return;
            }

            state.CutThroughOfferSent = true;
            state.AuthorizedObservedLane = SanitizeLogToken(observedLane ?? "(none)");
            stateSnapshot = state;
        }

        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_cutthrough_offer_sent; session_id={SanitizeLogToken(sessionId)}; offer_generation={offerGeneration}; contract_generation={stateSnapshot!.ContractGeneration}; attempt={stateSnapshot.CutThroughAttempt}; observed_lane={SanitizeLogToken(observedLane ?? "(none)")}");
        LogRuntimeUnlockRecoveryContract("session_recovery_contract_cutthrough_offer_sent", stateSnapshot.SessionId);
    }

    private bool MarkRuntimeUnlockCutThroughPeerReceived(
        string sessionId,
        long payerDecisionId,
        string nonce,
        string source)
    {
        RuntimeUnlockRecoveryRetryState? stateSnapshot = null;
        RuntimeUnlockTransactionDecision? transactionDecision = null;
        lock (accelerationGate)
        {
            var offer = runtimeUnlockOfferProofState;
            var state = runtimeUnlockRecoveryRetryState;
            if (offer is null ||
                state is null ||
                state.ContractState is SessionRecoveryContractState.Completed or SessionRecoveryContractState.Failed ||
                !state.CutThroughActive ||
                offer.Retired ||
                offer.PayerDecisionId != payerDecisionId ||
                !string.Equals(offer.Nonce, nonce, StringComparison.Ordinal) ||
                !string.Equals(offer.SessionId, sessionId.Trim(), StringComparison.Ordinal) ||
                !string.Equals(state.SessionId, sessionId.Trim(), StringComparison.Ordinal) ||
                state.CurrentOfferGeneration != offer.Generation)
            {
                return false;
            }

            offer.PeerReceived = true;
            state.CutThroughPeerReceived = true;
            state.AuthorityFailureReason = null;
            transactionDecision = ApplyRuntimeUnlockTransactionUnsafe(
                RuntimeUnlockTransactionEventKind.PeerReceived,
                sessionId,
                offer.Generation,
                source);
            stateSnapshot = state;
        }

        LogRuntimeUnlockTransactionDecision(RuntimeUnlockTransactionEventKind.PeerReceived, transactionDecision);
        LocalOperationalLog.Info(
            "NKN.Tuna",
            $"event=runtime_unlock_cutthrough_peer_received; session_id={SanitizeLogToken(sessionId)}; payer_decision_id={payerDecisionId}; offer_generation={stateSnapshot!.CurrentOfferGeneration}; contract_generation={stateSnapshot.ContractGeneration}; attempt={stateSnapshot.CutThroughAttempt}; source={SanitizeLogToken(source)}");
        LogRuntimeUnlockRecoveryContract("session_recovery_contract_cutthrough_peer_received", stateSnapshot.SessionId);
        MarkRuntimeUnlockRegularV4ActivationWindowPeerVisibleIfCurrent(
            sessionId,
            stateSnapshot.CurrentOfferGeneration,
            source);
        return true;
    }

